INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('775a30c2-948f-52e2-ab7b-52a83efe5349', '92c5a251-8327-55a2-a1b5-b9a2361f68e1', 'd0889706-eb31-564b-a00e-1dbf712e6534', 4, 4, 'ሌላም ዳማ ፈረስ ወጣ፤ በእርሱም ላይ ለተቀመጠው ሰላምን ከምድር ይወስድ ዘንድ ሰዎችም እርስ በርሳቸው እንዲተራረዱ ሥልጣን ተሰጠው፤ ታላቅም ሰይፍ ተሰጠው።'),
  ('813fee94-6b0b-565d-a644-e244535a3993', '92c5a251-8327-55a2-a1b5-b9a2361f68e1', 'd0889706-eb31-564b-a00e-1dbf712e6534', 5, 5, 'ሦስተኛውንም ማኅተም በፈታ ጊዜ ሦስተኛው እንስሳ “መጥተህ እይ” ሲል ሰማሁ። አየሁም፤ እነሆም ጥቁር ፈረስ ወጣ፤ በእርሱም ላይ የተቀመጠው በእጁ ሚዛን ያዘ።'),
  ('d2f44e43-3076-505b-ac61-7916d462c309', '92c5a251-8327-55a2-a1b5-b9a2361f68e1', 'd0889706-eb31-564b-a00e-1dbf712e6534', 6, 6, 'በአራቱም እንስሶች መካከል ድምፅ “አንድ እርቦ ስንዴ በዲናር ሦስት እርቦ ገብስም በዲናር፥ ዘይትንና ወይንንም አትጕዳ” ሲል ሰማሁ።'),
  ('9a8812a5-7c2f-52a4-ac2b-48ef20a9fa95', '92c5a251-8327-55a2-a1b5-b9a2361f68e1', 'd0889706-eb31-564b-a00e-1dbf712e6534', 7, 7, 'አራተኛውንም ማኅተም በፈታ ጊዜ የአራተኛው እንስሳ ድምፅ “መጥተህ እይ” ሲል ሰማሁ።'),
  ('2e8e045c-0651-52d3-a04d-f2011f15dec7', '92c5a251-8327-55a2-a1b5-b9a2361f68e1', 'd0889706-eb31-564b-a00e-1dbf712e6534', 8, 8, 'አየሁም፤ እነሆም ሐመር ፈረስ ወጣ፤ በእርሱም ላይ የተቀመጠው ስሙ ሞት ነበረ። ሲኦልም ተከተለው፤ በሰይፍና በራብም በሞትም በምድርም አራዊት ይገድሉ ዘንድ ከምድር በአራተኛዋ እጅ ላይ ሥልጣን ተሰጣቸው።'),
  ('8f33ba68-5468-5755-a5f9-59e4f18d97f1', '92c5a251-8327-55a2-a1b5-b9a2361f68e1', 'd0889706-eb31-564b-a00e-1dbf712e6534', 9, 9, 'አምስተኛውንም ማኅተም በፈታ ጊዜ፥ ስለ እግዚአብሔር ቃልና ስለ ጠበቁት ምስክር የታረዱትን የሰዎች ነፍሳት ከመሠዊያ በታች አየሁ።'),
  ('fd4942f0-7e33-52f3-a026-80e8c40781a9', '92c5a251-8327-55a2-a1b5-b9a2361f68e1', 'd0889706-eb31-564b-a00e-1dbf712e6534', 10, 10, 'በታላቅ ድምፅም እየጮኹ “ቅዱስና እውነተኛ ጌታ ሆይ! እስከ መቼ ድረስ አትፈርድም? ደማችንንስ በምድር በሚኖሩት ላይ እስከ መቼ አትበቀልም?” አሉ።'),
  ('be9aeb58-d9bf-59a3-a78c-3c0e395ba081', '92c5a251-8327-55a2-a1b5-b9a2361f68e1', 'd0889706-eb31-564b-a00e-1dbf712e6534', 11, 11, 'ለእያንዳንዳቸውም ነጭ ልብስ ተሰጣቸው፤ እንደ እነርሱም ደግሞ ይገደሉ ዘንድ ያላቸው የባሪያዎች ባልንጀራዎቻቸውና የወንድሞቻቸው ቍጥር እስኪፈጸም ድረስ፥ ገና ጥቂት ዘመን እንዲያርፉ ተባለላቸው።'),
  ('6ee5feae-ec90-50d9-ae35-e06aa490a866', '92c5a251-8327-55a2-a1b5-b9a2361f68e1', 'd0889706-eb31-564b-a00e-1dbf712e6534', 12, 12, 'ስድስተኛውንም ማኅተም በፈታ ጊዜ አየሁ፤ ታላቅም የምድር መናወጥ ሆነ፤ ፀሐይም እንደ ማቅ ጠጕር ጥቁር ሆነ፤ ጨረቃም በሞላው እንደ ደም ሆነ፤'),
  ('0c1f05ac-7d66-5cf3-aa2f-6b3a93278a98', '92c5a251-8327-55a2-a1b5-b9a2361f68e1', 'd0889706-eb31-564b-a00e-1dbf712e6534', 13, 13, 'በለስም በብርቱ ነፋስ ተናውጣ ቃርያዋን ፍሬ እንደምትጥል የሰማይ ከዋክብት ወደ ምድር ወደቁ፤'),
  ('7629fd18-0194-50ba-a0bd-107745161851', '92c5a251-8327-55a2-a1b5-b9a2361f68e1', 'd0889706-eb31-564b-a00e-1dbf712e6534', 14, 14, 'ሰማይም እንደ መጽሐፍ ተጠቅልሎ አለፈ፤ ተራራዎችና ደሴቶችም ሁሉ ከስፍራቸው ተወሰዱ።'),
  ('d6b8a424-2f19-5f1b-a196-c2ace8a95257', '92c5a251-8327-55a2-a1b5-b9a2361f68e1', 'd0889706-eb31-564b-a00e-1dbf712e6534', 15, 15, 'የምድርም ነገሥታትና መኳንንት ሻለቃዎችም ባለ ጠጋዎችም ኀይለኛዎችም ባሪያዎችም ጌቶችም ሁሉ በዋሾችና በተራራዎች ዐለቶች ተሰወሩ፤'),
  ('4e99b036-4d7a-5d04-aafb-2492b2108051', '92c5a251-8327-55a2-a1b5-b9a2361f68e1', 'd0889706-eb31-564b-a00e-1dbf712e6534', 16, 16, 'ተራራዎችንና ዐለቶችንም “በላያችን ውደቁ በዙፋንም ከተቀመጠው ፊት ከበጉም ቍጣ ሰውሩን፤'),
  ('f599d74b-8440-5a7c-a921-d856e4be920c', '92c5a251-8327-55a2-a1b5-b9a2361f68e1', 'd0889706-eb31-564b-a00e-1dbf712e6534', 17, 17, 'ታላቁ የቁጣው ቀን መጥቶአልና፤ ማንስ ሊቆም ይችላል?” አሉአቸው።'),
  ('7a09e09c-6a7a-5bec-a7ba-54ed948c531f', 'f5aaa174-03b7-5b1e-a28a-9e90ec2dad42', '247b43e3-0c7c-52bc-aff2-e12532acdd0f', 1, 1, 'ከዚህም በኋላ በአራቱ የምድር ማዕዘን ቆመው አራት መላእክት አየሁ፤ እነርሱም ነፋስ በምድር ቢሆን ወይም በባሕር ወይም በማንም ዛፍ እንዳይነፍስ አራቱን የምድር ነፋሳት ያዙ።'),
  ('521bb3f8-2a8e-513d-a96f-ba0b1da500b6', 'f5aaa174-03b7-5b1e-a28a-9e90ec2dad42', '247b43e3-0c7c-52bc-aff2-e12532acdd0f', 2, 2, 'የሕያው አምላክ ማኅተም ያለውም ሌላ መልአክ ከፀሐይ መውጫ ሲወጣ አየሁ፤ ምድርንና ባሕርንም ሊጐዱ ለተሰጣቸው ለአራቱ መላእክት በታላቅ ድምፅ እየጮኸ'),
  ('691c50ba-d820-5d71-a78e-398c7f399a1c', 'f5aaa174-03b7-5b1e-a28a-9e90ec2dad42', '247b43e3-0c7c-52bc-aff2-e12532acdd0f', 3, 3, '“የአምላካችንን ባሪያዎች ግምባራቸውን እስክናትማቸው ድረስ ምድርን ቢሆን ወይም ባሕርን ወይም ዛፎችን አትጕዱ፤” አላቸው።'),
  ('724d0b5d-9fff-5c6d-a645-6affd509a01a', 'f5aaa174-03b7-5b1e-a28a-9e90ec2dad42', '247b43e3-0c7c-52bc-aff2-e12532acdd0f', 4, 4, 'የታተሙትንም ቍጥር ሰማሁ፤ ከእስራኤል ልጆች ነገድ ሁሉ የታተሙት መቶ አርባ አራት ሺህ ነበሩ።'),
  ('246c8fd9-15e5-5e75-aa1d-c3a36e7ae570', 'f5aaa174-03b7-5b1e-a28a-9e90ec2dad42', '247b43e3-0c7c-52bc-aff2-e12532acdd0f', 5, 5, 'ከይሁዳ ነገድ ዐሥራ ሁለት ሺህ ታተሙ፤ ከሮቤል ነገድ ዐሥራ ሁለት ሺህ፥ ከጋድ ነገድ ዐሥራ ሁለት ሺህ፥'),
  ('ba898961-aa1d-5f5b-ac49-c515d01b15df', 'f5aaa174-03b7-5b1e-a28a-9e90ec2dad42', '247b43e3-0c7c-52bc-aff2-e12532acdd0f', 6, 6, 'ከአሴር ነገድ ዐሥራ ሁለት ሺህ፥ ከንፍታሌም ነገድ ዐሥራ ሁለት ሺህ፥ ከምናሴ ነገድ ዐሥራ ሁለት ሺህ፥'),
  ('566a7033-81d9-5f97-aea9-ec9aa4daf6ea', 'f5aaa174-03b7-5b1e-a28a-9e90ec2dad42', '247b43e3-0c7c-52bc-aff2-e12532acdd0f', 7, 7, 'ከስምዖን ነገድ ዐሥራ ሁለት ሺህ፥ ከሌዊ ነገድ ዐሥራ ሁለት ሺህ፥ ከይሳኮር ነገድ ዐሥራ ሁለት ሺህ፥'),
  ('07eb5416-f3d1-5a17-ac43-679837cd19de', 'f5aaa174-03b7-5b1e-a28a-9e90ec2dad42', '247b43e3-0c7c-52bc-aff2-e12532acdd0f', 8, 8, 'ከዛብሎን ነገድ ዐሥራ ሁለት ሺህ፥ ከዮሴፍ ነገድ ዐሥራ ሁለት ሺህ፥ ከብንያም ነገድ ዐሥራ ሁለት ሺህ ታተሙ።'),
  ('0ada11d0-eca8-54f7-a2fc-96c014534a37', 'f5aaa174-03b7-5b1e-a28a-9e90ec2dad42', 'e0ca509e-6e04-5427-ad05-b27c309a09a7', 1, 9, 'ከዚህ በኋላ አየሁ፤ እነሆም አንድ እንኳ ሊቆጥራቸው የማይችል ከሕዝብና ከነገድ ከወገንም ከቋንቋም ሁሉ እጅግ ብዙ ሰዎች ነበሩ፤ ነጭ ልብስም ለብሰው የዘንባባንም ዝንጣፊዎች በእጆቻቸው ይዘው በዙፋኑና በበጉ ፊት ቆሙ፤'),
  ('92be1dc9-91b0-51d4-a551-5d4a72c2a7d1', 'f5aaa174-03b7-5b1e-a28a-9e90ec2dad42', 'e0ca509e-6e04-5427-ad05-b27c309a09a7', 2, 10, 'በታላቅም ድምፅ እየጮሁ'),
  ('73a855ca-94b3-533d-a7e1-1b58c3cdea87', 'f5aaa174-03b7-5b1e-a28a-9e90ec2dad42', 'e0ca509e-6e04-5427-ad05-b27c309a09a7', 3, 13, 'ከሽማግሌዎቹም አንዱ ተመልሶ “እነዚህ ነጩን ልብስ የለበሱ እነማን ናቸው? ከወዴትስ መጡ?” አለኝ።'),
  ('26efee57-5d95-5668-a219-d8022c2afdc0', 'f5aaa174-03b7-5b1e-a28a-9e90ec2dad42', 'e0ca509e-6e04-5427-ad05-b27c309a09a7', 4, 14, 'እኔም “ጌታ ሆይ! አንተ ታውቃለህ፤” አልሁት። አለኝም “እነዚህ ከታላቁ መከራ የመጡ ናቸው፤ ልብሳቸውንም አጥበው በበጉ ደም አነጹ።'),
  ('5880ba88-6edb-58c2-ac14-1a859abca2c3', 'f5aaa174-03b7-5b1e-a28a-9e90ec2dad42', 'e0ca509e-6e04-5427-ad05-b27c309a09a7', 5, 15, 'ስለዚህ በእግዚአብሔር ዙፋን ፊት አሉ፤ ሌሊትና ቀንም በመቅደሱ ያመልኩታል፤ በዙፋኑም ላይ የተቀመጠው በእነርሱ ላይ ያድርባቸዋል።'),
  ('c082e845-dfb8-5737-a385-e150e9e1fb8c', 'f5aaa174-03b7-5b1e-a28a-9e90ec2dad42', 'e0ca509e-6e04-5427-ad05-b27c309a09a7', 6, 16, 'ከእንግዲህ ወዲህ አይራቡም፤ ከእንግዲህም ወዲህ አይጠሙም፤ ፀሐይም ትኵሳትም ሁሉ ከቶ አይወርድባቸውም፤'),
  ('5ffb73e8-bcae-500e-adac-a3e77c7b8643', 'f5aaa174-03b7-5b1e-a28a-9e90ec2dad42', 'e0ca509e-6e04-5427-ad05-b27c309a09a7', 7, 17, 'በዙፋኑ መካከል ያለው በጉ እረኛቸው ይሆናልና፤ ወደ ሕይወትም ውሃ ምንጭ ይመራቸዋልና፤ እግዚአብሔርም እንባዎችን ሁሉ ከዐይናቸው ያብሳል።”'),
  ('48b904dd-7492-5dcb-a762-304baa5e3b13', '6ffcdb11-6c6a-5ef1-a469-9e3a40ceefdb', '03a65113-e441-548c-a131-955a5ef890d6', 1, 1, 'ሰባተኛውንም ማኅተም በፈታ ጊዜ ግማሽ ሰዓት የሚያህል ዝምታ በሰማይ ሆነ።'),
  ('aae6f1e7-d453-5f11-a039-79158b5d095d', '6ffcdb11-6c6a-5ef1-a469-9e3a40ceefdb', '03a65113-e441-548c-a131-955a5ef890d6', 2, 2, 'በእግዚአብሔርም ፊት የሚቆሙትን ሰባቱን መላእክት አየሁ፤ ሰባትም መለከት ተሰጣቸው።'),
  ('b75e299a-787d-5565-afc5-2cdc3f753f13', '6ffcdb11-6c6a-5ef1-a469-9e3a40ceefdb', '03a65113-e441-548c-a131-955a5ef890d6', 3, 3, 'ሌላም መልአክ መጣና የወርቅ ጥና ይዞ በመሰዊያው አጠገብ ቆመ፤ በዙፋኑም ፊት ባለው በወርቅ መሰዊያ ላይ ለቅዱሳን ሁሉ ጸሎት እንዲጨምረው ብዙ ዕጣን ተሰጠው።'),
  ('539d6e88-3a27-5806-a091-1ec1e41f898f', '6ffcdb11-6c6a-5ef1-a469-9e3a40ceefdb', '03a65113-e441-548c-a131-955a5ef890d6', 4, 4, 'የዕጣኑም ጢስ ከቅዱሳን ጸሎት ጋር ከመልአኩ እጅ በእግዚአብሔር ፊት ወጣ።'),
  ('1cc73cf9-cfa2-5da9-a843-993fcb9b7d52', '6ffcdb11-6c6a-5ef1-a469-9e3a40ceefdb', '03a65113-e441-548c-a131-955a5ef890d6', 5, 5, 'መልአኩም ጥናውን ይዞ የመሰዊያውን እሳት ሞላበት፤ ወደ ምድርም ጣለው፤ ነጐድጓድና ድምፅም መብረቅም መናወጥም ሆነ።'),
  ('50527247-a538-58ca-a08c-4f7a5718e9b2', '6ffcdb11-6c6a-5ef1-a469-9e3a40ceefdb', '3c50d07f-775c-5aec-a3ac-2b61538152a4', 1, 6, 'ሰባቱንም መለከት የያዙ ሰባቱ መላእክት ሊነፉ ተዘጋጁ።'),
  ('c663cb10-5813-5796-a790-5942b45d5841', '6ffcdb11-6c6a-5ef1-a469-9e3a40ceefdb', '3c50d07f-775c-5aec-a3ac-2b61538152a4', 2, 7, 'ፊተኛውም መልአክ መለከቱን ነፋ፤ ደምም የተቀላቀለበት በረዶና እሳት ሆነ፤ ወደ ምድርም ተጣለ፤ የምድርም ሲሶው ተቃጠለ፤ የዛፎችም ሲሶው ተቃጠለ፤ የለመለመም ሣር ሁሉ ተቃጠለ።'),
  ('815c46fb-b9be-5901-ad85-0affb17473e0', '6ffcdb11-6c6a-5ef1-a469-9e3a40ceefdb', '3c50d07f-775c-5aec-a3ac-2b61538152a4', 3, 8, 'ሁለተኛውም መልአክ መለከቱን ነፋ፤ በእሳት የሚቃጠል ታላቅ ተራራን የሚመስል ነገር በባሕር ተጣለ፤ የባሕርም ሲሶው ደም ሆነ፤'),
  ('862edb3e-4471-5fdb-a92b-aa0bd6e7869e', '6ffcdb11-6c6a-5ef1-a469-9e3a40ceefdb', '3c50d07f-775c-5aec-a3ac-2b61538152a4', 4, 9, 'በባሕርም ከሚኖሩ ሕይወት ካላቸው ፍጥረቶች ሲሶው ሞተ፤ የመርከቦችም ሲሶው ጠፋ።'),
  ('b95ddd84-0781-5492-a74e-9da427d7fc47', '6ffcdb11-6c6a-5ef1-a469-9e3a40ceefdb', '3c50d07f-775c-5aec-a3ac-2b61538152a4', 5, 10, 'ሦስተኛውም መልአክ መለከቱን ነፋ፤ እንደ ችቦም የሚቃጠል ታላቅ ኮከብ ከሰማይ ወደቀ፤ በወንዞችና በውሃም ምንጮች ሲሶ ላይ ወደቀ።'),
  ('32db774a-939e-5007-a7c1-d8ab171e0f6c', '6ffcdb11-6c6a-5ef1-a469-9e3a40ceefdb', '3c50d07f-775c-5aec-a3ac-2b61538152a4', 6, 11, 'የኮከቡም ስም እሬቶ ይባላል፤ የውሃውም ሲሶ መራራ ሆነ፤ መራራም ስለተደረገ በውሃው ጠንቅ ብዙ ሰዎች ሞቱ።'),
  ('31e3d88d-a4a6-5f96-abab-6a77b2ff468f', '6ffcdb11-6c6a-5ef1-a469-9e3a40ceefdb', '3c50d07f-775c-5aec-a3ac-2b61538152a4', 7, 12, 'አራተኛውም መልአክ መለከቱን ነፋ፤ የፀሐይ ሲሶና የጨረቃ ሲሶ የከዋክብትም ሲሶ ተመታ፤ የእነዚህ ሲሶ ይጨልም ዘንድ፥ የቀንም ሲሶው እንዳያበራ፥ እንዲሁም የሌሊት።'),
  ('e7ec12f8-1be6-5631-a17e-c68e74a33fa8', '6ffcdb11-6c6a-5ef1-a469-9e3a40ceefdb', '3c50d07f-775c-5aec-a3ac-2b61538152a4', 8, 13, 'አየሁም፤ አንድም ንስር በሰማይ መካከል እየበረረ በታላቅ ድምፅ “ሊነፉ ያላቸው የሦስቱ መላእክት መለከት ስለሚቀረው ድምፅ በምድር ላይ ለሚኖሩት ወዮላቸው! ወዮላቸው! ወዮላቸው!” ሲል ሰማሁ።'),
  ('836b90e4-3a0c-56b5-a4a0-fe02b2de093d', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 1, 1, 'አምስተኛውም መልአክ መለከቱን ነፋ፤ ከሰማይም ወደ ምድር ወድቆ የነበረ ኮከብ አየሁ፤ የጥልቁም ጕድጓድ መክፈቻ ተሰጠው።'),
  ('ef44571e-b24e-55ea-ace1-cb5b58c27f0e', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 2, 2, 'የጥልቁንም ጕድጓድ ከፈተው፤ ጢስም ከታላቅ እቶን እንደሚወጣ ጢስ ሆኖ ከጕድጓዱ ወጣ፤ ፀሐይና አየርም በጕድጓዱ ጢስ ጨለሙ።'),
  ('db4c2f96-06a7-5f49-a78e-e349e13b640e', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 3, 3, 'ከጢሱም አንበጣዎች ወደ ምድር ወጡ፤ የምድርም ጊንጦች ሥልጣን እንዳላቸው ሥልጣን ተሰጣቸው።'),
  ('1f6eb39b-e7cd-5f80-ab47-b072085a61d5', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 4, 4, 'የእግዚአብሔርም ማኅተም በግምባራቸው ከሌለባቸው ሰዎች በቀር በምድር ያለውን ሣር ቢሆንም ወይም ማናቸውንም የለመለመ ነገር ወይም ማናቸውንም ዛፍ እንዳይጐዱ ተባለላቸው።'),
  ('1568cd84-5849-59b2-a73e-3fedc2b6eaf5', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 5, 5, 'አምስትም ወር ሊያሰቃዩአቸው ተሰጣቸው እንጂ ሊገድሉአቸው አይደለም፤ እነርሱም የሚያሠቃዩት ሥቃይ ጊንጥ ሰውን ነድፎ እንደሚያሠቃይ ነው።'),
  ('ba207416-e2f8-5f4a-a518-1750648ec876', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 6, 6, 'በዚያም ወራት ሰዎች ሞትን ይፈልጋሉ፤ አያገኙትምም፤ ሊሞቱም ይመኛሉ፤ ሞትም ከእነርሱ ይሸሻል።'),
  ('346c77c3-1a5e-57a6-a6a5-0b56338d6eac', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 7, 7, 'የአንበጣዎቹም መልክ ለጦርነት እንደ ተዘጋጁ ፈረሶች ነው፤ በራሳቸውም ላይ ወርቅ የሚመስሉ አክሊሎች ነበሩአቸው፤ ፊታቸውም እንደ ሰው ፊት ነበረ፤'),
  ('f7efb4b5-7a94-5183-ad3d-f649fdad8106', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 8, 8, 'የሴቶችን ጠጕር የሚመስል ጠጕር ነበራቸው፤ ጥርሳቸውም እንደ አንበሳ ጥርስ ነበረ፤'),
  ('593cd777-ff2e-5edc-ab9b-fe50487ced50', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 9, 9, 'የብረት ጥሩር የሚመስልም ጥሩር ነበራቸው፤ የክንፋቸውም ድምፅ ወደ ጦርነት እንደሚጋልቡ እንደ ብዙ ፈረሶች ሰረገላዎች ድምፅ ነበረ።'),
  ('e5b102cd-7ffc-58f7-a578-6d3a033d8625', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 10, 10, 'እንደ ጊንጥም ጅራት ያለ ጅራት አላቸው፤ በጅራታቸውም መውጊያ አለ፤ ሰዎችንም አምስት ወር እንዲጐዱ ሥልጣን አላቸው።'),
  ('0ce32aaf-10cf-53ff-ad4e-851194eff0f5', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 11, 11, 'በእነርሱም ላይ ንጉሥ አላቸው፤ እርሱም የጥልቅ መልአክ ነው፤ ስሙም በዕብራይስጥ አባዶን በግሪክም አጶልዮን ይባላል።'),
  ('917048c0-0e79-5269-a2b4-1b2945310f1c', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 12, 12, 'ፊተኛው ወዮ አልፎአል፤ እነሆ ከዚህ በኋላ ገና ሁለት ወዮ ይመጣል።'),
  ('87f9bbf4-2e7c-5cda-a87c-7644e313fe80', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 13, 13, 'ስድስተኛውም መልአክ መለከቱን ነፋ፤ በእግዚአብሔርም ፊት ካለ በወርቅ ከተሠራ መሠዊያ ቀንዶች አንድ ድምፅ ሰማሁ፤'),
  ('2ed5669b-8a60-561c-abd3-d9f902e32197', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 14, 14, 'መለከትም ያለውን ስድስተኛውን መልአክ “በታላቁ ወንዝ በኤፍራጥስ የታሰሩትን አራቱን መላእክት ፍታቸው፤” አለው።'),
  ('51ce63aa-30fe-5b88-af3f-0afc492fb8fb', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 15, 15, 'የሰዎችንም ሲሶ እንዲገድሉ ለሰዓቱና ለቀኑ ለወሩም ለዓመቱም ተዘጋጅተው የነበሩ አራቱ መላእክት ተፈቱ።'),
  ('3fec72d2-3af4-5d1c-a74e-17090434bc60', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 16, 16, 'የፈረሰኞችም ጭፍራ ቁጥር ሁለት መቶ ሚሊዮን ነበረ፤ ቁጥራቸውን ሰማሁ።'),
  ('a140e44e-b8e1-51a5-af42-1e525b2a1d62', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 17, 17, 'ፈረሶቹንና በእነርሱም ላይ የተቀመጡትን እንዲሁ በራእይ አየሁ፤ እሳትና ያክንት ዲንም የሚመስል ጥሩር ነበራቸው፤ የፈረሶቹም ራስ እንደ አንበሳ ራስ ነበረ፤ ከአፋቸውም እሳትና ጢስ ዲንም ወጣ።'),
  ('f2ab0359-bcab-5ae5-a982-2494618687b6', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 18, 18, 'ከአፋቸውም በወጡት በእሳቱና በጢሱ በዲኑም በእነዚህ ሦስት መቅሰፍቶች የሰዎቹ ሲሶ ተገደለ።'),
  ('fcbcdfd3-2b53-5f52-a887-e6eaba2f94a5', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 19, 19, 'የፈረሶቹ ሥልጣን በአፋቸውና በጅራታቸው ነውና፥ ጅራታቸው እባብን ይመስላልና፥ ራስም አላቸው፤ በእርሱም ይጐዳሉ።'),
  ('8d0cda49-22df-56f3-ac7c-7e251c34cab7', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 20, 20, 'በእነዚህም መቅሠፍቶች ያልተገደሉት የቀሩቱ ሰዎች ለአጋንንትና ያዩ ወይም ይሰሙ ወይም ይሄዱ ዘንድ ለማይችሉ ከወርቅና ከብር ከናስም ከድንጋይም ከእንጨትም ለተሠሩ ለጣዖቶች እንዳይሰግዱ ስለ እጃቸው ሥራ ንስሓ አልገቡም፤'),
  ('36118abe-bae8-5aa0-a1c6-0c51288d60fa', 'f6e94c93-a77a-577a-a7c9-d1f39991faa9', 'dc5d82e5-5ff1-505a-a7b6-a19f2d091862', 21, 21, 'ስለ መግደላቸውም ቢሆን ወይም ስለ አስማታቸው ወይም ስለ ዝሙታቸው ወይም ስለ ስርቆታቸው ንስሓ አልገቡም።'),
  ('649b84a8-27ad-5e24-a13f-2b75561deb6d', 'fd5e2b19-4130-5670-ac77-8f77a40bf1a3', 'c6f21dab-df9a-5b20-ae6a-829dbfbec8b5', 1, 1, 'ሌላም ብርቱ መልአክ ደመና ተጐናጽፎ ከሰማይ ሲወርድ አየሁ፤ በራሱም ላይ ቀስተ ደመና ነበረ፤ ፊቱም እንደ ፀሐይ እግሮቹም እንደ እሳት ዓምዶች ነበሩ፤'),
  ('0dc0c56c-b87c-5134-afc5-c1e7e04150e1', 'fd5e2b19-4130-5670-ac77-8f77a40bf1a3', 'c6f21dab-df9a-5b20-ae6a-829dbfbec8b5', 2, 2, 'የተከፈተችንም ታናሽ መጽሐፍ በእጁ ያዘ። ቀኝ እግሩንም በባሕር ላይ ግራውንም በምድር ላይ አኖረ፤ እንደሚያገሣም አንበሳ በታላቅ ድምፅ ጮኸ።'),
  ('730dd961-b443-5499-a194-e4f5511ca686', 'fd5e2b19-4130-5670-ac77-8f77a40bf1a3', 'c6f21dab-df9a-5b20-ae6a-829dbfbec8b5', 3, 3, 'በጮኸም ጊዜ ሰባቱ ነጐድጓድ በየድምፃቸው ተናገሩ።'),
  ('6dd7cb51-f1fe-58db-a8bc-95904d4c7152', 'fd5e2b19-4130-5670-ac77-8f77a40bf1a3', 'c6f21dab-df9a-5b20-ae6a-829dbfbec8b5', 4, 4, 'ሰባቱ ነጐድጓድ በተናገሩ ጊዜ ልጽፍ አሰብሁ፤ ከሰማይም “ሰባቱ ነጐድጓዶች የተናገሩትን ነገር በማኅተም ዝጋው፤ አትጻፈውም፤” የሚል ድምፅ ሰማሁ።'),
  ('af658b67-fc9d-5687-a35d-cea9334a9317', 'fd5e2b19-4130-5670-ac77-8f77a40bf1a3', 'c6f21dab-df9a-5b20-ae6a-829dbfbec8b5', 5, 5, 'በባሕርና በምድርም ላይ ሲቆም ያየሁት መልአክ ቀኝ እጁን ወደ ሰማይ አሻቅቦ ዘረጋ፤'),
  ('058f1a1a-1d69-52a9-aa9b-e72e9e90e24d', 'fd5e2b19-4130-5670-ac77-8f77a40bf1a3', 'c6f21dab-df9a-5b20-ae6a-829dbfbec8b5', 6, 6, 'ሰማይንና በእርሱም ያሉትን፥ ምድርንና በእርስዋም ያሉትን፥ ባሕርንና በእርሱም ያሉትን በፈጠረው፥ ከዘላለምም እስከ ዘላለም ድረስ ሕያው ሆኖ በሚኖረው ምሎ'),
  ('4201a9bc-2c7f-5399-adc3-9f10fa20d710', 'fd5e2b19-4130-5670-ac77-8f77a40bf1a3', 'c6f21dab-df9a-5b20-ae6a-829dbfbec8b5', 7, 7, '“ወደ ፊት አይዘገይም፤ ዳሩ ግን ሰባተኛው መልአክ ሊነፋ ባለው ጊዜ ድምፁም በሚሰማበት ዘመን፥ ለባሪያዎቹ ለነቢያት የምስራች እንደ ሰበከላቸው የእግዚአብሔር ምሥጢር ይፈጸማል፤” አለ።'),
  ('71a3358b-2c1c-5bb4-ac24-0f8ee9df324a', 'fd5e2b19-4130-5670-ac77-8f77a40bf1a3', 'c6f21dab-df9a-5b20-ae6a-829dbfbec8b5', 8, 8, 'ከሰማይም የሰማሁት ድምፅ እንደ ገና ሲናገረኝና “ሂድና በባሕርና በምድር ላይ ከሚቆመው መልአክ በእጁ ያለችውን የተከፈተችውን መጽሐፍ ውሰድ፤” ሲል ሰማሁ።'),
  ('7e9f51a5-97ef-59b3-a6ae-85af05a58152', 'fd5e2b19-4130-5670-ac77-8f77a40bf1a3', 'c6f21dab-df9a-5b20-ae6a-829dbfbec8b5', 9, 9, 'ወደ መልአኩም ሄጄ “ታናሺቱን መጽሐፍ ስጠኝ፤” አልሁት። እርሱም “ውሰድና ብላት፤ ሆድህንም መራራ ታደርገዋለች፤ በአፍህ ግን እንደ ማር ትጣፍጣለች፤” አለኝ።'),
  ('b9ca1e56-e617-550d-ad7c-60fd5ef26d6e', 'fd5e2b19-4130-5670-ac77-8f77a40bf1a3', 'c6f21dab-df9a-5b20-ae6a-829dbfbec8b5', 10, 10, 'ከመልአኩም እጅ ታናሺቱን መጽሐፍ ወስጄ በላኋት፤ በአፌም እንደ ማር ጣፋጭ ሆነች፤ ከበላኋት በኋላም ሆዴ መራራ ሆነ።'),
  ('ebd65fc6-e137-5865-a888-427904b2c8b7', 'fd5e2b19-4130-5670-ac77-8f77a40bf1a3', 'c6f21dab-df9a-5b20-ae6a-829dbfbec8b5', 11, 11, '“በብዙ ወገኖችና በአሕዛብም በቋንቋዎችም በነገሥታትም ላይ እንደ ገና ትንቢት ትናገር ዘንድ ይገባሃል፤” ተባልሁ።'),
  ('228d843b-ee3c-5325-aa65-d11e1c179a1c', '8879f715-30e7-55eb-aef1-2f5cb8afdc1d', 'de311d07-cd03-5fb8-a1d3-96420d51c091', 1, 1, 'በትር የሚመስል መለኪያ ለእኔ ተሰጠኝ፤ እንዲህም ተባልሁ “ተነሥተህ የእግዚአብሔርን መቅደስና መሠዊያውን በዚያም የሚሰግዱትን ለካ።'),
  ('3bd29f4c-37e5-5ec8-ab29-e648e1c7bc32', '8879f715-30e7-55eb-aef1-2f5cb8afdc1d', 'de311d07-cd03-5fb8-a1d3-96420d51c091', 2, 2, 'በመቅደሱም ውጭ ያለው እድሞ ለአሕዛብ ተሰጥቶአልና ተወው፤ አትለካውም፤ እነርሱም አርባ ሁለት ወር የተቀደሰችውን ከተማ ይረግጡአታል።'),
  ('5bb13c03-9d83-578d-adbe-3c0618003db2', '8879f715-30e7-55eb-aef1-2f5cb8afdc1d', 'de311d07-cd03-5fb8-a1d3-96420d51c091', 3, 3, 'ለሁለቱም ምስክሮቼ ማቅ ለብሰው ሺህ ከሁለት መቶ ስድሳ ቀን ትንቢት ሊናገሩ እሰጣለሁ።”'),
  ('d43ff4a8-03ad-5dce-a614-04f9afbeb5d8', '8879f715-30e7-55eb-aef1-2f5cb8afdc1d', 'de311d07-cd03-5fb8-a1d3-96420d51c091', 4, 4, 'እነዚህ በምድር ጌታ ፊት የሚቆሙ ሁለቱ ወይራዎችና ሁለቱ መቅረዞች ናቸው።'),
  ('5e1748c9-dff9-5732-aa58-483875b0bcd5', '8879f715-30e7-55eb-aef1-2f5cb8afdc1d', 'de311d07-cd03-5fb8-a1d3-96420d51c091', 5, 5, 'ማንምም ሊጐዳቸው ቢወድ እሳት ከአፋቸው ይወጣል፤ ጠላቶቻቸውንም ይበላል፤ ማንም ሊጐዳቸው ቢወድም እንዲሁ ሊገደል ይገባዋል።'),
  ('ae14bb23-69e4-54a2-a62f-472c6af62b03', '8879f715-30e7-55eb-aef1-2f5cb8afdc1d', 'de311d07-cd03-5fb8-a1d3-96420d51c091', 6, 6, 'እነዚህ ትንቢት በሚናገሩበት ወራት ዝናብ እንዳይዘንብ ሰማይን ሊዘጉ ሥልጣን አላቸው፤ ውሕሃዎችንም ወደ ደም ሊለውጡ በሚፈልጉበትም ጊዜ ሁሉ በመቅሠፍት ሁሉ ምድርን ሊመቱ ሥልጣን አላቸው።'),
  ('e6f56130-4bca-5dbd-a4c6-5d425f8a6c5e', '8879f715-30e7-55eb-aef1-2f5cb8afdc1d', 'de311d07-cd03-5fb8-a1d3-96420d51c091', 7, 7, 'ምስክራቸውን ከፈጸሙ በኋላ ከጥልቁ የሚወጣው አውሬ ይዋጋቸዋል፤ ያሸንፋቸውማል፤ ይገድላቸውማል።'),
  ('de09b4b5-0c5f-50ce-aeb6-68db6b099558', '8879f715-30e7-55eb-aef1-2f5cb8afdc1d', 'de311d07-cd03-5fb8-a1d3-96420d51c091', 8, 8, 'በድናቸውም በታላቂቱ ከተማ አደባባይ ይተኛል፤ እርስዋም በመንፈሳዊ ምሳሌ ሰዶምና ግብጽ የተባለች ደግሞ ጌታቸው የተሰቀለባት ናት።'),
  ('ce077da9-8e4a-52c0-ac73-cdb0774fc184', '8879f715-30e7-55eb-aef1-2f5cb8afdc1d', 'de311d07-cd03-5fb8-a1d3-96420d51c091', 9, 9, 'ከወገኖችና ከነገዶችም ከቋንቋዎችም ከአሕዛብም የሆኑ ሰዎች ሦስት ቀን ተኵል በድናቸውን ይመለከታሉ፤ በድናቸውም ወደ መቃብር ሊገባ አይፈቅዱም።'),
  ('97e55d00-0da2-54d2-a149-a27b66357814', '8879f715-30e7-55eb-aef1-2f5cb8afdc1d', 'de311d07-cd03-5fb8-a1d3-96420d51c091', 10, 10, 'እነዚህም ሁለት ነቢያት በምድር የሚኖሩትን ስላሠቃዩ በምድር የሚኖሩት በእነርሱ ላይ ደስ ይላቸዋል፤ በደስታም ይኖራሉ፤ እርስ በርሳቸውም ስጦታ ይሰጣጣሉ።'),
  ('8d5e72e0-dffa-5d29-aad8-78b1b4b7d735', '8879f715-30e7-55eb-aef1-2f5cb8afdc1d', 'de311d07-cd03-5fb8-a1d3-96420d51c091', 11, 11, 'ከሦስቱ ቀን ተኵልም በኋላ ከእግዚአብሔር የወጣ የሕይወት መንፈስ ገባባቸው፤ በእግሮቻቸውም ቆሙ፤ ታላቅም ፍርሃት በሚመለከቱት ላይ ወደቀባቸው።'),
  ('1db4071a-3da9-5a9c-ada0-23cf6f4f616d', '8879f715-30e7-55eb-aef1-2f5cb8afdc1d', 'de311d07-cd03-5fb8-a1d3-96420d51c091', 12, 12, 'በሰማይም “ወደዚህ ውጡ” የሚላቸውን ታላቅ ድምፅ ሰሙ፤ ጠላቶቻቸውም እየተመለከቱአቸው ወደ ሰማይ በደመና ወጡ።'),
  ('8f209259-c4a4-5b2b-af74-40a7617aa58b', '8879f715-30e7-55eb-aef1-2f5cb8afdc1d', 'de311d07-cd03-5fb8-a1d3-96420d51c091', 13, 13, 'በዚያም ሰዓት ታላቅ የምድር መናወጥ ሆነ፤ ከከተማይቱም ዐሥረኛው እጅ ወደቀ፤ በመናወጥም ሰባት ሺህ ሰዎች ተገደሉ፤ የቀሩትንም ፍርሃት ያዛቸው፤ ለሰማዩም አምላክ ክብር ሰጡ።'),
  ('4f91ce52-3294-5b21-af49-7d620d179904', '8879f715-30e7-55eb-aef1-2f5cb8afdc1d', 'de311d07-cd03-5fb8-a1d3-96420d51c091', 14, 14, 'ሁለተኛው ወዮ አልፎአል፤ እነሆ ሦስተኛው ወዮ በቶሎ ይመጣል።'),
  ('9bd135f5-3b0c-5cbc-a5a9-1a1f4ea88c69', '8879f715-30e7-55eb-aef1-2f5cb8afdc1d', 'a6e2ac8b-53c0-500d-a80d-d8d969169ed4', 1, 15, 'ሰባተኛው መልአክ መለከቱን ነፋ፤ በሰማይም'),
  ('7e6b2f13-a22e-52c3-ad7a-790f2d47d203', '8879f715-30e7-55eb-aef1-2f5cb8afdc1d', 'a6e2ac8b-53c0-500d-a80d-d8d969169ed4', 2, 19, 'በሰማይም ያለው የእግዚአብሔር መቅደስ ተከፈተ፤ የኪዳኑም ታቦት በመቅደሱ ታየ፤ መብረቅና ድምፅም ነጐድጓድም የምድርም መናወጥ ታላቅም በረዶ ሆነ።'),
  ('93921f8a-0da0-55f4-aa63-b81a7a1440a5', 'b75d73ee-faa1-5dba-abb5-c71b7d51d601', 'b2d2d368-f187-5aea-a019-a28b811839af', 1, 1, 'ታላቅ ምልክትም በሰማይ ታየ፤ ፀሐይን ተጐናጽፋ ጨረቃ ከእግሮችዋ በታች ያላት በራስዋም ላይ የዐሥራ ሁለት ከዋክብት አክሊል የተቀዳጀች አንዲት ሴት ነበረች።'),
  ('12b5d490-82ff-509d-a258-cfeb22a77d63', 'b75d73ee-faa1-5dba-abb5-c71b7d51d601', 'b2d2d368-f187-5aea-a019-a28b811839af', 2, 2, 'እርስዋም ፀንሳ ነበር፤ ምጥም ተይዛ ልትወልድ ተጭንቃ ጮኸች።'),
  ('75b4837d-cd45-5143-a672-6089288dcbd5', 'b75d73ee-faa1-5dba-abb5-c71b7d51d601', 'b2d2d368-f187-5aea-a019-a28b811839af', 3, 3, 'ሌላም ምልክት በሰማይ ታየ፤ ይኸውም ታላቅ ቀይ ዘንዶነው፤ ሰባት ራሶችና ዐሥር ቀንዶችም ነበሩት፤ በራሶቹም ላይ ሰባት ዘውዶች ነበሩ፤'),
  ('1de841fb-9bc1-50db-a789-62abea3f3d15', 'b75d73ee-faa1-5dba-abb5-c71b7d51d601', 'b2d2d368-f187-5aea-a019-a28b811839af', 4, 4, 'ጅራቱም የሰማይን ከዋክብት ሲሶ እየሳበ ወደ ምድር ጣላቸው። ዘንዶውም ሴቲቱ በወለደች ጊዜ ሕፃንዋን እንዲበላ ልትወልድ ባላት ሴት ፊት ቆመ።'),
  ('8de005d6-1ff4-5444-a375-bacce55f1374', 'b75d73ee-faa1-5dba-abb5-c71b7d51d601', 'b2d2d368-f187-5aea-a019-a28b811839af', 5, 5, 'አሕዛብንም ሁሉ በብረት በትር ይገዛቸው ዘንድ ያለውን ልጅ ወንድ ልጅ ወለደች፤ ልጅዋም ወደ እግዚአብሔርና ወደ ዙፋኑ ተነጠቀ።'),
  ('94bec430-2a8d-5af5-a62e-d5c9d67ebf1f', 'b75d73ee-faa1-5dba-abb5-c71b7d51d601', 'b2d2d368-f187-5aea-a019-a28b811839af', 6, 6, 'ሴቲቱም ሺህ ከሁለት መቶ ስድሳ ቀን በዚያ እንዲመግቡአት በእግዚአብሔር ተዘጋጅቶላት ወደ ነበረው ስፍራ ወደ በረሓ ሸሸች።'),
  ('dee8c11f-5d13-5058-ab97-902461e5c451', 'b75d73ee-faa1-5dba-abb5-c71b7d51d601', 'b2d2d368-f187-5aea-a019-a28b811839af', 7, 7, 'በሰማይም ሰልፍ ሆነ፤ ሚካኤልና መላእክቱ ዘንዶውን ተዋጉ። ዘንዶውም ከመላእክቱ ጋር ተዋጋ፤'),
  ('9dff7396-b9ec-5dd1-a833-8d410ee39cac', 'b75d73ee-faa1-5dba-abb5-c71b7d51d601', 'b2d2d368-f187-5aea-a019-a28b811839af', 8, 8, 'አልቻላቸውምም፤ ከዚያም ወዲያ በሰማይ ስፍራ አልተገኘላቸውም።'),
  ('107170b3-2ba0-560e-ae90-50c3348278ff', 'b75d73ee-faa1-5dba-abb5-c71b7d51d601', 'b2d2d368-f187-5aea-a019-a28b811839af', 9, 9, 'ዓለሙንም ሁሉ የሚያስተው፥ ዲያብሎስና ሰይጣን የሚባለው ታላቁ ዘንዶ እርሱም የቀደመው እባብ ተጣለ፤ ወደ ምድር ተጣለ፤ መላእክቱም ከእርሱ ጋር ተጣሉ።'),
  ('a5aa95da-0d01-560e-a6d4-f776d0abfb9b', 'b75d73ee-faa1-5dba-abb5-c71b7d51d601', 'b2d2d368-f187-5aea-a019-a28b811839af', 10, 10, 'ታላቅም ድምፅ በሰማይ ሰማሁ፤ እንዲህ ሲል'),
  ('6311321d-e4d5-5445-ad3c-42d78b5a2b58', 'b75d73ee-faa1-5dba-abb5-c71b7d51d601', 'b2d2d368-f187-5aea-a019-a28b811839af', 11, 13, 'ዘንዶውም ወደ ምድር እንደ ተጣለ ባየ ጊዜ ወንድ ልጅ የወለደችውን ሴት አሳደዳት።'),
  ('77b44ac4-4125-5b18-a285-2ee2559f5213', 'b75d73ee-faa1-5dba-abb5-c71b7d51d601', 'b2d2d368-f187-5aea-a019-a28b811839af', 12, 14, 'ከእባቡም ፊት ርቃ አንድ ዘመን፥ ዘመናትም፥ የዘመንም እኵሌታ ወደ ምትመገብበት ወደ ስፍራዋ ወደ በረሓ እንድትበር ለሴቲቱ ሁለት የታላቁ ንሥር ክንፎች ተሰጣት።'),
  ('913fa9df-66ac-5a8a-a6dc-690524d93fba', 'b75d73ee-faa1-5dba-abb5-c71b7d51d601', 'b2d2d368-f187-5aea-a019-a28b811839af', 13, 15, 'እባቡም ሴቲቱ በወንዝ እንድትወሰድ ሊያደርግ ወንዝ የሚያህልን ውሃ ከአፉ በስተ ኋላዋ አፈሰሰ።'),
  ('50ff29db-4d1f-512c-a5db-8671739b8071', 'b75d73ee-faa1-5dba-abb5-c71b7d51d601', 'b2d2d368-f187-5aea-a019-a28b811839af', 14, 16, 'ምድሪቱም ሴቲቱን ረዳቻት፤ ምድሪቱም አፍዋን ከፍታ ዘንዶው ከአፉ ያፈሰሰውን ወንዝ ዋጠችው።'),
  ('cbdabe6e-3286-549f-af97-306bbe7aef55', 'b75d73ee-faa1-5dba-abb5-c71b7d51d601', 'b2d2d368-f187-5aea-a019-a28b811839af', 15, 17, 'ዘንዶውም በሴቲቱ ላይ ተቈጥቶ የእግዚአብሔርን ትእዛዛት የሚጠብቁትን የኢየሱስም ምስክር ያላቸውን ከዘርዋ የቀሩትን ሊዋጋ ሄደ፤'),
  ('f19644fe-b6e9-5bdc-a9ff-592686fe470a', 'b75d73ee-faa1-5dba-abb5-c71b7d51d601', 'b2d2d368-f187-5aea-a019-a28b811839af', 16, 18, 'በባሕርም አሸዋ ላይ ቆመ።'),
  ('794f323f-0022-5055-a4a2-f68925f9441f', '96a40aa1-b864-565c-a544-b9b63565622b', 'e3757379-e5d1-5fb5-a8f9-ab44d04abc58', 1, 1, 'አንድም አውሬ ከባሕር ሲወጣ አየሁ፤ ዐሥር ቀንዶችና ሰባት ራሶች ነበሩት፤ በቀንዶቹም ላይ ዐሥር ዘውዶች በራሶቹም ላይ የስድብ ስም ነበረ።'),
  ('8291b77a-451f-520f-ae4f-6c2274468819', '96a40aa1-b864-565c-a544-b9b63565622b', 'e3757379-e5d1-5fb5-a8f9-ab44d04abc58', 2, 2, 'ያየሁትም አውሬ ነብር ይመስል ነበር፤ እግሮቹም እንደ ድብ እግሮች፥ አፉም እንደ አንበሳ አፍ ነበሩ። ዘንዶውም ኀይሉንና ዙፋኑን ትልቅም ሥልጣን ሰጠው።'),
  ('40f10018-ea0b-51a8-a42a-4d721ba2bc38', '96a40aa1-b864-565c-a544-b9b63565622b', 'e3757379-e5d1-5fb5-a8f9-ab44d04abc58', 3, 3, 'ከራሶቹም ለሞት እንደ ታረደ ሆኖ አንዱን አየሁ፤ ለሞቱ የሆነውም ቍስል ተፈወሰ። ምድርም ሁሉ አውሬውን እየተከተለ ተደነቀ፤'),
  ('bb166a95-c84c-5300-aad6-e32b70b2116f', '96a40aa1-b864-565c-a544-b9b63565622b', 'e3757379-e5d1-5fb5-a8f9-ab44d04abc58', 4, 4, 'ለዘንዶውም ሰገዱለት፤ ለአውሬው ሥልጣንን ሰጥቶታልና፤ ለአውሬውም “አውሬውን ማን ይመስለዋል? እርሱንስ ሊዋጋ ማን ይችላል?” እያሉ ሰገዱለት።'),
  ('1c359daf-c2fd-5a2f-a2b6-19ddc9c3f215', '96a40aa1-b864-565c-a544-b9b63565622b', 'e3757379-e5d1-5fb5-a8f9-ab44d04abc58', 5, 5, 'ታላቅንም ነገርና ስድብን የሚናገርበት አፍ ተሰጠው፤ በአርባ ሁለት ወርም እንዲሠራ ሥልጣን ተሰጠው።'),
  ('9d6c70e3-5e53-5d2a-a7dc-df83d09ce215', '96a40aa1-b864-565c-a544-b9b63565622b', 'e3757379-e5d1-5fb5-a8f9-ab44d04abc58', 6, 6, 'እግዚአብሔርንም ለመሳደብ ስሙንና ማደሪያውንም በሰማይም የሚያድሩትን ሊሳደብ አፉን ከፈተ።'),
  ('0cb41162-f88b-5ea2-a3c6-b282dbbf337a', '96a40aa1-b864-565c-a544-b9b63565622b', 'e3757379-e5d1-5fb5-a8f9-ab44d04abc58', 7, 7, 'ቅዱሳንንም ይዋጋ ዘንድ ድልም ያደርጋቸው ዘንድ ተሰጠው፤ በነገድና በወገንም በቋንቋም በሕዝብም ሁሉ ላይ ሥልጣን ተሰጠው።'),
  ('02f469ad-238e-5acc-a87d-123185049b41', '96a40aa1-b864-565c-a544-b9b63565622b', 'e3757379-e5d1-5fb5-a8f9-ab44d04abc58', 8, 8, 'ከዓለምም ፍጥረት ጀምሮ በታረደው በግ ሕይወት መጽሐፍ ስሞቻቸው ያልተጻፉ በምድር የሚኖሩ ሁሉ ይሰግዱለታል።'),
  ('ae90787f-6093-5dc1-af61-f85287a2df12', '96a40aa1-b864-565c-a544-b9b63565622b', 'e3757379-e5d1-5fb5-a8f9-ab44d04abc58', 9, 9, 'ጆሮ ያለው ቢኖር ይስማ።'),
  ('d21d314a-6be5-53ea-a80d-c8fb888cd55f', '96a40aa1-b864-565c-a544-b9b63565622b', 'e3757379-e5d1-5fb5-a8f9-ab44d04abc58', 10, 10, 'ይማረክ ዘንድ ያለው ማንም ቢኖር ወደ ምርኮነት ይሄዳል፤ በሰይፍ የሚገድል ማንም ቢኖር ራሱ በሰይፍ እንዲገደል ይገባዋል። የቅዱሳን ትዕግሥትና እምነት በዚህ ነው።'),
  ('09d72bb3-2d20-5948-a6df-beed7c4cb8de', '96a40aa1-b864-565c-a544-b9b63565622b', 'e3757379-e5d1-5fb5-a8f9-ab44d04abc58', 11, 11, 'ሌላም አውሬ ከምድር ሲወጣ አየሁ፤ የበግ ቀንዶችን የሚመስሉ ሁለት ቀንዶችም ነበሩት እንደ ዘንዶም ይናገር ነበር።'),
  ('d7e8789c-6bbc-50b8-adc4-5c1d14d45d13', '96a40aa1-b864-565c-a544-b9b63565622b', 'e3757379-e5d1-5fb5-a8f9-ab44d04abc58', 12, 12, 'በፊተኛውም አውሬ ሥልጣን በእርሱ ፊት ሁሉን ያደርጋል። ለሞቱ የሆነውም ቍስል ተፈወሰለት፤ ለፊተኛው አውሬ ምድርና በእርሱ የሚኖሩት እንዲሰግዱለት ያደርጋል።'),
  ('ca15c789-90f5-50be-a969-85f7a1bef4c5', '96a40aa1-b864-565c-a544-b9b63565622b', 'e3757379-e5d1-5fb5-a8f9-ab44d04abc58', 13, 13, 'እሳትንም እንኳ ከሰማይ ወደ ምድር በሰው ፊት እስኪያወርድ ድረስ ታላላቆችን ምልክቶች ያደርጋል።'),
  ('096bcd77-bf56-5c18-ab6d-d0bb8a6089ad', '96a40aa1-b864-565c-a544-b9b63565622b', 'e3757379-e5d1-5fb5-a8f9-ab44d04abc58', 14, 14, 'በአውሬውም ፊት ያደርግ ዘንድ ከተሰጡት ምልክቶች የተነሣ በምድር የሚኖሩትን ያስታል፤ የሰይፍም ቍስል ለነበረውና በሕይወት ለኖረው ለአውሬው ምስልን እንዲያደርጉ በምድር የሚኖሩትን ይናገራል።'),
  ('f56161ba-4dc8-5d68-aa96-224df01b4086', '96a40aa1-b864-565c-a544-b9b63565622b', 'e3757379-e5d1-5fb5-a8f9-ab44d04abc58', 15, 15, 'የአውሬው ምስል ሊናገር እንኳ ለአውሬውም ምስል የማይሰግዱለትን ሁሉ ሊያስገድላቸው፥ ለአውሬው ምስል ትንፋሽ እንዲሰጠው ተሰጠው።'),
  ('d38f7317-c409-524e-a69a-4a96612a932f', '96a40aa1-b864-565c-a544-b9b63565622b', 'e3757379-e5d1-5fb5-a8f9-ab44d04abc58', 16, 16, 'ታናናሾችና ታላላቆችም ባለጠጋዎችና ድሆችም ጌታዎችና ባሪያዎችም ሁሉ በቀኝ እጃቸው ወይም በግምባራቸው ምልክትን እንዲቀበሉ፥'),
  ('7b3c05fa-f661-59f2-a3bd-ff0def87902a', '96a40aa1-b864-565c-a544-b9b63565622b', 'e3757379-e5d1-5fb5-a8f9-ab44d04abc58', 17, 17, 'የአውሬውም ስም ወይም የስሙ ቍጥር ያለው ምልክት የሌለበት ማንም ሊገዛ ወይም ሊሸጥ እንዳይችል ያደርጋል።'),
  ('71af0f4a-aecc-5acb-a26f-2f2fc6e8d976', '96a40aa1-b864-565c-a544-b9b63565622b', 'e3757379-e5d1-5fb5-a8f9-ab44d04abc58', 18, 18, 'ጥበብ በዚህ አለ። አእምሮ ያለው የአውሬውን ቍጥር ይቍጠረው፤ ቍጥሩ የሰው ቍጥር ነውና፤ ቍጥሩም ስድስት መቶ ስድሳ ስድስት ነው።'),
  ('0dc47a6a-ecdc-5356-aaf3-8d9dcca9529f', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', 'd21f8928-34e0-51c8-a281-32be1949516b', 1, 1, 'አየሁም፤ እነሆም በጉ በጽዮን ተራራ ቆሞ ነበር፤ ከእርሱም ጋር ስሙና የአባቱ ስም በግምባራቸው የተጻፈላቸው መቶ አርባ አራት ሺህ ነበሩ።'),
  ('0ab502e6-6f8c-5d10-abd0-d19ca71ce586', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', 'd21f8928-34e0-51c8-a281-32be1949516b', 2, 2, 'እንደ ብዙ ውሃም ድምፅና እንደ ታላቅ ነጐድጓድ ድምፅ ያለ ከሰማይ ድምፅን ሰማሁ፤ ደርዳሪዎችም በገና እንደሚደረድሩ ያለ ድምፅ ሰማሁ።'),
  ('93efe05e-000b-5013-a177-f3bdd3061508', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', 'd21f8928-34e0-51c8-a281-32be1949516b', 3, 3, 'በዙፋኑም ፊት በአራቱም እንስሶችና በሽማግሌዎቹ ፊት አዲስ ቅኔ ዘመሩ፤ ከምድርም ከተዋጁት ከመቶ አርባ አራት ሺህ በቀር ያን ቅኔ ሊማር ለማንም አልተቻለውም።'),
  ('1825b3e8-58f9-5a27-a71e-fcd9b63d683d', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', 'd21f8928-34e0-51c8-a281-32be1949516b', 4, 4, 'ከሴቶች ጋር ያልረከሱ እነዚህ ናቸው፤ ድንግሎች ናቸውና። በጉ ወደሚሄድበት የሚከተሉት እነዚህ ናቸው። ለእግዚአብሔርና ለበጉ በኵራት እንዲሆኑ ከሰዎች የተዋጁ እነዚህ ናቸው።'),
  ('af5589e9-853a-5609-a781-8afc7eb3a6f7', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', 'd21f8928-34e0-51c8-a281-32be1949516b', 5, 5, 'በአፋቸውም ውሸት አልተገኘም፤ ነውር የለባቸውም።'),
  ('e9f91123-ddb9-5b01-adb7-057ab6f6720e', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', '2c95e6cb-0a94-5259-a82d-af45ab5d86dd', 1, 6, 'በምድርም ለሚኖሩ ለሕዝብም ለነገድም ለቋንቋም ለወገንም ሁሉ ይሰብክ ዘንድ የዘላለም ወንጌል ያለው ሌላ መልአክ ከሰማይ መካከል ሲበር አየሁ፤'),
  ('8dc1322d-0898-5855-aa5b-b8fdaec64601', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', '2c95e6cb-0a94-5259-a82d-af45ab5d86dd', 2, 7, 'በታላቅ ድምፅም “የፍርዱ ሰዓት ደርሶአልና እግዚአብሔርን ፍሩ፤ ክብርንም ስጡት፤ ሰማይንና ምድርንም ባሕርንም የውሃንም ምንጮች ለሠራው ስገዱለት፤” አለ።'),
  ('c820f4e3-52ab-5825-aeb5-62fa3e52e826', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', '2c95e6cb-0a94-5259-a82d-af45ab5d86dd', 3, 8, 'ሌላም ሁለተኛ መልአክ “አሕዛብን ሁሉ የዝሙትዋን ቍጣ ወይን ጠጅ ያጠጣች ታላቂቱ ባቢሎን ወደቀች! ወደቀች!” እያለ ተከተለው።'),
  ('22a3c10f-a5d1-55f6-a584-8ec148337852', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', '2c95e6cb-0a94-5259-a82d-af45ab5d86dd', 4, 9, 'ሦስተኛም መልአክ በታላቅ ድምፅ እንዲህ እያለ ተከተላቸው፤ “ለአውሬውና ለምስሉ የሚሰግድ በግምባሩም ወይም በእጁ ምልክቱን የሚቀበል ማንም ቢኖር፥'),
  ('bec69e3a-fac6-5e58-a206-bfa4bd38ac77', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', '2c95e6cb-0a94-5259-a82d-af45ab5d86dd', 5, 10, 'እርሱ ደግሞ በቍጣው ጽዋ ሳይቀላቅል ከተዘጋጀው ከእግዚአብሔር ቍጣ ወይን ጠጅ ይጠጣል፤ በቅዱሳንም መላእክትና በበጉ ፊት በእሳትና በዲን ይሰቃያል።'),
  ('03b276df-c40c-570b-a5ed-1e9425e063e9', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', '2c95e6cb-0a94-5259-a82d-af45ab5d86dd', 6, 11, 'የሥቃያቸውም ጢስ ለዘላለም እስከ ዘላለም ድረስ ይወጣል፤ ለአውሬውና ለምስሉም የሚሰግዱ የስሙንም ምልክት የሚቀበል ሁሉ ቀንና ሌሊት ዕረፍት የላቸውም።”'),
  ('96d96c15-9a52-59b5-a342-91da650e322a', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', '2c95e6cb-0a94-5259-a82d-af45ab5d86dd', 7, 12, 'የእግዚአብሔርን ትእዛዛት የሚጠብቁት ኢየሱስንም በማመን የሚጸኑት ቅዱሳን ትዕግሥታቸው በዚህ ነው።'),
  ('46133b05-bc7e-5a76-a010-dbafd9815f84', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', '2c95e6cb-0a94-5259-a82d-af45ab5d86dd', 8, 13, 'ከሰማይም እንዲህ የሚል ድምፅ ሰማሁ። “ይህንን ጻፍ፡ ከእንግዲህ ወዲህ በጌታ የሚሞቱ ሙታን ብፁዓን ናቸው።” መንፈስም “አዎን! ከድካማቸው ያርፉ ዘንድ፥ ሥራቸውም ይከተላቸዋል፤” ይላል።'),
  ('865fb05e-2608-56ac-a4bd-00571fcb1045', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', '62279e72-1c7d-5a5f-a258-9be1515f9f96', 1, 14, 'አየሁም፤ እነሆም ነጭ ደመና በደመናውም ላይ የሰውን ልጅ የሚመስል ተቀምጦአል፤ በራሱም ላይ የወርቅ አክሊል በእጁም ስለታም ማጭድ ነበረው።'),
  ('8a2626f8-24ae-5d9e-a3aa-516cd566472e', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', '62279e72-1c7d-5a5f-a258-9be1515f9f96', 2, 15, 'ሌላ መልአክም ከመቅደሱ ወጥቶ በደመናው ላይ ለተቀመጠው “የማጨድ ሰዓት ስለ ደረሰ ማጭድህን ስደድና እጨድ፤ የምድሪቱ መከር ጠውልጓልና፤” ብሎ በታላቅ ድምፅ ጮኸ።'),
  ('10108be0-f93d-5a92-a798-09a331a912f6', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', '62279e72-1c7d-5a5f-a258-9be1515f9f96', 3, 16, 'በደመናውም ላይ የተቀመጠው ማጭዱን ወደ ምድር ጣለው፤ ምድርም ታጨደች።'),
  ('33304151-8836-575e-a161-dafc9839b594', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', '62279e72-1c7d-5a5f-a258-9be1515f9f96', 4, 17, 'ሌላ መልአክም በሰማይ ካለው መቅደስ ወጣ፤ እርሱም ደግሞ ስለታም ማጭድ ነበረው።'),
  ('0d96748f-46f1-5c3c-a0c6-dedf343104b3', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', '62279e72-1c7d-5a5f-a258-9be1515f9f96', 5, 18, 'በእሳትም ላይ ሥልጣን ያለው ሌላ መልአክ ከመሠዊያው ወጥቶ ስለታም ማጭድ ያለውን “ዘለላዎቹ ፈጽመው በስለዋልና ስለታሙን ማጭድህን ስደድና በምድር ያለውን የወይን ዛፍ ዘለላዎች ቍረጥ፤” ብሎ በታላቅ ድምፅ ጠራ።'),
  ('08a39919-c0ad-50b8-a84c-e8f87d2c44ed', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', '62279e72-1c7d-5a5f-a258-9be1515f9f96', 6, 19, 'መልአኩም ማጭዱን ወደ ምድር ጣለው፤ በምድርም ካለው ከወይን ዛፍ ቈርጦ ወደ ታላቁ ወደ እግዚአብሔር ቍጣ መጥመቂያ ጣለ።'),
  ('ce0ee4fe-acd2-534b-ac72-a18c47bee31a', 'fe929a58-fe27-500f-a6bb-c816934d3dfe', '62279e72-1c7d-5a5f-a258-9be1515f9f96', 7, 20, 'የወይኑም መጥመቂያ ከከተማ ውጭ ተረገጠ፤ እስከ ፈረሶች ልጓምም የሚደርስ ደም ርቀቱ ሺህ ስድስት መቶ ምዕራፍ ሆኖ ከመጥመቂያው ወጣ።'),
  ('13c41896-d858-5796-ab0a-a188ec0ec356', '6e16fc82-4b30-50e9-a956-02cf7bc4dbab', '10b9d354-45e3-53cd-a762-ffb793f2b65a', 1, 1, 'ሌላም ታላቅና ድንቅ ምልክት በሰማይ አየሁ፤ የእግዚአብሔር ቍጣ በእነርሱ ስለሚፈጸም ኋለኛዎቹን ሰባት መቅሠፍቶች የያዙ ሰባት መላእክት ታዩ።'),
  ('40669b73-6deb-5df0-a00f-a59cf4b79a31', '6e16fc82-4b30-50e9-a956-02cf7bc4dbab', '10b9d354-45e3-53cd-a762-ffb793f2b65a', 2, 2, 'በእሳትም የተቀላቀለውን የብርጭቆ ባሕር የሚመስለውን አየሁ፤ በአውሬውና በምስሉም በስሙም ቍጥር ላይ ድል ነሥተው የነበሩት የእግዚአብሔርን በገና ይዘው በብርጭቆ ባሕር ላይ ሲቆሙ አየሁ።'),
  ('7e165995-3e4f-5a07-a0a9-095e4bb3a176', '6e16fc82-4b30-50e9-a956-02cf7bc4dbab', '10b9d354-45e3-53cd-a762-ffb793f2b65a', 3, 5, 'ከዚህም በኋላ አየሁ፤ የምስክርም ድንኳን መቅደስ በሰማይ ተከፈተ፤'),
  ('dd75f2c1-00be-5226-afc6-bf1691c11508', '6e16fc82-4b30-50e9-a956-02cf7bc4dbab', '10b9d354-45e3-53cd-a762-ffb793f2b65a', 4, 6, 'ሰባቱንም መቅሠፍት የያዙ ሰባቱ መላእክት ከመቅደሱ ወጡ፤ ከተልባ እግርም የተሠራ ጥሩ የጌጥ ልብስ ለበሱ፤ ደረታቸውንም በወርቅ መታጠቂያ ታጠቁ።'),
  ('df5e62b3-5f13-5ba9-af7c-000fc6315f46', '6e16fc82-4b30-50e9-a956-02cf7bc4dbab', '10b9d354-45e3-53cd-a762-ffb793f2b65a', 5, 7, 'ከአራቱም እንስሶች አንዱ ከዘላለም እስከ ዘላለም ድረስ የሚኖር የእግዚአሔር ቍጣ የሞላባቸውን ሰባት የወርቅ ጽዋዎች ለሰባቱ መላእክት ሰጣቸው።'),
  ('f5611dca-9793-579e-a5aa-4ce8bab37cf2', '6e16fc82-4b30-50e9-a956-02cf7bc4dbab', '10b9d354-45e3-53cd-a762-ffb793f2b65a', 6, 8, 'ከእግዚአብሔርም ክብርና ከኀይሉ ጢስ በመቅደሱ ሞላበት፤ የሰባቱ መላእክት ሰባቱ መቅሰፍት እስኪፈጸሙ ድረስ አንድ እንኳ ወደ መቅደሱ ይገባ ዘንድ አልቻለም።'),
  ('a0e0ed08-5d40-5665-a0f0-7261c247ad42', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 1, 1, 'ለሰባቱም መላእክት “ሄዳችሁ የእግዚአብሔርን ቁጣ ጽዋዎች በምድር ውስጥ አፍስሱ፤” የሚል ታላቅ ድምፅ ከመቅደሱ ሰማሁ።'),
  ('d346e2c2-1659-59c9-a393-1603f9baa1e8', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 2, 2, 'ፊተኛውም ሄዶ ጽዋውን በምድር ውስጥ አፈሰሰ፤ የአውሬውም ምልክት ባለባቸው ለምስሉም በሚሰግዱ ሰዎች ክፉኛ የሚነዘንዝ ቍስል ሆነባቸው።'),
  ('7dca5c1a-cb33-59c7-ad71-ce1d45ceb53a', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 3, 3, 'ሁለተኛውም ጽዋውን በባሕር ውስጥ አፈሰሰ፤ እንደ ሞተም ሰው ደም ሆነ፤ በባሕርም ከሚኖሩት ሕይወት ያለበት ነፍስ ሁሉ ሞተ።'),
  ('3b2ea1c7-887b-57b7-a57d-2585cbbfb89b', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 4, 4, 'ሦስተኛውም ጽዋውን በወንዞችና በውሃ ምንጮች ውስጥ አፈሰሰ፤ እነርሱም ደም ሆኑ።'),
  ('c6eb3b84-f10c-5c61-a9cf-9bdce96324af', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 5, 5, 'የውሃውም መልአክ “ያለህና የነበርህ ጌታ ሆይ! ቅዱስ ሆይ! እንዲህ ስለፈረድህ ጻድቅ ነህ፤'),
  ('913a1f65-40b1-584f-a506-b49ad5c0cff4', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 6, 6, 'የቅዱሳንንና የነቢያትን ደም ስላፈሰሱ ደምን ደግሞ አጠጥተሃቸዋል፤ የሚገባቸው ነውና፤” ብሎ ሲናገር ሰማሁ።'),
  ('9cfb7eb8-63db-5675-a266-5041597b09f7', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 7, 7, 'ከመሰዊያውም “አዎን፤ ሁሉን የምትገዛ ጌታ አምላክ ሆይ! ፍርዶችህ እውነትና ጽድቅ ናቸው፤” ብሎ ሲናገር ሰማሁ።'),
  ('a50d50a0-6073-55b0-a0a1-dcf0bcc62f94', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 8, 8, 'አራተኛውም ጽዋውን በፀሐይ ላይ አፈሰሰ፤ ሰዎችንም በእሳት ልታቃጥል ተሰጣት።'),
  ('e4dc7882-c7ed-51ed-ade1-86b5154422a1', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 9, 9, 'ሰዎችም በታላቅ ትኵሳት ተቃጠሉ፤ በነዚህም መቅሠፍቶች ላይ ሥልጣን ያለውን የእግዚአብሔርን ስም ተሳደቡ፤ ክብርንም እንዲሰጡት ንስሓ አልገቡም።'),
  ('7b7c5552-c3df-5c48-a03c-20f83cdf2871', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 10, 10, 'አምስተኛውም ጽዋውን በአውሬው ዙፋን ላይ አፈሰሰ፤ መንግሥቱም ጨለማ ሆነች፤ ከስቃይም የተነሣ መላሶቻቸውን ያኝኩ ነበር፤'),
  ('5e838bcb-c37f-5eec-a8a1-3e75176a4412', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 11, 11, 'ከስቃያቸውና ከቍስላቸውም የተነሣ የሰማይን አምላክ ተሳደቡ፤ ከሥራቸውም ንስሓ አልገቡም።'),
  ('74c3f1af-00a0-5d50-ab27-a6bf53213442', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 12, 12, 'ስድስተኛውም ጽዋውን በታላቁ ወንዝ በኤፍራጥስ ላይ አፈሰሰ፤ ከፀሐይም መውጫ ለሚመጡ ነገሥታት መንገድ እንዲሰናዳላቸው ውሃው ደረቀ።'),
  ('6e58468f-45e9-5926-ae57-7d86ee75513d', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 13, 13, 'ከዘንዶውም አፍና ከአውሬው አፍ ከሐሰተኛውም ነቢይ አፍ ጓጕንቸሮች የሚመስሉ ሦስት ርኵሳን መናፍስት ሲወጡ አየሁ፤'),
  ('1c1346c2-e0bc-579d-a622-beb854cadbf7', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 14, 14, 'ምልክት እያደረጉ የአጋንንት መናፍስት ናቸውና፥ በታላቁም ሁሉን በሚገዛ በእግዚአብሔር ቀን ወደሚሆነው ጦር እንዲያስከትቱአቸው ወደ ዓለም ሁሉ ነገሥታት ይወጣሉ።'),
  ('78fb8ccf-e1a9-5290-a8d3-5c4c3d58d4c4', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 15, 15, '“እነሆ እንደ ሌባ ሆኜ እመጣለሁ፤ ራቁቱን እንዳይሄድ ኀፍረቱንም እንዳያዩ ነቅቶ ልብሱን የሚጠብቅ ብፁዕ ነው።”'),
  ('5e136fdc-dbe6-5aea-a177-12f454a63f85', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 16, 16, 'በዕብራይስጥም አርማጌዶን ወደሚባል ስፍራ እስከተቱአቸው።'),
  ('23dbb3cc-7f51-5f26-a61a-f48c6fd40137', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 17, 17, 'ሰባተኛውም ጽዋውን በአየር ውስጥ አፈሰሰ፤ ከመቅደሱም ውስጥ “ተፈጽሞአል!” የሚል ታላቅ ድምጽ ከዙፋኑ ወጣ።'),
  ('d92be64c-e32a-5ea3-aa7a-a70710805501', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 18, 18, 'መብረቅና ድምጽም ነጎድጓድም ሆኑ፤ ትልቅም የምድር መናወጥ ሆነ፤ ሰው በምድር ከተፈጠረ ጀምሮ እንዲህ ያለ ታላቅ መናውጥ ከቶ አልነበረም፤ ከሁሉ በለጠ።'),
  ('1c1f504d-b657-57e2-ae59-f9827c123944', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 19, 19, 'ታላቂቱም ከተማ በሦስት ተከፋፈለች፤ የአሕዛብም ከተማዎች ወደቁ። ታላቂቱም ባቢሎን የብርቱ ቍጣው ወይን ጠጅ የሞላበትን ጽዋ እንዲሰጣት በእግዚአብሔር ፊት ታሰበች።'),
  ('bac6aa4a-a39d-53f4-ab6b-6ab0203f6a38', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 20, 20, 'ደሴቶችም ሁሉ ሸሹ፤ ተራራዎችም አልተገኙም።'),
  ('33a4a689-2166-5612-af30-ebd96f17dd84', '1082c020-f7d0-5661-a94c-9f1545677390', 'cd1b7e3b-5aa9-58a2-ae18-839c16359f04', 21, 21, 'በሚዛንም አንድ ታላንት የሚያህል ታላቅ በረዶ በሰዎች ላይ ከሰማይ ወረደባቸው፤ ሰዎቹም ከበረዶው መቅሰፍት የተነሣ እግዚአብሔርን ተሳደቡ፤ መቅሰፍቱ እጅግ ታላቅ ነውና።'),
  ('18194de9-a4ff-5365-a443-8840ff1bf0a8', '70c67db3-f30d-5b9c-a2a0-ad1daceeacd4', 'a628e132-04f3-5e28-a8c0-1bbb082fee76', 1, 1, 'ሰባቱንም ጽዋዎች ከያዙ ከሰባቱ መላእክት አንዱ መጥቶ “ና፤ በብዙም ውሃዎች ላይ የተቀመጠችውን የታላቂቱን ጋለሞታ ፍርድ አሳይሃለሁ፤'),
  ('6b6cd005-df5a-577f-a777-b6ee4243997b', '70c67db3-f30d-5b9c-a2a0-ad1daceeacd4', 'a628e132-04f3-5e28-a8c0-1bbb082fee76', 2, 2, 'የምድርም ነገሥታት ከእርስዋ ጋር ሴሰኑ፤ በምድርም የሚኖሩ ከዝሙትዋ ወይን ጠጅ ሰከሩ፤” ብሎ ተናገረኝ።'),
  ('7f611621-12d5-5c55-adfd-a9be9b7122a6', '70c67db3-f30d-5b9c-a2a0-ad1daceeacd4', 'a628e132-04f3-5e28-a8c0-1bbb082fee76', 3, 3, 'በመንፈስም ወደ በረሓ ወሰደኝ፤ የስድብም ስሞች በሞሉበት፥ ሰባት ራሶችና ዐሥር ቀንዶችም ባሉበት በቀይ አውሬ ላይ አንዲት ሴት ተቀምጣ አየሁ።'),
  ('4bdbeb89-6055-5092-a7e6-0134574ee1f9', '70c67db3-f30d-5b9c-a2a0-ad1daceeacd4', 'a628e132-04f3-5e28-a8c0-1bbb082fee76', 4, 4, 'ሴቲቱም በቀይና በሐምራዊ ልብስ ተጐናጽፋ በወርቅና በከበሩ ድንጋዮች በዕንቈችም ተሸልማ ነበር፤ በእጅዋም የሚያስጸይፍ ነገር የዝሙትዋም ርኵሰት የሞላባትን የወርቅ ጽዋ ያዘች፤'),
  ('c5db69c7-cd9f-5f84-abde-b586e3c0ada0', '70c67db3-f30d-5b9c-a2a0-ad1daceeacd4', 'a628e132-04f3-5e28-a8c0-1bbb082fee76', 5, 5, 'በግምባርዋም ምስጢር የሆነ ስም “ታላቂቱ ባቢሎን፥ የጋለሞታዎችና የምድር ርኵሰት እናት” ተብሎ ተጻፈ።'),
  ('7b88d166-dc02-5aa4-ab02-5c830f905637', '70c67db3-f30d-5b9c-a2a0-ad1daceeacd4', 'a628e132-04f3-5e28-a8c0-1bbb082fee76', 6, 6, 'ሴቲቱም በቅዱሳን ደምና በኢየሱስ ምስክሮች ደም ሰክራ አየኋት።'),
  ('68b38b87-e060-5797-af08-d9b856997ed1', '70c67db3-f30d-5b9c-a2a0-ad1daceeacd4', 'a628e132-04f3-5e28-a8c0-1bbb082fee76', 7, 7, 'መልአኩም አለኝ “የምትደነቅ ስለ ምንድር ነው? የሴቲቱን ምስጢርና የሚሸከማትን፥ ሰባት ራሶችና ዐስር ቀንዶች ያሉትን የአውሬውን ምስጢር እኔ እነግርሃለሁ።'),
  ('87dd7c32-c21c-5434-af45-8da53fda03f0', '70c67db3-f30d-5b9c-a2a0-ad1daceeacd4', 'a628e132-04f3-5e28-a8c0-1bbb082fee76', 8, 8, 'ያየኸው አውሬ አስቀድሞ ነበረ፤ አሁንም የለም፤ ከጥልቁም ይወጣ ዘንድ አለው፤ ወደ ጥፋትም ይሄዳል፤ ስሞቻቸውም ከዓለም ፍጥረት ጀምሮ በሕይወት መጽሐፍ ያልተጻፉ በምድር የሚኖሩ አውሬው አስቀድሞ እንደነበረ አሁንም እንደሌለ፥ ነገር ግን እንዳለ ሲያዩ ያደንቃሉ።'),
  ('9409ac67-6748-5298-a3f3-456ebe107157', '70c67db3-f30d-5b9c-a2a0-ad1daceeacd4', 'a628e132-04f3-5e28-a8c0-1bbb082fee76', 9, 9, 'ጥበብ ያለው አእምሮ በዚህ ነው። ሰባቱ ራሶች ሴቲቱ የተቀመጠችባቸው ሰባት ተራራዎች ናቸው፤'),
  ('4e458da4-ffa4-54b7-a083-7a9423c125e7', '70c67db3-f30d-5b9c-a2a0-ad1daceeacd4', 'a628e132-04f3-5e28-a8c0-1bbb082fee76', 10, 10, 'ሰባት ነገሥታት ደግሞ ናቸው፤ አምስቱ ወድቀዋል፤ አንዱም አለ፤ የቀረውም ገና አልመጣም፤ ሲመጣም፥ ጥቂት ጊዜ ሊቆይ ይገባዋል።'),
  ('e3f585fe-a5de-50cd-a3cf-e15d350d256e', '70c67db3-f30d-5b9c-a2a0-ad1daceeacd4', 'a628e132-04f3-5e28-a8c0-1bbb082fee76', 11, 11, 'የነበረውና የሌለውም አውሬ ራሱ ደግሞ ስምንተኛው ነው፤ ከሰባቱም አንዱ ነው፤ ወደ ጥፋትም ይሄዳል።'),
  ('8486376f-4467-5e49-a73c-f70ccd696096', '70c67db3-f30d-5b9c-a2a0-ad1daceeacd4', 'a628e132-04f3-5e28-a8c0-1bbb082fee76', 12, 12, 'ያየሃቸውም ዐሥሩ ቀንዶች ገና መንግሥትን ያልተቀበሉ ዐሥር ነገሥታት ናቸው፤ ዳሩ ግን ከአውሬው ጋር ለአንድ ሰዓት እንደ ነገሥታት ሥልጣንን ይቀበላሉ።'),
  ('bee3c977-446e-5a80-a4cc-05e6523e7ad8', '70c67db3-f30d-5b9c-a2a0-ad1daceeacd4', 'a628e132-04f3-5e28-a8c0-1bbb082fee76', 13, 13, 'እነዚህ አንድ አሳብ አላቸው፤ ኀይላቸውንና ሥልጣናቸውንም ለአውሬው ይሰጣሉ።'),
  ('e9bcf5bd-cf9e-5ca8-a23d-53eacde1a4f0', '70c67db3-f30d-5b9c-a2a0-ad1daceeacd4', 'a628e132-04f3-5e28-a8c0-1bbb082fee76', 14, 14, 'እነዚህ በጉን ይወጋሉ፤ በጉም የጌቶች ጌታና የነገሥታት ንጉሥ ስለ ሆነ እነርሱን ድል ይነሣል፤ ከእርሱም ጋር ያሉ የተጠሩና የተመረጡ የታመኑም ደግሞ ድል ይነሣሉ።”'),
  ('b7b654e3-ed70-5b42-a279-2a5378d18024', '70c67db3-f30d-5b9c-a2a0-ad1daceeacd4', 'a628e132-04f3-5e28-a8c0-1bbb082fee76', 15, 15, 'አለኝም “ጋለሞታይቱ የተቀመጠችባቸው ያየሃቸው ውሃዎች፥ ወገኖችና ብዙ ሰዎች አሕዛብም ቋንቋዎችም ናቸው።'),
  ('b3b2e2f1-7088-5ede-a061-c7edf53f658d', '70c67db3-f30d-5b9c-a2a0-ad1daceeacd4', 'a628e132-04f3-5e28-a8c0-1bbb082fee76', 16, 16, 'ያየሃቸውም ዐሥር ቀንዶችና አውሬው ጋለሞታይቱን ይጣላሉ፤ ባዶዋንና ራቁትዋንም ያደርጓታል፤ ሥጋዋንም ይበላሉ፤ በእሳትም ያቃጥሉአታል።'),
  ('9e7bb021-a4ee-534b-a8d3-fab61b99488f', '70c67db3-f30d-5b9c-a2a0-ad1daceeacd4', 'a628e132-04f3-5e28-a8c0-1bbb082fee76', 17, 17, 'እግዚአብሔር አሳቡን እንዲያደርጉ አንድንም አሳብ እንዲያደርጉ የእግዚአብሔርም ቃል እስኪፈጸም ድረስ መንግሥታቸውን ለአውሬው እንዲሰጡ በልባቸው አገብቶአልና።'),
  ('447ab95a-2a13-55c4-afbb-535083d67aa2', '70c67db3-f30d-5b9c-a2a0-ad1daceeacd4', 'a628e132-04f3-5e28-a8c0-1bbb082fee76', 18, 18, 'ያየሃትም ሴት በምድር ነገሥታት ላይ የምትነግሥ ታላቂቱ ከተማ ናት።”'),
  ('a200d8e3-fa9c-5ca5-a08d-7c2b85666171', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 1, 1, 'ከዚህ በኋላ ታላቅ ስልጣን ያለው ሌላ መልአክ ከሰማይ ሲወርድ አየሁ፤ ከክብሩም የተነሣ ምድር በራች።'),
  ('46907dd4-67c0-5eb6-a917-046289a1049a', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 2, 2, 'በብርቱም ድምፅ “ታላቂቱ ባቢሎን ወደቀች! ወደቀች! የአጋንንትም ማደሪያ ሆነች፤ የርኵሳንም መናፍስት ሁሉ መጠጊያ የርኵሳንና የተጠሉም ወፎች ሁሉ መጠጊያ ሆነች፤'),
  ('a9ac1862-59a3-52f1-a15a-87ba34e949e2', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 3, 3, 'አሕዛብ ሁሉ ከዝሙትዋ ቍጣ ወይን ጠጅ የተነሣ ወድቀዋልና፤ የምድርም ነገሥታት ከእርስዋ ጋር ሴሰኑ፤ የምድርም ነጋዴዎች ከቅምጥልነትዋ ኀይል የተነሣ ባለጠጋዎች ሆኑ፤” ብሎ ጮኸ።'),
  ('291e2bbd-389c-5386-a6ee-7b5baa383ec8', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 4, 4, 'ከሰማይም ሌላ ድምፅ እንዲህ ሲል ሰማሁ'),
  ('d332495c-0b4d-58ab-aafc-6ae5d0a8d065', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 5, 9, 'ከእርስዋም ጋር የሴሰኑና የተቀማጠሉ የምድር ነገሥታት የመቃጠልዋን ጢስ ሲያዩ ስለ እርስዋ እየጮሁ እያሉ ያለቅሳሉ፤'),
  ('10248565-a44f-50ca-aeb6-ee4377459a5b', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 6, 10, 'ሥቃይዋንም ከመፍራት የተነሣ በሩቅ ቆመው “አንቺ ታላቂቱ ከተማ! ብርቱይቱ ከተማ ባቢሎን! ወዮልሽ! ወዮልሽ! በአንድ ሰዓት ፍርድሽ ደርሶአልና፤” እያሉ ይናገራሉ።'),
  ('81f02b3c-dd6a-5b50-a2c5-1990d243c32f', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 7, 11, 'የመርከባቸውንም ጭነት ከእንግዲህ ወዲህ የሚገዛ የለምና የምድር ነጋዴዎች ያለቅሱላታል፤ ያዝኑላትማል፤'),
  ('c07d263d-99d6-5ce1-a035-383754f2bf35', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 8, 12, 'ጭነትም ወርቅና ብር፥ የከበረም ድንጋይ ዕንቁም፥ ቀጭንም ተልባ እግር፥ ቀይም ሐር፥ ሐምራዊም ልብስ፥ የሚሸትም እንጨት ሁሉ፥ ከዝሆን ጥርስም የተሠራ ዕቃ ሁሉ፥ እጅግም ከከበረ እንጨት፥ ከናስም ከብረትም ከዕብነ በረድም የተሠራ ዕቃ ሁሉ፥'),
  ('13409d4b-4682-5596-a3d5-8a0f6eb3994d', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 9, 13, 'ቀረፋም፥ ቅመምም፥ የሚቃጠልም ሽቱ፥ ቅባትም፥ ዕጣንም፥ የወይን ጠጅም፥ ዘይትም፥ የተሰለቀ ዱቄትም፥ ስንዴም፥ ከብትም፥ በግም፥ ፈረስም፥ ሰረገላም፥ ባሪያዎችም፥ የሰዎችም ነፍሳት ነው።'),
  ('29d2528b-3263-5853-ae1e-20abc166dce0', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 10, 14, '“ነፍስሽም የጎመጀችው ፍሬ ከአንቺ ዘንድ አልፎአል፤ የሚቀማጠልና የሚያጌጥም ነገር ሁሉ ጠፍቶብሻል፤ ሰዎችም ከእንግዲህ ወዲህ ከቶ አያገኙአቸውም።”'),
  ('d7d2f56d-6e60-5809-a2b2-cc526bba4808', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 11, 15, 'እነዚህን የነገዱ በእርስዋም ባለ ጠጋዎች የሆኑት እያለቀሱና እያዘኑ'),
  ('685a6e22-cb4f-5d5f-a541-e369948815f7', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 12, 16, '“በቀጭን ተልባ እግርና በቀይ ሐምራዊም ልብስ ለተጐናጸፈች በወርቅና በከበረ ድንጋይም በዕንቁም ለተሸለመች ለታላቂቱ ከተማ ወዮላት! ወዮላት! ይህን የሚያህል ታላቅ ባለ ጠግነት በአንድ ሰዓት ጠፍቶአልና፤” እያሉ ስቃይዋን ከመፍራት የተነሣ በሩቅ ይቆማሉ። የመርከብም መሪ ሁሉ በመርከብም ወደ ማናቸውም ስፍራ የሚሄድ ሁሉ መርከበኞችም ከባሕርም የሚጠቀሙ ሁሉ በሩቅ ቆሙ፤'),
  ('2a98bd03-744d-53fa-a411-57191a81f6dd', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 13, 18, 'የመቃጠልዋንም ጢስ ባዩ ጊዜ “ታላቂቱን ከተማ የምትመስላት ምን ከተማ ነበረች?” እያሉ ጮኹ።'),
  ('eb9890d8-1c4f-59ac-a33e-b965f385d7cf', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 14, 19, 'በራሳቸውም ላይ ትቢያ ነስንሰው እያለቀሱና እያዘኑ “በባሕር መርከቦች ያሉአቸውን ሁሉ ከባለ ጠግነትዋ የተነሣ ባለ ጠጋዎች ላደረገች ለታላቂቱ ከተማ ወዮላት! ወዮላት! በአንድ ሰዓት ጠፍታለችና፤” እያሉ ጮኹ።'),
  ('8965df1a-f014-50a1-a047-93c8fdfbe7b4', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 15, 20, '“ሰማይ ሆይ! ቅዱሳን ሐዋርያት ነቢያትም ሆይ! በእርስዋ ላይ ደስ ይበላችሁ፤ እግዚአብሔር ፈርዶላችኋልና።”'),
  ('a618dfdb-7de4-564f-a830-4e0e32acef35', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 16, 21, 'አንድም ብርቱ መልአክ ትልቅን ወፍጮ የሚመስልን ድንጋይ አንሥቶ እንዲህ ሲል ወደ ባሕር ወረወረው “ታላቂቱ ከተማ ባቢሎን እንዲህ ተገፍታ ትወድቃለች፤ ከእንግዲህም ወዲህ ከቶ አትገኝም።'),
  ('7f2603b0-20e2-5453-a2cc-4edba7a7bae7', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 17, 22, 'በገና የሚመቱና የሚዘምሩም ድምፅ እንቢልታንና መለከትንም የሚነፉ ድምፅ ከእንግዲህ ወዲህ በአንቺ ውስጥ ከቶ አይሰማም፤ የእጅ ጥበብም ሁሉ አንድ ብልሃተኛ እንኳ ከእንግዲህ ወዲህ በአንቺ ውስጥ ከቶ አይገኝም፤ የወፍጮ ድምጽም ከእንግዲህ ወዲህ በአንቺ ውስጥ ከቶ አይሰማም፤'),
  ('e7c83dab-9335-5e73-ab77-b2ae433d0437', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 18, 23, 'የመብራትም ብርሃን ከእንግዲህ ወዲህ በአንቺ ውስጥ ከቶ አይበራም፤ የሙሽራና የሙሽራይቱም ድምጽ ከእንግዲህ ወዲህ በአንቺ ውስጥ ከቶ አይሰማም፤ ነጋዴዎችሽ የምድር መኳንንት ነበሩና፤ በአስማትሽም አሕዛብ ሁሉ ስተዋልና።”'),
  ('24d43419-2433-580b-ad6b-ee6947c9fa46', 'e038233f-9731-581f-abea-9bc41ab9ebe2', 'aee83160-421b-589a-a4d6-e1b8649e4b27', 19, 24, 'በእርስዋም ውስጥ የነቢያትና የቅዱሳን ደም በምድርም የታረዱ ሁሉ ደም ተገኘባት።'),
  ('9be3869b-c20a-53ac-afe3-ff4fde4b67dd', '869ae244-c00e-56f8-a014-0495155321fd', '17f9af94-2818-5684-a035-659e8a3d286f', 1, 1, 'ከዚህ በኋላ በሰማይ'),
  ('5080a85f-4116-5a60-a74b-8a764ab9cb5e', '869ae244-c00e-56f8-a014-0495155321fd', 'e1475cbd-2fea-5364-a546-963ed2990105', 1, 5, 'ድምፅም'),
  ('a70e4520-cde8-5d9d-ac0d-de693bfa05a5', '869ae244-c00e-56f8-a014-0495155321fd', 'e1475cbd-2fea-5364-a546-963ed2990105', 2, 9, 'መልአኩም “ወደ በጉ ሰርግ እራት የተጠሩ ብፁዓን ናቸው፤” ብለህ ጻፍ፤ አለኝ። ደግሞም “ይህ የእግዚአብሔር እውነተኛ ቃል ነው፤” አለኝ።'),
  ('c3cfd475-c360-5838-a79b-78113610dfe3', '869ae244-c00e-56f8-a014-0495155321fd', 'e1475cbd-2fea-5364-a546-963ed2990105', 3, 10, 'ልሰግድለትም በእግሩ ፊት ተደፋሁ። እርሱም “እንዳታደርገው ተጠንቀቅ፤ ከአንተ ጋር የኢየሱስም ምስክር ካላቸው ከወንድሞችህ ጋር አብሬ ባሪያ ነኝ፤ ለእግዚአብሔር ስገድ፤ የኢየሱስ ምስክር የትንቢት መንፈስ ነውና፤” አለኝ።'),
  ('f0d1f776-1454-5f97-ad1a-1da9006f7a04', '869ae244-c00e-56f8-a014-0495155321fd', '712875f3-55f6-5736-a746-ef8101c3774e', 1, 11, 'ሰማይም ተከፍቶ አየሁ፤ እነሆም አምባላይ ፈረስ፤ የተቀመጠበትም የታመነና እውነተኛ ይባላል፤ በጽድቅም ይፈርዳል፤ ይዋጋልም።'),
  ('3134f754-2ea6-5c62-a8a4-5d8e2ab06948', '869ae244-c00e-56f8-a014-0495155321fd', '712875f3-55f6-5736-a746-ef8101c3774e', 2, 12, 'ዐይኖቹም እንደ እሳት ነበልባል ናቸው፤ በራሱ ላይም ብዙ ዘውዶች አሉ፤ ከእርሱም በቀር አንድ እንኳ የማያውቀው የተጻፈ ስም አለው፤'),
  ('0f28e53c-5c24-576b-a0ed-f844fddb7212', '869ae244-c00e-56f8-a014-0495155321fd', '712875f3-55f6-5736-a746-ef8101c3774e', 3, 13, 'በደምም የተረጨ ልብስ ተጐናጽፎአል፤ ስሙም የእግዚአብሔር ቃል ተብሎአል።'),
  ('49582177-0a33-5a88-ac8e-a22ade3fed3a', '869ae244-c00e-56f8-a014-0495155321fd', '712875f3-55f6-5736-a746-ef8101c3774e', 4, 14, 'በሰማይም ያሉት ጭፍራዎች ነጭና ጥሩ ቀጭን የተልባ እግር ልብስ ለብሰው በአምባላዮች ፈረሶች ተቀምጠው ይከተሉት ነበር።'),
  ('e8aa6f37-57fc-5347-a8c0-99fa5ff27581', '869ae244-c00e-56f8-a014-0495155321fd', '712875f3-55f6-5736-a746-ef8101c3774e', 5, 15, 'አሕዛብንም ይመታበት ዘንድ ስለታም ሰይፍ ከአፉ ይወጣል፤ እርሱም በብረት በትር ይገዛቸዋል፤ እርሱም ሁሉን የሚገዛ የእግዚአብሔርን የብርቱ ቍጣውን ወይን መጥመቂያ ይረግጣል።'),
  ('abe490f1-fda7-5918-a354-aebad6dba6fb', '869ae244-c00e-56f8-a014-0495155321fd', '712875f3-55f6-5736-a746-ef8101c3774e', 6, 16, 'በልብሱና በጭኑም የተጻፈበት “የነገሥታት ንጉሥና የጌታዎች ጌታ” የሚል ስም አለው።'),
  ('96e47bb4-3c67-5cdf-aa2d-6434bda1abe9', '869ae244-c00e-56f8-a014-0495155321fd', '712875f3-55f6-5736-a746-ef8101c3774e', 7, 17, 'አንድም መልአክ በፀሐይ ውስጥ ቆሞ አየሁ፤ በሰማይም መካከል ለሚበሩ ወፎች ሁሉ “መጥታችሁ የነገሥታትን ሥጋና የሻለቃዎችን ሥጋ የብርቱዎችንም ሥጋ የፈረሶችንም በእነርሱም የተቀመጡትን ሥጋ የጌታዎችንና የባሪያዎችንም የታናናሾችንና የታላላቆችንም ሁሉ ሥጋ እንድትበሉ ወደ ታላቁ ወደ እግዚአብሔር እራት ተከማቹ፤” ብሎ በታላቅ ድምፅ ጮኸ።'),
  ('e1f94f94-e29e-5f24-ad40-9da51abcdde9', '869ae244-c00e-56f8-a014-0495155321fd', '712875f3-55f6-5736-a746-ef8101c3774e', 8, 19, 'በፈረሱም የተቀመጠውን ጭፍራዎቹንም ይወጉ ዘንድ አውሬውና የምድር ነገሥታት ጭፍራዎቻቸውም ተከማችተው አየሁ።'),
  ('624bd6e5-4fbe-51e3-a230-c9a106219c09', '869ae244-c00e-56f8-a014-0495155321fd', '712875f3-55f6-5736-a746-ef8101c3774e', 9, 20, 'አውሬውም ተያዘ፤ በእርሱም ፊት ተአምራትን እያደረገ የአውሬውን ምልክት የተቀበሉትን ለምስሉም የሰገዱትን ያሳተ ሐሰተኛው ነቢይ ከእርሱ ጋር ተያዘ፤ ሁለቱም በሕይወት ሳሉ በዲን ወደሚቃጠል ወደ እሳት ባሕር ተጣሉ።'),
  ('445b425a-e396-5929-a655-627cc24fa618', '869ae244-c00e-56f8-a014-0495155321fd', '712875f3-55f6-5736-a746-ef8101c3774e', 10, 21, 'የቀሩትም በፈረስ ላይ ከተቀመጠው ከአፉ በሚወጣው ሰይፍ ተገደሉ፤ ወፎችም ሁሉ ከሥጋቸው ጠገቡ።'),
  ('8ad7ca30-e53d-515b-ac3d-8aee8c857739', '0c6ca786-6195-5765-ad69-6844bbd8d5c2', 'd99921f2-d8f3-52bb-a547-0a57daac04f4', 1, 1, 'የጥልቁንም መክፈቻና ታላቁን ሰንሰለት በእጁ የያዘ መልአክ ከሰማይ ሲወርድ አየሁ።'),
  ('e5541439-3d8b-56f7-a9a8-cf0f246ba025', '0c6ca786-6195-5765-ad69-6844bbd8d5c2', 'd99921f2-d8f3-52bb-a547-0a57daac04f4', 2, 2, 'የቀደመውንም እባብ ዘንዶውን እርሱም ዲያብሎስና ሰይጣን የተባለውን ያዘው፤'),
  ('c8544691-834f-5afd-ab97-7f5beb66554d', '0c6ca786-6195-5765-ad69-6844bbd8d5c2', 'd99921f2-d8f3-52bb-a547-0a57daac04f4', 3, 3, 'ሺህ ዓመትም አሰረው፤ ወደ ጥልቅም ጣለው፤ አሕዛብንም ወደ ፊት እንዳያስት ሺህ ዓመት እስኪፈጸም ድረስ በእርሱ ላይ ዘግቶ ማኅተም አደረገበት፤ ከዚያም በኋላ ለጥቂት ጊዜ ይፈታ ዘንድ ይገባዋል።'),
  ('b795e56b-0cdc-5747-a3e9-e5d1eaf3fc72', '0c6ca786-6195-5765-ad69-6844bbd8d5c2', 'd99921f2-d8f3-52bb-a547-0a57daac04f4', 4, 4, 'ዙፋኖችንም አየሁ፤ በእነርሱም ላይ ለተቀመጡት ዳኝነት ተሰጣቸው፤ ስለ ኢየሱስም ምስክርና ስለ እግዚአብሔር ቃል ራሶቻቸው የተቈረጡባቸውን ሰዎች ነፍሳት፥ ለአውሬውና ለምስሉም ያልሰገዱትን ምልክቱንም በግምባራቸው በእጆቻቸውም ላይ ያልተቀበሉትን አየሁ፤ ከክርስቶስም ጋር ሺህ ዓመት ኖሩና ነገሡ።'),
  ('997dfcaa-08fc-5900-a7d7-b096add5ea05', '0c6ca786-6195-5765-ad69-6844bbd8d5c2', 'd99921f2-d8f3-52bb-a547-0a57daac04f4', 5, 5, 'የቀሩቱ ሙታን ግን ይህ ሺህ ዓመት እስኪፈጸም ድረስ በሕይወት አልኖሩም። ይህ የፊተኛው ትንሣኤ ነው።'),
  ('d07f4a08-0769-5916-aa61-a1a82c0d6947', '0c6ca786-6195-5765-ad69-6844bbd8d5c2', 'd99921f2-d8f3-52bb-a547-0a57daac04f4', 6, 6, 'በፊተኛው ትንሣኤ ዕድል ያለው ብፁዕና ቅዱስ ነው፤ ሁለተኛው ሞት በእነርሱ ላይ ሥልጣን የለውም፤ ዳሩ ግን የእግዚአብሔርና የክርስቶስ ካህናት ይሆናሉ፤ ከእርሱም ጋር ይህን ሺህ ዓመት ይነግሣሉ።'),
  ('c2dcef18-d97d-52f2-a393-f27b3d91b2ef', '0c6ca786-6195-5765-ad69-6844bbd8d5c2', '72229735-0f8a-5a82-abcb-bce151cbe94d', 1, 7, 'ሺሁም ዓመት ሲፈጸም ሰይጣን ከእስራቱ ይፈታል፤'),
  ('adaf24a0-c348-5cc3-acbc-d64ef63845cb', '0c6ca786-6195-5765-ad69-6844bbd8d5c2', '72229735-0f8a-5a82-abcb-bce151cbe94d', 2, 8, 'በአራቱም በምድር ማዕዘን ያሉትን አሕዛብ፥ ጎግንና ማጎግን እንዲያስታቸው ለሰልፍም እንዲያስከትታቸው ይወጣል፤ ቍጥራቸውም እንደ ባሕር አሸዋ የሚያህል ነው።'),
  ('c3f659b7-4cf1-5b44-ae63-4fa96995b01e', '0c6ca786-6195-5765-ad69-6844bbd8d5c2', '72229735-0f8a-5a82-abcb-bce151cbe94d', 3, 9, 'ወደ ምድርም ስፋት ወጡ፤ የቅዱሳንንም ሰፈርና የተወደደችውን ከተማ ከበቡ፤ እሳትም ከሰማይ ከእግዚአብሔር ዘንድ ወርዳ በላቻቸው።'),
  ('2e89957d-dccc-5930-a857-0c60a7f75988', '0c6ca786-6195-5765-ad69-6844bbd8d5c2', '72229735-0f8a-5a82-abcb-bce151cbe94d', 4, 10, 'ያሳታቸውም ዲያብሎስ አውሬውና ሐሰተኛው ነቢይ ወዳሉበት ወደ እሳቱና ወደ ዲኑ ባሕር ተጣለ፤ ለዘላለምም እስከ ዘላለም ቀንና ሌሊት ይሰቃያሉ።'),
  ('57b39558-29c1-5fe5-a65d-fc7e9296b0a1', '0c6ca786-6195-5765-ad69-6844bbd8d5c2', 'e1e3a24d-a8b5-5328-a874-604d82223139', 1, 11, 'ታላቅና ነጭ ዙፋንን በእርሱም ላይ የተቀመጠውን አየሁ፤ ምድርና ሰማይም ከፊቱ ሸሹ፤ ስፍራም አልተገኘላቸውም።'),
  ('b9917a05-6fa3-5cde-af85-ead9e025fd39', '0c6ca786-6195-5765-ad69-6844bbd8d5c2', 'e1e3a24d-a8b5-5328-a874-604d82223139', 2, 12, 'ሙታንንም ታናናሾችንና ታላላቆችን በዙፋኑ ፊት ቆመው አየሁ፤ መጻሕፍትም ተከፈቱ፤ ሌላ መጽሐፍም ተከፈተ፤ እርሱም የሕይወት መጽሐፍ ነው፤ ሙታንም በመጻሕፍት ተጽፎ እንደ ነበረ እንደ ሥራቸው መጠን ተከፈሉ።'),
  ('ed970f89-a3aa-5dc8-aab9-bf8e1a923e05', '0c6ca786-6195-5765-ad69-6844bbd8d5c2', 'e1e3a24d-a8b5-5328-a874-604d82223139', 3, 13, 'ባሕርም በእርሱ ውስጥ ያሉትን ሙታን ሰጠ፤ ሞትና ሲኦልም በእነርሱ ዘንድ ያሉትን ሙታን ሰጡ፤ እያንዳንዱም እንደ ሥራው መጠን ተከፈለ።'),
  ('be360ded-e932-5eed-af40-6322d8ada99f', '0c6ca786-6195-5765-ad69-6844bbd8d5c2', 'e1e3a24d-a8b5-5328-a874-604d82223139', 4, 14, 'ሞትና ሲኦልም በእሳት ባሕር ውስጥ ተጣሉ። ይህም የእሳት ባሕር ሁለተኛው ሞት ነው።'),
  ('e79dad47-b15e-515d-ad53-3fb841463c09', '0c6ca786-6195-5765-ad69-6844bbd8d5c2', 'e1e3a24d-a8b5-5328-a874-604d82223139', 5, 15, 'በሕይወትም መጽሐፍ ተጽፎ ያልተገኘው ማንኛውም በእሳት ባሕር ውስጥ ተጣለ።'),
  ('5d6f5234-f635-5d94-a4cd-a4c6e5756482', '28d61d84-619c-5593-a58c-bdcbc2dd7387', 'ce66b300-eb3f-5f69-a8fc-22489f5b7ef4', 1, 1, 'አዲስ ሰማይንና አዲስ ምድርንም አየሁ፤ ፊተኛው ሰማይና ፊተኛይቱ ምድር አልፈዋልና፤ ባሕርም ወደ ፊት የለም።'),
  ('7c698bbf-77ef-52cb-ac0d-d537e12f7bc7', '28d61d84-619c-5593-a58c-bdcbc2dd7387', 'ce66b300-eb3f-5f69-a8fc-22489f5b7ef4', 2, 2, 'ቅድስቲቱም ከተማ አዲሲቱ ኢየሩሳሌም፥ ለባልዋ እንደ ተሸለመች ሙሽራ ተዘጋጅታ፥ ከሰማይ ከእግዚአብሔር ዘንድ ስትወርድ አየሁ።'),
  ('a41a7abe-9574-56d8-a5d0-eaea2e2b8448', '28d61d84-619c-5593-a58c-bdcbc2dd7387', 'ce66b300-eb3f-5f69-a8fc-22489f5b7ef4', 3, 3, 'ታላቅም ድምፅ ከሰማይ “እነሆ የእግዚአብሔር ድንኳን በሰዎች መካከል ነው፤ ከእነርሱም ጋር ያድራል፤ እነርሱም ሕዝቡ ይሆናሉ፤ እግዚአብሔርም እርሱ ራሱ ከእነርሱ ጋር ሆኖ አምላካቸው ይሆናል፤'),
  ('6dfec005-bcad-555e-a610-6233224079dc', '28d61d84-619c-5593-a58c-bdcbc2dd7387', 'ce66b300-eb3f-5f69-a8fc-22489f5b7ef4', 4, 4, 'እንባዎችንም ሁሉ ከዐይኖቻቸው ያብሳል፤ ሞትም ከእንግዲህ ወዲህ አይሆንም፤ ሐዘንም ቢሆን ወይም ጩኸት ወይም ሥቃይ ከእንግዲህ ወዲህ አይሆንም፤ የቀደመው ሥርዐት አልፎአልና፤” ብሎ ሲናገር ሰማሁ።'),
  ('e92c8c94-ac91-51ae-a03e-e6a0d181fe82', '28d61d84-619c-5593-a58c-bdcbc2dd7387', 'ce66b300-eb3f-5f69-a8fc-22489f5b7ef4', 5, 5, 'በዙፋንም የተቀመጠው “እነሆ ሁሉን አዲስ አደርጋለሁ፤” አለ። ለእኔም “እነዚህ ቃሎች የታመኑና እውነተኛዎች ናቸውና ጻፍ፤” አለኝ።'),
  ('9c8b6d2c-642f-57c2-a5d3-752a918360a3', '28d61d84-619c-5593-a58c-bdcbc2dd7387', 'ce66b300-eb3f-5f69-a8fc-22489f5b7ef4', 6, 6, 'አለኝም “ተፈጽሞአል፤ አልፋና ዖሜጋ፥ መጀመሪያውና መጨረሻው እኔ ነኝ። ለተጠማ ከሕይወት ውሃ ምንጭ እንዲያው እኔ እሰጣለሁ።'),
  ('90f6eb81-5f20-5e36-a092-15963388bd14', '28d61d84-619c-5593-a58c-bdcbc2dd7387', 'ce66b300-eb3f-5f69-a8fc-22489f5b7ef4', 7, 7, 'ድል የሚነሣ ይህን ይወርሳል፤ አምላክም እሆነዋለሁ፤ እርሱም ልጅ ይሆነኛል።'),
  ('bc5989ac-77fa-5537-ae51-c3a245dae859', '28d61d84-619c-5593-a58c-bdcbc2dd7387', 'ce66b300-eb3f-5f69-a8fc-22489f5b7ef4', 8, 8, 'ዳሩ ግን የሚፈሩና የማያምኑ የርኵሳንም የነፍሰ ገዳዮችም የሴሰኛዎችም የአስማተኛዎችም ጣዖትንም የሚያመልኩ የሐሰተኛዎችም ሁሉ ዕድላቸው በዲንና በእሳት በሚቃጠል ባሕር ነው፤ ይኸውም ሁለተኛው ሞት ነው።”'),
  ('cf553a93-353c-573e-a4bb-b9d9a61b8d6d', '28d61d84-619c-5593-a58c-bdcbc2dd7387', '8b49a099-24ea-54e1-a38d-730091ceddfa', 1, 9, 'ሰባቱም ኋለኛዎች መቅሠፍቶች የሞሉባቸውን ሰባቱን ጽዋዎች ከያዙት ከሰባቱ መላእክት አንዱ መጥቶ “ወደዚህ ና፤ የበጉንም ሚስት ሙሽራይቱን አሳይሃለሁ፤” ብሎ ተናገረኝ።'),
  ('0228d15e-a80c-502d-af30-a1915b1a19de', '28d61d84-619c-5593-a58c-bdcbc2dd7387', '8b49a099-24ea-54e1-a38d-730091ceddfa', 2, 10, 'በመንፈስም ወደ ታላቅና ወደ ረጅም ተራራ ወሰደኝ፤ የእግዚአብሔርም ክብር ያለባትን ቅድስቲቱን ከተማ ኢየሩሳሌምን ከሰማይ ከእግዚአብሔር ዘንድ ስትወርድ አሳየኝ፤ ብርሃንዋም እጅግ እንደ ከበረ ድንጋይ እንደ ኢያሰጲድ ድንጋይ ሆኖ እንደ ብርሌ የጠራ ነበረ፤'),
  ('357e60b1-c6c5-5cbb-a4ae-9cbb412b009f', '28d61d84-619c-5593-a58c-bdcbc2dd7387', '8b49a099-24ea-54e1-a38d-730091ceddfa', 3, 12, 'ታላቅና ረጅም ቅጥር ነበራት፤ ዐሥራ ሁለትም ደጆች ነበሩአት፤ በደጆቹም ዐሥራ ሁለት መላእክት ቆሙ የዐሥራ ሁለቱም የእስራኤል ልጆች ነገዶች ስሞች ተጽፈውባቸው ነበር።'),
  ('9f021cf1-7c53-57dc-a25b-1a0b9bdba187', '28d61d84-619c-5593-a58c-bdcbc2dd7387', '8b49a099-24ea-54e1-a38d-730091ceddfa', 4, 13, 'በምሥራቅ ሦስት ደጆች፥ በሰሜንም ሦስት ደጆች፥ በደቡብም ሦስት ደጆች፥ በምዕራብም ሦስት ደጆች ነበሩ።'),
  ('529eb772-f2ec-52d7-aac4-068543439232', '28d61d84-619c-5593-a58c-bdcbc2dd7387', '8b49a099-24ea-54e1-a38d-730091ceddfa', 5, 14, 'ለከተማይቱም ቅጥር ዐሥራ ሁለት መሠረቶች ነበሩአት፤ በእነርሱም ውስጥ የዐሥራ ሁለቱ የበጉ ሐዋርያት ስሞች ተጽፈው ነበር።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('f262e251-9ef9-5ad9-a19f-9bd27f1cd2a0', '28d61d84-619c-5593-a58c-bdcbc2dd7387', '8b49a099-24ea-54e1-a38d-730091ceddfa', 6, 15, 'የተናገረኝም ከተማይቱንና ደጆችዋን ቅጥርዋንም ይለካ ዘንድ የወርቅ ዘንግ ነበረው።'),
  ('0ccdfaf7-95d4-57c2-a195-95aad042395b', '28d61d84-619c-5593-a58c-bdcbc2dd7387', '8b49a099-24ea-54e1-a38d-730091ceddfa', 7, 16, 'ከተማይቱም አራት ማዕዘን ነበራት፤ ርዝመትዋም እንደ ስፋትዋ ልክ ነበረ። ከተማይቱንም በዘንግ ለካት፤ ሁለት ሺህ አራት መቶ ኪሎ ሜትር ሆነች፤ ርዝመትዋና ስፋትዋ ከፍታዋም ትክክል ነው።'),
  ('5d5b196f-d780-5da9-a4c0-ac3002a5d452', '28d61d84-619c-5593-a58c-bdcbc2dd7387', '8b49a099-24ea-54e1-a38d-730091ceddfa', 8, 17, 'ቅጥርዋንም ለካ፤ መቶ አርባ አራት ክንድ በሰው ልክ፥ እርሱም በመልአክ ልክ።'),
  ('8be78ff1-1796-5ed9-af0a-c0ee185cd2d2', '28d61d84-619c-5593-a58c-bdcbc2dd7387', '8b49a099-24ea-54e1-a38d-730091ceddfa', 9, 18, 'ቅጥርዋም ከኢያሰጲድ የተሠራ ነበረ፤ ከተማይቱም ጥሩ ብርጭቆ የሚመስል ጥሩ ወርቅ ነበረች።'),
  ('c51d7c5a-ba79-5a66-a589-198ec3773611', '28d61d84-619c-5593-a58c-bdcbc2dd7387', '8b49a099-24ea-54e1-a38d-730091ceddfa', 10, 19, 'የከተማይቱም ቅጥር መሠረት በከበረ ድንጋይ ሁሉ ተጌጦ ነበር፤ ፊተኛው መሠረት ኢያሰጲድ፥ ሁለተኛው ሰንፔር፥ ሦስተኛው ኬልቄዶን፥ አራተኛው መረግድ፥'),
  ('1e3161e5-7f7c-58e4-afb2-b12f313a6ce6', '28d61d84-619c-5593-a58c-bdcbc2dd7387', '8b49a099-24ea-54e1-a38d-730091ceddfa', 11, 20, 'አምስተኛው ሰርዶንክስ፥ ስድስተኛው ሰርድዮን፥ ሰባተኛው ክርስቲሎቤ፥ ስምንተኛው ቢረሌ፥ ዘጠነኛው ወራውሬ፥ ዐሥረኛው ክርስጵራስስ፥ ዐሥራ አንደኛው ያክንት፥ ዐሥራ ሁለተኛው አሜቴስጢኖስ ነበረ።'),
  ('c0f169c6-0465-5784-a195-f35d788e0199', '28d61d84-619c-5593-a58c-bdcbc2dd7387', '8b49a099-24ea-54e1-a38d-730091ceddfa', 12, 21, 'ዐሥራ ሁለቱም ደጆች ዐሥራ ሁለት ዕንቆች ነበሩ፤ እየአንዳንዱ ደጅ ከአንድ ዕንቍ የተሠራ ነበረ። የከተማይቱም አደባባይ ጥሩ ብርጭቆ የሚመስል ጥሩ ወርቅ ነበረ።'),
  ('2067a68d-7a95-5e80-a370-7b9d104a1c53', '28d61d84-619c-5593-a58c-bdcbc2dd7387', '8b49a099-24ea-54e1-a38d-730091ceddfa', 13, 22, 'ሁሉንም የሚገዛ ጌታ አምላክና በጉ መቅደስዋ ናቸውና መቅደስ በእርስዋ ዘንድ አላየሁም።'),
  ('f11fc706-bdcb-5a12-ae3e-b82e5296a984', '28d61d84-619c-5593-a58c-bdcbc2dd7387', '8b49a099-24ea-54e1-a38d-730091ceddfa', 14, 23, 'ለከተማይቱም የእግዚአብሔር ክብር ስለሚያበራላት መብራትዋም በጉ ስለ ሆነ፥ ፀሐይ ወይም ጨረቃ እንዲያበሩላት አያስፈልጓትም ነበር።'),
  ('dc67e496-38f7-579d-a820-8894a9c57cde', '28d61d84-619c-5593-a58c-bdcbc2dd7387', '8b49a099-24ea-54e1-a38d-730091ceddfa', 15, 24, 'አሕዛብም በብርሃንዋ ይመላለሳሉ፤ የምድርም ነገሥታት ክብራቸውን ወደ እርስዋ ያመጣሉ፤'),
  ('c0f72417-e93e-595d-ab4f-a189dbaf8305', '28d61d84-619c-5593-a58c-bdcbc2dd7387', '8b49a099-24ea-54e1-a38d-730091ceddfa', 16, 25, 'በዚያም ሌሊት ስለሌለ ደጆችዋ በቀን ከቶ አይዘጉም፤'),
  ('13e23127-14a0-565a-ac0d-63f6f4c10d23', '28d61d84-619c-5593-a58c-bdcbc2dd7387', '8b49a099-24ea-54e1-a38d-730091ceddfa', 17, 26, 'የአሕዛብንም ግርማና ክብር ወደ እርስዋ ያመጣሉ።'),
  ('bdfb40ac-8a45-573a-a10f-415bba44b0ba', '28d61d84-619c-5593-a58c-bdcbc2dd7387', '8b49a099-24ea-54e1-a38d-730091ceddfa', 18, 27, 'ለበጉም በሆነው በሕይወት መጽሐፍ ከተጻፉት በቀር፥ ጸያፍ ነገር ሁሉ ርኵሰትና ውሸትም የሚያደርግ ወደ እርስዋ ከቶ አይገባም።'),
  ('345678b5-5424-5024-a27c-611d6da74580', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', 'b623f505-4303-51de-aa25-3fafe540d1ff', 1, 1, 'በአደባባይዋም መካከል ከእግዚአብሔርና ከበጉ ዙፋን የሚወጣውን እንደ ብርሌ የሚያንጸባርቀውን የሕይወትን ውሃ ወንዝ አሳየኝ።'),
  ('49c19c6d-7d69-50b9-aa9b-95c056f8aebe', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', 'b623f505-4303-51de-aa25-3fafe540d1ff', 2, 2, 'በወንዙም ወዲያና ወዲህ በየወሩ እያፈራ ዐሥራ ሁለት ፍሬ የሚሰጥ የሕይወት ዛፍ ነበረ፤ የዛፉም ቅጠሎች ለሕዝብ መፈወሻ ነበሩ።'),
  ('dab999fa-ed74-5872-ad59-0d164fa4f98e', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', 'b623f505-4303-51de-aa25-3fafe540d1ff', 3, 3, 'ከእንግዲህም ወዲህ መርገም ከቶ አይሆንም። የእግዚአብሔርና የበጉም ዙፋን በእርስዋ ውስጥ ይሆናል፤ ባሪያዎቹም ያመልኩታል፤ ፊቱንም ያያሉ፤'),
  ('49c0e3cd-3b0e-535d-aacc-ad73c88004ab', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', 'b623f505-4303-51de-aa25-3fafe540d1ff', 4, 4, 'ስሙም በግምባሮቻቸው ይሆናል።'),
  ('1a7b4d2d-16ac-5e8b-aec2-61cbb4b68ab1', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', 'b623f505-4303-51de-aa25-3fafe540d1ff', 5, 5, 'ከእንግዲህም ወዲህ ሌሊት አይሆንም፤ ጌታ አምላክም በእነርሱ ላይ ያበራላቸዋልና የመብራት ብርሃንና የፀሐይ ብርሃን አያስፈልጋቸውም፤ ለዘላለምም እስከ ዘላለም ይነግሣሉ።'),
  ('18c24438-a05f-5a7d-a8b4-3974b3716200', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', '430ee0e6-e9ac-57bb-abab-31f0f4d471e1', 1, 6, 'እርሱም “እነዚህ ቃሎች የታመኑና እውነተኛዎች ናቸው፤ የነቢያትም መናፍስት ጌታ አምላክ በቶሎ ሊሆን የሚገባውን ነገር ለባሪያዎቹ እንዲያሳይ መልአኩን ሰደደ።”'),
  ('a1fba013-3187-52d7-ab8b-f8640473ea3a', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', '430ee0e6-e9ac-57bb-abab-31f0f4d471e1', 2, 7, 'እነሆም “በቶሎ እመጣለሁ። የዚህን መጽሐፍ ትንቢት ቃል የሚጠብቅ ብፁዕ ነው፤” አለኝ።'),
  ('9a38d0bc-fce1-568f-a5e6-3de51b522635', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', '430ee0e6-e9ac-57bb-abab-31f0f4d471e1', 3, 8, 'ይህንም ያየሁትና የሰማሁት እኔ ዮሐንስ ነኝ። በሰማሁትና ባየሁትም ጊዜ ይህን ባሳየኝ በመልአኩ እግር ፊት እሰግድ ዘንድ ተደፋሁ።'),
  ('e2a4cec1-46b8-5d08-a3ca-e1bdd5f65bbc', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', '430ee0e6-e9ac-57bb-abab-31f0f4d471e1', 4, 9, 'እርሱም “እንዳታደርገው ተጠንቀቅ፤ ከአንተ ጋር ከወንድሞችህም ነቢያት ጋር የዚህንም መጽሐፍ ቃል ከሚጠብቁ ጋር አብሬ ባሪያ ነኝ፤ ለእግዚአብሔር ስገድ፤” አለኝ።'),
  ('a03b8384-46f9-5459-a06e-b7aaabd9ba9f', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', '430ee0e6-e9ac-57bb-abab-31f0f4d471e1', 5, 10, 'ለእኔም “ዘመኑ ቀርቦአልና የዚህን መጽሐፍ ትንቢት ቃል በማኅተም አትዝጋው።'),
  ('8dd61c67-9404-5c9d-a183-4192c0b7f521', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', '430ee0e6-e9ac-57bb-abab-31f0f4d471e1', 6, 11, 'ዐመፀኛው ወደ ፊት ያምፅ፤ ርኵሱም ወደ ፊት ይርከስ፤ ጻድቁም ወደ ፊት ጽድቅ ያድርግ፤ ቅዱሱም ወደፊት ይቀደስ፤” አለ።'),
  ('1ff688fc-6151-564d-a59b-bd54cb13d741', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', '430ee0e6-e9ac-57bb-abab-31f0f4d471e1', 7, 12, '“እነሆ በቶሎ እመጣለሁ፤ ለእያንዳንዱም እንደ ሥራው መጠን እከፍል ዘንድ ዋጋዬ ከእኔ ጋር አለ።'),
  ('13368ac1-0935-5cce-a5cd-5aabd7a0dec7', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', '430ee0e6-e9ac-57bb-abab-31f0f4d471e1', 8, 13, 'አልፋና ዖሜጋ፥ ፊተኛውና ኋለኛው፥ መጀመሪያውና መጨረሻው እኔ ነኝ።”'),
  ('cc6f3a17-0436-5336-a4dd-d18e61182fef', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', '430ee0e6-e9ac-57bb-abab-31f0f4d471e1', 9, 14, 'ወደ ሕይወት ዛፍ ለመድረስ ሥልጣን እንዲኖራቸው በደጆችዋም ወደ ከተማይቱም እንዲገቡ ልብሳቸውን የሚያጥቡ ብፁዓን ናቸው።'),
  ('6a9194cf-7c89-5db9-ad91-b32a0825f9bb', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', '430ee0e6-e9ac-57bb-abab-31f0f4d471e1', 10, 15, 'ውሻዎችና አስማተኞች ሴሰኛዎችም ነፍሰ ገዳዮችም ጣዖትንም የሚያመልኩት ውሸትንም የሚወዱና የሚያደርጉ ሁሉ በውጭ አሉ።'),
  ('f72d7968-6296-54e1-ae75-cc1aa639d636', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', '430ee0e6-e9ac-57bb-abab-31f0f4d471e1', 11, 16, '“እኔ ኢየሱስ በአብያተ ክርስቲያናት ዘንድ ይህን እንዲመሰክርላችሁ መልአኬን ላክሁ። እኔ የዳዊት ሥርና ዘር ነኝ፤ የሚያበራም የንጋት ኮከብ ነኝ።”'),
  ('01c2b963-36b9-5760-a6e1-9c929e0f658d', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', '430ee0e6-e9ac-57bb-abab-31f0f4d471e1', 12, 17, 'መንፈሱና ሙሽራይቱም “ና!” ይላሉ። የሚሰማም “ና!” ይበል። የተጠማም ይምጣ፤ የወደደም የሕይወትን ውሃ እንዲያው ይውሰድ።'),
  ('d1891dc7-422b-5002-a20f-5ce1c473eae6', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', '430ee0e6-e9ac-57bb-abab-31f0f4d471e1', 13, 18, 'በዚህ መጽሐፍ የተጻፈውን የትንቢት ቃል ለሚሰማ ሁሉ እኔ እመሰክራለሁ፤ ማንም በዚህ ላይ አንዳች ቢጨምር፥ እግዚአብሔር በዚህ መጽሐፍ የተጻፉትን መቅሠፍቶች ይጨምርበታል፤'),
  ('77c8cf2a-0511-5eb9-a369-16a105265065', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', '430ee0e6-e9ac-57bb-abab-31f0f4d471e1', 14, 19, 'ማንምም በዚህ በትንቢት መጽሐፍ ከተጻፉት ቃሎች አንዳች ቢያጎድል፥ በዚህ መጽሐፍ ከተጻፉት ከሕይወት ዛፍና ከቅድስቲቱ ከተማ እግዚአብሔር ዕድሉን ያጎድልበታል።'),
  ('c38427d8-dc26-5d1f-ae10-63b8521f1ea1', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', '430ee0e6-e9ac-57bb-abab-31f0f4d471e1', 15, 20, 'ይህን የሚመሰክር “አዎን በቶሎ እመጣለሁ፤” ይላል። አሜን፤ ጌታ ኢየሱስ ሆይ!ጅ ና።'),
  ('46432d82-919f-5d70-a2f6-0f221904bfb2', 'e6a1a8b6-f91c-5a52-af55-31b7c081b2e8', '430ee0e6-e9ac-57bb-abab-31f0f4d471e1', 16, 21, 'የጌታችን የኢየሱስ ክርስቶስ ጸጋ ከሁላችን ጋር ይሁን፤ አሜን።'),
  ('dade9b05-eed4-5301-af07-ba172188cac2', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 1, 1, 'በአብ በወልድ በመንፈስ ቅዱስ ስም አንድ አምላክ ቅዱስ ቀሌሚንጦስ እንዲህ አለ ። ጌታችንና መድሐኒታችን ኢየሱስ ክርስቶስ ዕርገት በኋላ የቅዱስ ወንጌልን ዜና ይሰብኩ ዘንድ ተማሪዎች ወደ ዓለም ዳርቻ ሁሉ ተበተኑ።'),
  ('b87cb01f-af90-5176-a0b3-d21fea830378', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 2, 2, 'አርድእት ወደዓለም ዳርቻ ሁሉ ሊበተኑ የቻሉት ሕዝቦችን ወደ እምነትና ዕውቀት ለመመለስና ዳግም ልደትን የምታሠጠውን ጥምቀት እንዲያጠምቁዋቸው ነው።'),
  ('38efdf0b-db30-5c81-a27c-207f8984885c', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 3, 3, 'ከዚህ በተነሳ ሐዋርያት ከያንዳንዳቸው ጋር አብረው የሚሄዱትን ፈለጉ ። ከዚህ ጊዜ ስምዖን የተባለው ጴጥሮስ ከሱ ጋር ወሰደኝ ። የሱ ተማሪ እንድሆንም አደረገኝ እኔ በሱ ትምህርት እሱን ሰላከው አምላክ አምኛለሁና የሐዋርያት አለቃ መሆኑንም ተረድቻለሁና።'),
  ('d61846f6-d1e7-50c6-aa95-38272887e23f', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 4, 4, 'ጌታችን መድሐኒታችን ኢየሱስ ክርስቶስ በቅዱስ ወንጌል አንተ አለት ነህ በዚች እለት ላይ ቤተክርስቲያኔን እሠራታለሁ የሲኦል በሮችም አያይሉባትም የመንግሥት ሰማያትን ቁልፎች ላንተ እሰጣለሁ ያለውንም አስታወስኩ።'),
  ('5288acb0-470b-5bfe-ac22-9b6e5552f2a7', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 5, 5, 'ከጥቂት ጊዜ በኋላ ሁለት ሌሎች ወንድሞችን አስከተለ ተማሪዎቹንም አደረጋቸው። እኔ ከሱ ጋር ሃያ ዓመት ከኖርኩ በኋላ ወደናትና አባት አገሬ ወስደኝ እቺ አገር መጥሮጵያ ትባላለች። ጌታችን መድኃኒታችን ኢየሱስ ክርስቶስ በደብረዘይት ያስተማረውንም ምሥጢር ገለፀልኝ (አብራራልኝ) ።'),
  ('23e26e90-12a8-5ab2-aaa2-1c45c8940065', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 6, 6, 'በዚህ ወቅት ሐዋርያትና ሌሎች አማንያን በከባድ መከራ ላይ ነበሩ። መከራውን ያደረሰባቸው ከሐዲዎች አይሁድ ናቸው። ከሐዲዎቹ አይሁዶች ኢየሱስ ክርስቶስን ያመነ ሁሉ እያደነ በመግደል ላይ ነበሩ።'),
  ('93dc8191-4bd9-5578-aeb5-343ecf5b2cad', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 7, 7, 'ከዚህ ጀምሮ ጴጥሮስ እኔን አስከትሎ ሄደና ወዳንዲት አገር ደረሰ። ከዚሁ ከሄድንበት አገርም ለኔና ለጴጥሮስ ችግር ገጠመን። ችግሩ ከከሐዲዎቹ አይሁድ የመነጨ ነበር። ቅድስት ድንግል ማርያም ከይሁዳ ትውልድ የላትም እያሉ በመከራከር ችግር ፈጠሩብን። እንዲህ ማለታቸው የጌታችን መድሐኒታችን ኢየሱስ ክርስቶስ ወደዚህ ዓለም መምጣት ለመካድ ነው።'),
  ('f124fc5f-2c4e-5928-ab79-dd30eb3580b6', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 8, 8, 'እነዚህ ከሐዲዎች አይሁድ በመጀመርያ የዓለምን አፈጣጠር እንዳያውቁ ሐዋርያት ኦሪትን እንዳያነቡ ይከለክሉዋቸው ዘንድ እንዲሁም በክርስቶስ ያመነትን ያጠፉላቸው ዘንድ ለግሪክና ለሮም ሰዎች ብዙ ገንዘብን በመስጠት ላይ ነበሩ።'),
  ('59b2e1fd-064b-5f4a-a345-304caade73e6', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 9, 9, 'ይህን በኔ ላይና በጴጥሮስ ላይ የደረሰውን መከራና ችግር ካየሁ ጊዜ (ከከሐዲዎች አይሁድ ዘንድ) ዓለም ከመጀመርያው አንስቶ እንዴት እንደተፈጠረች ያስረዳኝ ዘንድ መምህሬን ጴጥሮስ ጠየቅሁት።'),
  ('04bad084-ebbe-52a9-a4cd-b73a4ac291b7', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 10, 10, 'ቅዱስ ጴጥሮስ ከጌታችን መድሐኒታችን ኢየስስ ክርስቶስ ምሥጢርን ሁሉ አውቆ ነበርና እኔም የፅርዓውያንን ጥበብና መጻሕፍቶቻቸውን ተምሬ ነበርና።'),
  ('3aad0885-9b48-594a-a761-b10d752e8b74', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 11, 11, 'በኔ ላይ ቂምና በቀል አድሮብኝ ነበር። ምክንያቱም ስለ ቅድስት ድንግል ማርያምና ስለ አባታችን አዳም አፈጣጠር ሲጠይቁኝ ስለ ኦሪትና ስለ ነቢያት የማውቀው ነገር ስላልነበረኝ መልስ ለመሥጠት አልቻልኩም ነበርና ተቸግሬ ነበር።'),
  ('64074021-814c-58e0-ac95-7b19a5762afb', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 12, 12, 'ከሁሉ በበለጠ በማርያም ንግሥትና ቅድስት ላይ ስድብን ያሰማሉ ። ነገር ግን እኔ በማውቀው ክፋታቸውና የረከሰ ቃላቸው ለዚሁ ምንም ምክንያትን አላገኙም ።።'),
  ('6184920e-52aa-5b08-ac4d-553531dce8e2', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 13, 13, 'ይህንን ሁሉ ለመምሬ ነገርኩት እሱም በጣም አዘነ መንፈሳዊ ቅንአትም አደረበት ። እንዲህም አለኝ ልጄ ሆይ የጠየቅኸኝን ሁሉ ዘርዝሬ አስረዳሀለሁ አለም ከተፈጠረ ጀምሮ አንስቼ እገልፅላሃለሁ የብርሃን ክርስቶስ እናት ስለሆነችውም ቅድስት ማርያም እነግርሃለሁ። እሷ ያለጥርጥር ከያዕቆብ ልጅ ይሁዳ ናት።'),
  ('e0b9e254-3df6-5c39-a0ea-40fc6ea18212', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 14, 14, 'ሠይጣን ከሰማይ እንዴት እንደወደቀሞ እነግራሃለሁ ልጄ ቀሌሚንጦስ ሆይ ልብ ብለህ ተከተለኝ። ከሁሉም በፊት እግዚአብሔር ይቀድማል መጀመርያ የለውም መጨረሻም የለውም ። ልእልናው ከሁሉ በላይ ነው በህሊና ሊደረስበት አይቻልም ላይና ታች የለውም ።ውስጥና ውጭም የለውም።'),
  ('207176b6-cea1-5327-ac3e-60750ecf8b8b', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 15, 15, 'እሱ ከሁሉ የቀደመ ሁኖ ዘለዓለማዊ ነው። አይለይም አይነገርምም እሱ ከሁሉ በላይ ነውና በመለኮትነቱም ያለ ነው። ከፍጥረቱ ጋር ሁኖ ከሁሉ በላይ ነው። ከፍጥረቱ በታችም ይገኛል ብርሃንን ፈጠረ እሱም ብርሃን ነው ጨለማ የማያገኘው ብርሃን ነው።'),
  ('3f03697e-e82b-5885-a052-38b2a3be2c52', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 16, 16, 'በብርሃናት ውስጥ ይኖራል ዓይኖች ሊመለከቱት አይችሉም ። ከሁሉ አስቀድሞ ያለ ነው ። ሁሉንም የፈጠረ እሱ ነው ። ምሥጋናው ከባህርዩ ይወጣል ። ሁሉን የፈጠረና የሚመሰገን እሱ ነው የግርማው መጠን አይታወቅም የሐያልነቱንም ፅናት አይታወቅም ሰማይንና ምድርን ፈጥሯል።'),
  ('072b7102-5c44-5d58-a27e-9f6ec9940c67', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 17, 17, 'ቀሌሚንጦስ ልጄ ሆይ ልዑል እግዚአብሔር ከሁሉ አስቀድሞ መላእክትን በአሥር ክፍል ከፍሎ ፈጠራቸው በመልካም ዜማና ማሕሌትም ያመሰግኑት ዘንድ አደረገ የሚያመሠግኑትም በየመዓርጋቸው በመቆም ነው ከመላእክት ሁሉ ትልቅ የሆነው ወደ እግዚአብሔር መንበር ይቀርባል።'),
  ('72984a6a-ebbf-5b78-a1d6-b535821ebe74', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 18, 18, 'የሳጥናኤል ክፍል የሆነው ነው ከሁላቸው መላእክት የሚቀድመው እነዚህ መላእክት ያለማቋረጥ ለእግዚአብሔር ምሥጋና ያቀርቡ ነበር። የዕለታት መጀመርያ በሆነው እለተ እሁድ የሰማዮች ሰማይና ምድርን እግዚአብሔር ፈጠረ። ከፍተኛውን ሥፍራ የያዙት መላእክትም በዚሁ ዕለት ተፈጠሩ።'),
  ('1aae03d3-4a45-557b-a056-a9251a4ac3f1', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 19, 19, 'ይህም የሣጥናኤል ወገን ነው መላእክት የመላእክት ዓለቆች ኃይላት መናብርት ሥልጣናት አጋእዝት የሚላላኩ ሱራፌልና ኪሩቤል ፀዳል ብርሃን መዓልት። ሌሊት ነፍሶች ውሆች እነዚህ ሁሉ በቅደም ተከተል ተፈጠሩ እግዚኣብሔር ይህንንም በተቀደሰው ቃሉ በተቀደሰ እሁድ አስተካከለ።'),
  ('ab2645ab-61d1-5a8e-ad87-91c2192343fa', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 20, 20, 'እግዚአብሔር ይህን ሁሉ በፈጠረበት ዕለት መንፈስ ቅዱስ በውሆች ላይ ሰፍፎ ነበር።'),
  ('a1f94813-8bc3-535d-ad3b-a953aedea9c9', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 21, 21, 'በመጀመርያው ዕለት እግዚአብሔር ፋሌክ የሚባለውን ሰማይ ፈጠረ እሱም ዝቅተኛው ክፍል ነው በዚሁም ሰማዮች ሁሉ ይህንን እንደሚመስሉ ይታወቃሉ። ይህንን ፋሌክ የሚባለውም ሰው ያየዋል። ይህ ሰማይ ከከፍተኞች ሰማዮች ተለይቶ ዝቅ ያለ ነው ምክንያቱም ፋሌክ ከተባለው ሰማይ ከፍ ያለ ሌላ ሰማይ ያለ ሲሆን ከሱ የቀጠለም ሌላ ሰማይ አለ ስሙ ድርቲቆን ይባላል።'),
  ('69307f60-c2bb-54bd-aa06-e66873a3cda9', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 22, 22, 'ከዚሁ ሰማይ በላይ ነደእሳት አለ ከእሳቱ በላይ ደግሞ ሰማይ አለ ሰማዮች ሁሉ በብርሃን የተሞሉ ናቸው ይህንን ብርሃን የሰው ዓይን ሊያየውና ሊመለከተው በምንም ዓይነት አይችልም።'),
  ('7d957d47-d323-5ced-a7e4-ff3f9d6f319e', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 23, 23, 'እግዚአብሔር ሰኞ እለት በምድር ላይ ባሉ ውሆች መካከልና በሰማይ በላይ ውሆች መካከል ልዩነትን ፈጠረ። እርስ በርሱ እንደተጫጫነ ደመናም ሆነ።'),
  ('85dace73-7775-5c90-a14e-a36fe6078134', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 24, 24, 'የቀሩት ውሆች በነፋሶች መካከል ይኖራሉ ወድያና ወዲህ በማለትም ለመንቀሳቀስ አይችሉም (አይንቀሳቀሱም)።'),
  ('24552f35-f6f3-55e1-a300-98ffed163bc7', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 25, 25, 'በሦስተኛው ቀን እግዚአብሔር ከሰማይ በታች የነበሩትን ውሆች እሱም ፋሌክ የተባለው ወዳንድ ቦታ እንዲሰበስቡ አዛቸው የብስም ይታይ ዘንድ አዘ። እሱም ታየ።'),
  ('2f683848-8fe7-53a3-a71e-a4611d679822', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 26, 26, 'ውሃው ጨርሶ ሳይለይ የብሱ ጭቃ ሁኖ ታየ መሬትና ውኃ ተደባልቀው ይታዩ ነበር። ውሃው ከየብስ ውስጥ ሆነ ነፋስ ደግሞ ከምድር ውስጥ ይወጣ ነበር። በቀስታም ይነፍሳል በዚሁም ሕይወት ያለው ፍጥረት ሁሉ ይኖራል።'),
  ('6214961e-7978-5d96-ad8c-0482534d65eb', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 27, 27, 'ምድር ከውሃ ላይ እንደምትኖር የሰፍነግ አምሳያ ሁና ተፈጠረች። በዚችም ምድር ላይ ሣርና ልምላሜ እንጨትም ሌሎችም ይበቅሉ ዘንድ እግዚአብሔር አዘዘ።'),
  ('48696338-13e6-5b13-a7e1-32125702e445', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 28, 28, 'እግዚአብሔር በአራተኛው ቀን ፀሐይን ጨረቃን ፈጠረ የፀሐይም ዋዕይ ምድርን ከጭቃነትዋ ያደርቃት ዘንድ አደረገ የምድርንም መሬት ያፀናል።'),
  ('2a8ac548-5d05-55b7-a333-f9d93ed8b6a2', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 29, 29, 'በአምስተኛው ቀን ውሆች የዓሣዎችን ዓይነት ያወጡ ዘንድ እግዚአብሔር ውሆችን አዘዛቸው ውሆችም የተለያየ መልክ ያላቸውን ዓሦች አወጡ ከነፋስ በላይ የሚበሩትንም ፈጠረ አስደናቂ መልክ ያላቸውንም ትላልቅ ነብሮች ፈጠረ።'),
  ('381ef80c-5024-5075-a45e-c31889d12593', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 30, 30, 'እግዚአብሔር በስድስተኛው ቀን ከምድር አራዊትን ሁሉና እንስሳት እንዲሁም ትሎች ፈጠረ። እንዲሁም አባታችን አዳምን በዚችው ዕለት ከአፈር ፈጠረው ሔዋንንም ከጐድኑ አጥንት ፈጠራት።'),
  ('fe49b43f-eadc-5f52-aa97-0df06dde058c', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 31, 31, 'በሰባተኛው ቀን እግዚአብሔር ሥራውን ፈፅሞ ዓረፈ ሰባተኛይቱንም ቀን ሰንበት ብሎ ሰየማት አዳምን በዕለተ ዓርብ በሦስት ሰዓት ነው የፈጠረው። ከላይ እንደተገለፀው በስድስተኛው ቀን አዳም ተፈጠረ። በዚችውም ዕለት ትዕቢትና ቅንዓት በሠይጣን ላይ አደረ።'),
  ('d39d17ba-8cb8-5836-ac9a-f7feb2baabeb', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 32, 32, 'እግዚአብሔር አባታችን አዳምን ከመፍጠሩ አስቀድሞ ሠይጣንን ወደምድር አወረደው። በዚህ ጊዜ የሰማያት ኀይሎች በሙሉ ለተወሰነ ጊዜ ፀጥ አሉ።'),
  ('b7952b7f-9e1b-5b8b-a277-73027a4f94b1', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 33, 33, 'እግዚአብሔር አብ ለወልድና ለመንፈስ ቅዱስ በአርአያችንና በአምሳላችን ሰውን እንፍጠር አላቸው። መላእክት ይህን ከልዑል እግዚአብሔር በሰሙ ጊዜ ከላያቸው ላይ ከባድ ፍርሐትና ድንጋጤ አደረባቸው።'),
  ('3ee183fe-cd18-5f9f-a44f-570293ffb504', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 34, 34, 'በየራሳቸውም ይህ ትልቅ አስደናቂ ተአምር የምንሰማው ምንድር ነው የፈጣሪያችንንና የአምላካችንን አርአያና አምግልንስ ማየት እንዴት ይቻለናል ተባባሉ። ከዚህ ጊዜ ጀምሮ የእግዚአብሔር ቀኝ በምድር ሁሉ ተዘረጋች ዓለም በመላ በእግዚአብሔር መዳፍ ላይ ሁና ለመላእክት ሁሉ ታየቻቸው።'),
  ('f930db84-b867-5917-acce-c018ace8edb5', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 35, 35, 'እግዚአብሔር ከምድር ትንሽ አፈርን ከመላ ምድር ውሆችም ጥቂት ጠብታን ከነፋሶችም ጥቂት ነፋስን ከዋዕየ እሳትም ጥቂቷን አጠራቅሞ በመዳፉ ማህል ሰበሰባቸው ያዛቸውም።'),
  ('c15ac8ca-7826-5d62-ad8b-0d41abac309c', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 36, 36, 'እግዚአብሔር አባታችን አዳምን ከነዚያ አራቱ ደካማዎች ፈጠረው አራቱ ኃይል የሌላቸው ናቸው ይህንን ያደረገው ፍጥረት እንዲታዘዝለት ነው መሬት ሰው ሁሉ እንዲታዘገለት ውሃ። በውሃ ውስጥ የሚንቀሳቀሱ ሁሉ እንዲታዘዙለት። ነፋስ የሚነፍሰውን ሁሉ ለማሽተት ይቻል ዘንድ እሳት። በዋዕይ እንዲጠነክርና የሚረዳውን ሐይል እንዲያገኝ።'),
  ('58f34ceb-5e35-567c-a4ee-95b9f15a60d4', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 37, 37, 'ስለዚህም እግዚአብሔር ልዑል አባታችን አዳሞን በተቀደሰች እጁ በአርአያውና በምሳሌው አድርጎ ፈጠረው ይህም ያደረገበት ምክንያት አዳም ጥበብን፡ ነቢብንና ዕውቀትን ሁሉ እንዲቀበል ነው።'),
  ('8030c8df-f21c-5779-a66a-0474702d3efe', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 38, 38, 'በአዳም ላይ ታላቅ ክብርና ታላቅ ምሥጋና ባዩ ጊዜ መላእክት ከግርማው ብዛት የተነሳ ፈሩ የመለኮት ብርሃን በአዳም ፊት ይበራ ነበር። የአዳም ፊት ብርሃን ከፀሐይ ይበልጥ ነበር። ሥጋውም እንደንጋት ኮከብ ይበራ ነበር።'),
  ('38aa29cd-d44c-5535-a056-ae17b3b9f362', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 39, 39, 'የአዳም አፈጣጠር ከተፈፀመ በኋላ አዳም በምድር ላይ ቆመ። እግሩንም ወደጎልጎታ አቀና ቀኝ እጁንም ጌታችን ወደተሰቀለበት ጎልጎታ ዘረጋ።'),
  ('94ccec05-ac98-56e9-a4f1-d06ae5b1159d', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 40, 40, 'ከዚህ ጊዜ ጀምሮ እግዚአብሔር አባታችን አዳምን የምስጋና አክሊልን ልብሰ መንግሥትን የግርማ ከፍተኛነትን አለበሰው በራሱ ላይም የመንግሥትን አክሊል አቀዳጀው። በዚህ ጊዜ ንጉሥነትንና ነቢይነትን ሠጠው በክብር መንበር ላይም አስቀመጠው።'),
  ('bfd4417b-7899-5dff-a37d-3ec751601832', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 41, 41, 'አራዊትና እንስሳት ወፎች እግዚአብሔር የፈጠረው ሁሉ ወደ አዳም ተሰበሰበ ከፊቱም ቁመው ራሳቸውን አዘነበሉ ለአዳምም ሰገዱ።'),
  ('868ac6b4-562f-5f8e-a014-75cd16e5677e', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 42, 42, 'አዳም ለሁሉም በየስሙ ሰየመው ፍጥረት ሁሉም ለአዳም ይታዘዝና ቃሉንም ይጠብቅ ነበር።'),
  ('701343e7-dc8d-5f12-a64b-97f25c05e615', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 43, 43, 'በዚህ ጊዜ መላእክት የእግዚአብሔር ቃል አዳም ሆይ እነሆ ንጉሥ ካህን ነቢይ መስፍን ለፍጥረት ሁሉ ገዢ ስላንተ በፈጠርሁት ሁሉ እንድትሆን አደረግሁ ፍጥረት ሁሉ አንተን ይስሙ ለቃልህም ይታዘዙ ከእጅህ በታችም ይሁኑ ይህንንም ሁሉ ላንተ ብቻ ሠጠሁ።'),
  ('b6085c1a-a1a7-5cab-aae7-7fe7e55d03c4', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 44, 44, 'የፈለግኸውን ታደርግ ዘንድ ይህንን ሥልጣን ሠጠሁህ ሲል ስሙ።።'),
  ('fddac940-c5a6-5b39-ad8d-b5631ce26ca2', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 45, 45, 'መላእክት ይህንን የልዑል እግዚአብሔር ቃል በሰሙ ጊዜ ትልቁ የአዳም ግርማ በፊታቸው ላይ እጅግ በዛ።'),
  ('d4a25aad-0a9e-570b-af34-c3a1d54f3bef', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 46, 46, 'ሠይጣን ለአዳም ከእግዚአብሔር የተሠጠውን ኃብተፀጋ ባየ ጊዜ ከዚች ሰዓት ጀምሮ ቅንአት አደረበት ። በአዳም ላይም ቀናበት እሱንም አስቶ ከእግዚአብሔር የሚያርቅበትን የሱንም ታዛዥ የሚየደርግበትን ተንኰል በማሰብ ከፀጋ እግዚአብሔር አዳምን ለማውጣት ተነሳ።'),
  ('3bc35100-b452-5e26-a4c0-531995a7961b', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 47, 47, 'በዚህ ጊዜ እግዚአብሔር በሠይጣን ላይ የነበረውን የምሥጋና ልብስና የግርማ ልዕልና አስወገደ። ሠይጣን ብሎም ሠየመው በእግዚአብሔር ላይ ታብዮአልና በእግዚአብሔር መንገድም አልሄደምና ለራሱም ክብር ወዷልና።'),
  ('d4ecd7fa-7c67-547c-a98f-0dbe0d7f0310', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 48, 48, 'አዳም በጎልጎታ ላይ ሳለ ፍጥረታት ሁሉ ወደሱ ተሰበሰቡ የተሰበሰቡበትም ምክንያት ከአዳም ጋር የሚናገረውን የእግዚአብሔር ቃል ለመስማት ነው።'),
  ('8b3d30a3-34fb-5f22-a05f-52a4f91ab9f8', '2ffd8cfb-fa6d-5cd8-a78f-7e5a04580e90', 'b4066b4d-cb25-5471-a1e3-9b7e39e28de5', 49, 49, 'ወድያው የብርሃን ደመና መጥቶ አዳምን ተሸከመው ወደገነትም ወሰደው የመላእክት ሠራዊት በዚህ ጊዜ ከአዳም ፊት ለፊት ከምስጋና ጋር ከማሕሌት ጋርና ከዝማሬ ጋር በጥዑም ዜማ እግዚአብሔርን እያመሰገኑ ይጓዙ ነበር። ኪሩቤል ባንድ በኩል ሲባርኩ ሱራፌልም ይቀድሱ ነበር። አዳም ወደገነት ዓርብ በሦስስት ሰዓት ገባ።'),
  ('c185b206-caf1-5440-ae92-435cedf7cd82', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 1, 1, 'እግዚአብሔር አዳምን ትእዛዛትን ሁሉ እንዲፈፅም አዘዘው በተለየም በገነት ከምትገኘዋ ዕፅ እንዳይበላ አዘዘው ወድያውም እግዚአብሔር በአዳም ላይ የሚጣፍጥ እንቅልፍን አመጣ እሱም በገነት ተኛ።'),
  ('fdbbacf9-1a82-535d-a7af-0f64b85dd320', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 2, 2, 'እግዚአብሔር ከአዳም ግራ ጐድን አንድ አጥንትን ነቀለ ከዚሁም ሔዋንን ፈጠራት አዳም ሔዋንን ባያት ጊዜ (ከእንቅልፍ ነቅቶ) እጅግ ደስተሰኘ በጣምም ወደዳት።'),
  ('946b2b1e-8bb5-5129-a7a7-c63b54d4faa8', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 3, 3, 'እነሱ በገነት ኤዶም ሲኖሩ እግዚአብሔር ክብርንና ግርማን ምሥጋናን አለበሳቸው እነሱም እጅግ እያመሰገኑ ደስ አላቸው ስለተሠጣቸውም ግርማና ትልቅ ምሥጋና በበለጠ ደስ ተሰኘ እግዚአብሔርም ለጋብቻ ወሰነላቸው መላእክት ሁላቸውም ስለአዳምና ሔዋን ደስ አላቸው።'),
  ('b5030fd6-1e69-558f-a6f7-6fd460118cdb', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 4, 4, 'ወልድ በግርማ መንግሥቱ ደግሞ ሲመጣ በቀኝ በኩል ከቆመት ይህን የመሰለ ደስታ እስኪሰማ ድረስ ከዚያ በፊት ተሰምቶ የማያውቅ ደስታ ተሰማ።'),
  ('86829d2a-1e35-52c8-a8b8-bcda3ad63f80', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 5, 5, 'አዳምና ሔዋን በገነት ለሦስት ሰዓታት ያህል ኖሩ ገነት ከነፋሳት ላይ ሁና መሬትዋ ሰማያዊ ነው ከረጃጅም ተራራዎች በላይ ትገኛለች ከረጃጅም ተራራዎች ገነት የምትገኝበት ከፍታ አሥራአምስት ሜትር ነው።'),
  ('c750872c-64d1-52bc-a502-cfb5c69ba100', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 6, 6, 'ገነት ክርስቶስ እጆቹን ዘርግቶ የተሠቀለበት ዕፀመስቀል ምሳሌናት ቅዱስ መስቀል በምድር ላይ ተተክሏል።'),
  ('e7a5a0e8-9343-51f5-a45b-eee35f559883', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 7, 7, 'ሠይጣን ግን በክፋቱ ከእግዚአብሔር ለአዳምና ሔዋን በተሠጠው ፀጋ ሁሉ ይቀና ነበር። በአውሬም እያመኻኘ ሠይጣናዊ ተግባሩንና ሠይጣናዊ ምቀኝነቱን ለማካሄድ ተነሳ።'),
  ('6ace4ac8-e4a7-514b-ac73-97fe22159a64', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 8, 8, 'ይህ አርዌ ከአውሬዎችና ከእንስሳት ሁሉ የአስተያየቱ ውበት ያማረ ነበር። የመጀመርያው አፈጣጠሩ በግመል ግልገል መልክ ነበርና።'),
  ('6b25c255-f1e6-52be-afa1-491a2d461f10', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 9, 9, 'ከዚያ በኋላ ሠይጣን የምድር አርዌን ተሸክሞ ወሰደው ወደገነትም አስገባው ከዚህ የተነሳም ሠይጣን መልኩ አስደሳች በሆነው የምድር አርዌ ላይ ተደበቀ። እግዚአብሔር አሳድሮለት የነበረውን የክብር ልዕልና ካስወገፁበት ጀምሮ መልኩ እጅግ የከፋና ማንም ወደሱ መመልከት የማይችል ሁኗል።'),
  ('242e2658-b607-554b-a265-fdb7655f667c', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 10, 10, 'ሔዋን በምድር አርዌ ውስጥ ተሠውሮ ባያናግራት ነሮ ከሱ ጋር መነጋገር ቀርቶ ደንግድጣና ፈርታ በሸሸች ነበር።'),
  ('5adbb51d-e0d5-56a8-ae4e-151917abf657', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 11, 11, 'ነገርግን ይህ ሠይጣን በሰው ቋንቋ እየተናገረ ወፍን የሰው ንግግር እንደሚያስተምር ብሩህ የሆነችንም መስታወት አንስቶ በራሱና በወፉ መካከል እንደሚኖር በመምሰልና ወፉን በፈለገው ቋንቋ እንደሚናገረው እንደሚያስተምረው በመምሰል አመካኘ።'),
  ('6db067af-c7f2-56df-a94e-4635a610f629', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 12, 12, 'ወፍ የራሱን ምስል በመስታወት ካየ ያየውን አይጥልም እሱ ራሱ ወደሱ የመጣ ይመስለዋል ከመፅሔቱ የሚታየውንም ምስል ትምህርት ለመማር ወደሱ ይመጣል።'),
  ('ead4710d-aebe-5eab-accf-ca024c194cfc', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 13, 13, 'እንደዚሁ ሁሉ ሠይጣን ወደአውሬው በገባ ጊዜ ወደሔዋን ሄደ ። ብቻዋ በገነት ላይ ቁማ ካለችበትም ደረሰና በስሟ ጠራት ። እሷም ዞር ብላ ተመለከተችው የራሷንም መልክ እንደመስታወት አስመስሎ አሳያት በቃሉም አሳታት።'),
  ('99357fb6-0d24-56ed-a607-4de2e8e8229b', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 14, 14, 'ሴት በተፈጥሮዋ ደካማ ናት የሰማችውን ሁሉ ምንም ሳታመዛዝን ዓሜን ብላ ትቀበላለችና።'),
  ('c118767b-8267-53bb-a58f-0c01a4ee57ea', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 15, 15, 'ሠይጣን በተንኰሉና በክፋቱ ብዛት ያነጋገራት በገነት ስላለችው ዕፅ ነው ዕጿ ጣፋጭ መሆንዋን ከመናገሩ በላይ እሷን ከበላሽ 13 አምላክ ትሆኛለሽ አላት።'),
  ('39a5ddde-ca69-51b1-aff6-dbf3c4d1437b', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 16, 16, 'እሷ ልዑል እግዚአብሔር ከዚች ዕፅ እንዳይበላ አዳም መታዘዙን አልሰማችም ነበርና ሠይጣን ጣፋጭነቷን ከነገራት የገነት ዕፅ ፍሬ ለመብላት ወደደች።'),
  ('f5ad385c-7714-580f-ab26-26d5239e556d', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 17, 17, 'ሠይጣንም በፍጥነት ሄዶ ከዕፁ ፍሬ ሠጣት እሷም በፍጥነት ወደአዳም ሄደችና ፍሬውን ሠጠችው ይህን ከበላህ አምላክ ትሆናለህም አለችው ።'),
  ('db192eca-0d5b-5a60-ae47-9a127f4246b3', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 18, 18, 'አዳም የሔዋንን ቃል ሰሞቶ አምላክ ለመሆን ወደደ እሷ እንዳለችው ሁለቱ ፍሬውን በበሉ ጊዜ ዕራቁታቸው ሆኑ የለበሱት ፀጋ እግዚአብሔር ከላያቸው ተገፈፈ በነሱ ላይ ከነበረው ፀጋ እግዚአብሔር ተገፎ ዕራቁታቸው ሲሆኑ ሐፍረታቸው ተገለጠ።'),
  ('0dbd5128-cb96-57e8-af88-da24bfb4b938', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 19, 19, 'በዚህ ጊዜ ከበለስ ቅጠል ቈርጠው ዕርቃናቸውን ለመሽፈን ያህል ቈርጠው ታጠቁ ለከባድ ሐዘን ተጋለጡ ሦስት ሰዓት ሙሉ ያለዕረፍት አለቀሱ አዳም ወደገነት የገባው በእለተ ዓርብ በሦስት ሰዓት ነው ከገባም ጀምሮ በመንፈሳዊ ፀጋና በንጉሥነት ይገኝ ነበር። ይህም እግዚአብሔር ለሁለቱ የሠጣቸው ነው። እግዚአብሔር ሁለቱን ብዙ ወቀሳቸው ዘጠኝ ሰዓት ሲሆን በብዙ ልቅሶ በብዙ ዋይታና ጩኸት ሳይወዱ በግድ ከገነት ተባረሩ።'),
  ('50c58fe6-2f90-5850-a6b8-aed2b60b19b8', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 20, 20, 'የበለስን ቅጠል ለብሰው ከቈዩ በኋላ እግዚአብሔር ቁርበትን አለበሳቸው ይህንንም ቁርበት የሐዘን ልብስ ነው።'),
  ('cba86eb6-3cb1-517f-ab3b-60a63b675714', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 21, 21, 'አዳምና ሔዋን ከገነት ወጥተው ከገነት ወደስተምሥራቅ በኩል ተኙ ከእንቅልፋቸውም ሲነቁ እግዚአብሔር አዳምን ተናገረው እንዲህም አለው አትዘን እነሆ ትእዛዜን አፍርሰህ ከወጣህበት ገነት መልሼ እንድትገባ አደርጋለሁ።'),
  ('309db599-0f4b-5a10-aacf-f5b81568a675', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 22, 22, 'እንግዲህ ልብ በል በአንተ የሥሕተት ሥራ ምድርን ረገምኩዋት ይህም ባንተ በደልና ሐጢአት ምክንያት ነው ዳግመኛም ሔዋንን ስላሳታት እባብን ረገምኩት እጅና እግሩንም ወደሆዱ እንዲገባና ምግቡም አፈር እንዲሆን አደረግሁ።'),
  ('b211ce7a-4935-590c-a4c1-5ea8159c3230', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 23, 23, 'አንተን ግን አልረገምኩህም ሔዋንን ግን ካንተሥር እንድትሆን ፈርጀባታለሁ እንግዲህ አስተውል ባንተ ላይ የፈረድኩትን ፍርድ ስትጨርስ ባንተና በሔዋን ምክንያት ምድር ስለተረገመች በኋላ ልጀንና ወዳጄን እልከዋለሁ እሱም ከሰማይ ወደምድር ይወርዳል ማርያም ተብላ ከምትጠራው ድንግልም ይወለዳል እሷም ያንተ ዘር ናት።'),
  ('24cdd45b-04e0-5ae6-ad6d-de6133e89592', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 24, 24, 'እሷንም እገነባትና እመርጣታለሁ ትውልድ አልፎም ትውልድ እየተተካ ወልድ ከሰማይ እስኪወርድ ድረስ ይቈያል።'),
  ('7e8479fe-7d1d-5088-abeb-8c2cc2cace49', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 25, 25, 'በዛን ጊዜ የድሕነትህ መጀመርያ ይሆናል ወደ ርስትህም ትመለሳለህ አንተ በሞትክ ጊዜ ከርቤና ዓልው በተባሉ የሽቱ ዓይነቶች ቀብተው አሥከሬንህን በቤተመዛግብት ያኖሩት ዘንድ ልጆችህን አዛቸዋለሁ ልጆችህ ከደብር ቅዱስ እስኪመጡ ድረስም ከዚያ ትቆያለህ።'),
  ('51185363-bd06-5ca0-af96-0d1b4b025ba2', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 26, 26, 'ወደተረገመች ምድርም ልጆችህ ይሰበሰባሉ ልጆችህንም ጋር በቤተመዛግብት ተጠብቆ ከኖረ በኋላ ሥጋህን ከነሱ ይውሰዱት እኔ ወደ ማመለክታቸውም ቦታ ይውሰዱት።'),
  ('0b045c0d-410f-5f88-ad06-c8c8df65f010', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 27, 27, 'ያ ቦታ ያንተን ሥጋ ካኖሩበት በኋላ ዘመን ያንተን መድሐኒትና የልጆችህንም መድሐኒት እንዲገለፅበት (እንዲፈፀምበት) አደርጋለሁ። ያ ያንተን ሥጋ የሚያኖሩበት ቦታ ለወደፊት ያንተን ድሕነት የማሳይበት ቦታ ይሆናል በዚሁም ያንተና የልጆችህ ድሕነት ይገለፃል አለው እግዚአብሔር ለአዳም ለወደፊት በዚች በተረገመች ምድር ሐዘን መከራና በሽታ እንደሚፈራረቁባት ከነገረው በኋላ እንዲታገሥ ነግሮታል።'),
  ('bbba716a-e5bc-5e3e-ad20-117c796b3983', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 28, 28, 'አዳምና ሔዋን ከገነት በወጡ ጊዜ እግዚአብሔር በገነት በር ላይ እሳታዊ መልአክን አቆመ ይህ መልአክ በእጁ ላይ የእሳት ጦር ነበር።'),
  ('17a71168-a7bd-57d7-a7d4-aa4cf69589f0', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 29, 29, 'አዳምና ሔዋን መጥርዮን ተብሎ ከሚጠቀስና በገነት በታች ከሚገኘው ደብር ቅዱስ ኖሩ።'),
  ('bd45717a-45c3-5ecd-a06f-c42ad5cba6e5', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 30, 30, 'በዚሁ ደብር ላይ ባንድ ዋሻ ውስጥ በንፅሕና ና በድንግልና ሁነው ለመኖር ቻሉ።'),
  ('ab243bed-4647-566e-a815-92cddcf86de6', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 31, 31, 'አዳም ከሔዋን ጋር እያለ ከገነት እግርጌ ወርቅን ከርቤንና ዕጣንን ያዘና ቀደሰው ባረከውም በዚች ዋሻ ለራሱ የጸሎት ቦታ አዘጋጅቶ ነበርና ይህንንንም ወርቅ ዕጣንና ከርቤ አጥን ሠጣት እንዲህም አላት ይህንን ሁሉ ያዥ እጅ መንሻ ነውና አምሃነቱም ወልደ እግዚአብሔር ወደዚህ ዓለም ሲመጣ ይሆናል።'),
  ('6bcc8df6-85b0-545e-a128-ea72924de256', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 32, 32, 'ወርቅ የወልደ እግዚአብሔር መንግሥት ምልክት። ዕጣን የህላዌ መለኮቱ ምልክት ከርቤ ከኛ ለሚለብሰው ክቡር ሥጋው መገነዣ ናቸው። ይህም ወልደ አምላክ እኛን ለማዳን ወደዚህ ዓለም በሚመጣበት ጊዜ በኔና ባንቺ መካከል ምስክር ይሆናል አለ።'),
  ('1982c242-7baf-5143-aabc-60ec196ed919', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 33, 33, 'አዳም እቺን ዋሻ ቤተመዛግብት ብሎ ሰየማት አዳምና ሔዋን ከገነት ወጥተው አሥር ዓመት በሙሉ በልቅሶ በዋይታና በታላቅ ሐዘን ነበሩ።'),
  ('6cf2998e-e45c-585d-ae78-9b584b687ce1', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 34, 34, 'አዳምና ሔዋን ከደብር ቅዱስ ወርደው ከሱ በታች ተቀመጡ በዚሁ አዳም ሔዋንን ተገናኛት እሷም ፀነሰች የመውለጃዋ ጊዜም ደረሰ ቃየልንና ሉድንም መንታዎች ወለደች።'),
  ('3a2ab720-a73d-5930-a400-3dbd18164c2f', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 35, 35, 'ዳግመኛም ሔዋን ፀነሰች የመውለጃዋም ጊዜ ደረሰ መንታዎቹን አቤልንና አቅሌምያንም ወለደች።'),
  ('925ba0ae-346c-5477-acf1-2a0c8a221b6a', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 36, 36, 'እነዚህ ሁለት ወንዶችና ሁለት ሴቶች የአዳም ልጆች አድገው ለጋብቻ ደረሱ። አዳም ይህን ተመልክቶ ሔዋንን እነሆ እግዚአብሔር እነዚህ ልጆቻችንን አሳደጋቸው ስለዚህ ቃየል የአቤልን እህት ኣቅሌምያን ያግባት አቤል ደግሞ የቃየልን እህት ሉድን ያግባት አላት።'),
  ('c4628b7f-4817-5c7c-ad5f-180ac72c54fa', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 37, 37, 'አዳምና ሔዋን በዚሁ ተስማሙ ቃየል ግን እናቱን ሔዋንን እናቴ ሔዋን ሆይ ለኔ ሚስት ትሆነኝ ዘንድ ከኔጋር የተወለደችውን ሉድን ልትሠጡኝ ይገባል ለአቤል ደግሞ ከሱ ጋር የተወለደችውን እህቱ አቅሌምያን ሚስት ትሆነው ዘንድ ትሠጡት ይገባል አላት።'),
  ('fe8b7e8d-054f-5324-a40c-b957a0d20623', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 38, 38, 'ቃየል እንዲህ ሊል የቻለበት ምክንያት የሉድ መልክ እንደናቷ ሔዋን መልከ መልካም ስለነበረ ነው አዳም የቃየልን አባባል ሰምቶ እጅግ አዘነ ቃየል ሆይ አንተ ካንተ ጋር የተወለደችውን መንትያህ ልታገባ አይገባም ህግ አይፈቅድምና አለው።'),
  ('d86f8ffb-1a12-50ed-ab08-513cd7e05395', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 39, 39, 'በዚህ ጊዜ በቃየል ላይ ቅንዓት አደረበት ወንድሙን አቤልንም ለመግደል ፈለገ። ወድያው አባታቸው አዳም ለአቤልና ለቃየል ለእግዚአብሔር መስዋዕትን ታቀርቡ ዘንድ ከምድር ፍሬና ከበግ ግልገሎች መርጣችሁ አቅርቡ አላቸው።'),
  ('eef7b538-ecd3-50ee-a644-ead1d8472a96', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 40, 40, 'አዳም ንግግሩን በመቀጠል እንዲህ አላቸው ወደደብር ቅዱስ ውጡ ከዚሁ ወደሚገኘው በዓተ መዛግብትንም ግቡ ከዚሁም ሁናችሁ በመጀመርያ ለእግዚአብሔር ጸሎት አድርሱ ወድያውም የተሸከማችሁትን ፍሬና በግ ለቁርባን አቅርቡ።'),
  ('567149d3-0447-534f-a95b-186ee038f2f9', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 41, 41, 'ይህን ከፈፀማችሁ በኋላ የየራሳችሁን ሚስቶች ትወስብችሁ።'),
  ('79f2f4dc-cbc6-507a-aff4-b0e7b1ae8a19', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 42, 42, 'ሁለቱ ወንድማማች ቃየልና አቤል አባታቸው ኣዳም እንዳዘዛቸው አዳረጉ ወደደብር ቅዱስ በመውጣት ላይ እያሉም ሠይጣን ወደቃየል ልብ ገባ አቤልን ወንድሙን ለመግደል እንዲነሳሳ አደረገው።'),
  ('36d0e974-5959-5539-aac6-e5316a3b6830', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 43, 43, 'ሁለቱ ቃየልና አቤል ቁርባናቸውን በእግዚአብሔር ፊት አቀረቡ እግዚአብሔር ግን የአቤልን መሥዋዕት ተቀበለ የቃየል መሥዋዕትን ግን አልተቀበለም። እግዚአብሔር የቃየልን ወንድሙን ለመግደል መነሳሳቱን አውቋልና።'),
  ('8f444282-0ad0-5297-a199-6bc5ade61b0b', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 44, 44, 'ቃየል የሱን መሥዋዕት ሳይቀበል እግዚአብሔር የዓቤልን መስዋዕት መቀበሉን ሲመለከት ቅንዓቱ ዕጥፍ ሆነ ቅንዓቱ ቁጣውና ንዴቱ ተጨመረ።'),
  ('20f88b36-a0e7-58d4-a537-40cafec3569e', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 45, 45, 'ከደብር ቅዱስ አቤልና ቃየል እየወረዱ እያለ ቃየል በአቤል ላይ ጨከነ በድንጋይም ማህል ራሱን መትቶ ገደለው።'),
  ('ec673ec2-4a01-5798-ac30-303959edeb5e', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 46, 46, 'እግዚአብሔር ወንድሙን አቤልን በመግደሉ ረገመው በሱ ላይ ልዩ ምልክት አሳደረ በፍርሐት በድንጋጤና በጭንቀት ይኖር ዘንድም አደረገው እሱንና ሚስቱንም ከደብረ ቅዱስ ወርደው በተረገመች ምድር እንዲኖሩ አደረገ።'),
  ('9f8fc9eb-6b4b-597d-a125-b729ec05e8fd', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 47, 47, 'አዳምና ሔዋን ባሉበት ሁነው በአቤል ሞት ምክንያት አዘኑ አለቀሱም ከዚህም በኋላ አዳም ሔዋንን ተገናኛት እሷም ፀንሳ ሴትን ወለደችው ሴት መልከ መልካም ብርቱ። ፅኑና መላ ቁመናው እንዳባቱ አዳም ሆነ እግዚአብሔርም በዚች ምድር ለሚኖሩ ሐያላን ሁሉ አባታቸው ይሆናቸው ዘንድ አደረገው።'),
  ('29c94b0e-14a3-583f-a174-e37d6cfaa895', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 48, 48, 'ሴት ከቃየል ጋር ተወልዳ ለአቤል ተሠጥታ የነበረችውን ሉድን አገባት ከዚያበኋላ ሄኖስን ወለደው ሄኖስ ቃይናንን። ቃይናን መላልኤልን ወለዱ።'),
  ('3f17e85e-d673-5f30-a0d1-44558fdb9636', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 49, 49, 'እነዚህ አበው አዳም በሕይወት እያለ ነው የተወለዱት ከዚያ በኋላ አዳም ዘጠኝ መቶ አምሳ ዓመት ኖረ አዳም እያለ መላልኤል የመቶ ሠላሳ ስምንት ዓመት ሰው ሁኖ ነበር።'),
  ('30f1dfb5-080f-568b-aae2-2536c0197861', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 50, 50, 'አዳም የመሞቻው ጊዜ ሲደርስ ሴትን ሄኖስን ቃይናንንና መላልኤልን ወደሱ ጠራቸው በነሱ ላይም ጸለየ ባረካቸውም ልጁ ሴትንም ልጄ ሴት ሆይ የማዝህና የሞነግርህን ነገር ሁሉ ልብ ብለህ ስማ ወደልብህም አስገባው።'),
  ('48f30190-dc48-5ae5-a3d0-1656bc39e927', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 51, 51, 'ከዚህ ዓለም የሞትለይበት ጊዜ ሲደርስ ልጅህ ሄኖስን እንዲህ ብለህ እዘዘው አንተ ቃይናንን እዘዝ ቃይናንም መላልኤልን ይዘዘው በዚሁም መንገድ ቅደም ተከተልን ይዘው ልጆችህ ይዘዙ ይህችንም ትእዛዝ ይጠብቁ።'),
  ('a560fdf9-0892-533a-a38f-e832bda86335', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 52, 52, 'ትውልድ አልፎ ሌላ ትውልድ እየተተካ ሕዝብም አልፎ ሌላ ሕዝብ ሲተካ እኔ በሞትኩ ጊዜ የኔን ሥጋ በተለያዩ መልካም ሽቶ ዓይነቶች ቀብተህ ጠብቀው በበዓተ መዛግብት (በደብረ ቅዱስ)ም አኑረው ጎረቤቶችህና ልጆችህ ከደብር ቅዱስ ወጥተው ወደገነት እስኪገቡ ድረስም ከዚያ ይኑር።'),
  ('9412e4b1-c08b-51da-aeb7-cf562ce0d64a', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 53, 53, 'ሥጋህንም ይሸከሙ ከነሱ ጋርም ወስደው ያስቀምጡት ትልቅ አጠባበቅንም ያድርጉለት በምድር ላይ በዚችም ምድር ያን ጊዜ ያንተ ድሕነትና የኔንም ሆነ የኔ ልጆችም ድሕነትን የሚያገኙት ከዚህም በማያያዝ ሕዝቦችህን ጊዜ ያን ጊዜ ይሆናልና። በመልካም አመራር ምራቸው እግዚአብሔርንም እንዲፈሩ አስተምራቸው።'),
  ('bff20d56-94d3-5150-a3cc-78d63c140596', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 54, 54, 'ራስህንና ልጆችህን ከነፍሰ ገዳዩ አቤል ቤተሰብ አርቅ የቀንንና እያፈራረቅህ የሌሊትንም ሰዓቶች አስተውል ሰአታቶቹ እግዚአብሔርን የምታመሰግንና እሱንም የምትለምን እንድትሆን። ይህንን ሁሉ አምላኬ አስተምሮኛል የእንስሳትንና አራዊትንም ሁላቸው ስም ነግሮኛል የሰማይ ወፎችንም ስም ነግሮኛል።'),
  ('9aaad36f-c1c2-5b79-a3f8-6411fec84c62', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 55, 55, 'ከዚህም በላይ እግዚአብሔር የቀን ሰዓቶችን ቁጥር ነገረኝ ከዚሁም ላይ መላእክት እሱን እንዴት እንደሚያመሰግኑት ገለፀልኝ።'),
  ('9e174092-cbf1-55a0-a003-c8bfeebcb030', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 56, 56, 'ልጄ ሆይ ማስተዋል ካንተ አይለይ። በመጀመርያው የልጆቼ ጸሎት ወደአምላክ ይቀርባል በሁለትኛው ሰዓት የመላእክት ጸሎትና ምልጃቸው ወደእግዚአብሔር ይቀርባል በሦስተኛው ቀን ወፎች አምላክን ያመሰግናሉ።'),
  ('ea84a6d7-5b15-531b-a642-64e5278208f4', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 57, 57, 'በአራተኛው ዕለት መንፈሳውያን እግዚአብሔርን ያመሰግኑታል ያመልኩታልም በአምስተኛው ቀን እንስሳና አራዊት ሁሉ ያመሰግኑታል በስድስተኛው ዕለት የኪሩቤል ምስጋና ይቀርባል በሰባተኛው ቀን መላእክት ወደ እግዚአብሔር ይገባሉ። አክሱም ዘንድ ይወጣሉ በዚችው ዕለት የሕያዋንን ሁሉ ልመናቸው ያቀርባሉና።'),
  ('5116763f-bf03-59c5-a237-0cfa4526b610', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 58, 58, 'በስምንት ሰዓት ብሩሃን ሰማያውያን እግዚአብሔርን ያመሰግናሉ በዘጠኝ ሰዓት መላእክት ለእግዚአብሔር ይገዛሉ በልዑል እግዚአብሔር መንበር ፊትም ይቆማሉ በአሥር ሰዓት መንፈስ ቅዱስ በውሆች ላይ ያንዣብባል በዚህ ጊዜ አጋንንት ከውሃው ወጥተው ይባረራሉ ከውሃም ይወገዳሉ።'),
  ('42f8d1e1-2f3f-5015-a18d-a12a1ac8dace', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 59, 59, 'መንፈስ ቅዱስ በውሆች ላይ በያንዣብብ ኑሮ በዚችው ሰዓት ሁልጊዜ ማንም ሰው ውሃን ለመጠጣት ባልቻለም ነበር። አጋንንትም የሰውን ሥጋዊ ሕይወት እያሳመሙ ሰውን ሁሉ በጨረሱ ነበር።'),
  ('38b5883d-07d3-5b6d-a953-ed1153de3323', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 60, 60, 'በዚችው ሰዓት ካህን የተቀደሰውን ዘይት በውሃ ጨምሮ በአጋንንት የተያዙና በሌላም ደዌ የተያዙትን በሽተኞች ቢቀባበት ካደረባቸው ደዌ ይፈወሳሉ።'),
  ('091684b9-18d2-5ba7-a371-0238c831a0e3', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 61, 61, 'በአሥራ አንድ ሰዓት (ከቀኑ) የጻድቃን ደስታ ይበዛል በአሥራሁለት ሰዓት ልዑል እግዚአብሔር የሁላቸውን የሰው ልጆች ጸሎትና ልመና ይቀበላል።'),
  ('b10c2cde-3071-5a89-a51a-7946e99e872f', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 62, 62, 'በምሽቱ አንድ ሰዓት አጋንንት ልዑል እግዚአብሔርን ያመሰግኑታል በዚች ሰዓት ውስጥ ማነኛውንም ሠይጣናዊ ተግባራቸው ያቆማሉ የእግዚአብሔርንም ተገዢነታቸው እስኪወርሱ ድረስ በሰው ላይ አደጋ አያደርሱም።'),
  ('44f10536-fa58-5da6-affc-67467673f042', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 63, 63, 'በሁለተኛው ሰዓተሌሊት አሦችና ማነኛውም በውሃ ውስጥ የሚንቀሳቀስ አውሬዎችና ነብሮች እግዚአብሔርን ያመሰግኑታል በሦስተኛው ሰዓተ ሌሊት እሳት እግዚአብሔርን ታመሰግነዋለች የእሳት ምሥጋና እስከ መትሕተ ታሕቲት ይደርሳል በዚችው ሰዓት ማንም መናገር አይችልም።'),
  ('ddac6ccf-e8db-589c-afcd-bc7f3d59c7d2', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 64, 64, 'በአራተኛው ሰዓተሌሊት ሱራፌል እግዚአብሔርን ያመሰግኑታል ባምስተኛው ሰዓተ ሌሊት ከሰማያት በላይ ያሉ ውሆች እግዚአብሔርን ያመሰግኑታል።'),
  ('7a59d014-3002-5aa4-aea7-593d5c815cfd', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 65, 65, 'ከገነት በነበርኩ ጊዜ መላእክት በዚችው ሰዓት እግዚአብሔርን ሲያመሰግኑት እሰማቸው ነበር። ድምፃቸውም እንደትላልቅ መንኩራኩር ይሰማኝ ነበር። ሞገዶችም ለደገኛው እግዚአብሔር በከፍተኛ ድምፅ ምስጋና ሲያቀርቡ እሰማ ነበር።'),
  ('10f03c02-b13a-551c-a46f-236e381ebea0', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 66, 66, 'ከሌሊቱ በስድስት ሰዓት ደመናዎች ብርሃናትና በረድ እግዚአብሔርን ያመሰግናሉ ከሌሊቱ በሰባት ሰዓት የብዙ ሱባዔ ያርጋል ይፈፀማልም በኋለኛው ዘመን ። ሁሉ ይፈፀማል ጊዜውም ይደርሳል አንተም ያገኘኸውን ሁሉ ትበላለህ (እግዚአብሔር ፊት) ምድርም ትቀደሳለች ወደሷም የጌቶች ጌታ እግዚአብሔር ይሄዳል።'),
  ('c643a0ae-0099-588a-a1b3-74df0b64fc24', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 67, 67, 'ሴት በራሱ ማሕተም ባባቱ አዳም ማሕተምና በናቱ ሔዋን ማሕተም ከሱ ጋር የወሰዳቸውን ልጆቹንም የልጅ ልጆቹን ሁሉ ጻፈ ይህንን ያደረገበት ምክንያት ካባቱ አዳም ስለነ ነው።።'),
  ('6e8da7e5-db67-5815-aaca-3f44816ec084', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 68, 68, 'እነዚህ የሴት ልጆች በሙሉ በሴት አማካይነት ወደ አዳም ተሰብስበው አንድም ሳይቀር ቀረቡ አዳምም ስለነሱ ድሕንነት ስለሰላምና አማላጅነት ብዙ ጸሎት ወደ እግዚአብሔር እየፀለየ ብዙ ሰዓታትን ካሳለፈ በኋላ ባረካቸው።'),
  ('eaff2445-828f-5b6c-ad95-ef5d04235cba', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 69, 69, 'አዳም በዘጠኝ መቶ አምሳ ዓመቱ ሞተ በመገነዣውም ጊዜ የመላእክት ሠራዊት በሙሉ ተሰበሰቡ አዳም በእግዚአብሔር ዘንድ ታላቅ ክብር ተሠጥቶታልና ነገር ግን የገነዘው ልጁ ሴት ነው። ሴት የአዳምን ሥጋ ከገነት በስተምስራቅ አቅጣጫ በታቦት ውስጥ አስቀመጠው ይህ ቦታ እግዚአብሔር ከገትት ባወጣቸው ጊዜ አዳምና ሔዋን የኖሩበት ነው።'),
  ('f8ee38af-f9bf-5c11-a928-037e21437a50', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 70, 70, 'አዳም በሞተ ጊዜ ፀሐይና ጨረቃ ለሰባት ቀንና ለሰባት ሌሊት ጨለሙ ያ የጻፈውንም የትእዛዝ መፅሐፍ ሴት በቤተመዛግብት አስቀመጠው ለቁርባን የተባለውንም ዕቃ ከዚሁ ጋር አስቀመጠው ለቁርባን የተባለው ዕቃ ሴት ከገነት የወሰደው ዕጣን። ወርቅና ከርቤ ነው። ስለዚህም አዳም ለሴት ይህ ዕጣን ከርቤና ወርቅ ወደ ሦስቱ የሰብዓ ሰገል ነገሥታት እጅ ይገባል እነሱም ክርስቶስ መድሐኔዓለም በቤተልሔም ሲወለድ ለእጅ መንሻ ይወስዱታል አለው።'),
  ('0fe13c3f-685b-516e-a120-76c37f4b0564', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 71, 71, 'አዳም ዓርብ በሦስት ሰዓት ሚያዝያ ሰባት ቀን በጨረቃ አቈጣጠር አራት ቀን ሞተ ጌታችን ኢየሱስ ክርስቶስም በተመሳሳይ ሰዓት ነፍን መዳባቱ አደራ ብላን።'),
  ('1ed26301-12e0-51d7-a4c0-264c39206634', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 72, 72, 'በአዳም ልጆችና በልጅ ልጆቹ ትልቅ ሐዘንና ልቅሶ ሆነ አርባ ቀን ሙሉ ሳያቋርጡ አለቀሱ። አዳም ከሞተ ጀምሮ ነገደ ሴትና ነገደ ቃየል ለሁለት ተከፈሉ።'),
  ('1a0f0d8a-8cf4-5820-ad65-fb058b5cc9ea', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 73, 73, 'ሴት ልጆቹን የልጅ ልጆቹንና ሚስቶቻቸውን ወደደብር ቅዱስ አስወጣቸው አዳም ከዚሁ ነሯልና ቃየልና ልጆቹ እንዲሁም የልጅ ልጆቹ ግን ከደብር ቅዱስ በታች ከሚገኘው ቦታ ውስጥ ይኖሩ ነበር። አቤል በዚሁ ነው የተገደለው።'),
  ('8ebd9baa-2bf3-59b6-a20c-f4bde6927df6', '6575e998-11f1-5f0d-abc1-a72d4f4677db', '0dff62dd-a401-5071-a3a2-168b11e310b9', 74, 74, 'ሴት ሕዝቦቹን በቅድስናና በንፅሕና ያስተዳድራቸው ነበር። ካባቱ አዳም የተነገረውንም ዜና አስተማራቸው።'),
  ('51507780-0459-58be-a427-aab4d6fea0d3', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 1, 1, 'ልጄ ቀሌሚንጦስ ሆይ ጌታችን መድሐኒታችን ኢየሱስ ክርስቶስ በተወለደ ጊዜ ሰብአ ሠገል ወደቅድስት ድንግል ማርያም መጥተው ነበር። ከነሱ ጋር አብሮ አንድ መፅሐፍ መጥቷል ከዛሬ ጀምሮ ለብዙ ጊዜ የምነግህ ምሥጢር ከዚሁ መፅሐፍ የሠፈረና የተገኘ ነው። የአዳም ልጅ ሴት ስለተባለበትንም ምክንያት እገልፅልሃለሁ።'),
  ('121da769-37bc-555a-a118-b020372b7919', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 2, 2, 'ሴት ማለት እግዚአብሔር ሆይ ጤና ሥጥ ማለት ነው። አዳምና ሔዋን በንፅሕናና በቅድስና ኑረዋል ስለህም እግዚአብሔር ከስሞች ሁሉ እጅግ ከፍ ያለውን ነገር ።።'),
  ('f242fb4e-f6cb-56af-aabb-007e1c16f8b8', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 3, 3, 'ሴትና ሕዝቡ ከገነት በታች ከምትገኘው ደብር ቅዱስ ላያ ኖሩ ። ከዚህም ሁነው እግዚአብሔርን መቀደስና ማመስገን ብቻ ሥራቸውን አደረጉ የዚህን ዓለም ትካዜ ፈፅሞ አይታያቸውም ነበር። ከምሥጋና በቀርም ሌላ ሥራ አልነበራቸም ምግባቸውም ከደብር ቅዱስ የተተከሉት የዛፍ ፍሬዎች ነበር።'),
  ('5e401d4a-84df-5b99-a140-a2e77f09d398', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 4, 4, 'የደብር ቅዱስ ዛፎች ፍሬ እጅግ ጣፋጭ ነበር። ይህ ምክንያት መልካም መዓዛ ከገነት እየተነሳ ወደነሱ ይገባ ስለነበር ነው።'),
  ('bd67130e-af2e-5c33-ab91-0efde6cba450', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 5, 5, 'እነዚህ ህዝቦች በፅድቅና በደግነት ብቻ ይኖሩ ነበር። ቂም ቅንኣት ነገሠሪነት ትዕቢት የስድብን ነገር ማስብ ፈፅሞ ከነሱ ዘንድ አልነበረም ሐሰትንም መናገርና ማስብ ፈፅሞ ከያንዳንዳቸው ህሊና ርቆ ነበር።'),
  ('6f9a891c-0a34-559d-a82a-01e84c07183a', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 6, 6, 'የእግዚአብሔርን ምህረት በፈለጉ ጊዜ መንፈስ ቅዱስ በውሆች ላይ ያንዣብባል ምድርም በመለዋ ፀጥ ትላለች በሷ ላይ ያለውም ሁሉ እንዲሁ ፀጥ ይላል ውሆችም ይተኛሉ በዚህ ጊዜ ካህን ተነስቶ ቅዱስ ቅብእን ከውሃ ጋር በማደባለቅ የታመሙትን ቢቀባቸው እንቅልፍ ያጡትንም ቢቀባቸው ከደዌአቸው ይፈወሳሉ እንቅልፍ በማጣት የተቸገሩትም እንቅልፍ አግኝተው ይተኛሉ።'),
  ('f4636851-0922-5ec1-abe0-37205e8b0239', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 7, 7, 'በስምንተኛው ዕለት ምድር ሣዕርንና ልምላሜን ታበቅላለች የተለያዩ ዕፀዋትንም ታበቅላለች።'),
  ('c3fbadfc-3460-5949-a044-96aabdb18755', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 8, 8, 'በዘጠኝ ሰዓት መላእክት ለእግዚአብሔር ይገዛሉ የሰው ልጆችም ሁሉ ጸሉት ወደልዑል እግዚአብሔር የምትደርሰው በዚሁ ሰዓት ነው።'),
  ('5024fa82-91d0-5da6-ae45-70dc391f0bed', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 9, 9, 'በአሥር ሰዓት የሰማይ በሮች ይከፈታሉ በዚህ ጊዜ የመሐይምናን ሁላቸው ጸሎት ከእግዚአብሔር ዘንድ ይደርሳል ከእግዚአብሔር ዘንድ በንፁሕ ልብ የለመኑትም ይፈፀምላቸዋል። የሱራፈል ድምፅም በመስማት በዚሁ ሰዓት ዶሮ ይጮኻል ወድያውም ፍጡራን ሁሉ እግዚአብሔርን ያመሰግኑታል።'),
  ('11e39026-0bd8-5b90-acdb-fe6b189fd52b', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 10, 10, 'በአሥራ አንድ ሰዓት ፍፁም ደስታ ይሆናል (በምድር ላይ) ፀሐይ ወደገነት ይገባልና የፀሐይ ብርሃን በዓለም ሁሉ ወጥቶ ፍጥረት ሁሉ በፀሐይ ብርሃን እንዲደሰት ይሆናል።'),
  ('ea16d198-5cf0-5dc6-a10b-a7f42814f6ae', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 11, 11, 'በአሥራ ሁለት ሰዓት ልጆቼ በፀጥታ ይቆሙ ዘንድ ይገባል የሚቆሙትም ከእግዚአብሔር ፊት ነው ለሱም ይገዙ በዚች ሰዓት ሰማያውያን ሁሉ ለጥቂት ጊዜ ፀጥ ይላሉና።'),
  ('a0c92bd1-c06c-58a6-abcd-9473f519d154', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 12, 12, 'ይህን ሁሉ ስማ ነገሬንም አድምጥ ልብ ብለህም አዳምጥ የእግዚአብሔር ቃል ከሰማይ ወደምድር ይወርዳል ይህንንም እግዚአብሔር አምላኬ ከገነት ባስወጣኝ ጊዜ ነግሮኛል።'),
  ('89f00a2f-a554-5f18-aef2-bedefbf2abec', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 13, 13, 'ሕያው እግዚአብሔር ቃሉ በኋለኛው ዘመን ካንዲት ልጅ 27 ማርያም የምትባል ሰው እንደሚሆን ከሷም እንደሚሠወር የሷንም ሥጋ እንደሚለብስ በሰው አምሳልም እንደሚወለድ ነግሮኛል አወላለዱም ከሱ በቀር ማንም ሊያውቀው አይልም በረቂቅ ሚስጢር ነው የሚወለደው።'),
  ('1a68681a-941b-541f-aea0-98c976851c5e', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 14, 14, 'ግልፅ ሁኖም በምድር ይመላለሳል ከልጆቼ ጋርም ወዲያ ወዲህ ይላል በምድር ላይም ጥቂት በጥቂት ያድጋል በዓመታትና በቀናትም ዕድገቱ ይቀጥላል። ግልፅ ተአምራትንና መንክራትንም ያሳያል ከምድር በባሕር ላይ በየብስ እንደሚጓዘው ይጓዛል ነፋሳትንና ባሕርን ይገሥፃል እነሱም በግልፅ ይታዘዙለታል የባሕርንም ሞገዶች ይጠራቸዋል እነሱም ፈጥነው አቤቱ እነሆ በማለት መልስ ይሠጡታል።'),
  ('f1f4f7df-a431-5d6a-a410-9285a7380bf4', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 15, 15, 'በዚሁም ዕውሮች ያዩ ዘንድ ለምፃሞች ይነፁ ዘንድ መስማት የተሳናቸው ይሰሙ ዘንድ። መናገር ያቃታቸው ይናገሩ ዘንድ ሙታን ይነሱ ዘንድ ሽባዎች ይድኑ ዘንድና መሄድ ያቃታቸው ይሄዱ ዘንድና ብዙዎችንም እግዚአብሔርን ወደማወቅ ይመለሱ ዘንድ ያደርጋል።'),
  ('11504200-3183-588b-ab2a-361d6b64c467', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 16, 16, 'አጋንንትንም ከሰው እያስወጣ ያባርራቸዋል።'),
  ('652a0dac-df96-5cfa-af3f-05c2201d6324', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 17, 17, 'ድጋሚም እንዲህ አለኝ አዳም ሆይ አትዘን ፈቅደህ ትእዛዜን አፍርሰሃል ስለዚህ የገባሁልህ ቃልኪዳን አሁኑኑ የሚፈፀም አይደለም ከጥቂት ጊዜ በኋላ ግን ይፈፀማል።'),
  ('9195bfcd-4a25-5c89-ab24-59eb11fb177d', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 18, 18, 'ዳግመኛም እግዚአብሔር አናገረኝ እንዲህም አለኝ ከገነት አውጥቼ እሾህና አሜከላ በምታበቅል ምድር ያስቀመጥኩህ እኔነኝ በሷም ለተወሰኑ ዓመታት ትኖራለህ ጀርባህንና ራስህን በገዛራሳሕ አድን ጉልበትህም ይንቀጥቀጥ የሥጋህ እርጅና ይታያል። የየዕለት ምግብህንም ትፈልጋለህ።'),
  ('42766dd8-9069-5b01-a523-8a76e10b3218', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 19, 19, 'ካምስት ቀንና ግማሽ ቀን በኋላ እምርሃለሁ ይቅርታም አደርግለሃለሁ በይቅርታየ ብዛትና በምሕረቴ ብዛትም ወዳንተ ቤት እወርዳለሁ በወገንህም ከርስ አድራለሁ ይህ ሁሉ ስላንተ ድህነት ይሆናል።'),
  ('e9690bbd-6002-56eb-a59a-7b7dabcb23cc', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 20, 20, 'አዳም ሆይ ሕፃን ሁኜ ስላንተ እወለዳለሁ አዳም ሆይ ስላንተ በገቢያ ሁሉ እመላለሳለሁ አርባ ዕለትም እፆማለሁ ስላንተ ብዙ መከራን እቀበላለሁ መከራውንም እታገሰዋለሁ በዕንጨት ላይም እሰቀላለሁ ይህ ሁሉ የሚፈፀመው ስላንተ ነው።'),
  ('411e1c24-3b4e-5e36-a45a-cf02c7e32a49', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 21, 21, 'ምስጋና ዘለዓለማዊነት ልዕልና ክብር ሥግደትና ዘምሮ ለአብ ለወልድ ለመንፈስ ቅዱስ ይገባል እስከ ዘለዓለሙ ዓሜን።'),
  ('a7c264b7-6a6e-532d-a198-128ebc3032a8', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 22, 22, 'ሴት ልጄ ሆይ ወንድሙ አቤልን በቅንአት ተነሳስቶ ስለገደለው ቃየል ልጆች በምድር ላይ የጥፋት ውሀ ይመጣል ቃየል ስለ እህቱ ሉድ አቤልን ገደለው ስለዚህ ከጻድቁ፦ አቤል ደም በቀር ለቃየል ልጆች ሌላ መሐላ የላቸውም።'),
  ('e8090a7b-62d5-5934-aac8-18c336292f70', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 23, 23, 'ሕዝቡ ሁሉ (ደቂቀ ሴት የሆኑ) ወደደብር ቅዱስ ይወጡና ከአዳም ሥጋ እየተባረኩ ይመለሱ ነበር። ለመባረክ የሚወጡት ትልቁ ትንሹ ሴቱ ወንዱ ሁሉም ናቸው።'),
  ('85510e78-06af-507e-ab3a-731bd84a2133', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 24, 24, 'ከዚያም ሁነው ዓይናቸው አንስተው ወደገነት ይመለከታሉ ከእግዚአብሔር ፊት ይሰግዳሉ ይቀድሶ።ል ያመሰግኑተል ። ከዚያ ወደማደርያቸው ይመለሳሉ።'),
  ('1ffe0252-77c9-5e7f-acbd-4f9241c9a313', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 25, 25, 'ሴት ዘጠኝ መቶ አሥራ ሁለት ዓመት ኖረና ሊሞት ታመመ በዚህ ጊዜ ሄኖስ ቃይናን መላልኤል ያሬድና ሄኖክ ከልጆቻቸው ከልጅ ልጆቻቸው ጋር ወደሴት ቀረቡ።'),
  ('0f4fb31f-d215-56f5-ad1b-1aab2e149f9a', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 26, 26, 'ሴት በነሱ ላይ ጸለየና ባረካቸው ስለነሱም ወደ እግዚአብሔር ማለደ እንዲህም አላቸው። በአቤል ጻድቅ ስም አደራ እላችሁ አለሁ ከናንተ ማንም ከደብር ቅዱስ ወርዶ ከነፍሰ ገዳዩ ቃየል ጋር አይደመር ቃየል አቤልን ከገደለው ጀምሮ በኛና በሱ መካከል ያለውን ጥል እናንተ ታውቃላችሁ።'),
  ('2a3ed2a6-5d7b-5e1c-a970-e4bd44d3666b', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 27, 27, 'በዚህ ጊዜ ሄኖስ ወደሴት ቀረበ ሴትም ባረከው እንዲህም አለው በቀና መንፈስና በእውነት ሕዝብሕን ምራቸው በሞትኩም ጊዜ ከተቀደሰው የአዳም ሥጋ ፊት ቁመህ ለእግዚአብሔር ተገዛ።'),
  ('1a855114-d56b-5ec8-a3bd-fa712ed12c58', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 28, 28, 'በጻድቁ አቤል ደምም አማለው በሕዝቡ ዘንድ አመራሩን በንፅሕናና በእውነት ያስተካክል ዘንድ በአዳም ሥጋ ሴትን ለእግዚአብሔር አገልግሎቱን እንዳያቋርጥ ነገረው ሴት ሞተ ዕረፍቱም ታሕሣሥ አሥር ቀን ሆነ ሄኖስ አባቱ ሴትን በክብር ገነዘው የተለያዩ መልካም ሽቶችንም አፈሰሰለት ከኣዳም ጋርም በቤተ መዛግብት አስቀመጠው።'),
  ('5fd1b0c1-2536-527f-a41a-027b62d08edb', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 29, 29, 'ሕገቡ በሴት ሞት ምክንያት አርባ ቀን አለቀስ ሴጋ ከመታ በኋላ ኄኖስ ሕዝቦቹን በቅንና በእውነት መራቸው አባቱ ሴት የነገረውንም ሁሉ ፈፀመ።'),
  ('8b8f20f9-e5a6-5f10-a5c1-aed6cff7870c', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 30, 30, 'ሄኖስ ስምንት መቶ ዓመት ሲሞላው ዓይነሥውሩ ላሜህ ነፍሰ ገዳዩን ቃየልን በዱር ውስጥ በእንጨቶች ማሕል ገደለው ቃየል የተገደለበት ቦታ ኖልእራጋር ይባላል ዕውሩ ላሜህ ቃየልን ሊገድለው የቻለው የዱር አውሬ ድምፅ መስሎ የቃየል ድምፅ ስለተሰማው በመደንገፅ እንጂ ሆን ብሎ አልገደለውም።'),
  ('7934cc64-0c52-5c29-a891-9bdaab110971', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 31, 31, 'ቃየል በእንጨቶቹ ውስጥ ድምፁን ሲያሰማ ዕውሩ ላሜህ ዲንጋይን አንስቶ ድምፅ ወደሰማበት አቅጣጫ ቢወረውረው ቃየልን በሁለት ዓይኖቹ ማህል አሳረፈበትና ሞተ በዚህ ጊዜ ይመራው የነበረው ልጁ ዲንጋይ ወርውረህ የገደልከው አባታችን ቃየልን ነው ቢለው ከሐዘኑ የተነሳ በኃይል እጆቹን አራገበና ሲያራግብ የሚመራውን ልጁ ገደለው።'),
  ('b0b8e11d-342d-59a4-a210-d608277194c9', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 32, 32, 'ሄኖስ ዘጠኝ መቶ አምስት ዓመት ሲሞላው ታመመ ሊሞትም ተቃረበ በዚህ ጊዜ ያሬድ ሄኖክ መላልኤል ቃይናንና ማቱሳላ ከልጆቻቸውና ከልጅ ልጆቻቸው ጋር ወደሄኖስ ተሰበሰቡ ሄኖስም ስለነሱ ጸለየ ባረካቸው ስለነሱም ወደ እግዚአብሔር ማለደ።'),
  ('968b6f7b-2362-55ab-a10f-322baf1b917b', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 33, 33, 'በጻድቁ አቤል ደምም ከነፍሰገዳዩ ቃየል ጋር እንዳይደባለቁ አማላቸው እንዲህም አላቸው በኛና በነፍሰ ገዳዩ ቃየል ያለውን መለያየት አስቡ አትርሱት።'),
  ('6cfbf585-094e-5073-ac21-d68d861fa4bb', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 34, 34, 'ቃይናን ሊሞት ወደቀረበው አባቱ ሄኖስ ቀረበ ሄኖስም ቃይናንን ባረከው ። እንዲህም አለው ሕዝብህን ጠብቃቸው ዘመዶችህን ጠብቅ እኔ እንደጠበቅሁዋቸው ጠብቃቸው በነሱ ላይም ትክክለኛውን ፍርድ ፍረድ መላልኤልንም ልጅህን ካንተ በኋላ መላልኤል ህዝቦቹን በትክክል ይመራቸው ዘንድ እዘዘው በአባታችን አዳም ሥጋ ፊት ለእግዚአብሔር መገዛቱ እንዳያጓድል አደራ በለው።'),
  ('1b1c5962-cbcd-5905-ac8d-3dd6345be610', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 35, 35, 'ሄኖስ በመጀመርያዋ ሳምንት ጥቅምት ሰባት ቀን ሞተ ሄኖስ ሲሞት ማቱሳላ የአምሳሰባት ዓመት ሰው ነበር። ቃይናን አባቱ ሄኖስን ገነዘው ከዚያ በመዛግብት ዋሻ ቀበሩት ሄኖስ ከሞተ በኋላ ሕዝቦቹ አርባቀን አልቅሷል። ።'),
  ('8b1f391c-3270-57f7-a1cb-200ce8af4e3f', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 36, 36, 'ቃይናን የሄኖስ ልጅ ሕዝቦቹን በእውነትና በቅንነት መራቸው የአባቱንም ሄኖስ ትእዛዝ ሁሉ በጥንቃቄ አከበረ ዘጠኝ መቶ ሃያ ዓመትንም ኖረ የመሞቻ ጊዜው ሲደርስ ልጆቹንና የልጅ ልጆቹን ባረካቸው ሰኔ አሥራ ሶስት ቀን በዕለተ ረቡዕ ሞተ መለራኤል ልጁም ገነዘው መላልኤል ስምንት መቶ ዘጠና አምስት ዓመት ኖረ።'),
  ('c3c32ec1-4c53-5d92-a9b2-7b6e94327b87', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 37, 37, 'መላልኤል ከዚህ ዓለም የሚለይበት ጊዜ ሲደርስ ከሱ በፊት የነበሩትን አባቶቹ እንዳዘዙት እሱም ያሬድን አዘዘው ቃይናን በዕለተ እሁድ ሚያዝያ ሁለት ቀን ሞተ ። ያሬድም ገንዞ በመዛግብተ ዋሻ አስቀመጠው (ባቶቻችን ጋር) ለያሬድ አምስት መቶ ዓመት ሲሞላው ከሴት ልጆች ወንዶች ተነሱ።'),
  ('53fc3e2b-03cf-5fa5-ae29-5ca74dadfab8', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 38, 38, 'ያባቶቻቸውን ትእዛዝ አፈረሱ ከአዳምና ከሌሎችም አባቶች የተረከቡትን አደራነት ጠሉ አንዳንድ እያሉም ከደብር ቅዱስ በመውጣት ከቃየል ልጆች ጋር ተጨመሩ ሠይጣን በታወረው የላሜህ ልጅ አመካኝቶባቸዋልና።'),
  ('71205d97-ffbb-53f2-af49-749d77c4c20e', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 39, 39, 'የቃኤል ቤተሰብ የሆነው ዕውሩ ላሜህ ሁለት ዮፊልና በልቄን የሚባሉ ልጆች ነበሩት እነዚህ ልጆች በመሰንቆ በአርጋኖን። በእንዚራና በከበሮ የታጀበ ዘፈንን ዘፈኑ።'),
  ('1d87527e-98cc-5205-aa1e-0810acf0c810', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 40, 40, 'የሴት ልጆች በሠይጣን ተታልለው የቃየል ልጆችን መከተል ጀመሩ በዚሁ በጣፈጠውም የዘፈን ዜማ ተመሠጡ ይህንንም መነሻ አድርገው ከደብር ቅዱስ እየወረዱ ከክፉወች የቃየል ልጆች ጋር ተጨመሩ።'),
  ('9e98cd31-2e9e-52b2-a11e-c5d8cb32385c', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 41, 41, 'የሴት ልጆች በዘፈን ተጠሞደው ወደቁ በመብል በመጠጥና በዝሙት ተያዙ ሴቶች ጐልማሳዎችን በመከተል ተሯሯጡ። ወንዶችም እንዳዱር አውሬ ዕራቁታቸው እየሆኑ በየገቢያው ይዞሩ ጀመር።'),
  ('1712292d-ade8-5067-a02f-926caf6a3d0e', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 42, 42, 'ሠይጣን የሴትን ልጆች አሳስቶ ከቃየል ልጆች ጨመራቸው የኸውም በዘፈን ድምፅ በመሰንቆ በጨዋታና በመዳራት በማታለል ነው ከደብር ቅዱስ ወደተረገመችው ምድር የወረዱት።'),
  ('b604c903-61fc-5d3d-aec3-8d0b5cccd116', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 43, 43, 'እግዚአብሔር ባለሟሎቹ አድርጎ አስቀምጦአቸው እያስ የአጋንንትን ፈለግ ተከተሉ የአጋንንት ባለሟሎችም ሆነ ከሕይወት ሞትን መረጡ ክብርን ናቁ ክብር ይግባውና ልዑል እግዚአብሔር አክብሮአቸው ነበር። ልጆቹንም አድርጎአቸው ነበር። ነቢዩ ዳዊት ስለነሱ እኔስ አማልክት ናችሁ የልዑል እግዚአብሔርም ልጆች ናችሁ አለ ይህን ማለቱ የእግዚአብሔርን ትእዛዝ በማክበር የነበሩበትን ለማስታወስ ነው። ከበደሉ በኋላ ስላለው ጊዜአቸው ሲገልፅ ደግሞ እናንተስ እንደሰው ትሞታላችሁ ከመላእክት አንዱ እንደወደቀም ትወድቃላችሁ አለ።'),
  ('7326ac7b-c4d5-57ed-ae9f-72dd6d6baeae', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 44, 44, 'እጅግ ተሳሳቱ ሥጋቸውንም አረከሱ በቃየል ልጆች አመነዘሩ ብዙ የረከሰ አድራጎትንም ፈፀሙ እጅግ የረከሰ ተግባርንም ፈፀሙ። ነፍሳቸውንም ረስተው በኃጢአት ተጠመዱ ሴት ከወንድ ጋር ወንድ ከሴት ጋር እንደእንስሳት ሁነው ተገናኙ ግልፅ የአመንዝራነትን ተግባር ፈፀሙ ሁለት ሦስት ሁነው ባንዲት ሴት ላይ ተገናኙ ምድርንም በመላዋ አረከሱዋት።'),
  ('7e54b8ae-b0bb-5143-ac23-3c9b3d1c01e3', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 45, 45, 'ማነኛውንም ተፈጥሮአቸው ወደቃየል ልጆች ጨመሩ አንዱ ካንዱ ሊለዩ እስከማይችሉ ድረስ ተደባለቁ ሠይጣን ሙሉ በሙሉ ገዛቸው። በወደቀና በረከሰው ውድቀታቸው የሚያሰሙት ጩኸትና ዋይታቸው እንደባዝራ ፈረስ እስከያብር ቅዱስ ተሰማ።'),
  ('551d9276-d933-5a8e-a75d-67b1e28e192d', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 46, 46, 'አንድ መቶ ኃይለኞች ከደቂቀ ሴት ውስጥ የሆነች ከደብር ቅዱስ ሊወርዱ ሲዘጋጁ ያሬድ አይቶና ሰምቶ እጅግ አዘነ ስለድቀታቸውም እጅግ ተከዘ።'),
  ('43e869f2-020b-5b38-a5a5-8ef1c46a3003', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 47, 47, 'ያሬድ መልእክተኛን ወደሱ ልኮ አስጠራቸውና እነሱም መጥተው ከፊቱ ቆሙ ይህንን የሠይጣን ሥራ አትሥሩ በማለት ገሠፃቸው በፃድቁ አበል ደምም አስማላቸው ከደብር ቅዱስም እንዳይወርዱ አስቀድማችሁ የገባችሁትን መሐላ አስቡ አላቸውም።'),
  ('4f07fc09-340d-57f5-a098-6f0955c2ed37', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 48, 48, 'ሄኖክም መጣና ተናገራቸው እንዲህም አላቸው ከናንተ መካከል ያባቶችን መሐላ ጥሶ ከደብር ቅዱስ ለመውጣት ያሰበ ካለ ደግሞ ተመልሶ ወደደብር ቅዱስ እስከዘለዓለሙ አይገባም ።'),
  ('f72c03b4-1246-5d03-a156-dfb12ce26aa2', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 49, 49, 'እነሱ ግን የያሬድን ምክር ሰምተው ወደኋላ ለማለት አልፈለጉም የሄኖክንም ምክር አልተቀበሉም ከደብር ቅዱስ ወርደው በምድር ላይ ታዩ የቃየል ሴቶች ልጆች ተውበው ዕርቃናቸው በመሆን ሲንቀሳቀሱ አዩዋቸውና ከነሱ ጋር አመነዘሩ ርስታቸውንም አጠፉ።'),
  ('96967b8d-6fa2-5444-ac8d-9a0106b02dfc', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 50, 50, 'እነዚህ ከቃየል ሴቶች ልጆች ጋር ሥጋቸውን ያረከሱ መቶ ደቂቀ ሴት ደብር ቅዱስ በድንጋይ እሳት መዘጋቱን ሳያውቁ ሊመለሱ ሞከሩ ግን የእሳቱ ዲንጋይ እንዳይገቡ ከለከላቸው ሌሉች የሴት ልጆችም የወገኖቻቸው መመለሻ አጥተው መቅረትን ሳያውቁ ከደብረቅዱስ እየወጡ ወደተረገመችው ምድር ወርደው ከቃየል የረከሱ ሴቶች ጋር አመነዘሩ።'),
  ('5a4e7841-824d-5dd5-ade8-0512d818b208', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 51, 51, 'ያሬድ ዘጠኝ መቶ ዓመት ሲሞላው ከዚህ ዓለም የሚለይበት ቀን ደረሰ በዚህ ጊዜ ወደሱ ሄኖክ ማቱሳላ ላሜህና ኖኅ ተሰበሰቡ ። ያሬድም በነሱ ላይ ጸለየ እንዲህም አላቸው እናንተ ከደብር ቅዱስ አትውረዱ ከቃየል ልጆች ጋርም አትጨመሩ ልጆቻችሁና ሚስቶቻችሁ ግን ከደብር ቅዱስ እየወጡ ከነሱ ጋር ይጨመራሉ።'),
  ('a62ca4d2-3d33-5806-a5dd-b25e2a939f32', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 52, 52, 'እግዚአብሔር ልዑል ግን እንዲህ እንዳበዱ ይኖሩ ዘንድ አይተዋቸውም የሱን ትእዛዝና የአበውን ትእዛዝ አፍርሰዋልና ለነሱ ልጆች ደግሞ እንዲህ አላቸው ከዛሬ ጀምሮ በተረገመችው ምድር ልትሰባሰቡ ነው። ሁላችሁም ደብር ቅዱስን ትታችሁ ስትወርዱ ከናንተ ጋር ያባታችን አዳምን ሥጋና የሌሎችንም አበው ሥጋ ይዛችሁ ውረዱ በተጨማሪም ቁርባንን። ወርቅን ፣ ዕጣንንና ከርቤንም ይዛችሁ ሂዱና ከአዳም ሥጋ ጋር አኑሩት።'),
  ('e38cea44-ea5a-5f04-a5fc-0910b1956c09', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 53, 53, 'ያሬድ ለሄኖክ እንዲህ ሲል መከረው ልጄ ሆይ አንተግን በአዳም አባታችን ሥጋ ፊት መዘመርንና ማመስገንን አትተው ከእግዚአብሔር ፊትም ተገገርነትህን በእውነትና በቅንነት ግለፅ በዘመንህ ሁሉ ይህ ይሁን ተግባርህ።'),
  ('a1131a6c-3549-535d-a907-9d42df6ee1a7', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 54, 54, 'ያሬድ ግንቦት አሥራ ሁለት ቀን በዕለተ ዓርብ በሦስት ሰዓት ሞተ ያሬድ ሲሞት ማቱሳላ ዘጠኝ መቶ ስድሳ አምስት ዓመት ሁኖት ነበር። ልጁ ሄኖክ ገንዞ በመዛግብት ዋሻ አኖረው።'),
  ('2f04a4b6-239d-569e-a95c-ebecb50364b2', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 55, 55, 'የቀሩትን የሴት ልጆች እግዚአብሔር ችላ አላቸው ሐጢአትን ወደ ዋታልና ከዚህም የተነሳ ተለያይተው ሁለት ክፍል ሆነ ጨርሰውም ከደብርቅዱስ ለመውረድ ወደዱ።'),
  ('860106e3-6b23-579f-a568-3d2e993afacd', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 56, 56, 'ሄኖክ፣ ማቱሳላ፣ ላሜህና ኖህ ይህንን ሲሰሙ በጣም ስለነሱ መጥፋት አዘነ ሄናክ ሦስት መቶ ስድሳአምስት ዓመት ሲሆነውና ከያሬድ ሞት በኋላ አምስት ዓመት ለእግዚአብሔር ተገገርነቱን ካሳየ በኋላ እግዚአብሔር የአስተዋይነትን ልቡና ሠጠው ወደሱ እንደሚወስደውም አስረዳው በዚህ ጊዜ ሄኖክ ማቱሳላን ላሜህንና ኖኀን ጠራቸው።'),
  ('56ff62a0-c527-5612-af8b-dcd8b810f92c', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 57, 57, 'እንዲህም አላቸው እነሆ ልዑል እግዚአብሔር በነሱ ላይ ቁጣውን እንደሚገልፅ አወቅሁ በነሱ ላይ እጅግ የፍርድ ቅጣት ያወርዳል ቁጣውም ምህረት የሌለበት ቁጣ ነው እናንተ ግን በአበው ቅዱሳን ተተክታቹኋል ከእግዚአብሔር ፊት ተገዢነታችሁን አታሳጉሉ ንፁሐን ሁናችሁ በደግነት ኑሩ በዚሁ በደብር ቅዱስ የሚወለድ እንደሌለም ዕወቁ ሕዝቦቹንም ለመምራት የሚችል በአበው አካሄድ ማንም አይኖርም።'),
  ('ac0ff4e2-fa7d-57e0-a7fa-13c3b9c31b03', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 58, 58, 'ሄኖክ ይህንን ንግግሩ ሲጨርስ ወደሕይወት ተመለሰ እግዚአብሔርም በገነት አደባባይ አስቀመጠው በም ሞት የለም። የቀሩት የሴት ልጆች ግን ማንም ሳያስገድዳቸው በሙሉ ቃየል ወደሚኖርበት ምድር ተሟጥጠው ወረዱ ከነሱ ውስጥ ማንም በደብር ቅዱስ አልቀረም ላሜህ ማቱሳላና ኖኅ ብቻ ቀሩ።'),
  ('dbd6e457-1843-517c-a5f5-85c320a4ba79', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 59, 59, 'ጻድቁ ኖኅም በድንግልና ራሱን አምስት መቶ ዓመት ጠበቀ ከዚህም የተነሳ እግዚአብሔር ኖኀን ሃይከል የተባለችውን የሄኖክ ልጅ የማቱሳላ ወንድም ልጅ ናማስን እንዲያገባት አዘዘው።'),
  ('81442fc0-dbbb-51e8-a1bb-fb5a4571cad9', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 60, 60, 'እግዚአብሔር ስለአይህ አመጣጥም ገለፀለተ የጥፋት ውሃ ተነስቶ በዝሙት የረከሰችውን ዓለም እንደሚያጥባት ነገረው ይህም ካንድ መቶ ዓመት በኋላ እንደሚፈፀም ገለፀለት ከወዲሁ ጀምሮም ለራሱና ለቤተሰቡ ድሕነት መርከብን እንዲዘጋጅ አዘዘ።'),
  ('bfdad3c7-479f-5ee7-a4f4-c30c17a8aad3', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 61, 61, 'እግዚአብሔር በድጋሚ ከደብር ቅዱስ ዛፎችን ይቈርጥ ዘንድ አዘዘው። እሱም ከደብረቅዱስ ቈርጦ በቃየል ልጆች ማደርያ አስቀመጠው በዚሁም ሶስት መቶ ክንድ ርዝመት፣ ጐድኑ አምሳ ክንድ የራሱ ጉድንና ቁመቱ ሰላሳ ክንድ የሆነ መርከብን መሥራት ጀመረ።'),
  ('3925ebfb-83f0-5aae-a1da-a45a62e0067d', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 62, 62, 'በዚሁ መርከብ ውስጥ ሦስት ክፍሎችን ይሠራል ታችኛው ክፍል ለአውሬዎችና ለእንስሳ ማደርያ ይሆናል መካከለኛው ክፍል ለራሱ ለሚስቱ፣ ለልጆቹና ለሚስቶቻቸው ይሆናል ። የውሃ መጠራቀምያ ገንዳንም ሠራ ከዚሁም በተጨማሪ ሦስት ክንድ ርዝማኔና አንድ ክንድ ጉድን ያለው ደወል ከሊባኖስ ዕንጨት ሠራ።'),
  ('4c5e5403-564a-50a9-a36f-ff75bc5aee25', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 63, 63, 'መርከቡን በሚሠራበት ጊዜ ሁልጊዜ ጧት ጧት ለሥራ እንዲሠበሰቡ ደወል ይደውላል። ቀትር ሲሆን ምሳ ለመብላት እንዲሰበሰቡ ይደውላል ቀኑ አልፎ ምሽት ሲሆን ወደየቤታቸው እንዲገቡ ይደውላል።'),
  ('996ccab5-e3af-5769-aecb-89eb82b2b4c3', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 64, 64, 'መርከቡን ለምን እንደሚሠራው ጠያቂ ቢነሳበት እግዚአብሔር የጥፋት ውሃን ይህቺን የረከሰች ምድር ለማጠብ እንደሚያዘንምና። በዚሁም ምክንያት ራሱን ሚስቱን ልጆቹንና ሚስቶቻቸውን ለማዳን መርከብን እንዲሠራ መታዘዙን ይገልፅለታል።'),
  ('ed2c7f20-b3cf-52e2-a4aa-c8ca3dd94d8b', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 65, 65, 'ኖኅ የእግዚአብሔርን ትእዛዝ ሰሞቶ ሚስት አገባ ካገባ በአርባ ዓመቱ ሦስቱን ሴሞ ካሞና ያፌትን ወለዳቸው ሦስቱን ወንዶች በቅደምተከተል ወለዳቸው።'),
  ('23a449af-c2d5-5aab-ac69-5450e79071ab', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 66, 66, 'የኖኅ ልጆች የማቱሳላ ልጆችን አገቡ ኖኅ እግዚአብሔር እንዳዘዘው የመርከቧን ሥራ እንደፈፀመ ማቱሳላ ሊሞት ተቃረበ።'),
  ('dfe6f084-290e-59dd-a836-f8b83914f11d', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 67, 67, 'ኖኅ ሴምና ያፌት ወደ ማቱሳላ ተሰበሰቡ ማቱሳላም በነሱ ላይና በሚስቶቻቸው ላይ ጸለየ ባረካቸውም ስለነሱም ወደእግዚአብሔር እያለቀሰ ማለደ እያዘነም ከናንተ በቀር ከሁላቸው አሕዛብ መካከል በዚሁ በደብር ቅዱስ ማንም ሊቀር አልቻለም ያላችሁት እናንተ ብቻ ናችሁ አባታችን አዳምንና እና።ኝን ሔዋንን የፈጠረ እግዚአብሔር ምድርንም በዘራቸው ይሞሉዋት ዘንድ የባረከ እሱ ነውና።'),
  ('a03f53e7-f924-5445-a195-24c16cb1db5e', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 68, 68, 'እንዲሁም እግዚአብሔር እናንተን ይባርክ ዘራችሁም ያብዛ እናንተንም ይጠብቅ ዕናቱንም ይሰጣችሁ ኀይልንና አቸናፊነትንም ይስጣችሁ በዚችው ከእግዚአብሔር በወጣች ትውልድ ሊመጣ ካለው መቅሰፍትም ይሠውራችሁ በልጆቻችሁና በልጅ ልጆቻችሁም ላይ በረከቱን ያውርድ ለአባታችን አዳም የሠጠውንም ፀጋ ለናንተም ይሥጥ።'),
  ('13643ca2-f8dc-50ed-aae7-7cb208155e27', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 69, 69, 'ስለናተም ወደእግዚአብሔር እለምናለሁ ዘራችሁ ሁሉ ይሞላ ዘንድ መንግሥትና ትንቢትንም ለናንተ ይስጥ አላቸው።'),
  ('4cbeb70b-3ce7-55a8-a6d6-7d7d0765f727', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 70, 70, 'ኖህን ደግሞ እንዲህ አለው እግዚአብሔር ዘንድ የተባረክህ ኖኅ ሆይ ቃሌን ስማ ትእዛዜንም አክብር እኔ ከኔ የቀደመት አበው ከዚህ ዓለም እንደወጡ ከዚህ ዓለም እወጣለሁ።'),
  ('46d69e8d-b6ae-50e0-a0aa-3d99424ccc69', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 71, 71, 'እነሆ ሰዎች ብዙ ሐጢአት ስለሰሩበት እግዚአብሔር የጥፋትን ውሃ ልኮ ምድርን ሊያጥባት ነው አንተና ቤተሰቦችህ ግን ከዚህ የጥፋት ውሃ ትድናላችሁ እኔ ስሞት ለቀደሙት አበው እንደተደረገው ሥጋየን ገንዘህ በቤተመዛግብት አኑረው።'),
  ('26789501-b958-5477-aa6b-8d5f168e281a', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 72, 72, 'ከዚህ በኋላ ሚስትህንና ልጆችህን የልጆችህም ሚስቶች ውሰድ ከደብር ቅዱስም ውረድ ያባታችን አዳም ሥጋንም ካንተ ጋር ውሰድ እግዚአብሔር እንድትሠራት ካዘዘህ መርከብ ውስጥም አስቀምጣት ቁርባን ወርቅ። ከርቤና ዕጣንንም ከአዳም በላይ አስቀምጥ የቀሩትንም አበው ሥጋ ከደብር ቅዱስ አውርደህ በአዳም ሥጋ ግራናቀኝ አስቀምጠው የአባታችን አዳም ሥጋም በአበው ሥጋ ማሕል ይቀመጥ ለራስህም ማደርያ በመርከቧ ላይ ሥራ።'),
  ('8dab7fdb-58cb-5132-aa0f-d7d9c98993f8', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 73, 73, 'ከመርከቡ በስተምሥራቅ ክፍል ላንተና ለልጆችህ ለሚስትህም ለልጆችህም ሚስቶች ክፍል ትሠራለህ በስተምዕራቡም ክፍል መኖርያቸው ይሁን በዚሁ ለመብልና ለመጠጥ ይሰብሰቡ ከመርከቧ እስክትወጣ ድረስም ከዚሁ ሁናችሁ ወደውጭ ተመልከቱ የጥፋት ውሃ ከምድር ሲወገድ በምድር ስትኖሩ ያንጊዜ በሕብረት እየተሰበሰባችሁ ብሉ ጠጡ በእግዚአብሔር ፊትና በአዳም ሥጋ ፊትም በቅድስናና በንፅሕና፣ በቅንነትና በፅድቅ ከመገዛት ወደኋላ አትበሉ።'),
  ('d260167f-02ef-52cb-ae31-bd6dd2a782be', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 74, 74, 'ከታቦት ከወጣችሁ በኋላ ያን ጊዘ ወርቅን ከርቤን፣ ዕጣንን (ከገነት የወጡ) ከምድር በስተምሥራቅ አስቀምጥ አንተም ከዚሁ ክፍል ከቤተሰቦችህ ጋር ትኖራለህ ከዚህ ዓለምም የምትለይበትን ጊዜ ሲደርስ ልጅህ ሴምን ያባታችን አዳምን ሥጋ ይውሰድና በምድር ላይ በክብር ቀብሮ ያስቀምጠው።'),
  ('0ce260e1-aab1-5ca1-a3ed-4a2be6f888dd', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 75, 75, 'የአዳም ሥጋ በተቀበረበት ለልጅ ልጆቹ መድሐኒት ይሆናል በአዳም ሥጋም ላይ አንድ ቅዱስ ሰው እግዚአብሔርን በክህነት እያገለገለ ይነር። ለአገልግሎት ይህ ሰው በንፅሕና በቅድስና ይነር።'),
  ('e5aea44c-7813-5892-a5ae-eab07afe3e72', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 76, 76, 'ጠጅ እንዳይጠጣ ደም እንዳያፈስ ራሱን እንዳይላጭ ጥፍሩንም እንዳይቆርጥ አዘዘው። በዚሁም የስንዴ ሕብስትንና ከወይን ፍሬ የተጨመቀ ወይን ብቻ ቁርባን እንዲያቀርብ ይሁን።'),
  ('ac84cc70-d499-5974-ae3e-806bc7f2da1a', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 77, 77, 'እነሆ አባታችን አዳም ሊቀበርበት ወደተዘጋጀው ያደርሰው ዘንድ የእግዚአብሔር መልአክ ከፊት ለፊቱ ይሄዳል ዳግመኛም ልብሱ ከእንስሳት ቁርበት የተሠራ ብቻ እንዲሆን አድርግ እሰ እግዚአብሔር የመረጠውና የቀደሰው የእግዚአብሔር ካህን ነውና።'),
  ('302fbb51-d9f9-53ba-a3d7-562017936add', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 78, 78, 'ይህን ሁሉ ትእዛዝ ተናግሮ በፈፀመ ጊዜ ማቱሳላ ከኀዘት ብዛት የተነሳ አለቀሰ እንባውም ወረደ በእለተ እሁድ መጋቢት አንድ ቀንም ሞተ የሞተው በዘጠኝ መቶ ስድሳ ዘጠኝ ዓመቱ ነው ላሜህ ልጁ ገንዞ በቤተመዛግብት ቀበረው ቤተመዛግብቱ የቅዱሳን አበው ዓፅም ያረፈፈት ነው።'),
  ('39b7a07c-341c-5b0c-ad87-cdce30efa117', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 79, 79, 'ስለሱም አርባ ቀን አለቀሱ ከሱ በኋላ ላሜህ ታመመ ልጁ ኖኀንም አባቱ ማቱሳላ እንዳዘዘው አዘዘው። ላሜህ በዕለተ ሐሙስ መስከረም ሃያ አንድ ቀን የኖኅ ልጅ ሴም የስድሳ ስምንት ዓመት እያለ ሞተ ልጁ ኖኅም ገነዘው በቤተመዛግብትም።'),
  ('d4dc1f2d-17dc-5000-a8d5-683cb3c504b8', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 80, 80, 'ቀበረው ስለሱም ሕዝቦቹ አርባ ቀን አስቀሉ አበው በሙሉ እስከዚህ ጊዜ ድረስ ከኖጎ ጋር በደብር ቅዱስ ነበሩ።'),
  ('388aa126-d551-58b0-a033-62e80e3d470c', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 81, 81, 'የቃየል ልጆች ከሴት ልጆች ልጆችን ወስዱ እነዚህም ልጆች እጅግ ሐይለኞች ሆኑ መጽሐፍ የሴት ልጆችን መላእክት ይላቸዋል ባልተፈቀደም መንገድ ሥጋዊውን ግንኙነት መፈፀማቸውን ይገልፃል። የሴት ልጆች የቃየልን ልጆች ዘፈን እየሰሙ በዓመፅ ቅድስናቸውን እየተው ወርዷል። ከቃየል ልጆች ጋርም በአመንዝራነት ግንኙትን ፈፅመዋል ጥንት እግዚአብሔር የሴትን ልጆች እናንተ አማልክት ናችሁ የልዑልም ልጆች ናችሁ ብሏቸው ነበር።'),
  ('f61ba594-748f-565a-a5db-aa23cfa3d6c5', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 82, 82, 'የሴት ልጆች በደብር ቅዱስ በነበሩ ጊዜ ንፁሐን በሐጢአት ያልተበከሉ ነበሩ ከደብር ቅዱስ ወርደው ከቃየል ልጆች ከተገናኙ በኋላ ግን እግዚአብሔር እኔስ አማልክት ናችሁ የልዑልም ልጆች ናችሁ ብያቸው ነበር። በኋላ ግን እንደሰው ትሞታላችሁ ከመላእክት ተለይቶ እንደወደቀው ዲያብሎስም ትወድቃላችሁ አለ።'),
  ('eb008ed4-6d39-5ed6-a6d5-666b6f0516ad', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 83, 83, 'ከመንፈስ የተፈጠሩ ሁሉ አፈጣጠራቸው እንደሰው አይደለም የሥጋ ፍትወትም የለባቸውም ፍትወተሥጋ በነሱ ላይ ቢኖር ኑሮ አጋንንት ሴቶችን እየተገናኙ በጨረሱዋቸው ነበር። በዚህም ዓለምን ሁሉ አንድም ሳያስቀሩ ለጥፋት አጋልጠው በጨረሱ ነበር።'),
  ('1cb7ff5d-fcc4-5a46-a692-5b575c34012a', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 84, 84, 'አጋንንት የረከሱ ናቸው ጥፋትን ብቻ ይወዳሉ ዝሙትንም ይወዳሉ ዝሙትን መፈፀም ስለማይችሉም በሰው ላይ እያደሩ ሰውን ዝሙተኛ ያደርጉታል የረከሰውን ክፉውንና ፍትወትንም ያሠሩታል።'),
  ('93e79a35-60c9-58b3-a775-24b62ce42bed', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 85, 85, 'ከዚህ ቀጥሎ ኖኅ የአዳምን ሥጋና የሌሎችም አባቶች ሥጋ አሰባስቦ ወስደ እየራሳቸውንም ለያይቶ አስቀመጣቸው በታቦትም ውስጥ አስገባቸው ሴም የቁርባነን ወርቅተሸከመ ካም የከርቤውን ቁርባን ተሸከመ ያፌት የቁርባኑን ዕጣን ተሸከመ ሁሉም ከበዓተ መዛግብት በታላቅ ሐዘንና ልቅሶ ለመውጣት ተነሱ ወጥተውም ሄዱ።'),
  ('318fcf78-387e-5e72-a456-93eac35ec6e8', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 86, 86, 'ሊወጡ ሲዘጋጁም ዓይናቸውን ገልጠውና ቀና ብለው ወደገነት ተመለከቱ። አለቀሱም እያለቀሱም እንዲህ አሉ ገነት ሆይ ሰላም ላንቺ ይሁን የደስታ ቦታ ነሽና ያባታችን አዳም ማደርያ ነበርሽ ወዮልን እንዴት እንሁን ወደተረገመችው ምድር ልንሄድ ነው በዚች የተረገመች ምድር ሐዘን ጭንቅ በሽታና ደዌ ይበዛል።'),
  ('eb82fc10-e69f-5dca-a99b-b22cb2aa2c55', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 87, 87, 'ቤተመዛግብት ሆይ ሰላም ላንቺ ይሁን አንቲ የንፁሐን ቅዱሳን ማደርያ ነሽና የእግዚአብሔር ወዳጆች ባንቺ ይኖራሉ። የእግዚአብሔር ወዳጆች አበው ሆይ ስለኛ ፀልዩ ባርኩን ስለኛም ማልዱ ድሕነትን ናገኝ ዘንድ ለርእሰ አበው ሴት ሰላም ሕዝቡን'),
  ('4afac594-6101-5f01-ab26-acc4da441709', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 88, 88, 'ያረጋጋ ሄኖስ ሰላም በእውነትና በቅንነት በሕገዝቦቻቸው ላይ ለፈረዱ ቃይናንና መላልኤል ሰላም።'),
  ('2cf03346-854d-50b8-afec-e11b13e3901b', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 89, 89, 'ለያሬድና ለሄኖክ ሰላም ለማቱሳላም ሰላም ለላሜህም ሰላም እነዚህ ሁሉ እግዚአብሔርን በንፅሕናና በቅድስና አገልግለውታል ወደሁላቸው ዓይናችንን እናጋጥጥ ስለኛ ድሕነት ይማልዱልን ዘንድ እነሆ ከዚህ ከተቀደሰው መኖርያ ልንወጣ ነው እስከ ዘለዓለምም ተመልሰን ይህን ቅዱስ ቦታ አናየውምና አሉ። ከዚህ ጊዜ ጀምሮ ከደብር ቅዱስ ለመውጣት ተነሱ የደብረ ቅዱስንም ዲንጋይና ዕንጨቱን እየተሳለሙ በታላቅ ልቅሶና ሐዘን ወጥተው ወደምድር ገቡ።'),
  ('45178786-2314-5c59-a23a-ab646021c637', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 90, 90, 'ኖኅ የአዳምን ሥጋ ከመርከቧ ማሕል አስቀመጠ ቁርባኑን ማለትም ከገነት ያመጡትን ወርቅ ከርቤና ዕጣን በአዳም ደረት ላይ አስቀመጠው ይህንንም በዕለተ ዓርብ ነሐሴ አሥራ ሰባት ቀን አደረገ በማግሥቱ አራዊቶቹን ሁሉ በታችኛው ክፍል አስገባ።'),
  ('a394c46b-1f20-5c96-a3c4-bb74f1bc080a', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 91, 91, 'ቀትር ሲሆን ኖኅ ወፎችንና ሕይወት ያላቸውን በራሪዎች በሙሉ ወደመርከብ አስገብቶ በመካከለኛው ክፍል አኖራቸው ፀሐይ ሲጠልቅ ኖኅ ከሚስቱና ከልጆቹ ጋር ወደመርከቧ ገባ ከነሱ ጋርም በመሆን ከመርከባ ወደላይ በሦስተኛው ደረጃ በተሠራው ክፍል ገቡ።'),
  ('5e96828c-42e6-5c34-abb2-77f7700a09fb', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 92, 92, 'የኖኅ ታቦት (መርከብ) ወንድና ሴት ብላ ልዩነት ባማታደርግ ቤተክርስቲያን ትመሰላለች ወደ ቤተክርስቲያን የመጣ ሁሉ የእግዚአብሔርን ፍቅርና አንድነትን ያገኛል በቤተክርስቲያን መለየት የለም ለዚህም ምሳሌ ትሆን ዘንድ በኖሕ መርከብ ውስጥ የተለያዩ የዱር እንስሳትና አውሬዎች በሰላም ለመኖር ቻሉ ።።'),
  ('9b25166d-402a-5cb7-a8f5-018fc2e76107', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 93, 93, 'ኖኅ ሕይወት ካለው ተንቀሳቃሽ ሁሉ እየመረጠ ወደታቦት አስገባ በየስማቸውም ደረጃ አስቀመጣቸው ኖኅ ይህን ሁሉ አስገብቶ ከጨረሰ በኋላ የታቦቷን መስኮቶችና በሮች ዘጋ ከዚህ ጊዜ ጀምሮ የሰማይ መስኮቶች ተከፈቱ የጥፋት ዝናማትም መዝነም ጀመሩ ምድርም ተሰንጥቃ በውሃ ተጥለቀለቀች ውሆች በምድር ላይ ተንሳፈፉ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('1ab620d3-83f7-5d3a-a587-4e11ccbeb6ce', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 94, 94, 'ዓለም አንዲት ባሕር ሆነች ሐኖስ የሚባል ባሕርም ተፈጠረ ይህም ሐኖስ ዓለምን ሁሉ የሸፈነ ነው ነፍሳት ከየአቅጣጫው ተነሱ በቃኤል ልጆች የተጣሉ የሴት ልጆች ሮጡ ወደኖህ መርከብ አንጋጠጡ ኖሕንም እንዲያስገባቸው ከሩቅ ለመኑት ።'),
  ('f650f45f-5632-5d31-ab39-d13bcc44cbc2', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 95, 95, 'ኖህ ግን ለጩኸታቸውና ለዋይታቸው መልስ አልሠጠም ታቦቷ ሙሉ በሙሉ ሁለመናዋ ተዘግታለችና በእግዚአብሔር ትእዛዝ ማንም እንዳይገባባት ሁናለችና በዚህ ጊዜ አዘኑ ተፀፀቱ (ደቂቀ ሴት) ረዳትም አላገኙም ከጥፋትም የሚያድናቸው አላገኙም።'),
  ('da8041ce-f0bc-5777-a934-e172cdc5ab79', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 96, 96, 'በዚሁ ትልቅ ስም ተሰይማችሁ ነበር። ነገር ግን ያባቶችን ትእዛዝ አፈረሳችሁ ሐጢአትንም ሠራችሁ ሥጋችሁን አረከሳችሁ በቃየል ልጆችም መንገድ ሄዳችሁ እነሆ ሁላችሁ ልታልቁ ነው አስቀድሞ ከሰማይ ከወደቀው ፍጡር ጋርም ፍዳችሁ ልትቀበሉ ነው።'),
  ('52eda931-5c25-5f3a-afe2-5dfdde837311', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 97, 97, 'ከሁሉ ምድር በላይ ታቦት ከፍ አለች በምድር ያለውም ነፍስ ያለው ሁሉ ጠፋ በጥፋት ውሃም ተደመሰሰ ውኃዎች ከተራሮች በላይ ተንጣለሉ ከተራራዎች በላይ በመንፈስ ቅዱስ ክንድ አምስት ሆኑ የባሕር ሞገዶች ታቦቷን ከገነት ሥር አደረሱዋት ራሳቸውም ዝቅ አድርገው ወደሷ ከሰገዱ በኋላ ወደኋላቸው ተመለሱ።'),
  ('b2d8e702-f8b7-5a76-a2e7-e9bf74558f9e', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 98, 98, 'በምድር ያለውንና የቀረውንም ሁሉ አጠፉ የኖኅ ታቦት ከፍ ብላ ከውሃው በላይ በመሆን ከምሥራቅ ተነስታ ወደ ምሥራቅ ተንሳፈፈች እንደገና ከደቡብ ተነስታ ወደ ሰሜን ተንሳፈፈች ይህም የመስቀል ምልክት ነው ላንድ መቶ አምስት ቀናት ውሃዎች በመጨመር ላይ ነበሩ ሳያቋርጡም ይዘንቡ ነበር።'),
  ('32682c04-92a6-5c34-aaac-4730e81e2ae8', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 99, 99, 'ከዚህ በኋላ ግን ውሆች መጨመራቸውን አቆሙ ወደታች ዝቅ ይሉም ጀመር የመጀመሪያና የመጨረሻውን የጥፋት ውሃ በዚህ ቆመ ታቦት የፍርዳ ከሚባሉ ተራራዎች ማሕልም ቆመች ውሆችም ተለይተው ወደየመከማቻቸው ገቡ ቀስበቀስም እስከ ብ ነሐሴ ድረስ ወደ ምድር ሰረጉ።'),
  ('be7afa77-b015-5cfd-a0e6-494e1d65369a', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 100, 100, 'በየካቲት ወር ኖኅ የተራሮችን ጫፍ ለማየት ቻለ መጋቢት አሥር ቀን ኖኅ የታቦቷን መስኮቶች ከወደምሥራቅ አቅጣጫ ከፍቶ ቍራንም በዚሁ መስኮት አስወጥቶ ላከው የምድርን ሁናቴ ይመለከት ዘንድ እሱ ግን አልተመለሰም እንደ ወጣ ቀረ ።።'),
  ('06f9e582-e636-5f35-a277-79e70fbcd9b2', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 101, 101, 'ኖኅ ዳግም ርግብን ላካት እሷም ተልእኮዋን ለመፈፀም ሄደች ምድር ላይ ዞረች የምታርፋትንም ደረቅ ቦታ ስላጣች ሲመሽ ተመልሳ ገባች እንደገና ሰባት ቀን ቆይቶ ኖኅ ርግብን ላካት ተልእኮዋን አከናውና የዘይቱን የለመለመ ቅጠል ይዛ ተመለሰች ።'),
  ('a4043253-1ba0-50da-aaee-e7313c680a25', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 102, 102, 'ከክፋዎችና የተረገመ ከሕዛብ ዘንድ በቅድምያ የእግዚአብሔር ትእዛዝ ተቀባይነትን አለማግኘቷ ከርግቧ ማረፊያ ባለማግኘቷ ይተረጐማል።'),
  ('9bb80243-8dc2-54aa-a092-c51314ba563f', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 103, 103, 'ሁለተኛዋ የርግብ ማረፍያ ማግኘት ደግሞ የእግዚአብሔር ትእዛዝ የጥምቀትን ምሥጢራት ተቀብለው የወልደ እግዚአብሔርን ወደዚህ ዓለም መምጣት የሰበኩና የፃድቁ ኖኅ ስድስት መቶ ዓመት ዘመን ፍፃሜን ትርጓሜ ያስረዳል።'),
  ('d50000d0-1dff-5d85-a611-ad21e650e7cd', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 104, 104, 'የሚያዝያ ወር አልፎ በአለተ እሁድ የጥፋት ውሃ ከምድር ተወገደ በምትኩም ደረቅ መሬት (የብስ) ታየ በዚችው እለት ኖኅ ከሚስቱ ጋር ከልጆቹ ጋርና ከልጅ ልጆቹ ሚስቶች ጋር በሕብረት ከታቦቱ ወጡ።'),
  ('f7a7a526-ba97-58b9-abe2-8c8343a6f990', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 105, 105, 'ኖኅ ሰዎቹን ካወጣ በኋላ የዱርአውሬዎቹን እንሰሳቱን ወፎቹንና ሌሎችንም ፍጥረታት ከነበሩበት የታባቱ ታችኛው ክፍል አስወጣቸው ኖኅና ልጆቹ አገርን ቈረቈሩ ንማቁ፡ ብለውም ሰየሟት ።'),
  ('aa2dbb60-0b02-51e5-a7ed-aad566198eef', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 106, 106, 'አቺም አገር ለብዙ ጊዜ ኖረች ኖኅ ከታቦት ውስጥ የወጡትን አንስሳትንና ሰዎችን ቈጠራቸው ኖኅ ከዚህ በመቀጠል ለእግዚአብሔር መሥዋእት የሚያቀርብበትን መሠዊያ ሠራ የእንስሳትንና የወፎችንም ንፁሕ መሥዋእት ለእግዚአብሔር አቀረበ ። እግዚአብሔርም መሥዋዕቱን ተቀበለ ዳግም በጥፋት ውሃ ምድርን እስከዘለዓለም እንደማያጠፋትም ለኖህ ቃልኪዳን ገባለት ።'),
  ('e19766bd-ea2f-56cb-a472-2b58db062f52', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 107, 107, 'እግዚአብሔር የመዓት ምልክት በደመና ላይ ይታይ የነበረውን አስወገደ ከጥፋት ውኃ በፊት የምድር አሕዛብ ከደመና ላይ የእግዚአብሔር የቁጣ ምልክት የሆነውን ዝናም በዘነመ ቁጥር ይመለከቱ ነበር። ኖኅ ከእግዚአብሔር ጋር ቃለኪዳን ከገባ በኃላ ግን ቀረ።'),
  ('77e603cf-9809-5c89-a0c7-ea2595cb73c1', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 108, 108, 'የኖኅ ልጆች የወይን ቦታን አዘጋጅተው ወይንን አመረቱ ከወይኑም የወይን ጠጅን አዘጋጁና ለኖሕ አጠጡት እሱም ከዚህ በፊት ወይን ጠጅን ጠጥቶ ስለማያውቅ ሰክሮ ተኛ ዕራቁቱንም ሆነ።'),
  ('fe0a49f1-35ee-565c-ae97-d873edca92c4', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 109, 109, 'ልጁ ካም የኖሕን ወይን ጠጥቶ በሥካር መያዝ አይቶ ሳቀ ወንድሞቹ ሴምንና ያፈትንም ጠራቸው ያባታቸውን ዕራቁቱ መሆን ተመልክተው እጅግ ደነገጡ ልብስንም አምጥተው በትክሻና በትከሻቸው በመዘርጋት ያባታቸውን ዕራቁትነት ላለማየት የኋሊት በመሄድ አለባበሱት።'),
  ('7e1216a7-d7c5-5a39-a72d-f9b7af73e8b2', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 110, 110, 'ኖኅ በነቃ ጊዜ በሱ ላይ ካም እንደሳቀና ሌሎቹ ልጆቹ ግን ዕራቁትነቱን እንደሸፈኑ ሚስቱ ነገረችው በዚህ ጊዜ ኖኅ እጅግ ተናደደ እንዲህም አለ ካም የተረገመ ይሁን ልጆቹም በሱ ጥፋት ለወንዱሞቹ ባሮች ይሁኑ።'),
  ('17614dd2-1526-5b4a-a1b3-67593113a0f4', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 111, 111, 'የካም ልጆች ከዚሁ በተነሳ ምክንያት ለወንድሞቹ ባሮች ሆነ ካም መላ የሕይወት ዘመኑ በዓመፅና የረከሰውን ነገር በመፈፀም ኖረ ሰባቱ ዕራቁትነት ዘብቷልና የኖኅ በሥካር መተኛትም ከጌታ ሥቅለት ጋር ያገናኙታል እንዲሁም ከጌታ ትንሣኤ ጋር በምሥጢር ይገናኛል ዳዊትም እግዚአብሔር ከእንቅልፍ እንደመነሳት ባለ አኳኋን ከሙታን ተለይቶ ተነሳ ብሏል።'),
  ('4977af79-dcd5-598b-ab82-d6a78008690c', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 112, 112, 'ኢየሱስ ክርስቶስ ከመቃብር ከተነሳ በኋላ የሠይጣንን ኃይል ሠብሯልና የሰቀሉትንም አይሁድ በመላ ዓለም ተበታትነው ካገራቸውም ተነቅለው እንዲቀሩ አድርጓልና በሄዱበትም አገር ለወንድሞቻቸውና ለጌቶቻቸው እንዲገዙና በድሕነትም እንዲንከራተቱ ሁኗል።'),
  ('58d70075-88de-5da0-a6e4-952a9bbb317a', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 113, 113, 'ከጥፋት ውሃ በኋላ ኖኅ ሦስት መቶ አምሳ ዓመት ኖረ ከዚህ ዓለም የሚለይበት ጊዜ ሲደርስ ሴም፣ ካም፣ ያፌት አርፋክስድና ፋሌቅ ወደሱ ተሰበሰቡ እሱም ፀለየላቸው ባረካቸው ስለነሱም ወደእግዚአብሔር ማለደ።'),
  ('e3c2c49e-ec84-57a8-a512-44a6e0cf625e', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 114, 114, 'ልጁንም ሴም እንዲህ ሲል አዘዘው፡ ሥጋየን በምድር በር ወደመዳኛዋም ታቦት ግባና ማንም ሳያይህ የአዳም አባታችንን ሥጋ አውጣው ስንቅንም አዘጋጅ ይህንንም ማንም አይወቅ መልከ ፄዴቅንም ካንተጋር ውሰደው ከናንተ ሁሉ አብልጦ እግዚአብሔር መርጦታልና አንተም ያባታችን አዳምን ሥጋ ተሸከም።'),
  ('10b49da1-b7c7-51fb-a20b-302ea231dc40', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 115, 115, 'በምድር ማሕል ስትደርስ በዚሁ የአባታችንን አዳም ሥጋ ቅበር መልከ ፄዴቅንም አዳም በተቀበረበት ቦታ አስቀምጠው ከአዳም ሥጋ ፊት ለእግዚአብሔር ይገዛ ዘንድ ወደምድር ማህል ስትጓዙ የእግዚአብሔር መልአክ ይመራቹኋል ከፊት ለፊታችሁ እየተጓዘም ጎልጎታ ከተባለው ቦታ ያደርሳቹኋል በዚህም የእግዚአብሔር ሐይል ይታያል።'),
  ('c930b41e-6c9d-5a0c-ad23-d880cd853638', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 116, 116, 'የዓለም መአዝን አራት መሆኑ ሲታወቅ አራት መሆኑ ቀርቶ አንድ ይሆናል በዚህም ጊዜ የአዳም ልጆች ድሕነት ይሆናል ይህም ሙሴ ከእግዚአብሔር በተቀበላት የዲንጋይ ፅላት ውስጥ ተፅፎ ነበር።'),
  ('7c74455b-bb40-5d2e-a06d-61d4492842a3', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 117, 117, 'በይበልጥ ግን ይህን ትእዛዝ አጥብቆ እንዲጠብቅ አጥብቆ አዘዘው እንዲህም አለው ይህን ትእዛዝ አዳም ለሴት ሴት ለሄኖስ። ሄኖስ ለቃይናንን ቃይናን ለመላልኤል መላልኤል ለያሬድ ያሬድ ለሄኖክ ሄኖክ ለማቱሳላ ማቱሳላ ለላሜህ ላሜህ ለራሱ ለኖኅ የተላለፈ ነው።'),
  ('a7b81fa9-9ac4-5cc3-a477-241e4ecf49e0', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 118, 118, 'ኖህ ሴሞን ለማንም አዳም የተቀበረበትን ቦታ እንዳያሳይ አስማለው ኖኅ ይህንን ሁሉ ተናግሮ ሲያበቃ ጥር ስድስት ቀን በዕለተ ረቡዕ ሞተ ልጁ ሴምም ገንዞ በምድር ላይ ቀበረው ስለኖኅ ሞት ወገኖቹ አርባ ቀን ሙሉ በታላቅ ሐዘን አለቀሱ የኖኀ ጠቅላላ ዕድሜ ዘጠኝ መቶ አምሳ ዓመት ነው።'),
  ('09155b05-1a97-5a5d-a31e-d7d37a2912c3', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 119, 119, 'ከዚህ በኋላ ኖኅ በድብቅ ወደታቦት ገባና የአዳምን ሥጋ አወጣ። ባባቱ ማሕተምና በራሱ ማሕተም ታቦቷን አተመ ካምንና ያፌትንም ጠርቶ አባቴ ኖኅ ሊሞት በተቃረበ ጊዜ ያዘዘኝን ሁሉ እወቁ እንዲህም አለኝ ወደከፍተኛው ቦታ ሂድ እየተዘዋወርክም ተመልከታት በሷ ውስጥ ያሉትን ፍራፍሬዎችንና ለሰው ልጅ መድሐኒት ሊሆኑ የሚችሉትን ዕፀዋት አውቅ ዘንድ።'),
  ('e46bbbcc-b1c5-57f5-a762-da425a306605', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 120, 120, 'እነሆ ሚስቴንና ልጆቼን ትቼ እሄዳለሁ እናንተ በጥንቃቄ ጠብቁዋቸው አላቸው።'),
  ('482670a3-b4be-5d03-a336-736471c236d5', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 121, 121, 'እነሱም ይህን የምትለውን የምትፈፅም ከሆነ ብዙ ሰውን አስከትለህ ሂድ የምትሄድበት ቦታ ብዙ አንበሶችና ነብሮች ላቸው። ያሉበት ነውና አሉት።'),
  ('46a47602-3cca-5030-a073-1fb520b50c65', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 122, 122, 'ሌም ሲመልስላቸው እንዲህ አላቸው የእግዚአብሔር መልአክ ከኔ ጋር ይሄዳል። እሱም ከአውሬዎች አፍ ይጠብቀኛል። ከዚህ በኋላ ማለዱት እንዲህም አሉት የአባቶቻችን አምላክ ካንተ ጋር ይሁን አይለይህ።'),
  ('628f0707-5b02-53f0-adae-2cdfd1341e09', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 123, 123, 'ሴም ለወንድሞቹ እንዲህ አላቸው አስተውሉ አባቴ ኖኅ ሊሞት በተቃረበ ጊዜ ከኔ ጀምሮ ማንም ወደታቦት እንዳይገባ በጥብቅ አስጠንቅቆ አስምሎኛል እኔም ባባቴ ኖሕና በራሴ ማሕተም አትሜአት አለሁ ስለዚህ እናንተም ሆናችሁ ልጆቻችሁ አንድም ሰው ወደታቦት ለመግባት እንዳይሞክር ተጠንቀቁ።'),
  ('995cfff5-1d17-5b08-a2c0-c65bb5493eb8', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 124, 124, 'እነሱም እሺ ለቃልህና ላባታችን ኖኅ ትእዛዝ እንታዘዘለን አሉት ቀጥሉ ሴም ወደመልከፄዴቅ አባትና እናት ሄዶ መልከፄዴቅ ይሠጡት ዘንድ ጠየቃቸው እነሱም መልከፄዴቅ ካንተፊት ነው እንደፈቀድህ አድርገው አሉት።'),
  ('854b86b5-4c83-5cd5-afe9-b18517cf7269', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 125, 125, 'መልከፄዴቅን ሴም በሌሊት ጠራው ከሱም ጋር የአባታችንን አዳም ሥጋ ተሸክመው ጉዞ ቀጠሉ መልአከእግዚአብሔርም እየመራቸው ወደማእከለምድር አደረሳቸው ማእከለምድር የተባለውን ቦታም ይህ ነው በማለት አስረድቶ ነገራቸው።'),
  ('8cdd5dcc-b8b9-55b8-a0d5-4950402daf17', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 126, 126, 'ምድር በመስኮት አምሳል ተሠነጠቀች የአዳምንም ሥጋ አስገብታ በገዛ ራስዋ እንደወትሮዋ ተዘጋች የጎልጎታም ቦታ እንዲሁ ሆነ ከዚህም ጊዜ ጀምሮ የፍጥረቶች ራስ በዚሁ አኖሩ የከይሲም ራስ በዚሁ ነበር።'),
  ('e676e6ca-da6e-590a-aa14-4578938c1e57', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 127, 127, 'ይህ ከይሲ አዳምንና ሔዋንን ያሳተ ነው የዚሁ ቦታ ስም ሉጦዴዬ ይባላል ትርጓሜውም ህዝብ ሁላቸው ማለት ነው ፍጡራን ሁሉ ለወደፊቱ በዚሁ ይሰበሰባሉና ሴም መልከፄዴቅን አንተ የዓለም ካህን ነህ አለው።'),
  ('23948a79-a506-5740-a4a9-a5c8912eb39b', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 128, 128, 'ዛሬ አንተን የመረጠ እግዚአብሔርን አመሰግነዋለሁ እሱ ለክህነት መርጦሃል እስከመጨረሻው ድረስ ከዚህ ቦታ አትለይ ሚስት አታግባ የራስሕንም ጠጉር አትላጭ ጥፍርህንም አትቍረጥ ደምን አታፍስስ በዚህ ዓለም የምትኖርበትንም ቤት ለመሥራት አትሞክር የእንሥሣትን መሥዋዕት አትሠዋ።'),
  ('75c29aad-82cd-58ae-a3b1-c4d56e4eeb00', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 129, 129, 'ነገር ግን ከእግዚአብሔር ፊት የሚቀርበው መሥዋእትህ ንፁሕ የስንዴ ሕብስትና ከወይን ፍሬ ይሁን የእግዚአብሔር መልአክም እስከ ዘለዓለም ካንተ ሳይለይ ይኖራል።'),
  ('2b5f5a94-193a-5dc9-a2b2-64d62e5993de', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 130, 130, 'ሴም መልከጼዴቅን ከመካነጎልጎታ ካደረሰው በኋላ ሳመውና ከቦታው ትቶት ሄደ።'),
  ('c3bcad84-efc4-5dac-a82f-2a6479f16d0e', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 131, 131, 'ሴም መልከጼደቅን የኣዳም ሥጋ እንዲያገለግል ካስቀመጠው በኋላ ተመለሰ ወደሱም የመልከጼዴቅ አባት ፋሌቅና ኢዮስዴቅ መጡ ሴምም መልከፄዴቅ ከመንገድ ታሞ ስለሞተ ቀበርኩት አላቸው።'),
  ('b634c563-be2a-5439-af69-2d414d71a2d1', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 132, 132, 'አባቱና መላ ቤተሰቦቹ የመልከፄዴቅን መሞት ሰምተው እጅግ አዘነ።'),
  ('4f1262fa-37c4-575b-adbe-269a308a2162', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 133, 133, 'ሴም ሦስት መቶ ዓመት ሲሞላው ሞተ ልጁ አርፋክስድ ገንዞ ቀበረው አርፋክስድም በአራት መቶ አምስት ዓመቱ ሞተ ልጁ ሳላም ገንዞ አርፋክስድ በሠራት አገር ቀበረው። አርፋክስድ የተቀበረባት ቦታ አርናሳዊት ተባለች።'),
  ('bd7e6b62-75fd-5ade-ad20-9a471313b0e7', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 134, 134, 'ሳላ አራት መቶ ዓመት ሲሞላው ሞተ ልጁ ቦኤርሞ ራሱ ሳላ ባነፀው ቦታ ቀበረው ይህ ቦታ የስንካርብ አጠገብ በመባል ይታወቃል ቦዔር አራት መቶ አርባ አንድ ዓመት ከኖረ በኋላ ሞተ ልጁ ፋሌቅም (የመልካፄዴቅ አባት) ራሱ ቦኤሪ ባሻነፃት መቃብር ቀበረው ታዋም በስሙ ተሰየመች።'),
  ('25233143-5d56-5a3b-adca-1b04d43cbacf', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 135, 135, 'ፋሌቅ አራት መቶ ሰላሳ ዓመት ኑሮ ሞተ ልጁ ራግውም ገነዘው ቀበረውም ራግው ሁለት መቶ ሠላሳ ዓመት ሲሆነው የሴም የካምና የያፌት ልጆች ተሰበሰቡ ከፍተኛ ወደሆነችውም ቦታ አንድ ላይ በመሆን ጉዞአቸውን ቀጠሉ የተጓዙበት ቦታ ንስቆባቱእ ይባላል።'),
  ('b2482e68-984f-5acf-ab4c-0257e53ab701', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 136, 136, 'በዚሁም ይኖሩ ጀመር በሱሩያን በፅርዕና በከለዳውያንም ቋንቋ ይናገሩ ነበር። የአዳም የንግግር ቋንቋ የእብራውያን ቋንቋ ነበር። የሚሉ ሁሉ ውሽታሞች ናቸው።'),
  ('4ebead5d-8074-5b1d-a997-1919b6f919bd', '5bc6200a-82ca-5c0a-ac0a-7309c6fccd85', '4ff36f52-0856-5564-a0bf-c44ac1626f56', 137, 137, 'በእግዚአብሔር ቀኝ የሚቆሙ ሁሉ በሱርስት ቋንቋ ብቻ ይናገሩ ነበር።'),
  ('f1352de7-3f69-5f51-aca5-911d879d3ea1', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 1, 1, 'ራግው አሕዛብ በቋንቋ እንደተለያዩ ባየ ጊዜ አዘነ ራግው በሁለት መቶ ሠላሳ ዘጠኝ ዓመቱ ሞተ።'),
  ('bf3f604d-6c96-54be-ae15-73b3f68cbfac', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 2, 2, 'ልጁ ሴሮኀ ገነዘው ባገሩም ቀበረው የቀበረበትንም ቦታ በስመ ሰየመው።'),
  ('a3461a3a-24ff-5410-a5a1-6dfdddc93369', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 3, 3, 'ከዚህ ጊዜ ጀምሮ ሕዝቦች ተለያዩ ምድርንም ተካፈሉዋት ለሴ ልጆች ሰላሳአምስት ነገሥታት ለካም ልጆች ሰላሳአምስት ነገሥታ ለያፌት ልጆች ሰላሳ ሰባት ነገሥታት ሆነላቸው።'),
  ('557dce5f-e1e4-57c7-aad0-7df03c4a34ca', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 4, 4, 'የሴም ልጆች መንግሥት ከፋርስ ምድር ጀምሮ ወደምስራቅ ይደርሳል ይህንንም ሆድሰፌን የሚባለውን የምስራቁን ባሕር ይይዛል።'),
  ('dc25c54c-44fb-57a4-aafd-f25570c31456', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 5, 5, 'የያፌት ልጆች መንግሥት ከደብርቅዱስ ዳርቻ ተነስቶ ደብረነን ወደተባለው ቦታና ወደምሥራቅ አቅጣጫ አስከሚገኘው ምዕጣሮስ ወደሚባለው ቦታ መሄጃ ይደርሳል።'),
  ('070cec83-9030-51ed-a14a-1e5c1572b4bd', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 6, 6, 'ሁለተኛውሞ ግዛት በምድር ላይ ነበራቸው ሴሮኝ መቶ ሰላሳ ዘጠኝ ዓመት ሲሞላው ሐይለኛው ናምሩድ ነገሠ ብዙ አገሮችንም ተቈጣጠረ ለመጀመርያ ጊዜ የነገሠው ግን በባጢሉን ነው።'),
  ('139e800c-a6dd-59b4-aeee-841124e31891', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 7, 7, 'ናምሩድ ጥቁር የተቀደደ የሚመስል ምልክትንና የተለያየ የቀለም መልክ ያለውን አክሊል በሰማይ ላይ አይቷል።'),
  ('2dfccd16-e4ef-55d9-a015-f33f59a073c4', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 8, 8, 'ናምሩድ ሱስን የተባለውን ሰው ከሰማይ ላይ ባየው መሠረት አክሊል እንዲሠራለት አዘዘው። እሱም ከተለያዩ የዓልማዝ። የዕንቁና የወርቅ ንጥረ ነገሮች አክሊልን ሠርቶ በራሱ ላይ ደፋለት።'),
  ('f479882a-d83e-5a6b-a73f-edec7cf0d14d', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 9, 9, 'ንጉሥ ሁኖ በራሱ ላይ አክሊልን በመድፋት ናምሩድ የመጀመርያ ነው ነገር ግን ናምሩድ ከሰማይ አክሊል እንደወረደለት የሚናገር መረዳት የተሳነው ልበቢስ ነው ተብሏል። የናምርሩድ ዘመን ስድሳ ዘጠኝ ነው ከዚያ ሞተ።'),
  ('c88f4657-0016-5aa0-a4a5-1ebabbdac1fc', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 10, 10, 'ከናምሩድ በፊት የነገሠው ሴሩ፥ ከአዳም በኋላ መቶ ሰላሳኛ ሁኖ ነገርሷል። ሴሩህ ግብፅንም ጠቅልሉ ሲገዛ ግብፃውያን ዓምፀው ለራሳቸው ለመጀመርያ ጊዜ ፍርቆር የተሳለውን ንጉሥ አነገሱ።'),
  ('ce48a0a4-dbc9-5942-a8ca-03f2ceaf89c9', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 11, 11, 'ፍርቆር በግብፃውያን ላይ ስድሳ ስምንት ዓመት ነገሰ ፌርኖስ የተባለውም ንጉሥ ሱባ በተባለው አገር በነገሰ ጊዜ ሁለት ያገር ታላላቅ ሰዎችን ጠራ። እነዚህን ሰዎች አውቂርና ካልያ ከተባለው አገር ነው የጠራቸው። ።'),
  ('726d5479-472c-504d-a182-532b815ee694', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 12, 12, 'በነዚሁ ሁለት አገሮች በወርቅ የተለበጠ ግንብን ይህ ንጉሥ መሥራቱ ይነገራል። ከሱ ቀጥሎ ናቶል የተባለው ንጉሥ ነገሠ።'),
  ('800bcdb5-4fc1-5ed7-a859-6982531d31c0', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 13, 13, 'ሱባ በተባለችውም አገር ግንብን ገነባ። በዚችው አገር እስከ መዋዕለ ሰሎሞን ወልደዳዊት ድረስ ሴቶች ብቻ እየነገሱ ኖሩ።'),
  ('086233f6-395c-5852-a6c3-8a1bf184588c', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 14, 14, 'ሰዎች ጣዖትን ማምለክና እግዚአብሔርን መካድ ጀመሩ ለጣዖቶች ሠገዱ በዚህም የርስበርስ መለያየት እየሰፋ ሄደ ይህ ሁሉ ሲሆን ግን ተው ተመለሱ የሚላቸው አስተማሪ ፈፅሞ በዚህ ምድር አልነበረም።'),
  ('361f78ea-0af0-5678-aadc-cf43a10ef8a4', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 15, 15, 'የየግላቸውንም መንገድ ተከተሉ ፀሐይን ያመለከ አለ ጨረቃንም ያመለከ አለ ሰማይን ያመለከ አለ ጣዖትን ያመለከ አለ ኮከቦችን ያመለከ አለ ምድርን ያመለከ አለ እንስሳትን ያመለከ አለ ዕንጨቶችን ያመለከ አለ ውሆችንና ነፍሶችን ያመለከ አለ ሰዎች ይህን ሁሉ ለማምለክና ከእግዚአብሔር ለመራቅ የቻሉት በአጋንንት ስለታወሩ ነው።'),
  ('730c948b-082f-54de-ad44-b14010996e71', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 16, 16, 'ሠይጣኑም መጨረሻ ወደሌለው የጨለማ ዐዘቅት ከተታቸው ከነሱ መካከልም ማንም በዘመን መጨረሻ የሙታን ትንሣኤ ሥእል እንዳለ ፈፅመው አያምኑም ነበር። የሞተውን ሰው ሥለው ለመታሰብያነት ያስቀምጡ ነበር።'),
  ('e2fcba83-dbcf-57dc-a3f4-75d664774360', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 17, 17, 'ምድር በመላ በሐጢአት ተመላች የሰው የእጅ ሥእልም በየቦታው መላ ሴሩኅ ሁለት መቶ ሰላሳ ሰባት ዓመት ሲሞላው ሞተ ልጁ ናኮሪም ገነዘው ራሱ በሠራት ቦታም ቀበረው በስሙም ሰየማት።'),
  ('005baf67-7fa4-599e-a117-ccedcb4b8644', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 18, 18, 'የናኮር ዕድሜ ስድሳስምንት ዓመት ሲሆን ልዑል እግዚአብሔር ፍጥረትን ሁሉ ተመለከተው ጣዖትን ማምለክ ሥራው አድርጎ ነበርና ምድርን አነዋወጣትና በየቦታው ተክለው ያመልኩባቸው የነበሩት ጣዖታት ሁሉ ሠጠሙ።'),
  ('a3c90c14-38fe-591b-a18c-54db248b4c6b', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 19, 19, 'እነሱ ግን ይህን ሁሉ የእግዙአብሔር ቁጣ ቢያዩም ከበደላቸውና ከክፋታቸው ጨርሰው ሊመለሱ አልቻሉም ታራ መቶ ሃያ ዓመት በገዢነት ሲኖር የሥራይን ነገር አስፋፋ በዘመነ አንድ ሀብታም ሰው ሞተና የሐብታሙ ሰው ልጅ የሟቹን ምሥል ከወርቅ አስቀርፆ በመቃብሩ ላይ አኖረ። ይህ ከሱ በፊት ተለምዶ በቆየው ባህልና ሥርዓት አደረገው እኔ እበልጥ እኔ እበልጥ በመባባል የሟቹን ሥእል በመቃብር ላይ የማስቀመጡ ባህል እጅግ ተንሠራርቶ ነበር።'),
  ('d9470307-f2dd-5f1d-a294-919c68a78d10', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 20, 20, 'ይህ የሀብታሙ መዋች ልጅ ባባቱ መቃብር ላይ ላስቀመጠው የወርቅ ምስል ጠባቂ ሰው አስቀመጠለት በወርቅ ምስሉ ላይ ያደረው ሠይጣን ጠባቂውን ሰው በሟቹ ሰው አንደበት አነጋገረው ሰውየውም የሰማውን ለሐብታሙ ልጅ ነገረው።'),
  ('bd3a14c3-78f3-5f7e-a99f-3e92b0f5310e', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 21, 21, 'ከጥቂት ጊዜ በኋላ ሽፍቶች የሟቹን ሃብታም ሰው ልጅ ቤት ዘረፉ ይህም ልጅ ወዳባቱ መቃብር ቤት መጥቶ ከወርቅ ምስሉ ፊት አለቀሰ በምስሉ ላይ ያደረው ሠይጣንም አናገረው።'),
  ('8042cad3-c961-533a-ae3a-627db72f2f74', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 22, 22, 'ባባቱ አንደበትም ካናገረው በኋላ ገንዘቡ በመሉ ሊመለስለት ከፈለገ ልጁን እንዲሠዋለት ጠየቀው። እሱም ትንሹን ልጁ አምጥቶ አርዶ ለሠይጣነ ሠዋው።'),
  ('06c27838-ebc1-53d8-a53e-907158b40c37', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 23, 23, 'ሠይጣን በዚሁ ሰው ከዚሁ ጊዜ ጀምሮ ገባበት የጥንቈላንም ሥራ አስተማረው የጣዖትንም ሥራ ሁሉ እንዲሠራ አደረገው። ከዚህ ጊዜ ጀምሮ ሰዎች ከዚሁ ሰው ልጆቻቸውን ለአጋንንት እያረዱ መሥዋዕተ ማቅረቡን ተያያዙት የናኮር ዘመን ሊያልቅ ሲቃረብ የአጋንንትን ተንኰልና የሰዎቹን በአጋንንት መመራት እግዚአብሔር ተመለከተ ጣዖት አምላኪነታቸውንና ልጆቻቸውን ማረዳቸውንም አየ። እግዚአብሔር ከፍተኛ ነፋስ ዓውሎ በነሱ ላይ ላከ አማልክቶቻቸውንም ገለባበጠ እነሱንም ወደምድር አስገብቶ እነሱም ደፈናቸው ከበላያቸውም ተራራዎችን ሠራ። ከነዚሁም እስከዘለዓለሙ በነዚህ ተራራዎች እንደተደፈነ ይኖራሉ።'),
  ('86ea574a-0f1f-50fc-a2fd-710e5a21e7fd', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 24, 24, 'ሌሎች ደግሞ በታራ ዘመን የጥፋት ነፋስ ተነስቶ እንደነበር ይገልፃሉ እንዲሁም የሕንድ መምህራን ተራሮችና አረብቶች'),
  ('01a7cdb9-f632-52db-afff-ff3d72fba665', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 25, 25, 'በጥፋት ውሃ ዘመን እንደተፈጠሩ ሲገልፁ ሌሎች ደግሞ የቃየል ልጆች በዚችው ምድር ጣዖትን ከማምለክ ጀምሮ ብዙ ሐጢአት ስለሰሠሩ የጥፋት ውሃ ሆነ ተራሮችና ኮረብታዎች በዚሁ ሊፈጠሩ ችለዋል ይላሉ።'),
  ('02e111df-b232-5ea4-a973-f6513f130ce6', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 26, 26, 'ይህን ሁሉ ስንመለከት ተራሮችና ኮረብቶች ከጥንት ጀምረው ተፈጥረዋል የሚለውን ሰው ትክክል እንዳልሆነ እንመለከታለን።'),
  ('4e3ea8d3-8dc2-50c8-a782-079e2318fb44', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 27, 27, 'እነዚህ ተራራዎችና ኮረብታዎች የተፈጠሩት እግዚአብሔር የሰውን ልጆች ስለተቈጣቸው ሊፈጠሩ ብቻ ችለዋል እግዚአብሔር ሰዎች ጣዖትን በማምለካቸው ምክንያት በቁጣ ስለፈጠራቸው በውስጣቸው አጋንንት አሉባቸው ይላሉ ናምሩድ በዘመኑ ከሰማይ እሳት አይቶ ነበር። ይህንንም ያየውን እሳት ያመልከው ጀመር። ይህን ከሰማይ እሳት ሊወጣ ያየበትን ቦታ ላየው እሳትን የሚሰግድበትና የሚያመልክበት አደረገው መላ ሕይወቱንም ለዚሁ ዕጣንን እያጤሰ ማምለኩን ቀጠለበት።'),
  ('8e69edb5-2042-50d9-a569-6f79e1c63b8d', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 28, 28, 'ሰብአሰገል ከዚሁ ጀምሮ ለእሳት መስገድ ጀመሩ። እሳቷ ወደሰማይ ስታርግ ደግሞ ያመልኩዋት ጀመር ዳግመኛም አንድ መኮንን ላስ የሚባል ወደዚሁ ቦታ ውሃ (የሚመነጭበት) ወርዶ ቆመ ነጭ ፈረስንም በዚሁ አቆመ። ውሃውን ለመጠመቅ የሚመጡ ሁሉ ለዚሁ ለቆመው ፈረስ ይሠግዱ ጀመር እሱንም አመለኩት አለው።'),
  ('8dac2e87-b891-57b8-ad82-a8637abcf8b6', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 29, 29, 'ከዚያ በፊት ባዩት መሠረትም ሰብአሰገል ፈረሱን ከፍ ከፍ ያደርጉት ነበር። ከነሱም አብዛኞቹ ወደሱ ይሰግዱ ነበር፡።'),
  ('7f5cb456-78d0-525d-a4c7-95ab95a3d8cf', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 30, 30, 'ናምሩድ ካገር አገር ከቦታ ቦታን መጐብኘት ባደረገ ጊዜ ከኖኅ አራተኛ ትውልድ የኾነውን ቦኒጦር አገኘው።'),
  ('a27bc73a-b689-5c60-a1bb-ac99a211686b', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 31, 31, 'ናምሩድ የኖኀ የልጅ ልጅ የሆነውን ቦኒጦር ባየው ጊዜ ሰገደለት በዚህ ጊዜ ለምን ወደኔ ትሰግዳለህ አለው በብዙ ድካም ስላገኘሁህ ሰገድኩልህ አለው ከሱም ዘንድ ናምሩድ ጥበብንና ምክርን ለመማር ፲ ዓመት ኖረ፡።'),
  ('a656c797-c2d6-528e-ab00-52e0c775b826', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 32, 32, 'ከአሥር ዓመት በኋላ የኖኀ አራተኛ ትውልድ የሆነው በኒጦር ናምሩድን ሸኘo ድጋሚም ወደሱ እንዳይመለስ ነገረው ናምሩድ ባለበት ከወደ ምሥራቅ ተጉዞ ከቦኒጦር የተማረውን ሁሉ በመጻሕፍት አፃፈው፡።'),
  ('a0b9f229-8505-599b-a1f8-096717fc6469', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 33, 33, 'በዚሁ አገር አዝዴሴር የተባለ ሰው ነበረ ሰውየው ለእሳት ይገዛ ነበር። የናምሩድን ትምህርትና ዕውቀት አይቶ በናምሩድ ላይ ቀናበት:'),
  ('b07b6883-3627-573f-a261-8169efa84317', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 34, 34, 'በእሳት እየተመሰለ ሲታይ የቈየው ሠይጣን ወደአዝዴሴር ሄደና አዝዴሴርም የናምሩድ ጥበብ እንዲያስተምረው ሠይጣኑን ጠየቀው ሠይጣኑ በዚህ ጊዜ የናምሩድን ጥበብ እንዳስተምርህ ከፈለግህ ሥርዓቴንና ህጌን ፈፅም ከናትህ እህቶችህና ሴት ልጆችህ ጋር ሥጋዊ ግንኙነትን ፈፅም።'),
  ('bb8541e3-3146-59e9-ab81-27d4fc4dab4b', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 35, 35, 'አዝዴሴር ከሠይጣን የተማረውን ሁሉ ፈፀመ የሱንም ሠይጣናዊ ሥራ ተከትለው ሰዎች እናቶቻቸውን እህቶቻቸውንና ሴት ልጆቻቸውን ይገናኙ ነበር።'),
  ('93bc7f34-b85f-5392-a93d-a60656ec653f', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 36, 36, 'ሠይጣን ለአዝዴሴር የሥራይንና የጥንቈላን ትምህርት ሁሉ አስተማረው የከለዳውያን ሰዎች ሁሉ በዚሁ ትምህርት ተሠማሩ ይህንን ተግባር የሚከተል ሁሉ ከእግዚአብሔር ዘንድ ይቅርታ የለውም።'),
  ('9d2aa11b-1756-5690-a0aa-8189b2ed0472', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 37, 37, 'ከኖኅ አራተኛ ትውልድ ከሆነው ቦኒጦር ዘንድ ናምሩድ የተማረው የከዋክብት ትምህርት የዓመታትንና የወራትን መለዋወጥ ለማወቅ የሚረዳን ነው ይህን ትምህርት ፅርዓውያን አስጠሮንያ እያሉ ይጠቅሱታል።'),
  ('a26fca18-41b2-55a8-ae2c-6db611868b7d', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 38, 38, 'ናምሩድ ትልልቅ አገሮችን ሠራ የነዚህም አገሮች ስም ግደብሮር አለር እሱ። ስልው ወቀጦአስትኑን። አርዳጊን የእርድገንንና የወለላን አገሮች ናቸው።'),
  ('dddb95a7-b6b4-51ff-a934-a2f2ac303aaf', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 39, 39, 'ሌሎችንም አገሮች ሠርቷል ታራ ሁለት መቶ ስድሳ ሦስት ዓመት ሲሞላው ሞተ ልጁ አብርሃምም ገነዘው ታግራን በተባለው አገርም ቀበረው።'),
  ('9f0ccc43-aaff-5d0a-ab57-fe7ae0904ad1', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 40, 40, 'በዚህ ጊዜ እግዚአብሔር አብርሃምን አዘዘው አባቱን ይቀብር ዘንድ እሱም ቀበረው ወደ ተቀደሰችውም አገር ይሄድ ዘንድም አዘዘው አብርሃምም ሚስቱን ሣራንና የወንድሙን ልጅ ሎጥን ይዞ በሰባ ዓመቱ ተነሳ ከአሕዛብ ነገታት ጋርም ጦርነት ገጠመ እነሱም ከፊቱ ሸሹ።'),
  ('121752ad-fb7b-54c0-a49f-6e57d917515b', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 41, 41, 'በዚሁ ጊዜ ለአብርሃም ልጅ አልነበረውም ሚስቱ ሣራ መካን ነበረችና አብርሃም ከጦርነት ከተመለሰ በኋላ እግዚአብሔር አብርሃም ዋሪግናን ወደተባለችው ቦታ ይሄድ ዘንድ አዘዘው ዋሪግናን ማለት ደብረዋኖስ ማለት ነው።'),
  ('df197ee5-65e6-5031-a6b7-963ab5499ae3', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 42, 42, 'አብርሃም ጉዞውን ቀጠለ መልከጼዴቅን ባየ ጊዜ ወደምድር ሰገደ የእግዚአብሔር ካህን የሆነውን መልከጼዴቅ ተገናኝቶታል።'),
  ('95c41c4c-8156-5eb8-aa18-47f0691f8a69', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 43, 43, 'አብርሃም መልከፄዴቅን ባየው ጊዜ ከሱፊት የስንዴ ሕብስትና የተጣራ የወይን ጭማቂ አቀረበለት በዚህ ጊዜ መልከጼዴቅ አብርሃምን ባረከው ስለሱም ወደእግዚአብሔር ማለደ። በዚህ ጊዜ እግዚአብሔር ጠጉሩን እንዲላጭ ጥፍሩንም እንዲቈርጥ ለመልከጼዴቅ ነገረው። እሱም የታዘዘውን አደረገ።'),
  ('e1c5cda2-e59a-50fe-ac49-945d6adb4997', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 44, 44, 'መልከጼዴቅ በዚህ ጊዜ ቀደሰና ለአብርሃም ከሕብስቱና ከወይኑ አቈረበው አብርሃም በበኩሉ ለመልከጼዴቅ ካለው ሀብት ሁሉ አንድ አሥረኛውን ሠጠው።'),
  ('15f3a44f-dc58-5663-af1e-55529ca6acb3', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 45, 45, 'እግዚአብሔር በድጋሚ ለአብርሃም ተናገረው እንዲህም አለው የመልከፄዴቅን በረከት ተቀብለህ በመልከጼዴቅ እጅ ቈርበሃልና እኔ አንተን ከፍ ከፍ አደርግሃለሁ አከብርህማለሁ ዓይኖቼም ካንተ ላይ ናቸው።'),
  ('4928d40e-0423-571d-a87e-de3f35f3d104', 'b9017446-a5c2-5087-a1f9-21109204171e', '5be93d17-5c6d-5d58-a78b-a6b22e7c0e29', 46, 46, 'እግዚአብሐር እንደገና ለአብርሃም እንዲህ አለው ከፍ አድርጌ እባርክሃለሁ ዘርህንም አበዛለሁ።'),
  ('7062c971-e6a8-558c-ae92-615b12e42545', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 1, 1, 'አብርሃም የሰማንያ ሰባት ዓመት ሰው ሲሆን እስማኤልን ከአጋር ግብፃዊት ወለደው። አጋር አብርሃም ወደግብፅ በተሰደደ ጊዜ የግብፅ ንጉሥ ፈርኦን አገልጋይዋ ትሆን ዘንድ አጋርን ለሣራ ሠጥቶአታል ሳራ የአብረሃም እሕትነቷ በናት አይደለም ባባት ብቻ የአብርሃም እህት ናት።'),
  ('b9cba31d-d46e-5c7e-aed2-a1e85ae81921', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 2, 2, 'ታራ ሁለት ሚስቶችን አግብቷል የመጀመርያዋ ሚስቱ ቱና ትባላላች ከሷ አብርሃም ተወለደ። ቱና አብርሃምን ብቻ ወልዳ ሞተች። ታራ እንደገና ትሕዴፍ የምትባለውን ሁለተኛዋ ሚስት አገባ። ከሷ ሣራ ተወለደች።'),
  ('93228076-4888-5069-a954-b52998ee0165', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 3, 3, 'አብርሃም ለግብፁ ንጉሥ ሣራ እሕቴ ናት ሊል የቻለው በዚሁ ምክንያት ነው።'),
  ('7bd61971-cb94-520a-a391-ebe6bcb336ed', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 4, 4, 'አብረሃም የዘጠና ዘጠኝ ዓመት ሰው ሲሆን እግዚአብሔር ወርዶ ለሣራ ልጅ ሠጣት አብርሃም መቶ ዓመት ሲሞላው ሣራ ልጁ ይስሐቅን ወለደችው እሱን እግዙአብሔር ለእብርሃም ሠጥቶታልና።'),
  ('e5c641aa-6c9a-551a-ab57-2cee79346eda', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 5, 5, 'ይስሐቅ የአሥራ ሁለት ዓመት ልጅ ሲሆን አብርሃም ከእግዚአብሔር በታዘዘው መሠረት ደብረማኖስ በተባለው ቦታ ሊሰዋው ወደደ። ደብረማኖስ የተባለው ቦታ በኋላ ጌታችን መድሓኒታችን ኢየሱስ ክርስቶስ ለሰው ልጆች ቤዛ ሁኖ የተሰቀለበት ጎልጎታ ነው። እግዚአብሔር አዳምን በጎልጎታ ነው የፈጠረው።'),
  ('8f597fdc-f3d5-5457-a864-3024df2bd50d', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 6, 6, 'እንደገናም አብርሃም በዚሁ ቦታ በእንጨት ላይ የታሰረን በግ አይቷል በዚሁ ቦታ የአባታችን አዳም ሥጋ ተቀብሯል በዚሁ ቦታ ዳዊት የኢየሩሳሌምን የጥፋት ሠይፍ የያዘ የእግዚያብሔርን መልአክ አይቷል ።'),
  ('4ccaf978-b03f-5274-a903-be11dfa02de2', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 7, 7, 'አብርሃም ይስሐቅን ወደ መሠዊያው የቀረበበት ምክንያት የጌታችን መድሐኒታችን እየሱስ ክርስቶስ ስለ አዳምና ልጆቹ ድሕነት የሚሰቅለውን ስቅለት አርአናያ ነው ጌታችን እየሱስ ክርስቶስ አብርሃም አባታችሁ ዕለቴን ያይ ዘንድ ተመኘ አየም በማለት የገለፀው የዚህን ምሥጢር ሲገልፅ ነው።'),
  ('11c9471d-2d55-5e3d-a918-48fff1ead0b3', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 8, 8, 'በዕንጨት ላይ ታሥሮ አብርሃም ያየውንም በግ የጌታችን መድሐኒታችን ኢየሱስ ክርስቶስ ምሳሌ ነው።'),
  ('5afd225d-bab2-5bd8-aa47-0280514bda23', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 9, 9, 'አብርሃም ደስሐቅን ዳዕዋው ዘንድ ወደተራራ ያወጣበት ምክንያት የኢየሩሳሌም የመታደስ ወቅት ስለነበር ነው መልከፄዴቅ የእግ ዚአብሔር ካህኑ በተገለጠ ጊዜ አሕዛብ ከያቅጣጫው በረከቱን ለመቀበል ወደሱ ጐረፉ።'),
  ('25664d01-5814-5362-a6b0-4f3f61b63501', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 10, 10, 'የመልከጼዴቅን በረከት ያመጡት ነገሥታት የእለግንደርዋ ንጉሥ አጉተማልንግ የሳኤል ንጉሥ የበታች የሆነ የዳላዞር ንጉሥ የእልሞ ንጉሥ የኢማኢሙራ ንጉሥ ባርኤል የሰዶም ንጉሥ የሆነው በርኡ የዓግያት ንጉሥ በሪኡስ የአለዎን ንጉሥ ሲይን የሰላም ንጉሥ ሲልአደን የደማደስቆ ንጉሥ አላን የባዳም ንጉሥ በጋጣረ ናቸው።'),
  ('a94054e4-371b-53da-a48c-e0d3c20a2e7c', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 11, 11, 'ልጄ ቀሌሜንጦስ ሆፃ የነገሥታቱን ሁናቴ እገልጽልሃለሁ እኒህ ከላይ ስማቸው የተዘረዘረው ነገሥታት በየበኩላቸው ወደያገራቸው አብሮአቸው ይሄድ ዘንድ የእግዚአብሔር ካህንና የሰላም ንጉሥ የሆነውን መልከጽዴቅን ለመኑት ንግግሩን ሰምተው አክብረውታልምና።'),
  ('00597c52-32ef-5044-ad83-4ab72d3fc3a2', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 12, 12, 'መልከፄዴቅ ግን እግዚአብሔር በዚሁ ቦታ እንዲቀመጥ ስላዘዘው ለመሄድ እንደማይችል ነገራቸው ነገሥታቱ በዚህ ጊዜ ተመካከሩና ቤተመቅደስን በገንዘባቸው እንዲሰሩ ወሰኑ መቅደስንም ሠርተው ለመልከጼዴቅ አስረከቡት መልከፄዴቅም መቅደሱን ኢየሩሳሌም አላት።'),
  ('c34767f1-0ed5-56db-a37d-9bab634ae107', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 13, 13, 'ከቴማን ነገሥታቸም አንድ መልእክተኛ ወደመልከፄዴቅ መጥቶ ባየው ጊዜ እጅግ አከበረው ብ እጅ መንሻንም ለመልከጼዴቅ ሠጠው።'),
  ('ee3f0dc1-38c1-58a1-af99-9243f7e8a8d4', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 14, 14, 'ነገሥታት መልከጼሌቅን በከፍተኛ መዓርግ ይመለከቱት ነበር። የነገሥታት አባት በማለትም ሰየሙት ብዙዎች መልከጼዴቅ አይሞትም የማለት አስተሳሰብ አድሮባቸው ነበር። ነቢዩ ዳዊት አንተ አንደ መልከጼዴቅ ሹመት የዓለም ካህን ነህ ያለውን በመመለከት ነው አይሞትምያሉት ዳዊት ግን አይሞትም አላለም እሱ ሰው ሆኖ ስለተፈጠረ እንዴት አይመችም ይላሉ።'),
  ('6821fafa-82c8-534c-a37a-abc14b157628', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 15, 15, 'ነገር ግን እግዚአብሐር ልዑል ካህንም አደረገው ሙሴ የመልአፄዴቅን በእግዚአብሔር ከመመረጡ በፊት ያለውን ሕይወቱ በኦሪት ውስጥ አልመዘገበም ነገር ግን እሱ የአርፋክስድ ልጅ የፋሌቅ ልጅ መሆኑ ይታወቃል።'),
  ('dd8e6264-9188-5f57-a9dd-7bf0db3eaa2c', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 16, 16, 'በዘመነ አብርሃም አንድ ንጉሥ በምሥራቅ ክፍል ነግሦ ነበር። ስሙ ብርመስ ይባላል ብርመስ አራት ልጆችን ወልዷል አራት አገርንም አቅንቶ በአራቱ ልጆቹ ስም ሰጠ አመርያ ቀሪንና ለዩሁ ብሉ ሰየማቸው ከዛ ዓመት በኋላ ይህ ንጉሥ ወደ ደሴት ሄደ በደሴቶቹም ግንቦች ሠርቶ አቆመና ።'),
  ('025d8afe-2ab5-5d48-a673-1d68c208784f', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 17, 17, 'በሚስቱ ስም ሰየማቸው። ሰዎች የዚህ ንጉሥ ምስል እየሳለ ይህወግዱ ነበር። የአብርሃም ሚስት ሣራ ስለሞተች አብርሃም የዳም ንጉሥ ልጅ የሆነችው በቀጥር ልጅ መንጠርባን አግብቶ ነበር።'),
  ('79d00394-bc3a-526f-a170-2496f421eb4a', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 18, 18, 'ይስሐቅ በአርባ ዓመቱ ሚስት እንዲያገባ ተፈቀደለት አልአዛርም ርብቃን ሊያገባው ሄደ አብርሃም በጀሮ ዓመቱ መተ ልጆቹ ይስሐቅና እስማኤል ሚስቱ ሣራ ከተቀበረችበት አጠገብ ቀበሩት'),
  ('9d20041c-9de8-5ab3-a0b5-baed2978706a', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 19, 19, 'ይስሐቅ ፵ ዓመት ሲሞላው ሚስቱ ርብቃ ፀነሰችለት ሄደች የመውለጃ ጊዜዋ ሲደርስም ወደ መልከፄዴቅ መልከፄዴቅም ባረካት ስለሷም ጸለየ ወደእግዚአብሔርም ስለሷ ማለደ ልዑል እግዚአብሔር ካንቺ ሆድ ሁለት ወንዶች ልጆች ይወለዳሉ።'),
  ('9490ba60-aed7-5164-afc2-bb397c434afd', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 20, 20, 'ሁለቱ ካንቺ የሚወለዱት ልጆች የሕዝብ ዓለቆች ይሆናሉ። ትልቁ ለትንሹ ይገዛል ሁለቱም በመካከላቸው ፍቅር የላቸውም እርስ በርሳቸው ይጣላሉ ከትልቁ የሚወለዱት ልጆች ከትንሹ ከሚወለዱት ልጀች ጋር ይጋደላሉ።'),
  ('4557ed11-40e2-5edd-a06b-60c9f569aa50', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 21, 21, 'ከትንሹ ልጅ ልጅ ለሚወለደው እኔ እገዛለሁ እሱም የልዑል አግዘአብሔር ልጅ ይባላል። አሱም ሕያው ነው በዕንጨት ላይ ተሰቅሎም በአዳም ውድቀት ለሰዎች የተላለፈውን መርገም ያስወግዳል።'),
  ('4e6773b5-65ae-5043-a4fc-56bac357879f', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 22, 22, 'ይስሐቅ አዲስ አገርን ሠርቶ አይል ብሎ ሰየማት ይስሐቅ ስድሳ ዓመት ሲሞላው ኢያሪኮን ስባት ነገሥታት ሠርዋት እነሱም የአልገልጊን ንጉሥ የባሳን ንጉሥ የአሞሬዎን ንጉሥ የገባኦን ንጉሥ የሄርጌሴኖን ንጉሥና የቀርናቤን ንጉሥ ናቸው።'),
  ('9c1d18e0-3e2d-598b-a877-79f8e451b455', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 23, 23, 'እነዚህ ሰባት ነገሥታት ለየግላቸው መታሰቢያ በኢያሪኮ ላይ ሠሩ የነሱንም ባህል የተከተለው የግብዑ ንጉሥ ሌላ አገርን አቀና ያቀናውንም አገር ምሥር አለው። ይስሐቅ መቶ ሠላሳ ዓመት ሲሞላው የያዕቆብም ዕድሜ ሰባ ዓመት በሆነ ጊዜ እግዚአብሔር ያዕቆብን ባረከው ያዕቆብ በሐጢአት የይስሐቅን በረከት ተቀበለ።'),
  ('ec5b4a93-857f-54fc-a0d7-31c9daa3ad42', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 24, 24, 'ያዕቆብ በጉዞ ላይ እያለ ሰባት ድንጋዮችን አሰባሰበና አስቀመጣቸው እሱም ተኛ በሕልሙም እስከሰማይ ድረስ የሚደርስ የእሳት መሰላል አየ። በዚሁም የእግዚአብሔር መላእክት ይወርዱና ይወጡ ነበር። ከእንቅፉም ሲነቃ ስለዚችው ቦታ ትንቢት ተናገረ እቺ ቦታ የልዑል እግዚአብሔር ቦታ ትባላለችም አለ።'),
  ('aace20af-ff53-5824-ac2f-c709031ee07f', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 25, 25, 'ይህ የሰማይ በር ነው ተብሏል ድንጋዮቹንም ሰበስባቸውና ለእግዚአብሔር መሥዋእት መሠውያ አድርጎ አቀረባቸው። የተቀደሰውንም ዘይት ቀባቸው በዚሁም ከንብረቱ ሁሉ አሥራትን ለእግዚአብሔር ቁርባን ለመሥጠት ተሣለ ያዕቆብ ያያት ምሥጢር እቺ ናት።'),
  ('fe3deff9-2a52-5321-aa1e-8e9f8ae7cf55', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 26, 26, 'ልጄ ቀሌሚንጦስ ሆይ ያዕቆብ ያየው ምስጢር ለወደፊት ስለነበረው ትንቢት ይገልፃል ይህም ስለክርስቶስ ወደዚህ ዓለም መምጣትን ያመለክታል መሰላሉ የክርስቶስን ስቅለት ያመለክታል የመላእክቱ መውጣት መውረድ ደግሞ የዘካርያስን የእመቤታችንንና የኖሎ ሎትንም መበሠር ያሳያል የእግዚአብሔር በመሳልል ላይ መታየት የልደቱን ምልክት ሲያሳይ ያች ያዕቆብ ያያት ቦታ ደግሞ የቤተክርስቲያን ምሳሌ በመሆን ትነገራለች።'),
  ('2197e193-09f5-59e4-a7cc-7170fa1af0ec', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 27, 27, 'ያዕቆብ ያቆማቸው ዲንጋዮች የታቦት አርአያና አምሳል ሲሆን የነሱም በቅዱስ ቅብ መቀባት የቅብዓተ ስብእት ምሳሌ ይሆናል የያዕቆብ ከገንዘቡ ከአሥር አንድ ለመሥጠት ብፅአት መግባት የቅዱስ ቁርባን ምሳሌ ነው።'),
  ('72414dbd-6020-580c-a7b8-7fc3c42e6135', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 28, 28, 'ያእቆብ ከዚሁ ቦታ ተነስቶ ወደላባ ሄደ ላባ የናቱ ወንድም አጉቱ ነው። በመንገዱም የበጎች ዓዘቅት ጉድጓድ አየ። ይህም ዓዘቅት በከባድ ድንጋይ የተዘጋ ነበር። በቀላሉ ለመክፈት አይቻልም ነበር።'),
  ('b68ecc1d-b7b3-535e-a789-f936b55939c6', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 29, 29, 'የላባ ልጅ ራሄል ከዚያ ቁማ ነበር። (በጎቿን ለማጠጣት) ያዕቆብ የውኃውን ጉድጓድ የተከደነበትን ድንጋይ ከፈተና የውሃ መቅጃ ከራሄል እጅ ተቀብሎ በጎቹን ከጉድጓዱ ውሃ በመቅዳት አጠጣቸው በጎቹን አጠጥቶ ሲያበቃ ያዕቆብ ራሄልን ተመለከታት ወደሷም ቀርቦ ሳማት።'),
  ('d6071b35-d86e-5ab7-af9d-3de0769239d4', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 30, 30, 'ያዕቆብ የውሃውን ጥልቅ ጉድጓድ መክፈቱ የቅድስት ጥምቀት ምሳሌ ነው የጥምቀት ምስጢር ረቂቅ ነውና ።'),
  ('b694f6bf-2739-52a5-ab08-e6f5047f8103', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 31, 31, 'ልጄ ቀሌሚንጦስ ሆይ የውሃውን ጥልቅ ጉድጓድ ከፍቶ በጎቹን ከማጠጣቱ በፊት ያዕቆብ ራሄልን ሊስማት አልቻለም የጥልቅ ጉድጓዱን መክደኛ ከፍቶ በጎቹን ካጠጣ በኋላ ግን ራሄልን ሳማት እኔም የዚሁን ምሳሌ እነግርሃለሁ ሰዎች በቅድስት ጥምቀት መንፈስ ቅዱስን ሳይቀበሉ ወደቅድስት ቤተክርስቲያን መግባት ክልክል ነው። በጥምቀት የክርስቶስ በጎች ይሆናሉና።'),
  ('3b54d486-8249-50eb-a396-f4bdfec97f72', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 32, 32, 'ነቢዩ ሙሴም ያዕቆብ ስለራሄል ልጁ ለላባ ሰባት ዓመት እንደተገዛለት ፅፏል ያዕቆብ ከመላ የላባ ሴቶች ልጆች አብልጦ ራሄልን ስለወደዳት ነው ያዕቆብ ስለራሄል ብሎ ሰባት ዓመት ያገለገለው የራሄል መልክ ከልያ መልክ ይበልጣልና።'),
  ('0a925186-701f-5c0c-ac08-fa8f9d40f0f6', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 33, 33, 'በፈርኦን እጅ ከመቀጥቀጥና ከመገዛት እግዚአብሔር በሙሴ መሪነት አይሁድን ያዳነበትንም ምሥጢር በዚሁ ይገለፃል።'),
  ('b94e35df-cd2e-5c58-a9a2-221d018b305b', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 34, 34, 'ላባ ለያዕቆብ እንዲያገባት በቅድምያ የፈቀደለት መልከ መልካሟን ራሄል ሳይሆን መልከጥፉዋን ልያ ነው ያገባው በሌላ በኩል መልከቀናዋ ልያ ራሷን ትከናነብ ነበር። (ውበቷን ላለማሳየት)።'),
  ('8e46db5c-4369-5fd1-ad5f-36aa7eefe71e', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 35, 35, 'መጥፎ መልክ ያላት ልያ የአይሁድ በአምልኮ ጣኦት መጠመድንና ከእግዚአብሔር መንገድ መውጣትን ያመለክታል። ራሄልም ጌታችንንና መድሐኒታችን ኢየሱስ ክርስቶስን ባመኑና ልቡናቸውንም እግዚአብሔር ያበራላቸውን ምእመናን ትመሰላለች።'),
  ('e03def46-0700-56cf-ad99-46e4a4a4b2e4', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 36, 36, 'ያዕቆብ የስድሳዘጠኝ ዓመት ዕድሜ ሰው ሲሆን ሮቤልን ወለደው ከሱ በማከታተል የሮቤልን ወንድሞች ስምዖንን ሌዊን ይሁዳን ይሳኮርን ዛብሎንን ዮሴፍን ብንያምን ጋድን አሴርን ዳንን ንፍታሌምን ወለዳቸው እነዚህ አሥራ ሁለት ልጆች እግዚአብሔር ለያዕቆብ የሠጣቸው በረከቶች ናቸው።'),
  ('290ccc7a-e25f-5e43-a298-77e6881d7bbc', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 37, 37, 'የይስሐቅ ዕድሜ መቶሃያ ዓመት ሲሆን ይስሐቅ ሞተ። ልጆቹ ኤሳውና ያዕቆብም አባታቸውን ይስሐቅን ገነዙት አባቱ አብርሃም ከተቀበረበት መቃብር አጠገብም ቀበሩት።'),
  ('85d347f8-43aa-5e6d-a59f-a6d962cf9071', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 38, 38, 'የያዕቆብ ሚስት ልያ ሞተችና ከአብርሃም መቃብር አጠገብ ቀበሩዋት የያዕቆብ ልጅ ይሁዳ ከነዓናዊት የሆነችውን ሴት በሚስትነት አገባ በዚሁም ያዕቆብ ከባድ ሐዘንን አዘነ ለልጁ ይሁዳም ባባቶቼ አብርሃምና ይስሐቅ ስም እቺን ሴት ከዘሮቼ እንዳትጨመር አለው።'),
  ('1031b7d8-a26b-5f58-a7b1-20b02a12873d', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 39, 39, 'ይሁዳ ግን የያዕቆብን ምክር አልሰማም ሆኖም ከከነዓናዊቷ ልጅ አልወለደም ልዑል እግዚአብሔር የያዕቆብን ልመና ሰምቷልና የከነናውያንም ዘር ከነገደ አብርሃም እንዲጨመሩ አላደረገም።'),
  ('6380dfa9-2af8-53bb-a500-04e1d5a75c12', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 40, 40, 'ይሁዳ ትእማርን ተገናኛት ከሷም ፋሬስንና ዛራን ወለደ በዚሁ ወቅት ያዕቆብ ከልጆቹ ጋር ወደምድረ ግብፅ ሄደ አሥራ ሁለት ዓመትም በግብፅ ኖሩ ያዕቆብ አንድ መቶ አርባ ዓመት ሲሞላው ሞተ በዚህ ጊዜ የዮሴፍ ዕድሜ አምሳሁለት ዓመት ሁኖ ነበር። ስለዚህ አባቱ ያዕቆብን ገነዘው ለጊዜውም ባለበት ምድረ ግብፅ ቀበረው።'),
  ('50e5a942-453e-553d-a1a1-fb32498fa6c7', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 41, 41, 'ካምሳ ሁለት ዓመት በኋላ ዮሴፍ ያባቱ ያዕቆብን ዓፅም ከግብፅ አፍልሶ ወደከነዓን በመውሰድ ባባቶቹ አብርሃምና ይስሐቅ መቃብር ላይ ቀበረው።'),
  ('19080744-6c71-5883-acb1-1f8b4995deb1', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 42, 42, 'ይሁዳ ፋሬስን ወለደ ፋሬስ ኤስሮሞን ወለደው ኤሥሮሞ አራሞን ወለደው አራሞ አሚናዳብን ወለደው አሚናዳብ ነአሶንን ወለደው።'),
  ('ecc4d8c3-fdc6-576b-a60b-34f0eabccb1a', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 43, 43, 'ከይሁዳ ትውድ ሁሉ የነአሶን ይበልጣል የነአሶን አባት አሚናዳብ የካህኑ አሮን አልአዛር ልጅን አግብቷል። ከሷም ፊኒሐስ ካህንን ወለደው ስለዚህ የቤተ እሥራኤል ክህነት ከአሚናዳብ ተመሠረተ። · ከነአሶን ደግሞ የቤተእስራኤል መንግሥት ተመሠረተ።'),
  ('491bcdb5-d1d6-5472-a2f1-20774cee117c', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 44, 44, 'ልጄ ቀሌሚንጦስ ሆይ መንግሥት በይሁዳ ለእሥራኤል ልጆች እንደተመሠረተ አስተውል ነአሶን ሰልሞንን ወለደው ሰልሞን ከራኬብ ቦኤዝን ወለደው ራኬብ የነገሥታት ዘር ናት።'),
  ('fae2f666-7f30-593b-acad-d7c84621102e', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 45, 45, 'ልዑል እግዙአብሔር ሎጥን ከሴቶች ልጆቹ ጋር የግብረ ሥጋ ግንኙነት በማድረጉ አላረከሰውም ነውር ሁኖም አልተቈጠረበትም አብርሃምን ተከትሎ ካገሩ በመውጣቱና ከሰዶም በመላእክት ትእዛዝ ሳያቅማማ ። በመውጣቱ በእግዚአብሔር ዘንድ ታላቅ ነው።'),
  ('05b44624-b469-523e-a031-7e1ecccb16a3', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 46, 46, 'ስለዚህ ራኬብ ከሎጥ ከተነሱ ነገሥታት ትውልድ ያላት ናት። ከነዚሁም ሲያያዝ መጥቶ ከራኬብ ዘር የሆነችውን ሚስት የዳዊት ልጅ ሰሎሞን አግብቷል። ሰሎሞን ከአብርሃም ዘር መሆኑ ሲታወቅ ሰባት መቶ ዕቁባቶችን አግብቶ በንጉሥነት ተቀምጦ ነበር።'),
  ('aae13e42-580f-5703-a83a-322f0841fe7e', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 47, 47, 'ሰሎሞን ግን ከነዚህ ሁሉ ዕቁባቶቹ አንድ ልጅ እንኳ አልወለደም ልዑል እግዙአብሔር የከነናውያን ዘር ጌታችን ኢየሱስ ክርስቶስ ሥጋን ከሚለብስባቸው የተመረጡ ሕዝቦች ጋር አንድ ለማድረግና ። ለማቀላቀል (ለማደባለቅ) አልፈለገምና።።'),
  ('597c3a77-2d09-508a-a19d-e5387c6f8310', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 48, 48, 'የሰሎሞን ሚስቶች በሙሉ ከምድረከነአን ዘሮች ነበሩ የሙሴ ታሪክ ቅዱሳት መጻሕፍት እንደሚነግፉን የያዕቆብ ልጅ ሌዊ ካባቱ ያዕቆብ ጋር ወደግብፅ ሄደ ከዝያው ስለቀረ ከሱ ዘሮች ሙሴ ትእማርንና የነዌ ልጅ ኢያሱና ካሌብ በምድረ ግብዕ የእሥራኤል ልጆች እያሉ ተወለዱ።'),
  ('f9d5e6e3-0b85-5998-aaf6-7ef0828dd72b', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 49, 49, 'ሙሴ ወደወንዝ ውሃ በተጣለ ጊዜ ሰፈር የተባለችው የፈርኦን ሴት ልጅ ወስዳ ከቤቷ አሳደገችው ሙሴ አርባ ዓመት ሲሞላው ናቦሞ የተባለውን የፈርኦን የመጠጥ አለቃ ገደለውና ራጉኤል ወደተባለው የምድያም ካህን ሽሽ።'),
  ('58516864-156e-596a-a95a-bce23022f273', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 50, 50, 'በዚሁ የራጉኤልን እህት አግብቶ ሁለት ልጆችን ወለደ ሁለቱን ልጆች የወለዳቸው በአምሳሁለት ዓመቱ ነው የሙሴ ጠቅላላ ዕድሜ መቶ ሃያ ዓመት ሲሆን በምድረግብፅ አርባ ዓመት በምድረ ምድያም ፵ ዓመት እስራኤልን በምድረበዳ እየመራ ዓመት ነራል።'),
  ('e4739981-2816-5e59-a22d-00edf38c06e0', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 51, 51, 'ሙሴ ከሞተ በኋላ የነዌ ልጅ ኢያሱ ሰላሳ አራት ዓመት እስራኤሎችን ገዛቸው ከሱ ቀጥሎ ከሐዲው ኩስ ስድሳ ዓመት ገዛቸው ከሱ ቀጥሎ ጎቶልያንያል ወልደ ቄፋዝ የካሌብ ልጅ ሃያ ዓመት ገዛቸው ከዚያ በኋላ ላንድ መቶ ስድሳ ዓመት በኤግሎሞ ንጉሠ ሞአብና በተከታዮቹ መቶ ስድሳ ዓመት እስራኤላውያን ሲገዙ ኖሩ።'),
  ('34e1d3b7-55fa-54eb-a1fa-409cfedecfc5', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 52, 52, 'ከሱም እጅ እግዚአብሐር አዳናቸው ከሱ በኋላ የጌራ ልጅ ናኦድ ሰማንያ ዓመት ሙሉ ገዛቸው ከዚሁ መካከል በሃያ ሰባተኛው ዓመተ መንግሥቱ ፍጥረት ከተጀመረ አራትሺ ዓመት ሞላ። ከናኦድ በኋላ ሕዝበ እስራኤልን የገዛው ኢያሜን ይባላል። ኢያሜን ሃያ አምስት ዓመት ገዝቷቸዋል።'),
  ('c94ae224-379f-520f-a2fd-1c4b2b6c99f8', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 53, 53, 'ከዚያ ዲቦራና ባርቅ አርባ ዓመት ገዙዋቸው። ከነሱ በኋላ ምድያማውያን ሰባት ዓመት ገዙዋቸው ከነሱም እጅ እግዚአብሔር አዳናቸው። ያዳናቸውም በጌዴዎን አማካይነት ነው። ጌዴዎን በበኩሉ እስራኤላውያንን አርባ ዓመት ገዝቶአቸዋል ከሱ በኋላ አቤሜሌክ መቶ ዓመት ገዝቶአቸዋል ከሱ ቀጥሉ ቱላ ወልደፉሕ ሃያ አምስት ዓመት ገዝቶአቸዋል።'),
  ('24b14384-83c2-5415-ad50-1a2495112951', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 54, 54, 'ከሱ ቀጥሎ ኢያኤር ገለአዳዊ ሃያሁለት ዓመት ገዛቸው ከሱ ቀጥሉ ኤሎፍላውያን አሥራ ስምንት ዓመት ገዙቸዋቸው ከነሱም እጅ እግዚአብሔር ልጁን በሰዋው ዮፍታሄ አማካይነት አዳናቸው።'),
  ('c7192091-7a35-5eb6-ab07-2b73f6d87ef8', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 55, 55, 'ዮፍታሄ እስራኤላውያንን ሰባት ዓመት ገዛቸው ከሱ ቀጥሎ ሄሴቦን ሰባት ዓመት ገዛቸው ከሄሴቦን ቀጥሎ ኤሎም አርባ ዓመት ገዛቸው ከሱ ቀጥለው ኢሎፍላውያን አርባ ዓመት ገዙዋቸው ከኢሎፍላውያን ቀጥሉ ኤሉም ዘቡላዊ ፵ ዓመት ገዛቸው ከኤሎም ዘቡላዊ ቀጥለው ኢሎፍላውያን አርባ ዓመት ገዙዋቸው።'),
  ('8fee7731-32e3-5a71-ab08-2badde2c45f2', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 56, 56, 'ከሱ ቀጥሎ እግዚአብሔር በኃይለኛው ሶምሶን እጅ ከኢሎፍላውያን እጅ አዳናቸው ስለዚህ ሶምሶን አሥራ ሁለት ዓመት ገዛቸው። ከሶምሶን በኋላ ግን ደቂቀ እሥራኤል ገገር ሳይኖራቸው አሥራ ሁለት ዓመት ኖሩ ከአሥራ ሁለት ዓመት ያለገዢ መኖር በኋላ ካህን ኤሊ ተነስቶ አርባ ዓመት ገዛቸው ከኤሊ ቀጥሉ ነቢዩ ሳሙኤል አሥራ ሁለት ዓመት ገዛቸው።'),
  ('27bf2e0d-bee1-5b65-a1c0-5ffc08f3c877', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 57, 57, 'በዚህ ጊዜ ሕዝበ እስራኤል ክፉ ሥራን ሠሩ እግዚአብሔርንም አስቀየሙ በላያቸውም ላይ ሣኦልን አነገሱ ሳኦል የእስራኤል የመጀመርያው ንጉሥ ነው አርባ ዓመትንንም ገዝቷቸዋል በዘመኑ ጎልያድ የሚባል ኃይለኛ ተነስቶ እስራኤላውያን አስጨንቆአቸዋል ብዙዎች ወጣቶቻቸውንም ገድሎባቸዋል።'),
  ('55ab460a-3e0f-58dc-a8f7-af688d144042', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 58, 58, 'ከዚያ በኋላ እግዚአብሔር ዳዊትን ላከ ዳዊትም ጎልያድን ገደለው ሳኦልን ደግሞ እግዚአብሐርን ትቶ በአጋንንት ስላሟረተ ኢሎፍላውያን ገደሉት ከሳኦል ቀጥሎ ነቢዩ የእሴይ ልጅ ዳዊት ፴ ዓመት ነገሠ ከዳዊት ቀጥሎ ሰሎሞን ነገሠ ሰሎሞን ብዙ ታላላቅ ሥራዎችን ሠርቷል ሰሎሞን ለአርባ ሰባት ዓመት ሙሉ አውቂር ወደተባለው አገር መርከቦችን እየላከ ወርቅን አስጫነ።'),
  ('157d3fc8-0be9-5c4f-a6b0-60fedf0974c7', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 59, 59, 'ሰሎሞን ብዙ አገሮችን አቅንቷል በምድረበዳው ውስጥ ትልቅ አገርን ሠራና ሀገረ ፀሐይ ብሎ ሰየማት የሰሎሞን ክብር እጅግ በዛ ዝናውም በብሔሮች ሁሉ ተሰማ ጥበቡና ክብሩ እጅግ የላቀ ሁኖ ታየ።'),
  ('8d917266-fdc5-55ab-a7fa-878800734474', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 60, 60, 'የአዜብ ንግሥት ወደሰሎሞን መጣች ለሱም ታዘዘች እንደገና ኀብራን የተባለው የጢሮስና የሲዶና ንጉሥ ወደዕሉሞን መጣ እጅግም ስሎሞንን ወደደው ረዳውም ፈቃዱንም ሁሉ አደረገ ይህ ኀብራን የተባለው ንጉሥ የሰሎሞንን አባት ዳዊትን እጅግ ይወደው ነበር። ነገር ግን ከኀብራን አስቀድሞ ነው ዳዊት የነገሠው።'),
  ('3ce79749-b64c-5252-aef6-47cbf13efd67', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 61, 61, 'ሰሎሞን አንድ ሺ ሚቶችን አገባ እጅግም ስለወደዳቸው ጥበቡን አጠፋ። እነዚህም ሴቶች እግዙአብሔርን ከማምለክ አውጥተው ጣዖትን እንዲያመልክ አደረጉ ለሎሞን በንጉሥነት አርባ ዓመት ሲገዛ ቈይቶ ሞተ።'),
  ('c421ab9a-f6c8-52f5-a428-4d8ed48c3000', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 62, 62, 'ኀብራን የተባለው የጢሮስና የሲዶና ንጉሥ የሰሎሞንን በአምልኮ ጣዖት መበከል ሲያይ እግዚአብሔርን ካደው እኔ እግዚአብሔር ነኝም አለ በባሕሮች ውስጥም የመኖር ችሎታ አለኝ አምላክ ነኝና አለ። ናቡከደነፆር ንጉሥ የኀብራን እግዚአብሔርን መካድ ሲሰማ ሄዶ ገደለው።'),
  ('35056303-e054-5c03-aacc-088971b648f2', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 63, 63, 'ሰሎሞን ሲሞት ልጁ ሮብአም ነገሠ በዚሁ ወቅት ምድር ። በአምልኮ ጣዖትና በዝሙት ረከሰች በኢየሩሳሌም ሰዎች ለአጋንንት መሥዋዕትን ሠው። በሮብአም ዘመን የዳዊት መንግሥት ለሁለት ተከፈለች። ሁለት መንግሥታትም ሆነ ባምስተኛው የሮብአም ዘመነመንግሥት ሴሳን የተባለው የግብፅ ንጉሥ ኢየሩሳሌምን ወረረና በቤተ እግዚአብሔር የነበረውን ።'),
  ('e4ab6723-db9c-511f-ab5a-65f2cc511c36', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 64, 64, 'ንብረት ሁሉ ዘረፈ። ዳዊትና ሰሎሞን በከባድ ጥረትና ድካም በቤተመቅደስ ያከማቹትን ወርቅና ብር አንድም ሳያስቀር ወሰደው ለአይሁድም ይህ ወርቅና ብር የዳዊትና የሰሎሞን ንብረት አይደለም – አባቶቻችሁ ከፈርኦን ግዛት ሸሽተው በወጡ ጊዜ ከግብፅ ይዘውት የመጡ የግብፃውያን ሐብት ነው አላቸው።'),
  ('181fab92-be34-538e-aac8-1c980a4e49e0', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 65, 65, 'የሰሎሞን ልጅ ሮብአም ሞተ የግዛት ዘመኑም አሥራሰባት ዓመት ነው ከሱ ቀጥሉ አብያ የተባለው ልጁ ነገሠ አብያ ሲነግሥ የሃያ ዓመት ልጅ ነበር። በእግዚአብሔር ፊትም ክፉ ሥራ ሠራ ሞተም።'),
  ('49295738-0491-5a1e-a831-439861279a15', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 66, 66, 'እሥራኤሎች አርባ ዓመት ያለንጉሥ ከቈዩ በኋላ የአብያ ልጅ አሳ ነገሠ በእግዚአብሔር ፊትም መልካም ሥራን ሠራ አምልኮ ጣዖትን አስወገደ ዝሙትንም አጠፋ የገዛ እናቱንም የጣዖት ማምለኪያ ሥለሠራች ከኢየሩሳሌም አባረራት የመንግሥቱ ዘመን ሃያ ዓመት ነው እሱ ከሞተ በኋላ ልጁ ዮሳፍጥ የሱን መንግሥት ወረሰ።'),
  ('11581d98-9cac-518b-a66e-d8b466e4287e', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 67, 67, 'ዮሳፍጥ ባባቱ መንገድ አልሄደም የአክ አብን ቤተሰቦች ወደዳቸው ከነሱ ጋርም ርስት መካፈል ጀመረ ብዙ መርከቦችንም ሠራና እንደስሉሞን ወርቅን ተጭነው ይመጡ ዘንድ አውቄር ወደተባለው አገር ላካቸው እግዚአብሔር ግን መርከቦቹን ወደባሕር አሰጠማቸው።'),
  ('16126f93-1481-54eb-ae21-084c27fa11d2', 'a10beb1d-25de-5add-a714-c1ef960f112c', '356cdfdb-a715-5442-a53c-47e20bf13fe9', 68, 68, 'ዮሳፍጥ ሃያ ዓመት በንጉሥነት ቈይቶ ሞተ ከሱ በኋላ ልጁ ኢዮራም በሰላሳ ዓመት ዕድሜው ነገሠ።'),
  ('97e61a7a-a65d-559b-a0ce-6d0c5a9ad90c', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 1, 1, 'በአብ በወልድ በመንፈስ ቅዱስ ስም አንድ አምላክ። ይህ ጴጥሮስ ለተማሪው ቀሌሚንጦስ ብዙ ምሥጢርን የገለፀበት ዝግጅት ነው። ጌታችን መድሐኒታችን ኢየሱስ ክርስቶስ ከትንሣኤው በኋላ በአርባኛው ቀን ወደሰማያት ያርግ ዘንድና ተመልሶ ግሩምና አስደናቂ እንዲሁም የመላእክትና የሊቃነመላእክት የማያቋርጥ ምሥጋና ወደሚሰማበት ሰማያዊ መንበሩ በምሥጋናና በታላቅ አምላካዊ ክብር ያርግ ዘንድ በወደደ ጊዜ በዛን ጊዜ ወደተቀደሰው ተራራ አወጣን እያለ ቅዱስ ጴጥሮስ ንግግሩን ቀጠለ።'),
  ('c5b2e08c-8098-550f-a1a8-f96854d2d8b5', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 2, 2, 'እንዲህም አለ እኔን የዘብዴዎስን ልጆች ያዕቆብንና ዮሐንስንና ቅድስት ድንግል ማርያምን ወሰደን የቀሩትን ሐዋርያት ደግሞ ተዋቸው ከተራራው እግርጌም እንዲቈዩ አዘዛቸው። እኛን ግን እፍ አለብን መንፈስ ቅዱስንም አሳደረብን ከዚህም አያይዞ እንዲህ አለን ወርቅንና ብርን አታከማቹ ስንቅንም አትሸከሙ በምትጓዙበት አገር ሁሉ በእጃችሁ በትርም ይሁን ሌላ 81 ፈፅማችሁ አትያዙ'),
  ('3dba769a-8afe-5831-a6ce-91c72149071c', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 3, 3, 'በበሽተኞች ላይ እጃችሁን በማሳረፍ ትፈውሉዋቸው ዘንድ ሙታንን ታነሱ ዘንድ የመንፈስቅዱስ ኃብት ከኔ ዘንድ ተሠጥቶአችኋል። ይህንንም ሀብት ከምድር በመላ በምትሄዱበት ሁሉ እንጂ በተወሰነ ቦታ ብቻ አይደለም። አሁንም ፀጋን ሠጥቻችሁ አለሁ እናንተም በፀጋ የተቀበላችሁትን ሁሉ በፀጋ ሥጡ በስሜ በተሰበሰባችሁበት ሁሉ እኔም ከናንተ ማህል እገኛለሁ።'),
  ('f2ff6b60-89bc-52a5-a846-0a2bf588421c', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 4, 4, 'ቀሌሚንጦስ እንዲህ አለ መምህሬ ጴጥሮስ ቀሌሚንጦስ ሆይ እኔ እንድገልፅልህ የምትፈልገው ሁሉ እጅግ ከባድ ነው ለሰው ሁሉም የሚገለፅ አይደለም ጌታችን ኢየሱስ ክርስቶስ ወደሰማያት ከማረጉ አስቀድሞ ይህን ምሥጢር ገልፆልናልና ስለዚሁ ሁሉን ዘርዝሬ እገልፅልህ ዘንድ አይገባም ልትሸከመው አትችልምና'),
  ('0eb3fc3c-8ef0-5f05-add2-7384b61f54ea', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 5, 5, 'ከዚህም በመቀጠል እኔ ቀሌሚንጦስ ወደመምህሬ ጴጥሮስ ልመናየን ቀጠልኩ ጌታችን ኢየሱስ ክርስቶስ የገለፀለትን ሁሉ ያስረዳኝ ዘንድ መምህሬ ጴጥሮስም ከሱ ዘንድ ብዙ ምሥጢርን ለማወቅ እንደጓጓሁ ተረድቶ እያለቀስኩ እየተጨነቅሁም እንደለመንኩት አውቆ ካሁን ጀምሮ የምገልፅልህን ፃፍ አለኝ አለ።'),
  ('1cda10aa-70f3-5906-a13d-fa3152e72c49', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 6, 6, 'እንዲህም አለ ዚያም ወደደብረዘይት አወጣኝ ጌታችን መድሐኒታችን ኢየሱስ ክርስቶስ ወደሰማይ ካረገበት ቦታም አቆመኝ ታላቅ ልቅሶም እያለቀሰ እኔን በትእምርተ መስቀል ባረከኝ ጌታዬ ኢየሱስ ክርስቶስ ሆይ በኅይልህ ዕናት ምሥጢሮችህን ለዚህ የኔተማሪ ቀሌሚንጦስ እገልፅለት ዘንድ ርዳኝ አለው።'),
  ('a3873353-3c3b-567e-ada8-abdc8eb8f83e', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 7, 7, 'ቅዱስ ጴጥሮስ ተናግሮ ሥግደቱን ቀጠለ አርባጊዜ ሳያቋርጥ ሰገደ እኔም ከሱጋር ሰገድኩ እሱ አርባ ጊዜ ከሰገደ በኋላ ፊቱን ወደኔ አዞረ። በዚህ ጊዜ ትልቅ ብርሃን ከላዩ ላይ ሲወጣ ተመለከትኩ ከአፉም የእሳት ነበልባል የመሰለ ነገር ሲወጣ አየሁ። በዚህ ጊዜ ፍርሃትና ድንጋጤ አደረብኝና በፊቴ ወደምድር ወደቅሁ።'),
  ('6445bb25-959e-576b-a1c4-24ae4a80de24', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 8, 8, 'ቅዱስ ጴጥሮስ እጄን ይዞ ከወደቅሁበት አስነሳኝ፡ ልጄ ቀሌሚንጦስ ሆይ አትፍራ በማለትም አፅናናኝ እንዲህም አለኝ ከጌታችን መድሐኒታችን ኢየሱስ ክርስቶስ ዘንድ ያየነውን ድንቅ ተአምር ባየህ ጊዜ ደነገጥክ ልትናገርም አልቻልክም ብዙ ፍርሀት ተሰምቶሃልና ከባድ ድንጋጤም አድሮብሃልና ለኛ ለተማሪዎቹም ከግርማው አስፈሪነት የተነሳ የምንችለውን ያህል ጥቂት ምሥጢርን ነው የገለፀልን።'),
  ('2b58c3a1-6782-5b61-a1ee-ff972e18c273', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 9, 9, 'እንዲህም አለኝ የምነግርህን ሁሉ በጥንቃቄ ጠብቅ እኔ የምናገረውን ሁሉ የማይቀበሉ በኋላ ዘመን ይመጣሉ አንተ የምትሠጠውንም ትምህርት የማይቀበሉ ይመጣሉ። ዳግመኛም የሐዋርያትን ሁላቸውን ትምህርት የማይቀበሉ ሰዎች ይመጣሉ።'),
  ('fd2077f4-b2a8-59a8-a4bd-c39f8fea01df', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 10, 10, 'ዳግመኛም እንዲህ አለኝ ልጄ ቀሌሚንጦስ ሆይ ልብ ብለህ አስተውል ጌታችን ኢየሱስ ክርስቶስ ወደሰማያት ያርግ ዘንድ በወደደ ጊዜ ወደዚሁ አመጣን ወደዚሁ ተራራም እንድንወጣ አደረገ በዚህ ጊዜ ከሌሎቹ ሐዋርያት ለይቶ ጴጥሮስ ሆይ አትፍራ እኔ የቤተክርስቲያን መሠረት ነኝና ቤተክርስቲያንን ካንተ ላይ እሠራታለሁ አለኝ።'),
  ('5733be18-79af-5da2-a30a-97f1c2bc2e97', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 11, 11, 'እኔም ከፊቱ ሰገድኩ ሰማዮችንና ምድርን እንዴት ፈጠርካቸው ሳትፈጥራቸውስ የኖርክበት ቦታ ምን ይባላል እሱስ የት ይገኛል። የምትመሰገንበትስ ቦታ የት ይገኝ ነበር። ምክንያቱም ከዚያ በፊት የፈጠርከው ነገር ለኛ አይታወቀንምና መንግሥትነትህስ በምን አማካይነት ይታወቅ ነበር። ያንተን መንግሥት ሊሸከም የሚችል ቦታ የለምና አንተሳ እንዴት ትገለጥ ነበር።'),
  ('fc588426-e3e2-5cbf-a1dc-fa2d67b2ee3c', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 12, 12, 'ጌታዬም መለሰልኝ እንዲህም አለኝ። ጴጥሮስ ሆይ አሁን አስደናቂ ነገርን ጠየቅኸኝ የጠየቅኸውም ጥያቄ የሰው ልቡና ሊሸከመው የማይችል ነው። ነገር ግን ይህን ምሥጢር ለማወቅ እንደምትፈልግ ስላወቅሁ ለማወቅ የምትችለውን ሁሉ እገልፅልሃለሁ።'),
  ('47a99007-22ae-55b6-a62f-994c7dd412d4', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 13, 13, 'ቦታ እኔ ነኝ ። ሁሉንም ችየ የምኖር እኔ ነኝ ። በምሥጋና መንበሬ ላይ ነበርኩ በፀጋየ ኃብት ነበርኩ አብ በኔ ዘንድ አለ በኔም ዘንድ መንፈስ ቅዱስ አለ ከኛ ዘንድ የመቅደምና ወደኋላ ማለት የለም ከመካከላችንም ፊተኛና ኋለኛ ተብሎ 84 የሚነገርለት የለም መጀመርያና መጨረሻም የለንም።'),
  ('5a07d6d8-9df8-5c15-ab2c-7c6f5ce36ba7', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 14, 14, 'የኛ ህላዌ የኛ መገኘት በሁሉ ዘንድ ነው የኃይላችንም ታላቅነት በሁሉ ይገኛል እ የፈጠርነው ሁሉ ከኛ የበታች ሁኖ ይኖራል ርዝመታችንና ስፋታችን በሰው አእምሮ አይገመትም ሁሉን እንችላለን ሁሉ ግን ማንነታችንን ሊረዳ አይችልም እኛ ከሁሉ በላይ ነንና የሐይላችንም ታላቅነት ሁሉንም ይዟልና።'),
  ('dd183418-eca2-51c8-a0f6-1b5037141c2c', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 15, 15, 'ግራና ቀኝ የለንም ውስጥና ውጭም በኛ ዘንድ የለም ውጭ እኛ ነን ውስጥም እኛ ነን ምስጋናችንና የፀጋችን ኃብት ከኛ ዘንድ ነው። ከባዕድ የሚያስፈልገን ነገር ፈፅሞ የለም አብ እውነተኛና ትክክለኛ ነው እኔም ይቅርታና ምሕረት ነኝ መንፈስቅዱስ ኃይልና ጥበብ ነው።'),
  ('f8a446e4-df0c-5e80-a99e-659b9c45a966', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 16, 16, 'እኛን መሽከም የሚቻለው ሰማይ የለም ምድርም የለም። ከግብር ወደግብር መለዋወጥ በኛ የለም ከቦታ ወደቦታም አንመላለስም የሰው ዓይን እኛን አያይም ሰውም በመራቀቅና በመመራመር እኛን ሊያውቅ አይችልም።'),
  ('acaec944-0596-564f-a3bf-dfe71e0f4990', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 17, 17, 'በኛ ዘንድ ጭማሪም ሆነ ሕፀት የለም አብ አእምሮ ነው እኔም ሥምረት ነኝ መንፈስ ቅዱስም ሐይል ነው እኛ ብዙዎች አይደለንም አንለያይምም ልዩነት አያገኘንም ጥፋትም አያገኘንም አብ በኔ ሁሉን ፈጠረ በመንፈስ ቅዱስም ተፈፀመ።'),
  ('25c12db0-c699-53af-a879-116558fc3843', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 18, 18, 'አብ ነቢብ ነው እኔም ቃል ነኝ መንፈስቅዱስ ደግሞ ሕይወት ነው የሚመሳሰለን የለም እኛ ከመመሳሰል በላይ ነንና እንደኛ የሚሆን የለም እኛ ከሁሉ በላይ ነንና አባቴ እሳት ነው ብርሃኑም እኔ ነኝ ። ሙቀቱም መንፈስ ቅዱስ ነው አባቴ ፀሐይ ነው ብርሃኑም እኔ ነኝ ። ሙቀቱም መንፈስቅዱስ ነው።'),
  ('10449c5b-b107-531c-aac2-98793341f54b', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 19, 19, 'አባቴ ውሃ ነው እኔም ጣዕሙ ነኝ። መንፈስ ቅዱስም ሕይወት ነው አባቴ ክብር ነው እኔም ክብር ነኝ መንፈስ ቅዱስም ጸጋ ነው። ከኛ ውጪ ፍጥረት የለም። ሰማያት ሳይፈጠሩ እኔ ከአብ ጋር ነበርኩ አባቴ ግርማ ነው እኔ ደግሞ ጸጋ ነኝ መንፈስ ቅዱስ ፍፃሜ ነው።'),
  ('3d4a04d8-8bb7-57da-a32a-a1429792c216', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 20, 20, 'እኔ በአብ መንፈስ ቅዱስ በአብና በኔ አባቴ ጥበብ ነው እኔም ቃል ነኝ መንፈስ ቅዱስ ደግሞ የቃል ድምፅ ነው። እኛ ነን በጥበባችን ሁሉን የፈጠርን ቀዳሚዎችም እኛ ነን መጀመርያና መጨረሻም የለንም።'),
  ('2f6d5b11-44c9-5172-a445-91bdc23c0a74', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 21, 21, 'ዘመናችን በፍጡራን ዘንድ አይታወቅም ከዘመንና ከአዝማን በፊት እኛ ነን። ከኛ ዘንድ የሚቀርብ የለም የሰው ሕሊናና የመላእክት አእምሮ ሊደርስብን አይችልም። እኛ ከሁሉ በላይ ነን። ከሕሊናዎችም በላይ ነው ምስጋናችንም ከራሳችን ነው።'),
  ('5810226a-cef8-5388-afd2-db764b87e80e', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 22, 22, 'እኛ መጀመርያና መጨረሻ የለንም ከፍቅራችን ብዛት የተነሳ ዓለምን እንፈጥር ዘንድ ወደድንይህም መንግሥታችን ይታወቅ ዘንድ መላኬነታችንና አቸናፊነታችንም ይታወቅ ዘንድ ብዕላችንና የኃይላችን ከፍታም ይታወቅ ዘንድ አብ እኔና መንፈስ ቅዱስ እሳትን ውሆችንና ነፋሶችን እንፍጠራቸው አልን።'),
  ('8dd6c7c3-31f0-597f-a05e-6c4599e1df83', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 23, 23, 'እኛም ፈጠርናቸው ከዚያ በፊት ሰማዮች ከውሆች ጋር ተቀላቅለው ነበር። ምድርም ከውሃ ጋር ነበረች የፀናችም አልነበረችም ሁሉም በዚሁ መልክ ነበሩ። ከዚህ ቀጥሉ ሥራችን ከነሱ ላይ ይሆን ዘንድ ሰማዮችን ፈጠርን በነሱ ላይም እንኖራለን።'),
  ('b75792eb-9ef6-567b-a09b-b09d51202490', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 24, 24, '4 ጴጥሮስ ሆይ የጥበብህ ህሊና ስለሰማኸው ምሥጢረ ሥላሴ ሊሸከመው አይችልም። ይኸውና እኛ የጠፉ ውሆችን ፈጠርን ከነሱም ሦስት ሰማዮችን ፈጠርን። ሰማዮቹ ብሩሃን ናቸው ልዑላንም ናቸው። የኛ ሥራ በነሱ ላይ ነው የፈጠርነው ብርሃንም ላይኛው ነው።'),
  ('bf836bc4-d46a-5de0-aee1-4325319aa328', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 25, 25, 'ብርሃኑ በሰማዮች ያለ ነው። ይህም ብርሃን አያልቅም አይለወጥምም የሁሉም መድረሻና መነሻ እኛ ነን ሁሉም የሚኖረው በመዳፋችን ነው ሰባቱ ሰማያትን ፈጥረን ከጨረስን በኋላ በቅፅበት ሌሎች ሰባት ሰማዮችን ፈጠርን የፈጠርነውም በቃላችን ነው።'),
  ('bce13897-be82-5da3-a1e3-e43d8fde9363', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 26, 26, 'በነሱ ላይም በጥበባችን ሥፍር ቁጥር የሌላቸውን ሌሎች ፈጠርን። ከኛም በቀር ማንም አያውቃቸውም። ውሆችንም ሁሉ አንድ ላይ ሰበሰብናቸው የሰበሰብናቸውም ከሰማያት 87 በህ በታች ነው። ይህም ውሆች የተሰበሰቡበት ቦታ ፋሌክ ይባላል ይህም አንድ ቦታ ሁኖ ዓለምን ሁሉ ይዞራል።'),
  ('f157b078-c6ba-539a-a331-08e27f3d680f', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 27, 27, 'ብዙ የተለያዩ ነገሮችን ፈጠርን ዘጠኙንም ነገደመላእክት ፈጠርን የነሱም መልክ ይለያያል በየነገዳቸው ሁሉ መልካቸው ይለያያል። አንዱ ሌላውን ያየዋል ሁላቸውም በየነገዳቸው ይለያያሉ። ከመላእክት መካከል ብዙ ዓይኖች ያሉት አለ። ፊቱም ብዙ የሆነ አለ ሁለመናውም የሚነድ እሳት ሁኖ የተፈጠረ አለ።'),
  ('6042bb4f-be27-5ee6-a2d9-8f18d3dae416', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 28, 28, 'መንፈስ ብቻ ሁኖም ከነሱ መካከል አለ። መንፈስና እሳት በመሆንም የተፈጠሩ አሉ ነገርግን ሁሉም ይዘምራሉ ያለዕረፍትም በማያቋርጥ ያመሰግናሉ ካንዱ የመላክት ማረጊያ ወደሌላው የመላእክት መገኛ የምትመለከተውን የሰማይና የምድር ርቀት ያህላል።'),
  ('1ff9ff7a-ccf3-58db-a0b0-02da6714088e', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 29, 29, 'የነዚህ መላእክት ቁጥር እልፍ አዕላፋት ከዚያም የእጥፍ እጥፍ ነው እነዚህ እኛን በማመስገን ይኖራሉ ዕረፍት የላቸውም። ሱራፌልና ኪሩቤልም በየፊናቸው ያመሠግኑናል ዕረፍትም የላቸውም።'),
  ('1e6c5f09-21c0-56c2-a0b3-0e0fe1cc9e09', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 30, 30, 'ሁሉም በየወገናቸው በሦስቱ የብርሃን። የእሳት አብያተ ክርስቲያናት ላይ ይገኛሉ ኢየሩሳሌም ሰማያዊትንም ከሰማይ በላይ ከሚገኘው ውሃ በላይ ፈጠርናት እሷ ከሦስቱ ሰማያት በላይ ትገኛለች።'),
  ('0ddd870d-6d20-5e54-a31b-14465bca32fe', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 31, 31, 'ኢየሩሳሌም ምድራዊትን ትጋርዳታለች ሥራዋም ከብርሃንና ከፀዳል ነው ምሰሶዎቿ ከእሳት ናቸው። እሷ የቆመችባቸው ምሰሶዎች በታላቅ ግርማ ያሸበረቁ ናቸው ቤተመቅደሷም የሚነድ እሳት ነው በውስጧ ያለው ታቦት ከብርሃን የተሠራ ሁኖ ማንም ሊመለከተው የማይችል ነው። የታቦቷ ሁለንትና ግርማ ፀዳልና ብርሃን ነው።'),
  ('043cdb74-053e-5d7f-a786-ed0f26f5b6a2', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 32, 32, 'ሰማያዊቷ ኢየሩሳሌም በግርማ የታጀበች ቅድስት ናት የዐጋ ብዕልና ብርሃን ዙረዋታል ከሷ የሚወጣው አእምሮን የሚመስጥ ሽቶ በዓለም ሁሉ ሊገኝ የማይችል ግሩም ነው።'),
  ('fbe24c14-60d0-54af-a2d9-612e8b518fb5', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 33, 33, 'በኢየሩሳሌም ሰማያዊት ላይ ያለው ብርሃን ዕልመት አያገኘውም የሷንም ጐድን ቁመትና አቀማመጥ ፈፅሞ በፍጡራን ሊታወቅ አይችልም።'),
  ('43fffca7-63d0-5de8-a285-1aac04c2e656', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 34, 34, 'ጴጥሮስ ሆይ እነሆ ጆሮ ያልሰማውንና ዓይን ያላየውን በሰው ልቡናም የማይታሰበውን ልገልፅልህ ነው እኛ (ሦስቱ አካላት) ከግርማ፣ ከእሳትና ከብርሃን ሥራችንን ሠራን ይህ የሠራነው ሥራ ከብርሃን ሥራችንን ሠራን ያህም የሠራነው ሥራ ከብርሃን ከእሳት አራቱ እንስሳ ይሽከሙታል። እነዚህ እንስሳት ብዙ ዓይኖች ያሉዋቸው ናቸው።'),
  ('e2dcefde-d03f-5d85-ac0d-e7996248f79b', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 35, 35, 'ከአፋቸው የነደእሳት አምሳል ይወጣል እነሱ የሰው ፊት የእንስሳፊት የንሥር ፊትና የአንበሳ ፊት ናቸው። አራታቸው በግራና በቀኝ ይቆማሉ የሁላቸው ክንፍ የሚነድ እሳት ነው ከነሱ ቀጥሎ ደግሞ ከእሳት የተሠራ አስፈሪ መንኩራኩር ይገኛል።'),
  ('e2de6389-e423-5aec-a2f6-1164936f75dd', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 36, 36, 'በሁለት ባሕሮች ላይ አንዱ የእሳት ሌላው የነፋስ የሆኑ ናቸው። (መንኰራኩሮቹ) ከበታቹ እየተነሳም ወደገነት የሚፈስ ባህር አለ።'),
  ('f8555b07-bfd5-57b4-a5bb-aea908a8ae15', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 37, 37, 'ከመልካም ሽቶ ሁሉ የበለጠ መልካም ሽቶ በዚያ አለ የእሳት ባሕር ካለበትም ቦታው ነፋሻማ ይሆናል ወደዚሁም ከብርሃን የሚፈልቀውና መጀመርያው የማይታወቅ መጨረሻውም የማይታወቅ ነው። ከሰማይ ካለው ሁሉም የዚህን አመጣጥ የሚያውቅ የለም። በምድር ያለውም የዚሁን መነሻ አያውቅም የሚወጣበትና የሚደርስበትም አይታወቅም ትልቅ ድቅድቅ ጨለማም ይከበዋል ይህ ድቅድቅ ጨለማ ከብርሃን የተለየ ቦታ ነው ከብርሃን የማይማሳሰሉ ሁሉ ከዚያ አሉ።'),
  ('fb26841b-9268-5598-a3de-72495afb4d90', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 38, 38, 'ጴጥሮስ ሆይ እኛስ ምስጋናችን ከኛ ዘንድ ነው ምስጋናችንም አይቋረጥም መጨረሻም የለውም ፍፃሜም የለውም እኛ ከሶስትነት አናንስም ጭማሪም አንፈቅድም ቀደምት እኛ ነን ኋለኞችም እኛ ነን ማነኛውም ነገር ሁሉ በመዳፋችን ነው። ደመናትንም ከእግራችን መረገጫ በታች እንዲሆኑ አደረግን።'),
  ('49d9b028-af49-54eb-aa71-f84ab4708b32', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 39, 39, 'ሱራፌልንና ኪሩቤልን የነፋሳትን ትክሻዎች ይረግጡ ዘንድ አዘዝናቸው ምድርንም እንመለከታታለን እንድትንቀጠቀጥም እናደርጋለን የመላእክት ዓይኖች እኛን መመልከት አይችሉም ። ሥራቸው እኛን ማመስገን ብቻ ነው ያመሰግነናልም መዓርጋት መላእክትን የመላእክት ዓለቅነትን በሁለት የፈጠርን እኛ ነን።'),
  ('a5015d77-107d-5623-a446-8352b77b67ce', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 40, 40, 'እነዚህም መንበራችንን እንዲዞሩ አዘዝናቸው። አንደኛው አለቃ ሚካኤል ነው እሱም የመዓት መልአክ ነው ሁለተኛው ደግሞ ገብርኤል ነው ገብርኤል መልእክተኛ። የደኀንነትንና የሰላምን ብሥራት ነጋሪ ነው።'),
  ('c0f3ca9b-c2b6-5421-a0d7-366b4bcd60ec', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 41, 41, 'የሁለቱ ሌሎቹ አለቆች ስም ሱሩያልና ሩፋኤል ይባላል። እነሱም የዜና መልእክተኞች ናቸው ገብርኤል በሰማይ ውስጥ ይኖራል። የሱ ሠራዊት ደግሞ የብርሃንን ማሕደር ይዞራሉ እኛም ከሁሉ በላይ ነን።'),
  ('2082919d-e279-5fa4-a7dc-b2c4603d6b0d', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 42, 42, 'የፈለግነውን ለመሥራት ካቀድን የሚከለክለን የለም ከፍጥረት ሁሉ ሊቃወመን የሚችል ማንም የለም የመላእክቱ ባብ ሕሊናም አያውቀንም ዓይኖች አይነኩንም እያንዳንዳችን ምሕረታችን ታስወግደዋለች። አንለያይም ቁጣችንን ኩነኔ ይቅርባይነታችንም መዓታችንን ታቀዘቅዘዋለች። የሚገባው ቢኖርም በትክክለኛው ፍርዳችን በምሕረትና በይቅርታ እንጐበኘዋለን እንጂ አናጠፋውም።'),
  ('99c86f0d-a5c9-52a8-a141-04d8ba4fc8b7', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 43, 43, 'እኛ ሁሉንም እንፈጥራለን የምንፈጥረውም ያለድካም ነው የራቀውን እናቀርባለን የቀረበውን እናርቃለን ሁሉን እናያለን እኛን ግን የሚያየን የለም በሁሉም ዘንድ እኛው ነን ሐይልንና መድኀኒትን የምንሠጥ እኛ ነን ኃይላችን ከሁሉም በላይ የኛ ኃይል የሠለጠነ ነው ከፈጠርነው ፍጡር ምስጋናም አንሻም ምስጋናችንስ ከኛው ነው ኃይልም ሁሉ ከኃይላችን በል ነው።'),
  ('2b2d42ae-22d7-51ae-aad9-d4a5fab243c1', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 44, 44, 'ጸጋችን ከጸጋ ሁሉ ይበልጣል ክብራችንም ከክብር ሁሉ ይበልጣል።'),
  ('c925ff3b-2a1f-5887-a337-a73d56c4bcc0', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 45, 45, 'ጴጥሮስ ሆይ ልብ በል አስተውልም ከሥራየም ተረዳ እኔ እግዚአብሔር እንደሆንኩም እወቅ ብልሐተኛ ሁሉ በጥበቡ ይቃወቃልና።'),
  ('231784a4-20b4-58e8-a492-79ab24ec65ce', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 46, 46, 'ጌታችንና መድሐኒታችን ኢየሱስ ክርስቶስ ስለሰማያትና ስለምድር አፈጣጠርና ስለነፋሳትና ስለውሆች አፈጣጠር በነገረኝ ጊዜ ጌታችን ሁሉን የፈጠረ እንደሆነ አወቅሁ ተረዳሁም።'),
  ('cf7342b1-75ce-58c5-a35e-fd9e791388ba', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 47, 47, 'ደግሞም ጴጥሮስ ሆይ አስተውል አለኝና ክረምትና በጋ በኔ ይሆናሉ የክረምትና የበጋ አምላክ እኔ ነኝና እኔ ከአብ ጋርና ከመንፈስ ቅዱስ ጋር ያለመለየት በፍፁም ተዋህዶ እኖራለሁ መለያየት በኛ ዘንድ የለም።'),
  ('6900655b-b1db-5654-a97a-909129125724', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 48, 48, 'እኛ ዝናማትን እናወርዳለን ምድርንም እናጠጣታለን ባሕርን እናደርቃለን የብስንም ባሕር እናደርገዋለን ወንዞችንም እንዲደርቁ እናደርጋለን። ከነፋሳት ባሕር ትንሽ ነፋስ ብዙ አገሮችን ታጠፋለች ተራሮችንና ኰረብቶችን እንሠራለን ምንጮችንም ወደወንዞች እንልካለን።'),
  ('28c70c88-65a9-504a-ac98-95ba3a17fb91', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 49, 49, 'ጴጥሮስ ሆይ ከእሳት ባሕር ነፋስን እንደምንልክ ልብ በሉ ይህም የእሳት ባሕር መልእልተ ሰማያት ይገኛል። ይህም ትንሽ እሳት ብዙ አገሮችን ያቃጥላል ብዙ ተአምራትንና ብዘ መንክራትን እናደርጋለን ይህንንም ሁሉ በኃይላችን ብዛት እናደርጋለን። ውሆችንም እናረጋለን ረግተው በደመናት ላይ ዝናም እንዲሆኑ እናደርጋለን በርድንና ውርጭን ወደምድር እንልካለን።'),
  ('11ee0af1-74db-51e5-a6c6-84b9b29d7f60', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 50, 50, 'ጴጥሮስ ሆይ ልብ ብለህ አስተውል የነፍሥና የሥጋ ወገን ፍጥረት ሁሉ እኛ የፈጠርነው ነው። የዕፀዋትንም ቁጥር ፈጥረናል ምድር ሥሒን የተባለውንም ከዕፀዋት ጋር ባንድነት ፈጠርን ከኛ በቀር ሌላ አምላክ የለም በቅፅበት የሚታየውንና የማይታየውን ሁሉ እኛ ፈጠርን የሚዳሰስና የማይዳሰስ የሚያልፈውንና የማያልፈውን የፈጠርን እኛ ነን። ይህን ሁሉ ከኛ በቀር የሚያውቀው የለም። ሰማይን የሠቀልነው እኛ ነን ያለምሰሶ እኛ ሰቀልነው ምድርንም በውሃ ላይ እኛ ፈጠርናት ነፋሳትንም አስቀመጥናቸው።'),
  ('413034d1-56d0-5c47-a81d-01ec58678c4b', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 51, 51, 'ጴጥሮስ ሆይ ከቅድስት ድንግል ማርያም ዘንድ ሥጋ ለመልበስ ባልፈልግ ኑሮ አዳምን ሰማያትንና ምድርን ባልፈጠርኩዋቸው ነበር።'),
  ('b37969fe-93c0-5e98-a8ed-df47a296f546', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 52, 52, 'ጴጥሮስ ሆይ እኔ ሰው ባልሆን ኑሮ የምሥጋናየና የክብሬ ዝ 93 ብዕል ባልታወቀ ነበር። ጴጥሮስ ሆይ ባልወድህ ኑሮ ይህን ምሥጢር ባልገለፅኩልህም ነበር። እነሆ ብዙ ምሥጢርን እገልፅልሃለሁ ሰዎችንም ባልወድ ። ኑሮ በዚሁ በለበስኩት ሥጋ ባልተገለፅኩላቸውም ነበር። እቺ ቅድስት ድንግል ማርየምን ባልመርጣት ኑር ሔዋንን ባልፈጠርኩዋት ነበር።'),
  ('1deadbfe-310a-51f8-afd7-c3387339ea35', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 53, 53, 'ጴጥሮስ ሆይ እኔ የለመንከውን ሁሉ እሠጥሃለሁ ምሥጢሮቼንም እገልፅልሃለሁ እንደምትወደኝ አውቃለሁና የመለኮቴን ብርሃን ከፍጡራን ሁሉ አንድም የሚያውቅ የለም የቀናች ሃይማኖት ያለችው ሰው ካልሆነ በቀር እኔን የሚያይ የለም እኔም ለሃይማኖተኛ ሰው በመለኮቴ ግርማ እታየዋለሁ።'),
  ('ae6de1f9-7b06-59ca-afa4-3d43547a1e56', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 54, 54, 'ቅዱስ ጴጥሮስ ከዚህ በኋላ እንዲህ አለኝ ልጄ ቀሌሚንጦስ ሆይ ጌታችን ኢየሱስ ክርስቶስ በተናገረኝ ጊዜ እያየሁት ወደሰማይና ወደምድር እጆቹን ዘረጋና ሰማይና ምድርን በትንሽ ክርታስ እንደተያዘች ደብዳቤ አስመስሎ በመጠቅለል በማህል እጁ አስቀመጣቸው።'),
  ('174727de-51a3-5dc5-a2c4-e6eabc6ee371', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 55, 55, 'እንዲህም አለኝ ጴጥሮስ ሆይ ጆሮህን ወደማሕል እዴ አቅርብ ልብ ብለህም ይህንን ስማ እኔም ቀረብኩ የብዙዎችንም ድምፅ ሰማሁ።'),
  ('1762bab4-29a4-56f5-af83-2e2f33984ffd', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 56, 56, 'ብዙ ጩኸትንና ፍጅትን ሰማሁ ቀጥሎ ግሩም ወደሆነ ቦታ አደረሰኝ ይህ ቦታ ከሰማይ አይደለም ኮከምድርም አይደለም እንዲህም አለኝ ጴጥሮስ ሆይ ያለህበት ቦታ የት ነው?'),
  ('af337837-e741-50eb-ade9-e6ddcd9cfc58', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 57, 57, 'ደግሞም እንዲህ አለኝ ዓይኖችህን አንሳ በዚህ ጊዜ ተመለከትኩና የብርሃን መጋረጃ ያለበት የብርሃን አየሁ ሕብሩ የተለዋወጠ ነበር። እኔም አይቼ ደነገገጥኩ። በኋላ እጄን ይዞ አስነሳኝ ያየንው ምንድር ነ0ሁ ።። ወይም ምድር ብሎ ጠየቀኝ።'),
  ('23a25e81-6115-5f04-a5e8-8e5adc0401a1', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 58, 58, 'ጌታየና አምላኬ ሆይ ምንም አልታየኝም አላት ተመልከት አለኝ እኔም ወደታች ተመለከተ ። ጥልቀት ያለውንም ጨለማ አየሁ መነባውና ። አይታወቅም የምትመለከተውን አስተውል ሰማዮችን ከዋክብትንና ጨረቃን ተመለከትኩ።'),
  ('638b01b6-1603-54fd-a0b5-56da793940f1', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 59, 59, '9 ባሕርን የሚፈሱ ወንዞችን አየሁ እነዚህ ሁሉ በጌታ እጅ የተያዙ ናቸው። እኔ ጴጥሮስ ያየሁት ሁሉ በሕልም ያየሁት አይደለም በገሀድ እንጂ በሐሰትም አይደለዎ። ከዚያ ጌታችን ሁሉን ካሳየኝ በኋላ ወደየቦታቸው መለሳቸህ እኛም እንደነበርንበት በቀድሞው ሁኔታችን ወደ ደብረዘይት ተመለስን።'),
  ('7e572388-f963-5e77-a664-e5defa37148e', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 60, 60, 'ደግሞም ጌታችንና መድሐኒታችን ኢየሱስ ክርስቶስ ወደኋላህ ተመለስ አለኝ እኔም ወደኋላየ ተመለስኩና ኢየሩሳሌም ሰማያዊትን አየሁዋት። እሱም ትያትና ምድር በእጄ እንደሆኑ እወቅ አለኝ።'),
  ('4e16f44a-2bc2-55ba-a281-7eb04258d6c7', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 61, 61, 'እንዳያሃቸው የትም አይወገዱም በመለኮቴ ጥበብ ይህን ሁሉ ፈፀምኩ። የአብርሃም ይስሐቅና ያእቆብ አምላክ እኔ ነኝ ። ምሕረቴና ምስጢሬ አይታወቅም ነገር ግን ያንተ አእምሮ ሊቀበለው የማይችለውን ምሥጢር እነግርሃለሁ።'),
  ('0c5b2986-37d0-5cfd-a7fb-9fc6bd6a8185', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 62, 62, 'የመንግሥተ ሰማያት መክፈቻን ሠጥቸሃለሁና የሲኦል በሮች የማይበረቱባትን መንግሥተ ሰማያት ትዘጋና ትከፍት ዘንድ የወደድከውንም ታደርግ ዘንድ እንዲህም አለኝ የፊት እኔ ነኝ ። የኋላም እኔ ነኝ ። የምገድልም እኔ ነኝ ። የምፈውስ እኔ ነኝ ። እኔ በአብና በመንፈስ ቅዱስ አለሁ አብና መንፈስ ቅዱስም በኔ ህልዋን ናቸው በሥላሴ አንድነት እኔ አለሁ።'),
  ('694a529e-7d72-5138-a7ec-c299997aab02', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 63, 63, 'ሰማይ መንበሬ ነው ምድርም የእግሬ መርገጫ ናት። ከኔ ፊት የሚቆም ማን ነው በአርአያየና በምሳሌየ አዳምን ፈጠርኩት በሱ ላይም የሕይወት እስትንፋስ እፍ አልኩበት።'),
  ('6a941a29-1727-5dcf-a6e2-3406ba565ad0', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 64, 64, 'በሱ ላይ ነባቢት ነፍስን አሳደርኩበት እቺም የማትሞት ናት በምልክትና በአምሳል አትታወቅም በመላእክት ምሳሌነትም አትታወቅም ከሰማያት መንበሩ የወደቀው ዲያብሎስንም እንዲቃወመው አደረግሁት።'),
  ('337bdb98-daf1-5960-a4a2-3ccc5c9a5acd', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 65, 65, 'ጴጥሮስ ሆይ እኔ ልጁ እንደሆንኩ አብ ገለጠልህ ከሱ ጋር አንድ እንደሆንኩም አስረዳህ ጴጥሮስ ሆይ እኛ መላእክትን በፈጠርናቸው ጊዜ አዳምን ፈጠርነው። በፀጋየም ቤተክርስቲያንን ሠራኋት አፍላግንና ዕፅዋትንሃም በሷ ላይ ሾምኩ ቤተክርስቲያን ከአንድ በላይ ከተራሮችዎ ከፍ እንድትል አደረግሁዋት ። ይህም በመንፈስ ቅዱስ ነው።'),
  ('d2192e48-d30e-5410-ae55-11813ba03498', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 66, 66, 'እኔም መለስኩ እንዲህም አልኩት በመንፈስ ቅዱስ ክንድ ስንት ያህል ነው አልኩት እሱም መጠኑ የሚለካው እጆቼን በመስቀል ግራና ቀኝ ዘርግቼና ማሕል እጄም በመስቀል ላይ በዘረጋሁበት ነው።'),
  ('e7c5dac9-8ced-580e-ad2c-9e03d2608107', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 67, 67, 'የዚህም መጠኑ ከምሥራቅ ተነስቶ እስከ ምዕራብ ይደርሳል ጴጥሮስ ሆይ በገነት የተከልኩዋት መንፈሳዊቷ ዕፅና በሷም ላይ መልካምን ሁሉ ያደረግሁ በሷ ላይ ክብሬንና ምሥጋናየን እገልፅ ዘንድ ነው። ገነትንም አደረግሁዋት የቤተክርስቲያን ምሳሌነትም ሠጠኋት እቺም ቤትክርስቲያን በገነት ያለች እቺንም ቤተ ክርስቲያን ለመሐይምናንና ለደናግል እንድትሆን አዘጋጀኋት ርዝመቷና ስፋትዋ መንፈሳውያን የአዳም ልጆች በሚኖሩበት ገነት ኤዶም መጠን ነው የተሠራችው።'),
  ('81981730-c609-5d69-a02e-584eae12a74a', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 68, 68, 'ፈያታዊ ዘየማንንም በሰማያት የዕርገቴን ዜና ከአብ ዘንድ እንዲናገር ላክሁት ጴጥሮስ ሆይ ምሥጢሮቼን እገልፅልሃለሁ። ይህንንም ለምነኸኛል ስለዚህ በሰማያት ያለውን ከአብ ዘንድ ታያለህ።'),
  ('77fc48e4-4334-5a75-ab34-0a79e0d862fb', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 69, 69, 'በዚህ ጊዜ ከፊቱ ሰገድኩ እንዲህም አልኩ ጌታዬና አምላኬ ሆይ እነሆ የክብርህ ልዕልናና ግርማህ አውቅ ዘንድ ናት። እጁ ያስተዋይነትህን መንገድ ገለጥክልኝ እኔ እንደማምንህና እንደማፈቅርህ አንተ ታውቃለህ አሁንም ሰማዮች። መላእክትና ሥልጣናት እንዴት እንደተፈጠሩ አስረዳኝ ስንት መዓርጋት አሉዋቸው አርአያቸውስ የሰው አርአያ ያለው ነውን እንደጥላ ናቸውን ጉድንና ቁመትስ አላቸውን።'),
  ('6c01e2f7-bdc8-5cee-aa68-775aa2d7b9b9', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 70, 70, 'በየትኛውስ ጊዜ ፈጠርካቸው ሰማይንና ምድርን ከመፍጠርህ በፊት ነውስ ወይ በኋላ በየትኛው ወር ፈጠርካቸው በየትኛውስ ሰዓት በአምላካዊ ሥልጣንህ ሊፈጠሩ ቻሉ።'),
  ('f4d74566-f082-5e0a-aa52-6aba20eac843', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 71, 71, 'እንደሰው ሐጢአት ሊኖራቸው ይችላልን አእምሮ መሥማት ማየትና ማሰብስ ተሠጥቶአቸዋልን ይንቀሳቀሳሉን መልካቸውስ ተመሳሳይ ነውን ወይስ ይለያያሉ ወይም ደግሞ ቁመናቸውና ምስጋናቸው ይለያያል ወይስ አንድ ነው።'),
  ('0399e092-7c29-5966-aa28-e77fa4345cb8', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 72, 72, 'የቃላቸውስ ድምዕ እንዴት ሊሰማ ይችላል ሥጋ አልለበሱምና ንባባቸው እንዴት ሊታወቅ ይችላል ልሣን ከሌለው ፍጡር ንግግር እንዴት ይሰማል ከሙታን በኋላስ እነዚህ እንዴት ይሆናሉ።'),
  ('c1b3419a-8aac-545c-a50c-03cfca620900', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 73, 73, 'ጌታዬ ኢየሱስ ክርስቶስም መለሰና እንዲህ አለኝ ጴጥሮስ ሆይ እነሆ አስደናቂ ጥያቄን ጠየቅኸኝ ይህን የሰዎች የጥበብ አስተሳሰብ ሊደርስበት የማይችል ነው አሁንም የምነግርህን ልብ ብለህ ስማ ፍጥረትን የጀመርኩበት ወር ኔሳን ይባላል እሱም ወርሐ ሚያዝያ ነው።'),
  ('c01bd8fb-3071-568b-a964-69b0fe446d0a', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 74, 74, 'መፍጠርን የጀመርከበትንም እለት እለተ እሁድ ናት ከዕለቱ፡ በመጀመሪያው ሰዓት ሰማይን ፈጠርከት መላእክትንም ሁሉ ፈጠርኩ ይህንንም ለመሴ አልነገርኩትም።'),
  ('1a7b164a-5f9d-557f-acfd-9a8680ceab97', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 75, 75, 'በዕለተ ዓርብ በመጀመርያው ሰዓትም ዲያብሎስን አደከምኩ ከመንበሩም ነቀልከት እሱ መንግሥቱን ተመኝቷልና መንግሥቴንም እንደተመኘና እንደፈለገም አውቄአለሁና።'),
  ('c35253fe-a5ae-5da3-a0cd-179b7e46ddf1', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 76, 76, 'እኔም ከምስጋናየ እንዲለይ አደረግሁት ከክብሬም እያ። እንዲናቅ አደረግሁት እሱ ትዕቢተኛ ሁኗልና ሐሳቡ ሁሉ ትዕቢትና መጥፎ ምክርም ሁኗልና እኔም መልሼ እንዲህ አልኩት ጌታዬ መድሐኒቴና አምላኬሆይ አንተ በከሐዲነቱ ሠይጣን እንደሚሆን አስቀድመህ እያወቅህ ለምን ፈጠርከው ።'),
  ('d0bd05f4-9469-5c4c-a3b0-66ad3de216d1', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 77, 77, 'እንዲህም ብሎ መለሰልኝ ጴጥሮስ ሆይ ይህ ከሐዲ ፍጡር እኔን እንደሚያስቈጣኝ አስቀድሜ አውቅ ነበር። ነገር ግን በሱ ላይ ባመጣሁት ኩነኔ ይቀጣ ዘንድና እንደሱም ሌላ መልአክ ከሐዲነትን እንዳያስብ ለማድረግ ፈጠርኩት ዲያብሎስ ማንም ሳያስገድደው በገዛ ራሱ ከሐዲነትን ገንዘብ አደረገ።'),
  ('43f8a666-b856-5728-aeae-33b1309b33d8', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 78, 78, 'ነገር ግን እኔ በክብር ፈጠርኩት በምሕረትም ፈጠርኩት ። ነገር ግን ከፍ ባደረግሁት ጊዜ እሱ ሲክደኝ አወረድኩት የተለየና የራቀም ፍጡር አደረግሁት የበታችም እንዲሆን አደረግሁት በምድር ሁሉም የተጠላ ሆነ ሕዝብ ሁሉ ይጠሉታል።'),
  ('aebb584a-ec39-5ee1-adde-fd7a7dce3801', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 79, 79, 'ጴጥሮስ ሆይ ሁሉን በምሕረት ፈጠርኩ እሱንም ከፍጡራን ለይቼ አልፈጠርኩትም ክፉ እንዲሠራም አላዘዝኩትም። ነገር ግን እሱ ያዋጣኛል ብሎ ከሐዲነቱን ተከተለ ወደኋላ የሚደርስበትንም አስቀድሜ ሳላውቅ የፈጠርኩት ማንም የለም።'),
  ('c69d0715-c782-5694-a536-4aa558aac545', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 80, 80, 'እነዚህ ለኔ ታዛዦች የሆኑ ያሰብኩትን እኔ እንዳልተው ምንም ሳላጓድል እፈጥር ዘንድ ወደድኩ በእውቀትና በአእምሮ በፍቅርም ያሰብኩትን ሁሉ ፈጠርኩ በዚህም ዲያብሎስን ፈጠርኩት ከመላእክት ሁሉም ከፍ አደረግሁት ከሁሉ በላይም ወደኔ ቀራቢ እንዲሆን ፈቅጄለት ከፍተኛውን ሥልጣን ይዞ ነበር።'),
  ('b20f44ee-cca2-5131-a84b-a4bec951da0e', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 81, 81, 'እኔም ትእዛዜን የሚክድ ከመላእክት ሁሉ መካከል እንደሌለ አስቀድሜ አወቅሁ ዲያብሎስ ብቻ እንደሚክድ አስቀድሜ አወቅሁ ዲያብሎስ ብቻ እንደሚክድ አስቀድሜ አውቅ ነበር። እኔ ከመላእክት ሁሉ የበላይ አድርጌ የፈጠርኩት ለክሕደቱ ምክንያት እንዳይኖረው ነው ከኔ በላይ ሌሎች መላእክትን ከፍ አደረግህ እንዳይል የሁሉ በላይ እንዲሆን አደረግሁ።'),
  ('032b557d-2fc1-53d0-aa39-90d2bc35605c', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 82, 82, 'ይህ ባላደርግ ኑሮ ለከሐዲነቱ ምክንያት በፈጠረ ነበር። ጥንት ወደኔ ቀራቢ ነበር። ከመንበሬ ፊትም ይቆም ነበር። ለኔ ተገዢነቱንም ለማረጋገጥ መጋረጃን ይይዝ ነበር። ከሱ በታች አድርጌም በፈጠርኩዋቸው መላእክቶቼ መካከልም ምሥጋናየን ማቅረብ ሥራው ነበር ።'),
  ('0681adb9-7684-5e5c-a73d-1a0c5be09239', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 83, 83, 'ፃ'),
  ('08f20725-1bf4-5c7a-a6d1-03fd1b4cbd1b', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 84, 84, 'በፈጠርኩት ጊ ።;።። መንሰርና አስቀD።።።; አደረግሁት በሚዶላሪ / አስቀመየኩት እናም ያ ሚካኤልንም ። መላእክት ሰሀት ና ኡራኤል እነሱ። የነ ን'),
  ('12807076-6361-54af-a897-fcbc33e724ef', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 85, 85, 'ስለሚያምኑ ኃጢአተኞች ይ። ይማልዳሉ በአንቃዕድዎም ይፀናሉ።'),
  ('5b4e2629-61c5-5d8d-a0fd-a1dd7fba6ee2', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 86, 86, ''),
  ('f83a1498-5d67-5e3b-ac1c-0f4400474d80', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 87, 87, 'ጴጥሮስ ሆይ ቤተክርስቲያንን ከዘመናት በፊት አነፅኩዋት ። ለሚያምኑም ሁሉና ለኔም ማደርያ እንድትሆን አደረግሁዋት።'),
  ('0cfbceac-1637-51a1-ad07-283b8362faba', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 88, 88, 'ጴጥሮስ ሆይ የመንግሥተ ሰማያትን ቁልፍ ሠጠሁህ ይህም ስለሐጢአት ሥርየት ነው። ሰማይንና ምድርንም መላእክት ሳይቀሩ ላንተ ይታዘዙ ዘንድ አደረግሁ።'),
  ('937afcf9-2be5-5150-a5dd-f6b888c4dd24', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 89, 89, 'ጴጥሮስ ሆይ ሰማይና ምድር ከመፈጠራቸው በፊት የፈጠርኩት የለም ፍጥረት ሁሉ ሐላፊ ነው።'),
  ('5224d45d-d273-560b-a5d2-627511bf55cc', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 90, 90, 'እኔም በድጋሚ ጌታየና አምላኬ ሆይ እንደሚበድል እያወቅህ አዳምን ለምን ፈጠርከው በማለት ጠየቅሁት።'),
  ('7ae205d3-0716-5e91-a043-907dea1ad58c', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 91, 91, 'ጌታዬና አምላኬ መለሰልኝ እንዲህም አለኝ የጠየቅኸኝን አስቀድሜ መልሼልሀለሁ አዳምን መንፈሳዊና ብሩህ አድርጌ እፈጥረው ዘንድ ወደድኩ በሰማይ ውስጥም የወደድኩትን ሁሉ ፈጠርኩ አዳምን ግን በዓራቱ መዓዝነ ዓለም የበላይ አድርጌ ፈጠርኩት ንጉሥነትንና መስፍንነትንም ሠጠሁት በምድር ላይ ከሁሉ በላይ አደረግሁት በዚች ምድር ባሉት ፍጡራን በሙሉ የበላይነትን ሠጠሁት ነገር ግን እንደሚክደኝ አውቅ ነበር።'),
  ('0dbce2c8-78dd-52b4-a6d5-f229e396ae4d', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 92, 92, 'ነገር ግን አዳምን በፍቅርና በምሕረት ፈጠርኩት አለኝ እንዲህም አለኝ ጴጥሮስ ሆይ ልታውቀው የሚገባህ ጉዳይ አለ ገበሬ ዘር ሲዘራ ዘሩን በማጣቱ ለጊዜው ያዝናል ባንድ ምትክ ሰላሳና ስድሳ መቶም ባፈራለት ጊዜ ግን ይደሰታል የቀድሞውንም ሐዘነ ይረሳል እንደዚሁ ሁሉ እኔም አዳምን ፈጠርኩት ራራሁለትም ከሞትም አዳንኩት ትእዛዜን ባፈረሰ ጊዜ ግን በሱ ላይ ሞትን አመጣሁ አላዘንኩም (እሱን በመፍጠሬ)።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('49a18acb-734a-5a5f-aaf9-c77f0641f763', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 93, 93, 'ጴጥሮስ ሆይ እኔ አዳምን ሕያው አድርጌ ፈጠርኩት ትእዛዜንም ይጠብቅ ዘንድና ከጥፋትም ይርቅ ዘንድ አዘዝኩት ልትሠራው የሚገባህን ትሠራ ዘንድ መብት ሠጠሁህ ክፉውንና ደጉንም ለይቼ አስረዳሁህ ትዕቢትን እንደዲያብሎስ እንዳትፈልግ አልኩት ዲያብሎስ በትዕቢት ራሱን ከፍ ስላደረገ ከመንበሩ ወደቀ አንተም ሞትን ከምታፈራ ዕፅ እንዳትበላ አልት።'),
  ('98ea4c60-16ea-56cc-abea-65ccefe5226e', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 94, 94, 'ከእፅዋ ከበላህ ሞትን ትሞታለህ ቃሌን ካልሰማህና ትእዛዜን ካልጠበቅህ ከገነት አስወጣሃለሁ በተረገመችውም ምድር እንድትኖር አደርጋሃለሁ። ምድር ስለተረገመች አሾህንና አሜከላን ታበቅላለች ከተከለከለችው እፅ ካልበላህና ትእዛዜን ከጠበቅህ ሞትን አትሞትም ነገር ግን እስከዘላለሙ ሕያውና ደስተኛ እንደሆንክ ትኖራለህ አልኩት።'),
  ('291fe96f-4766-57ad-a8c7-cb46cb6c6082', '4f5ab826-1159-5ef8-af53-dec9f9fc4a80', 'f6995a9a-1f5a-5013-ae22-76b32d1cc4f8', 95, 95, 'ጴጥሮስ ሆይ ዲያብሎስ ዓለምንና አዳምን እደሚያስታቸው አውቅ ነበር። ይልቁንም በአዳም ላይ የኔን ትእዛዝ አፍራሽነት እንደሚያመጣበት አውቅ ነበር። ስለዚህም ትእዛዜን ጠብቅ ከተከለከለውም ዕፅ አትብላ አልኩት ትእዛዜንም እንደሚያፈርስ አስቀድሜ ስላወቅሁ መዋችና ሕያው አድርጌ ፈጠርኩት እሳት ውሃና ነፋስ ከተቀላቀሉበት አፈርም ፈጠርኩት።'),
  ('97cf5a8e-a336-5e05-a284-b6519ca3869e', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 1, 1, 'ጌታችን ኢየሱስ ክርስቶስ ለጴጥሮስ ጴጥሮስ ሆይ የትስብእቴን ምሥጢር ነገርኩህ ሰው ስለመሆኔንም አዳምን እንደፈጠርኩትና ከገነት ለብሶት የወጣውን ሥጋ ለብሶ ወደገነት እንደሚመለስም ገለፅኩልህ ጴጥሮስ ሆይ ለሰው ልገልፀው የማልፈልገው ምሥጢርም አለኝ። እኔም ከጌታዬና አምላኬ ይህን ሰምቼ ከፊቱ ሰገድኩ ለመንኩም ወደሱም አንጋጠጥኩ እንዲህም አልኩ። ጌታየ ሆይ የመላእክት ነገዳቸው እንዴት ነው?'),
  ('f4dbdaa4-42ee-508c-afdf-2bd1b70d2c83', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 2, 2, 'እሱም መለሰ እንዲህም አለኝ የመላእክት ወገኖች ብዙ ናቸው አርአያቸውም አንድ አይደለም አራት ገፅ ያለው መልአክ አለ ሁለመናው (መላአካላቱ) ገፅ የሆነ አለ ብዙ ዓይኖች ያሉትም አለ ሁለንትናው ዓይን የሆነም አለ ሁለንትናው ከፀሐይ ብርሃን የበለጠ ብርሃን ያለውም አለ።'),
  ('5b40732f-9201-5d37-af5e-44963fd54bb8', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 3, 3, 'ከነሱ መካከል የሰው ፊት ያለውና አራት ፊት ያለው አለ። ከነሱ መካከል አራት ክንፍ ያለው አለ። ከነዚህ መላእክት ለያንዳንዳቸው ስም አላቸው የመላእክትና የሊቃነ መላእክት የአጋእዝትና የሥልጣናት የኃይላት እንዲሁም የመናብርት አርባብ ኪሩቤል ናቸው ኪሩቤል ብዙ ዓይኖች ያሉዋቸው ናቸው ሱራፌልም ስድስት ክንፍ ያላቸው ናቸው።'),
  ('b96a7fa8-06c0-53f7-ad8d-0e325ad0b730', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 4, 4, 'ዘጠኝ ነገደመላእክት አሉ ካንዱ የመላእክት ነገድ ወደሌላው የመላእክት ነገድ ድረስ ያለው ርቀት የሰማይና የምድር ርቀት ያህል ነው። በመካከላቸውም ፀዳልና ብርሃን አለ። የዚህም ብርሐን እጅግ የደመቀ ነው። ይህም እርስበርሳቸው ይናገሩ ዘንድ ነው ስለራሳቸውም አፈጣጠር እጅግ ያደንቁ ነበር። ስሜንም ያመሰግናሉ ከነሱ አፍ መልካም ምስጋናን አገኘሁ።'),
  ('84b1de37-d244-5dd6-adaf-28ae69e60055', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 5, 5, 'ከነሱ ውስጥ የሚዘምር አለ የሚያወድስ አለ የሚቀድስ አለ ከመካከላቸው የሚያስታኩት አለ። ከነሱ መካከልም የሚያመሰግን አለ የሚባርክ አለ እልል የሚል አለ። የነሱ ሕይወት እስከዘለዓለሙ በዚህ የተመሠረተ ነው።'),
  ('b3fc43e3-3cff-5ea8-a1a3-e74d6182fc56', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 6, 6, 'ጴጥሮስ ሆይ እንዲያገለግሉኝ እነዚህን አልፈጠርኩዋቸውም ነገር ግን የኔን ብዕል አድላቸው ዘንድና ክብሬንም አጐናፅፋቸው ዘንድ ብቻ ፈጠርኩዋቸው እኔ ፍጥረታትን ሁሉ ከመፍጠሬ አስቀድሞ ምሥጋናየ ከኔ ዘንድ ነበረ።'),
  ('1488067d-733f-5e6d-a2f4-6c80dd38cea5', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 7, 7, 'መላእክትን በፈጠርኩዋቸው ጊዜ ያመሰግኑኝ ዘንድ አደረግሁዋቸው። በጥዑም ዜማና በተለያየ ማሕሌት ያመሰግኑኛል። እነዚህ መላእክት መንፈሳውያን ናቸው ሥጋ አልለበሱም ወደምድር ሲወርዱ ድምፅ የላቸውም የክንፉቸውም እንቅስቃሴ አይሰማም።'),
  ('e0359a41-b994-5e30-ab85-cead55e2acc8', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 8, 8, 'ለእግራቸው ኮቴም ምልክት የለውም ሩጫቸው ከነፋሳት ይቀላል። ምሥጢራቴን ለመፈፀም ይላካሉ በአብ በወልድ በመንፈስ ቅዱስ ስም የሚጠመቁትን ይጠብቁዋቸዋል በኔ አምነው በስሜ ለተጠመቁት ሁሉ በነዚህ መላእክት ጥበቃ ይደረግላቸዋል ለያንዱንዱ ክርስቲያን ሁለት ጠባቂዎች መላእክት ይላኩለታል በግራና በቀኝ በመሆንም ይጠብቁታል ከክፉ ነገር ሁሉ እንዲታቀብ ያደርጉታል ላላመኑብኝ ግን ከይቅርታየና ከምሕረቴ አርቃቸዋለሁ።'),
  ('f8ccd51b-4083-5b74-adf9-617448f1ce9f', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 9, 9, 'ይህን ከሰማሁ በኋላ ከፊቱ ወድቄ ሰገድኩ ጌታዬና አምላኬ ሆይ የገነትን ሁኔታ ንገረኝ ገነት በሰማይ ላይ ነው የምትገኘው ወይስ በምድር ላይ አንተ የሰውን ልጆች ታድን ዘንድ ወደዚህ ዓለም መምጣትህን አውቃለሁ ይህን ምሥጢር ግለፅልኝ በማለትም ጠየቅሁት።'),
  ('b583cd84-73f1-5438-aa2a-fc7dbb0d1731', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 10, 10, 'አስተዋይ ልቡና እንዲኖር የሚያደርግ ክፉውንና ደጉን የሚያሳውቅ ዕፅ ምን ዓይነት ዕፅ ነው። ከዚህ ዕፅ አዳም እንዳይበላ ተከልክሏል ዕፀ ሕይወት ማለት ትርጉሙ ምንድር ነው አዳምና ሔዋንስ የበለስ ቅጠል እንዴት ለበሱ በገነት እያሉ የበለስን ቅጠል ሊለብሱ የቻሉት ፀሐይና ጨረቃ ከዚያ አሉን ሌትና ቀንስ ይፈራረቃሉን።'),
  ('2944c12b-8753-5c93-aab9-7abeaccc6945', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 11, 11, 'በገነት መብልና መጠጥ አለን ብዙ ዛፎችስ ከዚያ ይገኛሉን ዛፎቹስ የዚችን ምድር ዛፍ ይመስላሉን ሙቀትና ቅዝቃዜ በገነት ይኖራልን ረሐብና ጥምስ አለን። ከዚያ ለሚኖሩ ልብስ ያስፈልጋልን ወይስ ይህ ሁሉ የለም ይሆን ለሰዎች መኖርያ ሠው ሠራሽ ግንብ ከዚያ ይኖራልን እነዚያ ምድርን የሚያጠጡ አራት ወንዞችስ ከየት ይመነጫሉ።'),
  ('6746143a-29b7-5fe2-ad10-6cd3ab669c30', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 12, 12, 'ከገነትና ከመንግሥተ ሰማይ ማን ይበልጣል የገነት ቁመትና ርዝመትስ ምን ያክል ነው ገነት ይህ ዓለም ሲያልፍ ታልፋለችን ወይስ ሳታልፍ አሁን ባለችበት ለዘለዓለም ፀንታ ትኖራለች? አልኩት።'),
  ('b5220ca3-09f6-5d88-a71d-a3a9934c6aa1', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 13, 13, 'ወልደ እግዚአብሔር ክርስቶስ የሚከተለውን ጴጥሮስ ሆይ የኔን ምሥጢራት ለማወቅ እጅግ ተግተሃል ገነትን በኤዶም ውስጥ አኖርናት ይህንንም ያደረግነው ሰማይንና ምድርን ከፈጠርን በኋላ ነው ገነትን ጨለማ እንዳያገኛት በማድረግ ነው የፈጠርናት። ገነት ብሩህ ሁና በንፅሕና በመዓርግ በግርማ ያለች ናት ከፍ ያለችም ናት እሷ ከዚች ምድር ከፍ ትላለች። እሷም ከምሥራቅ እስከ ምዕራብ በምድር መጠን ትደርሳለች።'),
  ('04321777-a944-5930-aa49-4da3bbd9d87a', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 14, 14, 'ሶስት መስኮቶች በገነት አሉ አንደኛው መስኮት ከአዳም የለበስኩት ሥጋ በተቀበረበት ጎልጎታ አቅጣጫ አንፃር ይገኛል ሁለተኛው መስኮት ደብረዘይት በሚገኝበት ሥፍራ ትይዩ ይገኛል። ይህ ቦታ አንተ ያለህበት ነው ሦስተኛው መስኮት በደብረሲና ትይዩ ይገኛል።'),
  ('c79f4c20-7eea-5ea2-a21a-577e8c3ecc51', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 15, 15, 'ገነት በመንበራችን ከወደታች ሁና በምሥራቅ በኩል ትገኛለች ብርሃንዋም ከፀሐይ ብርሃን ይበልጣል ከሷም መልካም መዓዛ ያለው ሽታ ይወጣል የዚህ መዓዛ ተመሳሳይ በምድር ፈፅሞ አይገኝም የመለኮት ማደርያም ናት።'),
  ('b12083e4-2f0e-5ffa-ae83-8f548052f057', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 16, 16, 'የገነት ዛፎች በመላእክት ይመሰላሉ ዓለምን የሚያጠጡ አራቱ ወንዞች ከምሥጋናየ መንበር ሥር የማሚመነጩ ናቸው። እነሆ አራት የውሃ መውረጃዎችን አዘጋጀሁ እነዚህ የውሃ መውረጃዎች የነፋሳትን ባሕር የሚያልፉ ሁነው ወደኤዶም ይወርዳሉ። ከዚሁም ውሃ ይመነጭና ዓለምን ያጠጣታል።'),
  ('5770bbbc-dc3d-549d-a03b-0626bb869385', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 17, 17, 'በገነት የሚኖሩ መብላትና መጠጣት ይፈልጋሉ በገነት ብርድና የፀሐይ ቃጠሎ የለም ከገነት የሚመነጨው መልካሙ ሽታ የመብላትንና የመጠጣትን ፍላጎት ያስወግዳል።'),
  ('c67a200c-d09a-51c2-a166-32d1c4832d5c', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 18, 18, 'የገነት ዛፎችስ እንደዚህ ዓለም ያሉ ዛፎች አይደሉም ብሩሃን መላእክት ናቸው። እነዚህም መላእክት እኔን ማመስገንና መዘመርን አያቋርጡም በገነት ስላለውና መልካምንና ክፉውን የሚያሳውቀውስ የሱን ምንነት የማውቅ እኔ ብቻ ነኝ።'),
  ('86725a5f-ec36-5137-a906-0fa764190fb7', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 19, 19, 'ጴጥሮስ ሆይ ዲያብሎስ አለቅነትን ሠጥቼ በብዙ መላእክት ላይ ስለሾምኩት አምላክ ሁኖ በነሱ ላይ እንዲመለክ እንደፈለገ አባትህ አዳምም እንዳይበላ ከከለከልኩት ዕፅ የበላው አምላክነትን ስለፈለገ ነው ወድያውም የፍትወት ተገዢ ሆነ (ፍትወትን አወቀ)።'),
  ('a2fbb7b8-fc30-506f-aca3-0335d27a990a', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 20, 20, 'ይህ ዕዕ ግን ሞትን አፈራ ይህም ሞት ሁለት መንገድ አለው አንደኛው ሊሆን የማይችለውንና የማይገባውን አምላክነትን መመኘቱ ሁለተኛው እኔ ሳዘው ጤናማ አስተዋይ ሰው ነበረ ትእዛዜን ሲያፈርስ ግን ዓበደ በዕብደቱ ሥሕተት ላይ ለወደቀ ኩነኔ አይገባውም አዳም ግን ጤናማ ኑሮ ትእዛዜን በማፍረሱ ዓበደ።'),
  ('3e873d03-da42-59f6-aa38-1687a6434cda', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 21, 21, 'አዳም እብድ ሁኖ አልተፈጠረም አስተዋይ ብልሐተኛ ሁኖ ነው የተፈጠረው ከጥበቡ ብዛት የተነሳም ፍጡራንን ሁሉ በየስማቸው ስየሞአቸው።'),
  ('f526a91d-2ba8-54b2-a7bf-d0a64ea72d2b', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 22, 22, 'ጴጥሮስ ሆይ በገነት ውስጥ ያሉ ዛፎች መላእክት ናቸው በሌላ በኩል የገነት ዛፎች እኛ ነኝ መልካሙንና ክፍውን የሚያሳውቀው የገነት ዛፍ ማለት እኛ ነን ጴጥሮስ ሆይ የሕይወት ዛፍ ማለት እኔ ነኝ ። የምሕረትም ዛፍ ነኝ ከኔ የበላ የዘልዓለም ሕይወት አለው አባቴ የርትእ ዛፍ ነው የዕቅድም ዛፍ ነው እኔ ደግሞ ይቅርታና ምሕረት ነኝ መንፈስ ቅዱስም የሕወት ዛፍ ነው።'),
  ('06374a57-3f20-5086-aaf6-c57e24ef5306', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 23, 23, 'ጴጥሮስ ሆይ ጨለማ ወደገነት አይገባም ገነት ሁለንትንዋ ብረሃን ናት ይህም ብርሃን ከፀሐይ ብርሃን ይበልጣል የሚመሳሰለውም የለም በገነት ለሚገኘው መዓዛም የሚስተካከለው የለም ሞት በገነት የለም በገነት ለሚኖሩ ሕመም ደዌ ሞት የለባቸውም።'),
  ('eca5773d-b601-5c88-a447-195d16e414ac', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 24, 24, 'ወደገነት ህግ አፍራሽነት ተላላፊነትና ርኩሰት አይገባም ህግ ተላላፊዎችና ርኩሳት ወደገነት አይገቡም በገነት ሌትና ቀን ምሥጋና አይታገልም ይህም አኳኋን እንደ ሰማያዊቷ ኢየሩሳሌም ያለ ነው የገነት ብርሃን ከፀሐይ ብርሃን ይበልጣል የዚህ ብርሃን መጠን በሰው አንደበት ሊገለፅ አይችልም የራሴ ግርማ ፅናት ኃይሌና ብርሃኔ በኔ ላይ ያለ ነውና።'),
  ('956bcc8d-61b6-55c7-a51a-d476169852d4', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 25, 25, 'ጴጥሮስ ሆይ ገነትን አከበርኩዋት በመንግሥቴ በታችም አስቀመጥኩዋት ጴጥሮስ ሆይ እቺ ገነት ለደጋግ ሰዎች ብቻ የተዘጋጀች ናት ደጋግ ሰዎች ማለትም በሕይወት ዘመናቸው ፈቃዴን የፈፀሙ ናቸው። ጴጥሮስ ሆይ በገነት ክረምት የለም በጋም የለም የዚህ ዓለም ፍትወት የለም መብል መጠጥ የለም በዚችው በተመረጠችውና በተቀደሰችው ገነት የሚኖሩ ሁሉ በሷ በሚፈልቀው መልካም መዓዛ ይኖራሉ።'),
  ('8c891bb7-7825-5549-a9be-b21a2e82bb74', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 26, 26, 'በዚችው ገነት ውስጥ ለሚኖሩ ሁሉ የዚህ ዓለም ጣጣ ውጣውረድ የለባቸውም አይራቡም አይጠሙም መገዳደርም ሆነ መታበይ በነሱ ዘንድ ፈፅሞ አይታወቅም የለምም በፀጋ የተዋቡ ስለሆኑም አይራቈቱም።'),
  ('1d68f41d-e70a-5e74-a01d-8be67adf8e12', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 27, 27, 'የበለስ ቅጠልን አዳምና ሔዋን እንደለበሱ የሚባለው እነሱ ለብሰውት አይደለም ፀጋ ሲለያቸው ሐፍረታቸውን በእጃቸው ነው የሸፈኑት ጴጥሮስ ሆይ የገነት አሠራር እጅግ አስደናቂና የሚያስገርም ነው።'),
  ('385a1992-657d-5981-a8ee-6e1840ff004a', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 28, 28, 'መንግሥተ ሰማያት ግን ከገነት ከፍ ትላለች ትበልጣለች ትከብራለችም መንግሥተ ሰማያትን ለመግባት የታደለው አስቀድሞ ወደገነት ይገባና በዚሁ ይደሰታል ከዚያ በዚህ ቀን ያልፋል ወደማይባለው መንግሥተሰማያት ይገባል።'),
  ('686f147c-7eeb-5194-a03f-62346989b298', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 29, 29, 'ጴጥሮስ ሆይ ለጻድቃንና ለደጋግ ሰዎች ያዘጋጀኋቸው ግሩማን የሆኑ በውስጣቸው ብርሃን ያለባቸው ብዙ በሮችና ማደርያዎች አሉ።'),
  ('19405654-4dd3-55f1-af84-6912f19cdb42', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 30, 30, 'ጴጥሮስ ሆይ የመንግሥተ ሰማያትንና የምድርን ቁልፍ ሠጠሁህ ሁሉም በእጅህ አስረክቤሀለሁ ይህንንም የምገልፅልህ ክብር አንተን የሚመለከት ነው። የብርሃን ማደርያ የተባለው የክብር ቦታ ላንተ ይሠጣል ይህም በሰማያት ያለ ሲሆን ካንተ ሌላ እኔን የሚያምኑ ሁሉ እንዲገቡበት አስቀድሞ የተዘጋጀ ነው አለኝ።'),
  ('d8e56673-fc82-5b40-a422-0dcd431d27ce', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 31, 31, 'ይህን ሁሉ ተናግሮ (ጌታችን መድሐኒታችንና አምላካችን ኢየሱስ ክርስቶስ) ዝም አለ። ከዚያ እኔ ከፊቱ ሰገድኩ አቤቱ ሆይ አገልጋይህን ይቅር በለው ከፊትህ ይናገር ዘንድም ፍቀድለት ብየ ለመንኩት። እሱም መለሰ እንዲህም አለኝ የምትፈልገውን ተናገር የምትወደውንም ለምን እኔ ልመናህን አልከለክልም እኔም ስመልስለት እንዲህ አልኩት አቤቱ ጌታዬ ሆይ የጻድቃንንና የነቢያትን ማደርያ (መኖርያ) የት ይገኛል እነሱ ኣንተን የሚያምኑ ናቸውና ደጋግ ሰዎችስ እስከ ዳግመኛው መምጫህ ጊዜ የት ይኖራሉ ።'),
  ('135335ef-fd24-5a21-ac52-602a85740672', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 32, 32, 'ጌታዬና መድሐኒቴ ኢየሱስ ክርስቶስ መለሰና እንዲህ አለኝ ጴጥሮስ ሆይ የመሐይምናንን ማደርያቸው እነግርሃለሁ በኔ ለሚያምኑ መሐይምናን ለጻድቃንና ለነቢያት እንዲሁም ለሌሉች ከዕርገቴ በኋላ ግሩም ወደሆነው መኖርያየ ከሄድኩ በኋላ የንፁሐንንም ማደርያቸው በስሜም አምነው የተጠመቁ ሁሉና ሞት ሳይቀድማቸው ንሥሐ ለገቡ ሁሉ ማደርያቸው የት እንደሆነ እነግርሃለሁ።'),
  ('42bdd0d0-86ac-5808-a72e-6fd21b4bc92b', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 33, 33, 'የኒህ ሁሉ ማደርያቸው ገነት ናት ይህችንም ገነት በኤዶም የተከልኳት ናት በሷም ያርፋሉ እስከ ዘላዓለምም ከዚያው ይሆናል። እናንተም ይህንን ዓለም ንቃችሁ ያላችሁንም ዓለማዊ ንብረት ትታችሁ እኔን የተከተላችሁ አንተም ማደርያችሁ በመንግስተ ሰማያት ይሆናል በሰው ልቦና ያልታሰበ ዓይን ያላየው ጆሮም ያልሰማው ሕመምና ደዌ የሌለበት ሐዘንና ሰቆቃም የራቀበት የደስታን ቦታ ትወርሳላችሁ ይህንንም ላንተ ቃል ገብቻለሁ።'),
  ('0472e8a2-18ef-5407-a2be-49e5795a7463', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 34, 34, 'ጴጥሮስ ሆይ አንተንና አሥራ አንዱን ሐዋርያት እኔ አስቀድሜ ስለመረጥኩዋችሁ በአሥራ ሁለት ነገደ እሥራኤል ላይ እሾማችሁአለሁ በነሱ ላይም ትፈርዳላችሁ በሥራቸውም መጠን ፍርድ ታስቀምጡባቸዋላችሁ።'),
  ('59663cfa-f2d4-5319-abe0-fd87aa650a45', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 35, 35, 'ካህናትንም በብርሃን ማደሪያ አሳድራቸዋለሁ ለያንደንዳቸውም ግሩም ማደሪናያ አዘጋጃለሁ ይህም እንደየትልቅነታቸው ነው ጴጥሮስ ሆይ አንግዲህ ኣስተውል የሰጠሁህን ብዕሌንና ፀጋዬን የለመንከኝነንም ሁሉ ገና እሠጥሃለሁ እጨምርሃለሁ።'),
  ('2187178f-4dc6-530c-ac1e-7c8aaef47c19', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 36, 36, 'ጴጥሮስ ሆይ በፀጋየ ብዕል መላእክትን ፈጠርኩዋቸው የኔም ክብር ይጋርዳቸዋል በዕለተ ትነሣኤም በኔ ለሚያምኑ መሐይምናን ሴቶችና ወንዶች የሞትን ምንነት እንደማያውቁ መንፈሳዉያን ሞትን እንደሌለባቸው ከነውር ሁሉ ንፁሐን ይሆኑ ዘንድ አደርጋቸዋለሁ መሐይምናን በሴቶችና በወንዶች ፆታነት ያሉ ናቸው።'),
  ('74c2bfd2-d4ad-5bcf-ad7c-2f835d1137b1', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 37, 37, 'የወደዱትንም ያደርጉ ዘንድ መብት እሠጣቸዋለሁ በጆሮቻቸው ይሰሙ ዘንድ የሚሰሙትም ድምፅ ከእሳት የሚወጣ ነው እሳትቱም አይፈሩትም ጴጥሮስ ሆይ በዕለተ ትንሣኤ የሚሆነው አሳይሀለሁ ነገር ግን ወደሚበልጠው ደረጃ እስክትደርስ ድረስ ታገሥ።'),
  ('98c7a2fc-5f11-5ba2-adb4-38c381553e1b', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 38, 38, 'ጴጥሮስ ሆይ እነሆ ወደሰማይ ካረግሁ በኋላ በሕዝቤ ላይ ከፍተኛ መከራ ይደርሳል ከመከራ ብዛት የተነሳም ሕዝቦቼ እስከዓለም ደርቻ ድረስ ይሰደዳሉ በአሳት ይቃጠላሉ አካላታቸው ይቆርጣቸዋል እኔ ግን ከሕዝቦቼ አልለይም ኃይሌንና ተአመራቴን በነሱ ላይ አሳያለሁ።'),
  ('1b063765-6844-56ee-aafb-83d4233d238f', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 39, 39, 'ጴጥሮስ ሆይ ከዲያብበሎስ አገዛዝ ሃያ ሱባዔ ይቀራል ይህ የዲያብሎስ አገዛዝ ሲያልፍ በድጋሚ እኔ ለሰው ልጆች የምሠጠውን ጸጋየና መንከራቴ አሳያለሁ ይህንን የኔን ጸጋ የሚጐናፀፉት የኔ መዕምመናን ብዙ ናቸው ከነሱ አንዱ እልፎቹን ያሳድዳቸዋል ሁለቱም ደግሞ አእላፈ አእላፋቱን ያሳድዱዋቸዋል ይህንን አስደናቂ ነገርን የተመለከቱ ሕዝብ ብርሃኔን ተአምራቶቼንና መንክራቶቼን አይተው ይደነቃሉ።'),
  ('474f0ab3-98d8-543f-a453-3e8a00d4f436', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 40, 40, 'ጴጥሮስ ሆይ ወዳባቴ ባረግሁ ጊዜ ካልተለየሁበት ምስጋናየም በሆንኩ ጊዜ ወዳንተና ወደሁሉም ተማሪዎቼ ለሁል ጊዜ አብሮአችሁ የሚኖርን መንፈስ ቅዱስን እልካለሁ።'),
  ('0d5d9d98-f4e7-58d5-a887-72faadc44cca', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 41, 41, 'አልተዋችሁም ይቅርታየም አሳድርባቸዋ ለሁ ይህም እስከ ዘለዓለም ነው ጴጥሮስ ሆይ አትዘን የምነግርህንና የምገልፅልህን ሁሉ ጠብቅ እወቅ ወደ ልብህም አስገባው በተሰቀልህም ጊዜ በመንግሥተ ሰማያት አንደምታገኘኝ አስተውል ።'),
  ('13279bd5-d801-5acf-af8c-fa425b4372ac', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 42, 42, 'የተገደለው ያዕቆብ በአናብስት የተበላው ዮሐንስና አርድእት ሁላቸው በጠላቶቻቸው ተገድለው እኔን ያገኙኛል ተስፋቸውም በመንግሥተ ሰማያት ብዙ ነው።'),
  ('d0e107df-7e32-5823-a19a-5585feb423f6', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 43, 43, 'ጴጥሮስ ሆይ በኔ የሚያምኑ ምእመናን እንደሚሉት አስተውል በዚህም ሃይማኖታቸው ለማንም የተለየች ትሆናለች ስለሃይማኖትም ተለያይተው ወደያገሩ ይሰደዳሉ ። አስቀድሞ በተቃራኒነት ባንተ ላይ ሲሞን መሠርይ ይነሳል እሱም የዲያብሎስን መንገድ ይከተላል ሲሞን በሰይጣናዊ ምግባሩ ሕግን የሚያጠፋ ነው ስለዚህ በተቃራኒነት አንተ ጋር ስለገጠመ አጠፋዋለሁ።'),
  ('d6bc6798-7c5c-51d0-a618-62d21ed94c4e', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 44, 44, 'ከሱም ቀጥሎብዙዎች ተቃራኒዎች ይነሳሉ እነሱም ያስዴውያን አጥሌም ናባዶን በቶቆድን አጥሶን ቃርጣን ፍርምና በድሪናን፣ አንናሶ፣ አልማንድዩ፣ መቄዶንያ፣ ጠይጣለን፣ መርቃልደስ፣ የቅጥርያ ሕዝብ የበለፋንያ ሕዝብ የቅርደንያ ሕዝብና ሌሎችንም አነሱም የመሰሉ ያገር ሕዝችን ግለሰቦች ናቸው ።'),
  ('bc08cd41-f148-534f-a877-ce4b831f0a78', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 45, 45, 'በዘመናቸው ረሐብ ይፀናል ምግብ አይኖርም በምድርላይም ብዙ ስዎች ይሞታሉ ጴጥሮስ ሆይ የአንበሳ ደቦል በተመለሰ ጊዜ ወደቦታውም በሄደ ሂዜ ይህን ስታይ የማለቂያ ጊዜ እንደደረሰ እወቅ ተረዳ የሞትን መብዛት ባየህም ጊዜ ረሐብ አንደበዛ ባየህ ጊዜ ሁለት ነገሥታትም እርስበርሳቸው ሲገዳደሉ ባየህ ጊዜ ምድር እንደምትጠፋ ተረዳ።'),
  ('0829108e-d0b1-5220-a902-cd537c009dde', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 46, 46, 'አስደንጋጭ ሕልም ይበዛል የሰማይ ምልክት በዚሁ ምድር ይበዛል በዚሁም ጦርነትና ምርኮ ይበዛል ሰዎችንም ደግሞ ለሞት አሳልፌ እሠጣለሁ እኔም ጸሎታቸውን አልሰማም ልመናቸውንም አልቀበልም።'),
  ('1d75cebb-88f1-5203-a71a-431dba9a800d', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 47, 47, 'በዚሁ ሕዝብ ጥፋት በነሱ ላይ ከፍተኛ ስደት ይደርሳል ከፍተኛ መከራም ይደርሳቸዋል ይህን ሁሉ መከራ የሚፈጽመው በመሐይምናን ሕዝቤ ላይ ነው። እነሱም ከዚሁ መከራ ለመዳን ወደኔ በማንጋጠጥ ያለቅሳሉ። ይህንንንም ልቅሶና መከራ እጅግ የበዛ ነው ከጥንትም ጀምሮ ያልሆነው ይሆናል።'),
  ('b74a16da-3bf1-5f1b-aded-f02a93e9bfda', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 48, 48, 'አዳም ዕፀበለስ በልቶ ጥፋት በተቈጠረበት ጊዜ ይህን ያህል ቢለምን ኑሮ ከገነት ባልወጣ ነበር። እንዲሁም በዘመነ ኖኅ የተፈፀመው ጥፋት ከመድረሱ አስቀድሞ ይህን ያህል ምህላ ቢፈፀም ኑሮ ጥፋት ባልደረሰም ነበር። የሰዶም ጥፋትም እንዲሁ።'),
  ('41979ca6-280e-5d65-ab81-ddf7b36bbf14', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 49, 49, 'ጴጥሮስ ሆይ ሕዝቦችን የካሐዲዎችን መንገድ እንዳይከተሉ ንገራቸው። በቀናች ሃይማኖት ይፀኑ ዘንድም አሳምናቸው ከዚህ ሌላ ግን ከሌላ ክፉ ነገር ርቆና ተጠብቆ በዚች የቀናች ሃይማኖት የቆመ ሁሉ እስከዘለዓለሙ ይድናል የጸጋየንም ብዕል ይወርሳል። ይህም ዓይን ያላየው ጆሮ ያልሰማው ነው የሰማይ መላእክትም ኃይላትም ያላዩትም ያያል።'),
  ('ca1a7172-4875-5929-ab3c-04dbad188f3c', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 50, 50, 'ጴጥሮስ ሆይ በነዚህ ሰዎች ዘመን ለሚያረግዙና ለሚያሳድጉ ሴቶች ወዮላቸው በዚሁ ዘመን በኔ ከሚያምኑ አብዛኞቹ ይገደላሉ የሚገደሉትም በሠይፍ ነው በዚህ ጊዜ ድንጋዮችና አብያተ ክርስቲያናት ይጮኻሉ ውሆች ይደርቀሉ ወንዞች ውሃን ማፍሰሳቸው ያቆማሉ እንዲህ እያለ ዘመናትና ዓመታት ያልፋሉ ፀሐይ ጨረቃና ከዋክብት ይረሳሉ ሦስት ቀንና ሦስት ሌሊት ሳያቋርጥ ጨለማ ይሆናል ይህም የሚሆነው በኢየሩሳሌም ዙርያ ባሉት አገሮች ነው በሰዎች ላይ ቂምና ቁጣ ይበዛል። መልካምም ነገር ከሰዎች ይጠፋል።'),
  ('33b336d3-4acd-5af3-a11d-95542b6a9d3f', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 51, 51, 'የሰዎች ክፋታቸው ከደግነታቸው ትበልጣለች በደላቸው እጅግ በዝቶ ይታያል። የዱር ዛፍ ፍሬ ይጐድላል አጋንንት በሰዎች ላይ ያድራሉ ሐሰተኞች ነቢያት ይነሳሉ የዱር አውሬዎች የሰውን ሥጋ መብላት ያዘወትራሉ የመጨረሻ ጊዜአቸው ስለሚደርስም ምድርን ተቀራምተው ይከፋፈሏታል።'),
  ('5d5f00e6-f50f-5c17-a242-ab3a28f73fa1', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 52, 52, 'ከዚህ በኋላ የሕይወትና የመድሐኒት በትር ይወጣል (ከቴማን) ከዚህ በኋላ እነዚህ ሕዝቦች በተራራሮች ላይ እያሉ ይቀጠቀጣሉ እነሆ ንጉሥ ከምሥራቅ ይመጣል እሱም የሚመጣው ከእንቅልፍ ያነቃ ዘንድ ነው። የጦር መሣርያ ይበዛል ጦርነትም ይበረታል የሰው አስከሬን በየሜዳው እንደተራራ ይከመራል የሰዎች ነፍሳትም እንደበግና እንደፍየል ይጠፋሉ።'),
  ('5f215db4-1c27-5c1d-a128-8d0414f383c8', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 53, 53, 'በደል ትበዛለች የደናግል ሴቶች ሐፍረት ይገለጣል አባት ልጁን ልጅ አባቱን ይክዳሉ አገልጋይ አሠሪውን ይክዳል እናት ልጇን ልጅ እናቷን ይክዳሉ አገልጋዮች በሐላፊዎች ላይ መታበይን ያሳያሉ እመቤት ትፈጫለች ሠራተኛዋ እንደእመቤት ትሆናለች ወጣቶች ሽማግሎችን ንቀው ከበላይ ይቀመጣሉ ሽማግሎች ደግሞ ከታች ይቀመጣሉ።'),
  ('0de58176-235d-5697-a05a-ae518c75500c', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 54, 54, 'ለሞትም አሳልፌ እሠጣቸዋለሁ ውሾችም ይበሉዋቸዋል የሰማያት ሐይልም ይነዋወጣል የምድር ነገሥታት እርስበርሳቸው ይገዳደላሉ የምድር ነገሥታት ሁሉ ከቴማን ንጉሥ ፊት መቆም ተስኖአቸው ይሽሻሉ የቴማን ንጉሥ ግን ካራቱ መዓዝነ ዓለም ካሉ ነገሥታት ጋር ይዋጋል።'),
  ('b5a1b630-7f90-565b-a6a8-4e4ca0a25730', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 55, 55, 'ነገሥታትን ይገዛል የጣዖትንም ቤት ያፈራርሳል ወረትን ያስወግዳን ሐዘን ይወገዳል ተገዥነትም ይወገዳል ድሕነትና ሰላም ይረጋገጣል ጥጋብ ይበዛል በምደር ሁሉ ጥጋብ ያበዛል መጥፎ ጊዜ ያልፋል ሰዎች ግን ዳግም መጥፎ ጊዜ ሊመጣ ይችላል እያሉ በስጋትና በጭንቀት ይዋጣሉ። ፍርሐትና ድንጋጤ ከዚህ ይመጣል የዚሁ ዓይነት ፍርሐትና ድንጋጤ መቼም ያልታየ ነው። ከሰዎች ፍርሐት ብዛት የተነሳ የነፍስ ነውጥ ይበረታል።'),
  ('12445bf8-0b6d-5773-a1ac-4e7cd83726c2', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 56, 56, 'ጦርነት ይነሳል ብዙ ደም ይፈሳል የሰማይ ወፎች የሰውን በድን ሰልተው ይጠግባሉ ከጥቂት ሰዎች በቀር የሚድን የለም ከሞት የተረፉት ሰዎች አንዱ ለሌላው ከየት ብሔር ነህ ይለዋል ሴትም ሌላይቱን ጓደኛዋን ከማን ወገን ነሽ ትላታለች አባት ልጁን ይጠብቃል ልጅም አባቱን ይጠብቃል ።'),
  ('4f587d09-7bf6-5697-aad1-efc570017286', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 57, 57, 'እርስ በርሳቸው አይተዋወቁም ወንድ ባልንጀራውን ይገድላል ሌላም ቁም ነገር አያውቅም መሐይማንንም ይይዙዋቸዋል በራሳቸው ጠጉርና በብረት ሰንሰለትም አንገት አንገታቸውን ያስራቸዋል ወደወንዝም እየወረወሩ ይጥሉዋቸዋል ነገር ግን ውሃ እንዳይጠጡ ይከለክሉዋቸዋል።'),
  ('07563bec-3310-585e-a622-c24c32acade2', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 58, 58, 'በድጋሚ ትልቅ ፍርሐት ይሆናል ምድር ባንድ ዕለት ውስጥ ሦስት ጊዜ ትንቀጠቀጣለች በድጋሚ የቴማን ንጉሥ ይነሳል እሱ ላም ይመስላል ያመነ በራሱ ላይም ሶስት ቀንዶች አሉት።'),
  ('16644c2e-5654-5f72-aae9-072fbdc693ae', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 59, 59, 'እሱ ፍጥረትን ሁሉ ያጠፋል በአልበካ ከተበላችሁ አገርም ይደርሳል በዚችውም አገር የወደደውን ሁሉ ያደርጋል ከዚያ ብዙ ጥፋት ይደርሳል ወደሀገሩም መልሰው ራሱን ከፍ ከፍ አድርጓልና የፈጣሪውንም ምስጋና ትቷልና ትምክህትን በማብዛቱ ራሱ ተመስግኗል ክፉንም አስቧል ።'),
  ('99d45147-816b-5db1-a452-b1da71303e16', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 60, 60, 'ከትዕቢቱ ብዛት የተነሳም በኃይሌ ፅናት ምድርን ፈጠርኳት ይላል ከዚህም የተነሳ የጠፋ ይሆናል የሚያጠፋውም የምስራቅ ንጉሥ ነው እኔም አጠፋዋለሁ በምድር ሁሉም መዘባበቻ እንዲሆን አደርጋለሁ ጴጥሮስ ሆይ ከዚህ በመቀጠል ጦርነትን አመጣለሁ ግብፅንም እንድትመዘበር አደርጋለሁ ግንቧንም አፈርሳለሁ።'),
  ('7febd307-f945-52fb-a06d-03f02d85edce', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 61, 61, 'ደምግባትዋንም እደመስሳለሁ ብሔረ ግብፅ ከተደመሰሰች በኋላ አንድ ተኩል የሱባኤ ጊዜ ቆይቶ በደሴቶች ላይ ተአምራት ይታያል በባሕር ላይ ደግሞ ፍርሐት ይበዛል በባህሩ ዙሪያ የሚኖሩ ርኩሳን ሰዎች ወደቤተ ክርስቲያን ይገባሉ አብያተ ክርስቲያናትንም በእሳት ያቃጥሉቸዋል።'),
  ('80154355-f7a1-56ab-a805-35b58a8338c0', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 62, 62, 'በእግራቸውም ትእምርተ መስቀሌን ይረግጣሉ። መሐይምናንንም ይከተሉዋቸዋል። በዚሁም ቦታ ይገድሉዋቸዋል እነሱ ግን በምድር ሁሉ ይበታተናሉ የዚህ ዓይነት ስደት ከዚህ በፊትም ታይቷል። መጥፎ ሕልምም ይበዛል። ባገር ሁሉም ትልቅ ፍርሐት ይበዛል በመሐይምናን ላይ ጥላቻ እጅግ ይበዛል። መሐይምናንን ግን በጠላቶቻቸው እጅ እንደወደብ፡ አልተዋቸውም። በዚሁ ዘመን ፀሐይ ይጨልማል፥ ጨረቃም እንዲሁ። ከዋክብትም ከሰማይ ይወድቃሉ።'),
  ('75021f6b-1f5a-5d98-a3ca-880865fe9199', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 63, 63, 'የምሥራቅ ንጉሥ ከዚህ በኋላ ይመጣል ጦርነትም ይበዛል (በመካከላቸው)። በምድር ላይ ነፋስ ይነፍሳል። የግብዕ ሰዎች ባሰቃቂ ረሐብ ያልቃሉ። የወረርሺኝ በሽታም ከረቡ ተከታትሎ ይጨርሳቸዋል በአዳም ልጆች ሞትን አመጣለሁ በሰማይም ተአምራቴን ይታያል።'),
  ('f0720c2a-4579-5c20-ae26-60dfb071ee97', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 64, 64, 'ከዚህ በኋላ የምሥራቅ ንጉሥ ወደግብዕ ይሄዳል የቀሩትንም ሰዎች እንደገና ይገድላቸዋል። በምድር ሁሉም ይነግሳል አገሮች ሁሉም በሱ ሥር በመሆን የሱ ታዛገዦች ይሆናሉ ከሠራዊቱ ብዛት የተነሳም ብዙ ታላላቅ አገሮችን ይወርሳል። ከዳር እስከዳር ሁሉንም ይቈጣጠራል የሠራዊቱም ድምፅ እንደመኪና ይሰማል።'),
  ('e66c1988-d585-5e35-ac2e-a15b69bdd9ab', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 65, 65, 'ከግርማው አስፈሪነት የተነሳ ኰረብታዎች ይጮኻሉ የሰማያት ኀይልም ይነዋወጣል ታላቅ ፍርሐትም ይሆናል ኮረብታዎችና ተራሮች እንደሰው ያለቅሳሉ ከምሥራቅ እስከ ምዕራብ ከሰሜን እስከደቡብ ለቅሶ ይሆናል።'),
  ('6c2e8399-57bc-5541-a332-5d58d5795a46', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 66, 66, 'ከዚህ በኋላ ይቅርታየንና ምሕረቱን በነሱ ላይ (በምድር አሕዛብ ሁሉ) እልካለሁ ጸሉታቸውንና ልመናቸውን አሰማለሁ ይህንንም የማደርገው ላመኑብኝ ብቻ ነው። ወደኔ በአንቃዕድዎ ለፀለዩ ሁሉ ይህንን ሁሉ እፈፅምላቸዋለሁ። ለሚቃረኑኝ (ለሚቃወሙኝ) ሁሉ ግን የመቅሰፍቴ በትር አነሳባቸዋለሁ እገድላቸዋለሁ አጠፋቸዋለሁ በግልፅም በምድር ላይ መድሐኒትን አመጣለሁ።'),
  ('780472e5-6dc7-56f1-a741-60dc6cfcd19a', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 67, 67, 'ምስጋናየ በሚያምኑ ላይ አሳያለሁ በመከራ ላይ የነበሩትም ሕዝብ እንደቀድሞው ይሆናሉ የተደበቀውም ግልፅ ይሆናል። ምሕረቴንም በምድር ላይ አደርጋለሁ የሙት ልጆችንም አነሳለሁ።'),
  ('2794c2d4-6d63-5acc-a7c2-5501dcaeef34', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 68, 68, 'የአንበሳ ዶቦልን አነሳለሁ ነገሥታትንም ሁሉ ይሰዳቸዋል። ይቀጠቅጣቸውማል እነሱን እንዲቃወም አደርገዋለሁ ሥልጣንም እሠጠዋለሁ። የአንበሳው ዶቦል አነሣሥ ከእንቅልፍ እንደመነሳት ያለ ነው በዚሁም አኳያ ከመንግሥቱ ከወደምዕራብ አቅጣጫ ያለውን ቦታ እንዳለ ለመውረስ ይችላል።'),
  ('51902dc9-21ba-5a1f-a37c-010afcb26a56', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 69, 69, 'በዚህም ምክንያት በሱ ላይ ቅንአት አደረበት ጴጥሮስ ሆይ እነሆ ከዕርገቴ በኋላ በሰማይ ላይ ብዙ ሁኔታዎች ይፈጠራሉ ነገሥት ስሜን ይክዳሉ። መሐይምናንም ሁሉ ይገድሉዋቸዋል የሚገደሉት መሐይምናን በስሜ የሚያምኑ ናቸው ነገሥታቱ ይህን ለማድረግ የሚነሱት ዲያብሎስ ልባቸውን ስለሚያፀና ነው።'),
  ('759cdeed-df9e-55fa-a2ac-cbc29d970892', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 70, 70, 'ከነዚህ ነገሥት አስቀድሞ የሚነሳው «ዐ» ይባላል። ይህም ንጉሥ የኔ ወንድም የሚባለውን ያዕቆብን ይገድለዋል ይህም የዕቆብ የኔ ደቀመዝሙር ነው። ከሱ ቀጥሎ «ነ» የሚባለው ንጉሥ ይነሳል ይህም ንጉሥ አንተን ይገድለሃል። ከሱ በኋላ «ጠ» የሚባለው ንጉሥ ይነሳል ይህ ንጉሥ አይሁድን ይገድላቸዋል።'),
  ('71124a93-0bc8-5a74-a598-df0baeeef6fa', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 71, 71, 'የአይሁድን ሥረ መሠረትም ይነቅላል «ነ» «ሰ» ከሱ ቀጥሎ «ቀ» «አ» ቀጥሎ «ከ» ከሱ ቀጥሎ «ሰ» ከሱ ቀጥሎ «አ» እንዲሁም «መ።አ።ዕ።ቀ።ቈ» በቅደም ተከተል ይነግሳሉ «ቈ» በመጨረሻው የሚነግለው ሲሆን ይህ ንጉሥ የኔን የቀናች ሀይማኖት ያስፋፋል መስቀሌንም ከተደበቀበት አውጥቶ እንዲታይ ያደርጋል።'),
  ('847c3846-2b5b-5dd4-a1a4-874b81c632bc', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 72, 72, 'ስሙንም በትውልደ ትውልድ ሁሉ ከምስራቅ እስከ ምዕራብ ይታወሳል የምድር ነገሥታትም ከሱ ይባረካሉ በዕድቅና በቅንነት ይፈርዳል ጽድቅን ይወዳል ዓመፅንም ይጠላል በዘመኑ የኔ ተአምር በሰማይና በምድር ተአምሬ ይታያል መስቀሌም ለሁሉ ፍጡር ይታያል።'),
  ('e80c6dbe-6e5a-59b4-a428-b6e71042efd5', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 73, 73, 'እኔም ከሱ ጋር እኖራለሁ ኃይልንና አቸናፊነትንም አሰጠዋለሁ መሐይምናን ይበዛሉ። ጠላቶቻቸውንም ያቸንፋሉ ከዚሁ ቀጥሎም «ከ፣ ር፣እ፣ስ » የሚባሉ ነገሥታት ያነግሳሉ። ከዚያ በመቀጠል ግን ከነሱ ወገን የሆነ «ሰ» የሚባል ይነግሣል እሱም ሁለቱን ነገሥታት ይገድላቸዋል መሐይምናንንም ይቃወማቸዋል በዚሁ ዘመን ስደትና መከራ ይሆናል።'),
  ('995471ff-e2cd-5a5d-a65c-c4bd0545c85b', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 74, 74, 'ከሱ በመቀጠል «የወ» ይነግሳልሉ ። ከነሱ በኃላ ደግሞ «ዋ›› የሚባል ይነግሳል እሱ የተባረከና የተመረጠ ይሆናል ሃይማኖቱም የቀና ደግ ይሆናል በሱ ዘመን ብዙ ተአምራቶቼንና ድንቅ ሥራዎቼን አሳያለሁ የማሳየውም ለሚያምኑብኝ ነው።'),
  ('e57f2824-04e0-503d-a645-54a2088a3993', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 75, 75, 'እሱም ደግ የተባረከ በቀናች ሃይማኖት የሚሄድ በፅድቅና በቅንነት የሚፈርድ ይሆናል እኔም በሕይወቱ ሁሉ ከሱ አልለይም ከሱ በመቀጠልም ‹‹ለ› በመባል የሚጠራ ንጉሥ ይነግሣል ይህም ንጉሥ እንደበፊቱ ደግ ይሆናል።'),
  ('ab0965fb-0ac3-5c48-a596-41df55068f53', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 76, 76, 'ከሱ ቀጥሉ ‹‹ር» በመባል የሚጠራ ንጉሥ ይነግሣል ይህ ንጉሥ ከሐዲና የእሥክንድርያን ሕግንና ሥርዓትን የሚያጠፋ ይሆናል ከሱ በበመቀጠልም «ነ፣ሰ፣ጠ፣ሀ፣» ይነግሣሉ ከሐዲዎች ናቸው።'),
  ('175e3781-bcb0-5a23-a0e1-cf090a49996f', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 77, 77, 'ከሱ በመቀጠል ‹‹ሀ› የሚባል የሱም ሙሉ ስም ‹‹ሀርቃል›› የሚባል ይነግሣል እሱም ለኔ መዓት የተጋለጠ የቀናችንም ሃይማኖት ለማጥፋት ሆን ብሎ የሚነሳ ነው በዘመነ ከርጉም ዲያብሎስ የመነጨ እጅግ የተጠላ ህግ ይታያል ። በዚህም ከሐዲ ንጉሥ ምክንያት በሕዝቦቼ ላይ መዓቴን እልካለሁ በመቅሰፍቴ በትርም እመታቸዋለሁ።'),
  ('cf2af172-8c45-5ee1-a9fe-57528dfdc85f', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 78, 78, 'እንደአሞራዎች ያለ ጥፍር ባላቸው የዱር አውሬዎች አጠፋቸዋለሁ እነሱ የከሐዲዎች ልጆችና የመናፍቃን ልጆች ናቸው የእፍኝት ልጆችም የዓመፅ ልጆችም ይባላሉ የሰውን ሥጋ የሚበሉ ናቸው የመራራው ልጅ ውጤቶች ናቸው የረከሰውንና የከፋውን ሥጋ ለመብላት ብቻ ይተጋሉ በመብልና በመጠጥ ጊዜአቸውን ያሳልፋሉ።'),
  ('6b95e242-97e7-5ff2-a943-4b7601dd23b5', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 79, 79, 'ጴጥሮስ ሆይ ሰዎች መጥፎውን ሥራ እንዲሠሩ ባያስገድዱዋቸው ኑሮ ይህንን ሁሉ ለመፈፀም ባልተገደዱም ነበር። በመግደልና በማንገላታት ሌሎች ሰዎች የነሱን ፈቃድ እንዲፈፅሙ ያደርጋሉ በዚሁ ሕዝብ ዘመን ከባድ ነውጥና ድንንጋጤ ይከሰታል።'),
  ('eb32a5c9-6594-5434-a7c0-b5758d587f95', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 80, 80, 'ሕዝቦች ከሕዝቦች ጋር ይጣላሉ ራሳቸውን ይላጫሉ ወገባቸወንም ይታጠቃሉ ከዚህም የተነሳ በሚፈፅሙት ቅጥ ያጣ አካሄድ ሌላ ፍጡር መስለው ይታያሉ የገዛ ሥጋቸውንም በመሽላለም ልዩ ፍጡር ለመምሰል ይጥራሉ እንደ አጋንንት ይሆናሉ እኔም ከተወለዱበት አገር አስወጥቼ ወደሌላ እንዲባረሩ አደርጋለሁ፡።'),
  ('a03d36de-6d58-54db-ab5f-dd9c2dc41a22', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 81, 81, 'በምዕራብ እስከምስራቅ ከሰሜን እስከ ደቡብ ባሉት ቦታዎች ሁሉም ይበታተናሉ በየደረሱበትም አገር ሁሉ ብዙ አገሮችን ያጠፋሉ የነሱም መንግሥት ጣዖትን እስከሚያመልኩ አገሮች ይደርሳል የነገሥታትን ቤቶች ለማፍረስ የተዘጋጁ ይሆናሉ በየቀኑም ጦርነትን ይቀሰቅሳሉ ይህንንም የሚፈፅመት ወጣቶቻቸው ናቸው፡።'),
  ('ffbc03bb-4c59-520e-a1be-04d709158c8e', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 82, 82, 'ልጆች ወላጆቻቸውን ይጣላሉ ሽማግሌዎችንም ይዘልፋሉ የሚሳደቡትና የሚሰደቡት ሽማግሌዎች ሃይማኖተኞች ናቸው ሲሳደቡም ሐፍረትና ፍርሐት አይሰማቸውም ልጅ አባቱን አባት ልጁን ያለፍርሐት ይገድላል፡።'),
  ('091ab2f6-81c0-5a12-a20f-24300fab6e16', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 83, 83, 'እነዚህ ሕዝቦች አብያተክርስቲያናትን ይበረብራሉ ከወርቅና ከብር የተሠራ ንብረትንም ይወስዳሉ በናስም የታነፁትንም አብያተክርስቲያን ያፈርሳሉ መሠረቶቻቸውንም ይነቅላሉ እኔን የሚያምኑትንም ምእመናን አፋቸውን ጆሮቻቸውንም እጆቻቸውንና እግሮቻቸውን ይቆርጣሉ በዚህም የረከሰ ተግባር የብዙሐንን ነፍሳት ለማጥፍት የተሠለፉ ይሆናሉ ምሕረትና ርሕራሄ በነሱ ዘንድ ፈፅሞ የለም በመዓታቸውም አገሮቻውን ያጠፍሉ።'),
  ('3b2aec1b-6fcf-5ca9-a576-cfcfb67b407c', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 84, 84, 'የአንበሳ ዶቦልን አነሳለሁ ነገሥታትንም ሁሉ ይሰዳቸዋል ይቀጠቅጣቸዋል እነሱን እንዲቃወም አደርገዋለሁ ሥልጣንም እሠጠዋለሁ የአንበሳውን ዶቦል አነዚሥ ከእንቅልፍ እንደመነሳት ያለ ነው በዚሁም አኳያ ከመንግሥቱ ከወደምዕራብ አቅጣጫ ያለውን ቦታ እንዳለ ለመውረስ ይችላል።'),
  ('3e0f01fa-f75e-52e0-a953-e991c8bb0b4a', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 85, 85, 'በዚህም ምክንያት በሱ ላይ ቅንአት አደረበት ጴጥሮስ ሆይ እነሆ ከዕርገቴ በኃላ በሰማይ ላይ ብዙ ሁኔታዎች ይፈጠራሉ ነገሥት ስሜን ይክዳሉ መሐይምናንም ሁሉ ይገድሉዋቸዋል የሚገደሉት መሐይምናን በስሜ የሚያምኑ ናቸው ነገሥታቱ ይህን ለማድረግ የሚነሱት ደያብሎስ ልባቸውን ስለሚያፀና ነው።'),
  ('6bdd99d6-c878-5a94-a5fb-0a2341c702ce', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 86, 86, 'ከነዚህ ነገሥት አስቀድሞ የሚነሳው «ዐ» ይባላል ይህም ንጉሥ የኔን ወንድም የሚባለውን የዕቆብን ይገድለዋል ይህም ያዕቆብ የኔ ደቀመዝሙር ነው ከሱ ቀጥሎ ‹‹ነ› የሚባለው ንጉሥ ይነሳል ይህ ንጉሥ አይሁድን ይገድላቸዋል። ከሱ ቀጥሎ ‹‹ነ› ‹‹ከነ›› ከጥሉ «ቀ» ከቀ ቀጥሎ «ከ» ከሱ ቀጥሎ «ሰ» ከሱ ቀጥሉ «አ» እንዲሁም «መ፣ አ፣ ዕ፣ ቀ፣ ቁ፣ » በቅደም ተከተል ይነግሳሉ «ቁ» በመጨረሻም የሚነገሰው ሲሆን ይህ ንጉሥ የኔን የቀናች ሀይማኖት ያስፋፋል መስቀሌንም ከተደበቀበት አውጥቶ እንዲታይ ያደርጋል።'),
  ('d7283f54-31fe-57de-a1b7-57c3f67fc010', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 87, 87, 'ስመንም በትውልደ ትውልድ ሁሉ ከምስራቅ እስከ ምዕራብ ይታወሳል ። የምድር ነገሥታትም ከሱ ይባረካሉ በዕድቅና በቅንነት ይፈርዳል ጽድቅን ይወዳል ዓመፅንም ይጠላል በዘመነ የኔ ተአምር ይታያል ተአምር በሰማይና በምድር ተአምሬ ይታያል መስቀል ለሁሉ ፍጡር ይታያል።'),
  ('60f67fc4-9561-5064-a008-e55a3ab91a57', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 88, 88, 'እኔም ከሱ ጋር እኖራለሁ ኃይልንና አቸናፊነትንም እሰጠዋለሁ መሐይምናን ይበዛሉ ጠላቶቻቸውንም ያቸንፋሉ። ከዚሁ ቀጥሎም «ከ፣ር፣እ፣ስ » የሚባሉ ነገሥታት ይነግሳሉ ከዚህ በመቀጠል ግን ከነሱ ወገን የሆነ «ሰ» የሚባል ይነግሣል እሱም ሁለቱን ነገሥታት ይገድላቸዋል ።። መሐይምናንንም ይቃወማቸዋል በዚህ ዘመን ስደትና መከራ ይሆናል።'),
  ('e4c6d66c-2f58-58d5-a740-2f0c05af9e4a', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 89, 89, 'ከሱ በመቀጠል «የወ» ይነግሳሉ ከነሱ በኃላ ደግሞ «ዋ» የሚባል ይነግሳል። እሱ የተባረከና የተመረጠ ይሆናል ሃይማኖቱም የቀና ደግ ይሆናል በሱ ዘመንም ብዙ ተአምራቶቼንና ድንቅ ሥራዎቼን አሳያለው። የማሳየውም ለሚያምኑብኝ ነው።'),
  ('284759c4-69dc-53a2-abc3-c492c7a75764', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 90, 90, 'ከዚሁ በኋላ ለመ ይነግሣል በእሱም ደግ የተባረከ በቀናች ሃይማኖት የሚሄድ በዕድቅና በቅንነት የሚፈርድ ይሆናል እኔም በሕይወቱ ሁሉ ከሱ አልለይም ከሱ በመቀጠልም «ለ» በመባል የሚጠራ ንጉሥ ይነግሣል ይህም ንጉሥ እንደበፊቱ ደግ ይሆናል።'),
  ('35fdc491-b7d2-5d9a-ae32-78c7d6a28d07', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 91, 91, 'ከሱ ቀጥሎ «ር» በመባል የሚጠራ ንጉሥ ይነግሣል ይህ ንጉሥ ከሐዲና የእሥክንድርያን ህግንና ሥርዓትን የሚያጠፋ ይሆናል ከሱ በመቀጠል «ነ፣ ሰ፣ጠ፣ ሀ» ይነግሳሉ ከሐዲዎችም ናቸው።'),
  ('04b32ef9-b5a9-52e1-ad80-8795e80036ee', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 92, 92, 'በነዚህ ዘመናት ሕዝቦች በሕዝቦች ላይ ይነሳሉ ነገሥትም በነገሥታት ላይ ይነሳሉ በሠራዊት ላይም ሠራዊት ይነሳሉ ከነሱም ዘንድ ፍቅር ትርቃለች በዚህም ጊዜ መሐይምናን በአንቃዕድዎ ይቆማሉ ወደኔም ይኸሉ እኔም ፀሉታቸውን አልሰማም ክፍዎች ናቸውና።'),
  ('ae46aa53-b8fd-5f9b-afe2-68bef1f8d5d0', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 93, 93, 'ሕዝቦችም መቃብርን እየቆፈሩ በኖህ ዘመን ሙተው የተቀበሩትን ሰዎች ዓፅምን ያወጣሉ ቆፍረው የሚያወጡትም እስከዘመናቸው ተጠብቆ የኖረውን ነው የሰዎችንም ልብሶች በያዙት ጦር ይወጋሉ በዘመናቸው የሰዎች አጥንት በምድር ላይ የተዘሩ የእሕል ዘር መስሎ በምድር ሁሉ ይበተናል።'),
  ('acf29121-e8f4-5a85-a81f-d538c2681665', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 94, 94, 'በያገሩ ያሉትም ሕዝቦች ይፈሩአቸዋል በባሕር ጠረፍ ያሉት ሁሉ እነሱን ይፈራሉ እነሱን ከመፍራት የተነሳም መርከቦች ይሠጥማሉ እነሱም መርከቦቹን በእግራቸው ይረግጡአቸዋል የሚበሉትም (ምግባቸው) የተምር ፍሬ ነው የፈለጉትን ቢሠሩ ሊከለክላቸው የሚደፍር የለም የተገነባውን ያፍርሳሉ የፈረሰውንም ያንፃሉ የምድረበዳንም መሄጃ ያበጃሉ ትምክሕታቸው ራስን በመላጨት ይገልፁታል በልብስም ይገልፁታል።'),
  ('9c2a54ec-0032-573f-a860-dc1d5a4862d0', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 95, 95, 'በዘመናቸው ኢየሩሳሌምን ይከቧታል አውራጃዎቿንና አካባቢዋንም ይወርሳሉ የሚወርዋትም ከምሥራቅ እስከ ምዕራብ ያለው ክፍል ነው እንደገና ሌላው መንግሥት ከምዕራብ እስከ ምሥራቅ ያለውን ለመያዝ ሠራዊቱን ያዘምታል ብዙ ቦታዎችን በቁጥጥሩ ያስገባል።'),
  ('0ad814d2-346f-5071-a110-cac240ead903', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 96, 96, 'ከዚህ በኋላ ወደኢየሩሳሌም ይሄዳል የፈረሰውንም ሠርቶ ግንቡን ከፍ ያደርጋል አውራጃዎቿንም ይወርሳል ጴጥሮስ ሆይ ያንጊዜ መሐይምናን ሁላቸው ይደሰታሉ መሐይምናኑ በኔ እምነት ይኖራሉ እነሆ ደማስቆንም ያቃጥሏታል መሠረቶቿንም ይነቃቅላል በነዋሪዎቿ ጥፋት ይደርሳል ።'),
  ('fb2a611a-f096-55b5-a7d7-8c606c6abbd9', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 97, 97, 'ከዚያ በኋላ ወደ ቀድሞው የመንግሥቱ አገር ይመለሳል የሚመለሰውም እየተደሰተ ነው በመንበረ መንግሥቱም ብዙ ዓመታትን ያሳልፋል እሱ ትዕዛዜን የደርጋልና እኔም ከሚያምኑ ሰዎች ጋርም ሌሎችን ይቃወማል በዚሁም ለሁለት ሱባኤ ይቆያል በእጁም ያድናቸዋል።'),
  ('2bc6d642-f6f8-57ee-a2f2-8f4b77ea8523', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 98, 98, 'ከዚያ በመቀጠል እነሆ አስቀድመን የጠቀስነውን ጥፋተኛ ሕዝብ ይዙታል እኛም በመሐይምናን ላይ ክፉ ስለሠሩ ዕጥፍ ድርብ አድርገን እንበቀላቸዋለን ከአንበሳ ደቦል ስለተፈፀመው ይህ ነገር ፍጥረታት ሁሉ ያደንቃሉ ሞት ወደኛ አይመጣም ይላሉና ።'),
  ('b2e821bd-a7d1-52aa-a99d-1f8bb0d7e3d1', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 99, 99, 'ከዚህ ጊዜ ጀምሮ የሕግ ተላላፊዎች ልጆች የጦር መሣሪያ አይሽከምም የጠፋው አገር ይቀናል እኔም የሚሞት መሐይምናን ደስ ይሰኛሉ ደስታቸውም አያልቅም ጴጥሮስ ሆኑ አስተውል ይህ ሁሉ የሚሆነው ወደዚህ ዓለም ከመምጣቴ አስቀድሞ ሰባሁለት ሱባኤና ግማሽ ሱባኤ ካለፈ በኋላ ነው ።'),
  ('a97be640-9600-57fd-aed4-9c64bdfabcea', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 100, 100, 'ጴጥሮስ ሆይ እነሆ በሌላ ዘመን የሚሆነውን ሁሉ ከገለዕኩልህ በዓለም ሁሉም መንግሥታትን ሾምኩህ እነዚህም ነገሥታት አንዱ በአራቱ አምሳያ ሆኖ አንዱ የንሥር ገዕ ይኖረዋል ሁለተኛው ደግሞ የአውሬ መልክ ይኖረዋል።'),
  ('9525491c-58fe-5319-aae7-e05abb73a9d8', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 101, 101, 'ሶስተኛው በነብር ይመሰላል ከፍተኛው በአንበሳ ይመሰላል አንበሳ ከአራዊት ሁሉ ይጠነክራል በንሥር የተመሰለው የመጀመሪያው የባቢሎን ንጉሥ ነው በአውሬ ፊት የተመሰለው ሁለተኛው የኢልድዮስ ልጆች ንጉሥ ነው በነብር የተመሰለው የዮናናውያን ንጉሥ ነው በአንበሳ የተመሰለውና አራተኛው ከሁሉ የበላይ የሆነው የሮም ንጉሥ ነው እሱም ከነገሥታት ሁሉ ይበልጣል ።'),
  ('a656b338-9f4e-57ea-aa92-297af229353f', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 102, 102, 'የባቢሎን ንጉሥ ለአምስት መቶ ዓመት ያህል ይነግሣል የኤልድዮስ ልጆች ንጉሥ በበአሉ በአሰብ አቆጣጠር መጠን ይነግሣል የዮኖናውያን ንጉሥ ደግሞ ሶስት ጊዜ አምስት ሱባዔን ይነግሣል ።'),
  ('f30819c8-8a1b-5744-a855-623bd9d84335', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 103, 103, 'የሮም ንጉሥ ግን እስከ ዘለዓለም እስከ ዳግም መምጫዩ ጊዜ ድረስ ይቆያል ከኤልድዮስ ልጆች ንጉሥ አሥራሁለት ነገሥታት ይወጣሉ ከነዚህ ነገሥታት ትክክለኛውን ፍርድ በእውነት ይፈርዳሉ ከነሱ በኋላ ሁለት ንኡሳን ነገሥታት ይነግሳሉ ዕድሜያቸው ጥቂት ነው ሁለታቸው በምድር ማሐል ይጠፋሉ ከነሱ ይልቅ የአራቱ ነገሥታት መንግሥት ትዐናለች።'),
  ('c27a2d54-f1df-509d-a624-314428c6376d', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 104, 104, 'ሦስቱ ነገሥታት ብቻቸውን ይቀራሉ ሦስቱ አንድ ነገድ ናቸውና አንደኛው በአልጋው ላይ እያለ ይገደላል ሁለተኛው ቀጥሎ ላንድ ዓመት ተመንፈቅ ይነግሳል ሶስተኛው ክፉ ይሆናል በራሱም ፍላጐት ብቻ ይመራል የሰውን ምክር አይቀበልም ራሱ ጦርነትን ይቀሰቅሳል ከሠራዊቱ ጋርም እስከ ሁለቱ ወንዞች ይደርሳል።'),
  ('9094465e-4811-59ea-a204-7c061793d1ef', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 105, 105, 'ከዚህ ጊዜ ጀምሮ ያልፋል ወደ ሶርያ ይገባል ምድረበዳውንም ይዞረዋል ብዙ ሕዝብንም ይገድላል እንደገና ተመልሶ ወደ ሶርያ ይገባል ምድረ በዳውንም ለሁለተኛ ጊዜ ይዞረዋል ባለበትም የፋርሳውያንን አገር አስሶ ያገኛል በዚህ ጊዜ በሁለቱ ተራሮች መካከል ፋርሳውያን ይገድሉታል ከዚያ በመቀጠል ቀደም ብለው ከተጠቀሱት አሥራሁለት መካከል አንድና «ሮ» የሚባል ይነግሣል።'),
  ('f73c8986-1b4a-5dea-a1b0-cb5164c60dc7', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 106, 106, 'በሱ ዘመን ሕዝብ ይከተሉታል እሱ በሚጓዝበት መንገድም ይጓዛል ህጉንና ሥርዓቱንም ይፈፅማሉ ከሱ ቀጥሎ «ዕ» በሚል ፊደል ስሙ የሚጀምረው ንጉሥ ይነግሣል። ይህ ንጉሥ ብዙ አገሮችን ይቆጣጠራል አገሮቹን የሚቆጣጠረው በእርቅ በፍቅርና በሰላም ነው በኔ የሚያምኑትን መሐይምናን ያፈቅራቸዋል እነሱ የኔን ቃል ኪዳን ይጠብቃሉ።'),
  ('fb938644-703d-5a29-a0ad-6a402ff04a7d', '523d3401-365c-5568-a170-89c3a04b0762', 'b96639fc-50d4-5591-ae48-a0713eaadef3', 107, 107, 'ከዚያ ቀጥሎ የሚነግሰው መ በሚለው ፊደል የሚጠራው ነው ይህ ንጉሥ ደርባን በመባል የምትታወቀውን አገር ይቆጣጠራል እሱ ለመዥመሪያ ጊዜ በፅድቅና በቅንነት የሚፈርድ መስሎ ይታያል ውስጡ ግን ቀማኝነትንና ውንብድናን የተሞላ ነው ከዛም ቀጥሎ «ዓ» በሚል ፊደል ስም ይነግሣል እሱም ያልዘራውን የሚያጭድ የራሱ ያልሆነውን የሚሰበስብ ነው።'),
  ('0764a3dd-4ae6-5e7b-a70b-372eb95b6b6e', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 1, 1, 'በአብ ወወልድ በመንፈስ ቅዱስ ስም አንድ አምላክ እግዚአብሔር ለቅዱስ ጴጥሮስ የገለፀለትን ተአምር አስቀድመን እንፅፋለን ።'),
  ('00db0ab2-5f6e-5dea-ad8e-7534dae1e7cb', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 2, 2, 'ይህ ጴጥሮስ የመንግሥተ ሰማያትን ሥልጣን የተረከበ ከሊቀ ካህናት ክርስቶስም ለመንግሥተ ሰማያት ዝግጁዎች የሆነትን ያስገባ ዘንድ ቁልፍ የተረከበ የሐዋርያት መጋቢ ነው።'),
  ('17a91429-9b9c-59e7-a16c-eae8ff3e56e3', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 3, 3, 'በድጋሚም መንግሥተ ሰማያት እንዳይገባ ለሚገባው (ከመንግሥተ ሰማያት እንዲርቅ ለሚገባው) የመከልከል ሥልጣን ተሠጠው ጌታችን ኢየሱስ ክርስቶስ ከመታን ተነስቶ በመለኮቱ የመንግሥተ ሰማያትን ምሥጢር አስተምሮናል።'),
  ('0eaa474d-0dac-5ab6-aa8d-ca057aedc922', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 4, 4, 'በኛ ላይም መንፈስ ቅዱስን እፍ አለብን ይህ መንፈስ ቅዱስ ከአብ የወጣ ነው እኛም እሱን ተቀበልን እኛም በየደረጃው ይህንን (መንፈስ ቅዱስን) በቅድምያ ለሊቃነ ጳጳሳት እንድናስተላልፍ ሥልጣን ተሠጠን እነሱም ለካህናትና ለዲያቆናት እንዲያስተላልፉ ሥልጣን ተሠጣቸው የጌታችን ዕርገት በደረሰ ጊዜ ወደደብረዘይት ወጣን ተአምራትንም ሁሉ ለማየት ቻልን።'),
  ('4208abf4-5d86-5abb-ae1e-8cccbcfc7f4a', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 5, 5, 'ጌታችን በመለኮቱ ዓለምን እንዴት እንደፈጠረ (በቃሉና በኪነጥበቡ)። በዓለም ያሉትንም ፍጡራን ነፍሳቸው በመዳፉ እንደሆነች አሳየን። ስለዳግም ምፅአቱ ምሥጢርም አሳየን ሐጢአተኞች ከፃድቃን እንዴት እንደሚለዩ (በመንግሥተ ሰማያት) አሳየን ሐጢአተኞች ወደኩነኔ ቦታ እንዴት እንደሚጣሉም አሳየን።'),
  ('a0407b21-2cd6-5780-ac67-6b23e3096ccb', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 6, 6, 'ጌታችን ኢየሱስክርስቶስ ይህንን ሁሉ አስተማረን። እሳየን። አእምሮአችን ከፈተልን። ልቡናችን እስኪሞላ ድረስ። እንዲህም አለን እኔ ከገለፅኩላችሁ ሁሉ የሚዘነጋችሁ ካለ ካያችሁትም ተአምራትና መንክራትና ከሰማችሁትም ሁሉ የምትዘነጉት ካለ እኔ ካረግሁ በኋላ አባቴ ወደናንተ የሚልከው መንፈስ ቅዱስ ወደናንተ ይመጣል።'),
  ('1a93310d-b97e-5e22-af9f-d564a8a38de6', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 7, 7, 'ይህ መንፈስ ቅዱስ የተረሳውን ሁሉ ያስታውሳቹኋል ፈቃዴንም ትጠብቁ ዘንድና ፈቃዴን ታደርጉ ዘንድ ያጠናቹኋል።'),
  ('a2d80eb5-d8bd-5e26-aeb0-b9edeed8480c', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 8, 8, 'ልጄ ቀሌሚንጦስ ሆይ ዛሬ አንተ እኔን እንደጠየቅኸኝ እኔም በጊዜው ለአምላኪየና ለመድሐኒቴ ጠየቅሁት እንዲህም አልኩት የቤተክርስቲያንን መሪዎች ሥርዓትን የሚጠብቁበት እንዴት ልዘዛቸው በማለት ጠየቅሁት እሱም መለሰና እንዲህ አለኝ ጥንቃቄ ማድረግ አለብህ ምሥጢራትን ሁሉ አስተዋይ አእምሮ ለሌላቸው አትግለጥ ለነሱ ከነገርካቸው ቃሌን መዘባበቻ ያደርጉታል ስለዚህ ለማን ምሥጢራትን መግለጥ እንዳለብህ እወቅ ተረዳ።'),
  ('8ac053ec-ecbf-5ab3-a48e-1de2d1bd4a16', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 9, 9, 'ይህንን ታላቅ ምሥጢር ለጳጳሳትና ለኤጲስ ቆጶሳት ካልሆነ በቀር አእምሮ ለሌላቸው አትንገር ጳጳሳቱ በሕዝብ ተመርጠው የቀረቡ ናቸውና ቃላቸው በመለኮት ጨው የተጣፈጠ ነው ኃጢአተኛውን ከወደቀበት የሐጢአት ዓዘቅት ወደፅድቅ በንሥሐ ጐትተው ያወጡታል።'),
  ('d6649453-8ea3-5a99-a49b-949e13a9f330', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 10, 10, 'ትእዛዜን ለማይጠብቁና ለማይቀበሉ ይህ ምሥጢር ተገልጦ አይነገር ይህ ምሥጢር ከአፌ የወጣ ነውና እነዚያ ትእዛዜን የማይቀበሉ ሁሉ ወንጀለኞች ናቸው። ሁሉም የምድር ሐጢአተኞች የተረገሙ ናቸው። ስለዚህ ከትእዛዜ የራቁ ይሆናሉ። ይህ ምሥጢር እጅግ የተጠበቀ ይሆናል።'),
  ('30c651a2-c243-5438-a434-d71d3221b819', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 11, 11, 'ይህ የምነግርህ ምሥጢር ክቡርና የተደበቀ ነው። ንፅሕና የሌለው ስው አያየውም ዘማዊ የረከሰ የሚያስጠነቁል ጠንቋዮችን የሚከተል በኮከብና በሌላም የሚያሟርትም አያየውም።'),
  ('9606810a-f4c4-5905-af2a-028531f28296', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 12, 12, 'በወፍ የሚያሟርት በእሳት በባሕር በወንዝ። በእግር እንቅፋት። በአውሬ ጩኸት። በግራ ወይም በቀኝ በባሕሮችም ቢሆን በምድረ በዳም ቢሆን። ሥጋውን በእንስሳና በአራዊት። በምድረበዳ እንዲሁም በተለያየ መንገድ እኔ የምጠላውን ሁሉ የሚፈፅም አምልኮተ ባእድንም የሚፈፅም አይኑር።'),
  ('605692e1-b38d-5428-aea8-91a0363f0f7f', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 13, 13, 'ለሱ ያልተሠጠውን ልብስ ለመልበስ የሚጓጓ። በሌብነት የሚኖር ዓመፀኛ ቀማኛ ትግሉን በመጥፎ አካሄድ ያደረገ የሌላውን ሐብት የሚመኝ ቀረፅ የሚቀበል ክፋትን መሥራትና መናገር የሚያዘወትር መጥፎ ነገርን ለመሥራት የሚራቀቁትን ሰዎች የሚከተል ገንዘቡን በአራጣ የሚያበድር ከሰው ይህን አስፈፅምልሀለሁ እያለ ጉቦን የሚቀበል እነዚህን የመሳሰሉት ሁሉ እፀየፋቸዋለሁ።'),
  ('75512785-efd5-5c9d-a87c-1e5d746f8c5f', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 14, 14, 'ይህን የረከሰ ተግባር የሚፈፅሙ በዚሁም ሕይወታቸው የሚመሩ ቃሌን አይሰሙም ይህቺንም መፅሐፍ የነሱን የመዘባበቻና መጠቃቀሻ ሊያደርጉዋት አይገባም ይህን ከፈፀሙ ወድያው የቁጣየን በትር እንዳላጎርፍባቸው ይጠንቀቁ ላጠፋቸውም እችላለሁ ቃሌን ችላ በሚሉ ሰዎች ላይ ቁጣዬ ይበዛል።'),
  ('9e7e3ea0-6d63-5c73-aa14-642b5c7d6315', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 15, 15, 'ከነዚህ በመጥፎ ሥራ ተሠልፈው ከሚኖሩ መካከል ይህንን የመሰሉ የተግሳፅን ቃላት ብሰማ ኑሮ ቀድሞውኑ ለጥፋት ሥጋየንና ነፍሴን በክፉ ነገር ባላበላሸሁ ነበር። የሚል ካለግን።'),
  ('c0e68250-984d-58e1-a31b-42e972fb8e81', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 16, 16, 'ነፍሱም ስለደነገጠች በልቅሶና በሐዘን ከተጸጸተ ሐጢአቱን እሠርዝለታለሁ። እኔ እግዚአብሔር ይቅርባይና ፈጣሪ ሁሉን ለመመገብ የምችል ነኝ ሁሉንም የምጠብቅና ሁሉንም የምመግብ እኔ ብቻ ነኝ በውስጥም ይሁን በውጭ ሥጋ ለባሽ የሆነውን ሁሉ በየጥቂቱ ሰውን እገነባዋለሁ። በፍጥነትም አሳድገዋለሁ፡ በረቀቀ አኳኋን አለመልመዋለሁ በደከመ አካልም አነሳዋለሁ በሰፊው እሰበስበዋለሁ እንደትብያ እበትናለሁ በአስደናቂ ሁኔታም እዘጋለሁ።'),
  ('8066162f-cc64-51ac-ab49-a52a5dbbe4e1', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 17, 17, 'መብረቅን አሮጠዋለሁ በቅፅበትም እመልሰዋለሁ የባሕር ውስጥ ዋሻውንም አበራዋለሁ ጥልቅ ውሆችንም እገልፃለሁ። ከበታቹን አነዋውጠዋለሁ መሠረቱን እንዲንቀጠቀጥ አደርጋለሁ። አሣውንም ካለበት እንዲጨነቅ አደርጋለሁ።'),
  ('8f493473-0976-5067-a118-68bce278bd25', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 18, 18, 'ትዕቢተኛውን አሥረዋለሁ በሠንሰለቴ አሥረዋለሁ ንሥሐ ለገባ ከታሠረበት እፈታዋለሁ የበታች ሁኖ የኖረውን አነሳዋለሁ ትዕቢተኛውን አዋርደዋለሁ ንሥሐ ለሚገባም ሥርየትን እሰጠዋለሁ አንተም ጳጳሳትና ሊቃነጳጳሳት ይህንን ሊቀበሉ የሚችሉትን አስተዋዮች እየመረመሩ እንዲገልፁላቸው ንገራቸው።'),
  ('f9147756-e14b-56c7-a0a2-abc1587028fc', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 19, 19, 'ይህን በፍጥነት ካላስተላለፍክ ባንተ ላይና አንተን በመሰሉ ሁሉ መዓት ሊወርድ ይችላል ቃሌንና ነገሬን መሳለቂያ የሚያደርጉ ሰዎች እንዳይኖሩ አስተውል። ለክፉዎች መልካም ሥራን መሥራት ይመራቸዋል የሐጢአትን ሥራ መሥራት ደግሞ ይጥማቸዋል።'),
  ('fc2b8f20-c17e-5693-a2c3-c215e5e4000c', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 20, 20, 'ለሚወዱኝ ግን ቃሌ ይጥማቸዋል ከማርና ከሱኳር በበለጠም ይጣፍጣቸዋል ከብዙ እልፍ ወርቅና ብርም ይመረጣል በሚወዱኝ ዘንድ ቃሌ የከበረ ነው ትእዛዜን በሚያከብሩም ዘንድ የከበረ ነው። እኔም ዘወትር ከነሱ አልለይም የኔም ህግ በልባቸው አሥርፀው ከነሱ ጋር ይዘውት ይገኛሉ እኔም ልቡናቸው በርቶ እኔን በቀና መንፈስ እንዲከተሉኝ ልቡናቸውን አበራለሁ በሕሊናቸው ቃሌን አሰማቸዋለሁ።'),
  ('07f00b81-0548-5469-adda-9d5e5ead31c7', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 21, 21, 'ያባቴ መንፈስም በተናገሩት ሁሉ ይናገርላቸዋል በወንጌል 138 መንፈስ ወደፈቀደው ይነፍሳል ድምፅን አይሰማም የት እንደሚገባና እንደሚወጣም አይታወቅም የሚል ተፅፏል እንደዚሁ ሁሉ ቃሌን ለሚያከብር መንፈስቅዱስ ይጠብቀዋል። እኔን ለሚጠሉና ቃሌንም ለሚጠሉ እንደዚሁም ትእዛዜን ለማይፈፅሙ የአባቴ መንፈስ አይጠጋቸውም ከነሱ ይርቃል እንጂ።'),
  ('e253e271-ee63-5a14-abb3-f821f6a4da81', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 22, 22, 'የዲያብሎስም መንፈስ ያድርባቸዋል እሱም የረከሰ መንፈስ ሁኖ መጥፎ ሥራን ያሠራቸዋል ይህም አስቀድሜ እንደነገርኩህ የዘወትር ሥራቸው ይሆናል። መንፈስቅዱስ ከዲያብሎስ ሥራ ጋር አይገናኝምና በመካከላቸውም ስምምነት የለም የዲየብሉስን ሥራ የሚሠሩ ከዲያብሎስ ጋር ይኵነናሉ የመንፈስ ቅዱስን ሥራ የሚሠሩ ደግሞ ከሞት በኋላ በዓፀደ ነፍስ ሲደሰቱ ይኖራሉ።'),
  ('c999497e-eb74-5317-ac9c-a1364feae0ec', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 23, 23, 'አንተ ግን የቤቱን ሹማምንት ሕጌን እንዲጠብቁ ሥርዓቴን እንዲያከብሩ ንገራቸው።'),
  ('85a26da3-e46b-5220-a01d-79f0c321a3f5', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 24, 24, 'እነሱ ለተከታዮቼ ምዕመናን መልካሙን አርአያ ማስተላለፍ አለባቸው። እነሱን በመመልከት ምዕመናን የፅድቅን ሥራ ሊሠሩ ይችላሉ። ከዝሙትም ይጠበቃሉ በእጃቸው መጥፎውን እንዳይነኩ በዓይናቸው መጥፋትን እንዳያዩ መጥፎም ነገር እንዳይሰሙም ይሆናሉ።'),
  ('7d04a8f5-9b70-56c6-ae0f-6a1c9c2c440d', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 25, 25, 'ከዚሁም ለመራቅ ራሳቸውን ንፁሕ ያድርጉ። ምንም ይሁን ምን አስነዋሪ ምግባርን እንዳይፈፅሙ ይሁኑ ከኃጢአት ሥራ ሁሉ ይራቁ ይህ ከሆነ ከእግዚአብሔር አምላካቸሙ ዘንድ ይገባሉ።'),
  ('ea7f632e-c1b6-506b-a227-4e0703a38cc3', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 26, 26, 'የእግዚአብሐር አምላካቸውን ትእዛዝ ባልቻሉም ነበር። ይህንን ባያደርጉ የእሥራኤል ካህናት እንኳ ከመጥፎ ተግባር ለመጠበቅ አልቻሉም የእግዚአብጠርን ትእዛዝ አፍርሰው ለጣዖት የሰገዱበት ጊዜ አለ ከዚህም የተነሳ ከነቢያቶቻቸው አንዱ ስለነሱ ጥፋት አሕዛብ የናንተን መጥፎነት አይተው በእግዚአብሔር ስም ላይ ይሳደባሉ ብሏቸዋል።'),
  ('33c4f338-6166-5428-a783-db42a2a370d5', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 27, 27, 'ትእዛዜን ይጠብቁ ዘንድ ሕጌንና ሥርዓቴንም ይጠብቁ ዘንድ እዘዛቸው እናንተ ተማሪዎቼ ትእዛዜን እንደጠበቃችሁ እንዲሁ ይሆናል። ማንንም ነገር ሳትመረምርና ሳትጠነቀቅ በችኮላ አንድን ነገር አትሥራ በችኮላ አንድን ነገር ለመሥራት ከሞከርክ ተመልሶ ነቀፋንና ውርደትን ያስከትልብሃል።'),
  ('e8616f08-85c6-5d93-a24c-36c9fc461111', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 28, 28, 'ከድንግል ሰውና ከድንግል ሴት የተመረጠ ሰው ይወለዳል ከአመንዝራ ሴትና ወንድ ግን መልካም ሰው አይወለድም እንደአሮንና እንደሙሴም ትእዛዜን የሚጠብቅ አይወለድም።'),
  ('12660a5b-ab0a-5aee-ac2f-43fe2571d379', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 29, 29, '(ሀ) እንዲሁ ንፁሐን ካህናቶቼ ነውር የሌላቸው ይሁኑ ስባሪ ጉድለት ቀልሞይሁን ። ግራ አካላታቸው የተስተካከለ ይሁን ጆሮአቸው በትክክል መስማት የሚችሉ ሁነው ለክህነት ይመረጡ በማንኛውም ነገር የሚነቀፉም አይሁኑ።'),
  ('eabd9970-f244-5a17-ad8b-657eeff83986', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 30, 30, '(ለ) ያንተን ቃል አልቀበልም የሚል ካለም ከቤተ ክርስቲያን እንዲከለከልና እንዲርቅ አድርግ ለሱም የመንግሥተሰማያትን በር አትክፈትለት አንተ የመንግሥተ ሰማያት ቁልፍ ነህና በሌላ አባባል የመንግሥተ ሰማያት ቁልፍ ባንተ እጅ ነው እኔ አለት ነኝ አንተም የኃይማኖት አለት መሆንህን አትዘንጋ ሁሉም በእጅህ ነውና።'),
  ('477a077e-a197-5ec1-afc9-70e16e1d424a', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 31, 31, 'ኬፋ ማለት በእብራውያን ቋንቋ አለት ማለት ነው ቤተክርስቲያንን ባንተ ላይ ሠርቻታለሁ የተጠሉና የረከሱ የሲኦል በሮች አይበረቱባትም እኔ ከሰማያዊው አባቴ የተቀበልኩትን የጸጋየን መንፈስ እነሆ ላንተ ሠጠሁህ።'),
  ('c449e0b4-e2b6-570d-a22d-61b351df8f16', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 32, 32, 'አንተም ካንተ በኋላ ለሚነሱ ንብረትን በመቀማት ሰውን ለሰቆቃ የማይዳርጉትን የዚህን ሐላፊ ዓለም ድሎትንና ከንቱነትን ተረድተው ብልሕነታቸው ለሥጋዊ ጥበብ ብቻ ያላስገዙትና በቃላቸው የሚፀኑት ይህንን ታስተላፋለህ።'),
  ('294de163-0d24-57e4-aa81-8ced27fa966c', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 33, 33, 'ካንተ በኋላ የሚተካው የበደለኞች ጥፋት ይቅር የሚል ከጥፋታቸው በሰላማዊ አነጋገር የሚመልሳቸው ንሥሐቸውንም የሚቀበል ያለአድልዎ ፍትሕን የሚቀበል ፊቱንም የማይቋጥር ጉቦን የማይቀበል ዋጋ ሳይከፍል የሰውን ንብረት ለመውሰድ የማይመኝ ትክክለኛ ሰው ይሁን።'),
  ('e2111b4f-68a8-5810-afbe-eca12670c0fa', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 34, 34, 'ካንተ በኋላ የቤተክርስቲያን ሊቀካህናት ሊሆን የሚገባው 14 በማንኛውም ምግባረሠናይ ተፈትኖ የፀና። በቀንም ሆነ በሌሊት የእግዚአብሔርን ትእዛዝ የሚፈፅም ነዳያንንና እሥረኞችን በመንፈሳዊም ሆነ በሥጋዊ መግቦትን የማይረሳ በዓጸደ ቤተክርስቱያን የወደቁትን የሚያስታውስ መሆን አለበት።'),
  ('5af2b6a7-ac52-5dff-a584-e35325c669a2', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 35, 35, '(ሀ) የቤተክርስቲያንን ንብረት አይበትነ ለቤተሰቦቻቸውንም አይሥጡ እንዲሁም ለሥጋ ዘመዶቻቸው አያካፍሉ የሰውን ፊት በማየት አያዳሉ ድሐ ሀብታም ትልቅ። ትንሽ በማለት ምዕመናን በሚመግቡበት ጊዜ አይበሉ።'),
  ('925b41e8-27ef-5ef7-ad6c-0ddae50849e4', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 36, 36, '(ለ) ከዚህ ቃል ወጥቶ የተገኘ ሁሉ የተከለከለ ነው ከቤተክርስቲያንም ይውጣ ባንተ ላይና በኔ ላይም ቦታ አይኖረውም ዋዛ ፈዛዛ ተናጋሪዎች የሚናገሩት ቃል በኔም ሆነ ባንተ ተቀባይነት አይኖረውም።'),
  ('855abb2a-488c-50fd-a262-68f3038cadf2', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 37, 37, 'ጴጥሮስ እንዲህ አለ ጌታዬ ሆይ ያዘዝከኝን ሁሉ እፈጽም ዘንድ ፈቃድህ ይሁን እኔ በማሕበር ገንዘብ ሁሉ በቤተክርስቲያን የተለያዩ ንዋያተ ቅድሳት በአገልግሎት ላይ በሚውሉ ንዋያት ሁሉ በጠረጴዛም ይሁን በመሳሰለው እደክማለሁ። በዲያቆናት። በመዘምራን በአንባቢያን በሕዝባውያን። በሴቶቹም በወንዶቹም አመራሬን አከናውናለሁ። ለሕፃናትና ለልጆችም እጠነቀቃለሁ።'),
  ('094d2091-90ae-5f03-ad18-dfc074b402d0', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 38, 38, 'አንተ በሰማያዊቷ ኢየሩሳሌም ቅድስት ለደጋግና በየደረጃው ሥጦታ እንደምትሠጥ ለክፉዎች ደግሞ መለየትን ትሠጣለህ።'),
  ('57962bb9-8f00-5f81-a296-2411c1c7b0a9', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 39, 39, 'የሚለዩትም የሓናኒያን መንገድ የተከተሉ ናቸው ሐናንያ ወይኑን ከፍሉ እየሽጠ ያጠራቀመውን ገንዘብ ግማሹን አመጣ በገንዘብም የመንፈስ ቅዱስን በረከትና ፀጋ ፈላጊ አበዳሪና የእግዚአብሔርን ፀጋ በገንዘብ ለመግዛት የሚችል መሰለው በዚሁም ከፊቴ ቆመ ቤተክርስቲያን ጠባቂነትንም ተመኘ በዚህም ነፍሱን አጠፋ ወደሲኦልም ወረደ ጎልማሶችም ቀበሩት'),
  ('b9de0678-f6e0-5198-a423-4943f7f71314', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 40, 40, 'እኔም በሱ ላይ ተቆጣሁ የቤተክርስቲያን ጠባቂ የሆነው መልአክ የሱን ሁናቴ ሲመለከት ሓናንያ ነፍሱን እንዳጠፋ ባየጊዜ የሱን ነፍስ አጠፋ ።'),
  ('a0004e74-7435-5413-aefd-aaf61ceacfad', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 41, 41, 'በመቀጠል የሐናንያ ሚስት ወደኔ መጣች ባልዋ ሓናንያም እንደሞተ ሰማች ከእግሬ ሥር ወድቃም ለመነችኝ እኔም ለምን አንቺና ባልሽ መንፈስ ቅዱስን አስቆጣችሁት አንቺም ከሱ ጋር ጠፍተሻል አልኳት ነፍሷንም መልአከ እግዚአብሔር እንድትጠፋ አደረገ ይህን ያደረገውም ከእግዚአብሔር ስለታዘዘ ነው።'),
  ('57b23e0b-8c79-5fa1-a908-29624eedc262', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 42, 42, 'ልጄ ቀሌሚንጦስ ሆይ ቤተክርስቲያንን በሚደፍሩ ሰዎች ላይ ቸልተኝነትን አታሳይ ገሥፃቸው የምትበቀላቸውም አንተ አይደለህም ባንተ አማካይነት የእግዚአብሔር መልአክ ለቤተክርስቲያን ይበቀልላታል።'),
  ('1ff21ee1-7059-5f07-a9f4-74b70f472a8a', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 43, 43, 'እግዚአብሔር የፈቀደውን ይፈፅማል አንተ ግን ቀድመህ ራስህን ገሥፅ ምግባርህንም አስተካክል ።'),
  ('135597ff-f384-57b9-a4bc-59e1f5fc15bb', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 44, 44, 'ከዚህም አያይዘህ ያለፍርሐት ገሥፅ ስለእውነት እስከደምጠብታ ድረስ ተጣላ የደም ባለቤትስ ከእግዚአብሔር የተላከው ወልድ ነው እሱ በዕፀመስቀሉ ለባረካትና በደሙ ለዋጃት ቤተክርስቲያን ይቆማል።'),
  ('09a95953-d65e-5fb5-a7ea-767396c5076b', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 45, 45, 'ቀድሞውም ለሙሴ የድንኳንን ሥራ ይሠራ ዘንድ አሳየው ድንኳንዋ ሰማያዊት ናት እግዚአብሔር ስለዚችው ያለውን ለሙሴ ገልፆ አጠናቀቀ ድንኳንዋን ሌዋውያን እንዴት ሊያገለግሉዋት እንደሚችሉም ሙሴ ህግ እንዲሠራላቸው ከእግዚአብሔር መመሪያ ተሠጠው።'),
  ('fdf5cef9-150e-56ed-af00-70d29472ca25', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 46, 46, 'ሌዋውያን እንደሌሎቹ የእስራኤል ልጆች ባጠፉ ጊዜና ለጣዖትም በሰገዱ ጊዜ እግዚአብሔር ባንድ ጊዜ ሊያጠፋቸው ወደደ በዚህ ጊዜ ሙሴ ወደነሱ ወረደና ሁላችሁም ሠይፋችሁን አንሱና ባለሠይፍ የሆነው ሁሉ አጠገቡ ያለውን በያዘው ሠይፍ ይምታው ብሎ አዘዘ።'),
  ('3e426e4c-36c7-5637-a264-8481b849f343', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 47, 47, 'ስለዚህ የድንኳን ሥርዓት ስላረከሱ እንደዚህ አዘዛቸው እቺን ድንኳን ራሱ እግዚአብሔር ከሰዎች ጋር እንዲገናኝባት አድርጎ ይሠራት ዘንድ አስቀድሞ ለሙሴ አዘዘው በሷ ላይም ተጨማሪ አሥር ትእዛዛት ሰጠው የመጀመሪያዋ ትእዛዝ እግዚአብሔር አምላክህን በህሊናህ ሁሉ በኃይልህ ሁሉና በልቦናህ ሁሉ ውደደው ትላለች።'),
  ('c391ef79-bb13-5b80-a401-e530dde01cfb', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 48, 48, 'ባልንጀራህን እንደራስህ ውደድ የእግዚአብሔርን ሰንበት አክብር አትግደል አትሥረቅ ከወንድ ሚስት አትሂድ በሐሰት አትመስክር በእግዚአብሔር ስምም በሐሰት አትማል አታመንዝር የራስህ ያልሆነውን የሌላ ሰው ንብረት አትመኝ ሌላ ሰው ያፈራውን ንብረት ለመውሰድ አትመኝ ሌሎችም ይህን የመሰሉ ብዙ ትእዛዛት አዘዘው።'),
  ('3bef55d3-3cca-5c0e-ad70-fb2efd892f09', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 49, 49, 'ይህን የተጻፈውን ትእዛዝ ያፈረሰ ሰው በሙሴ ህግ ይሞት ዘንድ ተወሰነበት ሲሞትም በድንጋይ ተወግሮ ነው ስለሰንበት ደግሞ የተለየ መመሪያ ነበር። በእለተሰንበት እንጨት ሲሰብር ሰው ቢገኝ ተይዞ ወደሙሴ ይወሰድ ነበር። ሙሴም ለሌሎች ይሠጠውና ሥርየትን ለማግኘት ይለምን ነበር።'),
  ('352dd0b2-5bf7-555a-aa8f-80a8edeccfd1', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 50, 50, 'እግዚአብሔር ለሙሴ እንዲህ ሲል አናገረው አስቀድሞ የሌለውን በደል የተመለከተ ሰው ለምስክርነት ይጠራ ጥፋተኛው በድንጋይ ሲደበደብም ያ ምስክር ሰው አስቀድሞ በድንጋይ መውገሩን ይጀምር ከዚያ የቆመው ሁሉ ይውገረው ።'),
  ('6af1301e-7356-5f88-a700-12217844d8e9', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 51, 51, 'ስለዚህ ተመልከት ይህን ሁሉ ያደረገው ስለድንኳኑ ክብር ብሎ ነው አንተም በቅድስተ ቅዱሳን ውስጥ የሚፈፀመውን ቅዱስ ሥራ ጠብቅ ጳውሎስም ለቆሮንጦስ ሰዎች በክርስቲያን መካከል ስህተትን የሚከተል ካለ እንዲወገድ አድርጉ አለ።'),
  ('958af013-205e-5187-a958-cb8073fc2937', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 52, 52, 'ይህንን በመልእክትህ ላይ ጠብቅ ካንተ በኋላ ለሚሾሙ የእግዚአብሔር ዓይኖች ጳጳሳትም በመልእክት አስተላልፍ ይህን ትእዛዝ በንፁሕ ልቦና እንዲጠብቁትና እንዲያስተላልፉት እግዚአብሔር በነሱ ላይና በመንጋዎቻቸው እንዳይቆጣ ያደርጉ ዘንድ አዘዛቸው።'),
  ('5d3e38af-7212-551b-ae01-2859d1b88474', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 53, 53, 'መንጋዎችን ለመጠበቅ የተሾሙትን ካህናት ያስጠነቅቁዋቸው ዘንድና ካህንነትና ሊቀካህናትነት ለሚሾሙ ይመነዋቸው ዘንድ ጥብዓትን ስጣቸው የነሱ ክህነት በሰማይና በምድር ኃላፊነትን ያስከትላልና።'),
  ('79489fb5-b1bc-5653-a73d-79e38e9bf0e8', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 54, 54, 'የጌታ ቃል ለአፍ የሚጣፍጥ የሚጥም ነው። ይህን ጥዑም ቃል መላእክት ሰምተው ሥልጣነ በእጁ የሆነውንና በነገሥታትና በመኳንንት የበላይ የሆነውን የሐይል ሁሉም ኃይል የሆነውን አምላክ ሊያዩት ይወዳሉ በሱ ዘንድ አድልዎ የለም ፀሐይም በሰማይ ጠፈር ያበራ ዘንድ ያደረገ እሱ ነው።'),
  ('fb782eed-5ea1-5086-a745-7455590a160b', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 55, 55, 'ጌታችን ዓለምን አበራው ፀሐይንም ወደመግቢያው ያስገባዋል የሱንም ብርሃን ለዓለም ያደርሳል ጌታችን ባረገ ጊዜ (ወደሰማያት) ወደሱ ሰበሰበንና የቅድስት ቤተክርስቲያንን ሥዕል እንድንሠራ አስተማረን አስተዋይነትን ሠጠን ብልሕነትንም አሳደረብን ይህንን ያደረገበት ምክንያት በኋላችን ለሚነሱ የኛ ተከታዮች በቅድስት ደብተራ ሥርዓትን ይጠብቁ ዘንድ እናስተምራቸው ዘንድ ነው።'),
  ('0544ac53-cd9e-5ddf-a7fe-af91adb5b299', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 56, 56, 'ጌታችን እኔ ከናንተ ጋር እንደነበርኩ ታውቃላችሁ እናንተም ከኔጋር እንደነበራችሁ ታውቃላችሁ እኔ ካባቴ ጋር እንደነበርኩና እሱም እንደላከኝ እኔም እናንተን እልካችሁአለሁ የምልካችሁም ይህ እኔ የምመሰገንባትን ቤተክርስቲያን ህግንና ሥርዓትን ትጠብቁ ዘንድ ነው አለን።'),
  ('62ccceff-38d7-52a7-a956-a895e584a31d', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 57, 57, 'እኔ ስለቤተክርስቲያን ተሰቀልኩ ምትኩም በጥንቃቄ የቤተክርስቲያንን ሥርዓት ጠብቁ እኔ አባቴ ጋርና ከመንፈስቅዱስ ጋር በሷ እመስገን ዘንድ ዓለም ሁሉ በስላሴ ነው የተፈጠረውና ዓለምና በዓለም ውስጥ ያለው ሁሉ በሥላሴ ተፈጥረዋል።'),
  ('ac57ec6b-e034-5ac2-a513-4aec15fa27c3', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 58, 58, 'በዛን ጊዜ አሕዛብን በስመአብ ወወልድ ወመንፈስ ቅዱስ ስም በሉ ባንድ ስምም ሦስት አካላት እንዳሉ ያምኑ ዘንድ አስተምሩዋቸው እኔም ከምድር ወደሰማይ ከፍከፍ ባልኩ ጊዜና ወዳባቴ ባረግኩ ጊዜ እንደሙት ልጆች የተጣላችሁ እንዳትሆነ መንፈስ ቅዱስን እልክላችሁአለሁ።'),
  ('836032e1-39e2-54b1-a1fe-cfb497aba8a5', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 59, 59, 'ከናንተ መካከል ሆኜ ያስተማርኩዋችሁን ሁሉ መንፈስቅዱስ እንድታስታውሱ ያደርጋቹኋል አባቴም ይወዳቹኋል እኔ እንደቀድመው ስለናንተ አብን አልለምነውም ነገርግን አባቴ ይወዳቹኋል የምትለምኑትንም ይሠጣችኋል እኔም ከናንተ አልርቅም ከቤተክርስቲያንም አልርቅም ደግሞም እስከዓለም መጨረሻ ድረስ ከናንተ ጋር እሆናለሁ አልለያችሁም።'),
  ('d75a0398-25db-590d-a259-77faa91fef61', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 60, 60, 'አስተዋዮች እንድትሆኑና እንድትፀኑ አደርጋችሁአለሁ የኔም መልአክ ለቤተክርስቲያን እንዲቆም አደርግላቸው ዘንድ አንተም ለቤቴ ሹማምንት ንሥሐን ሳይፈልጉ ለተንኮል ወደነሱ ከሚመጡ ክፉዎች አሕዛብ እንዲጠነቀቁ ንገራቸው ድጋሚም ስለእኩያን አሕዛብ ብቻ አይደለም በግ ለምድ ለብሰው ከናንተ በኋላ ከሚመጡ የሐሰት ነቢያትም እንዲጠበቁ ንገራቸው።'),
  ('817ab234-95f3-53f1-a17b-4296dd7b63a6', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 61, 61, 'ውስጣቸው ግን የሚነጥቁ ተኩላዎች ናቸው። ቃለ እግዚአብሔርን ይንቃሉ በተሳሳተ መንገድና ለነሱ እንደሚያመች በማድረግም ይተረጉሙታል በቃለ እግዚአብሔርም ላይ ይዋሻሉ። ሠይጣን አስቶአቸዋልና በማስመሰልም ወደጥፋት ይወስዳቸዋል።'),
  ('7493a77f-d1c0-54b9-a95c-d3d2838ea9f5', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 62, 62, 'እናንተ ግን ሰላም አትበሉዋቸው በነሱ መንገድም አትጓዙ እነሱ ዲያብሎስን ይመስሉታልና የጥንቆላንም ሥራ ይሠራሉና ውስጣቸው በክህደት የተሞላ ነው።'),
  ('1e7f8040-e5c7-5972-a8ad-4c5f8c28e349', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 63, 63, 'ከነሱ ራቁ የነሱን ተንኮል መንገድ አታውቁምና እነሱና እናንተ አንድ አይደላችሁም እነሱ የጨለማልጆች ናቸው እናንተ ደግሞ የብርሃን ልጆች ናችሁ እናንተ በደሜ ገንዘብ ያደረግሁዋት ቤተክርስቲያን ልጆች ናችሁ ሁሉን የሚገዛ እግዚአብሔር ይላል።'),
  ('579eeaf4-7ce1-545d-aef4-e674482321b0', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 64, 64, 'መብራታቸውን አጠፋለሁ እነሱ የህግ ክፍያዎች ናቸውና በዚሁ ክፉሥራ ሴቶችና ወንዶች ይጠመዳሉ በዚሁ ክፋት ተጠምደው ጠንቋዮች ይሆናሉ እነሱ ወደቤተክርስቲያን አይግቡ እሷ የሰማይና የምድርጌታ ማደርያ ናትና። ሰማያዊው ንጉሥ በአራቱ ጠባይአት ሰውን ይመግባል ሁለቱ የሚዳሰሱ ሁለቱ የማይዳሰሱ ሦስቱ የሚታዩ አንዱ የማይታ ጠባዮች በሰው አሉ።'),
  ('8da0cdb9-b429-5c50-a583-bcabc4a6b928', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 65, 65, 'በዚሁ ጠባይእ ሁሉን ይመግባል ነፍስ ያለው ሁሉና ሥጋ ያለው ሁሉ በሱ ይመገባል ውሃን በደመና ይቋጥረዋል ጉምን እንደአመድ ይበትነዋል በረድን በተበታተነ ቅርዕ ያወርደዋል አሣነባሪውን አፉን ይዘጋዋል ቀማኛውን ያሥረዋል በትሕትና ሕይወቱን የሚመራውን ይፈታዋል ነዳዩን ከፍ ያደርገዋል ምስኪኑንም ከመሬት ያነሳዋል።'),
  ('2c9fafdd-b935-5fcf-a037-9dc093c30ee4', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 66, 66, 'ወላድን ደስ ያሰኛታል ለምድርም ክረምትን ያዘጋጃል ቤተክርስቲያንን አስቀድሞ በነቢያት ከዚያ ቀጥሎ በሐዋርያት መሠረታት ከሐዋርያት ቀጥሎ ደግሞ ለሊቃውንትና ለጳጳሳት በአደራነት አስረከባት።'),
  ('9d0e8f67-050b-55f3-a0df-cbcf399de114', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 67, 67, 'በመቀጠል ለመዘምራን ለካህናትና ለጻድቃን አስረከባት እንዲሁም ለአንባብያን ለወንዶችም ለሴቶችም አስረከባት የቤተክርስቲያን ፍሬ እንደዘንባባ ፍሬ ነው ቤተክርስቲያን አንዲት ስትሆን ብዙ ቅርንጫፎች አሏት።'),
  ('9bcd0d18-067d-5c7f-a3a9-302f6ee22c33', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 68, 68, 'እንዲሁም እነደሮማን ቅራፊ ናት የሮማን ዛፍ ፍሬ እንዴት ሁና (ባንጂ) የሮማን ፍሬ ብዙ ዘሮች አሉ ብዙ አካሎችም አሉ ነገርግን ባንዲት ፍሬ ተጠቃለው ይታያሉ በፍሬዋ ውስጥ እንደጠወለገ ኖት ያለ ፍሬ አይታይም የሮማን ፍሬ ጌታችን እንደረገማት ዕፀበለስም ሆና አትታይም።'),
  ('fd1288b2-4953-5ecd-a0fe-9c74f501c9e2', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 69, 69, 'ከነዚህ መሰሎች ሰዎች ተጠበቁ ሃይማኖታችሁ እንዳይጣመም 149 ተጠንቀቁ ሃማኖት አለን እያሉ በኮከብ በመርፌ ወይም በጦር በእህል በድንጋይ በአውሬ ድምፅ በወፍ በዘፈን እና በሌሎችም የሚያመልኩ ሁሉ እናንተን እንዳያሳስታችሁ ተጠንቀቁ።'),
  ('f95aa39e-ba42-510e-a81e-1b25dda0e8a6', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 70, 70, 'ሰዎች (ወንዶችም ሆኑ ሴቶች) ሐዘንም ይሁን ሌላ የሚያበሳጭ ነገር ሲገጥማቸው ፊታቸውን በብረት የሚተረትሩ ጢማቸውን የሚላጩ ሴቶች ሁነው በአካላቸው ላይ ጥፋት የሚፈፅሙ በድንጋይ ወይም በእንጨት በሰውነታቸው ላይ ጉዳት የሚያደርሱ አሉ።'),
  ('8a8e8630-b7d9-587c-a62d-3ba2f2fbad82', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 71, 71, 'እንዲህ ያሉ ሰዎች ከእግዚአብሔር ጋር የሚጣሉ ይመስላሉ። የደረሰባቸውንም ፈተና በአኮ ቴት አይቀበሉትም እንዲህ ያሉ ሰዎች የወረሱትን መጥፎ ባህል እንዲተው ይነገራቸው የሚሠጣቸውን ምክር ለመቀበል ፈቃደኞች ካልሆኑ ግን ከቤተክርስቲያን ይለዩ ።'),
  ('f89b72f3-6484-574d-a0ae-ca2a27727037', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 72, 72, 'ልጆችን ዘፈን የሚያስተምር ካለ ፈረስን የሚጋልብ ካለ በመዓስብነት የሚኖር ካለ ሕልምን በመተርጎም የሚኖር ካለ ማደርያው ጨዋታ ብቻ ያደረገ ካለ እነዚህ ሁሉ ወደቤተክርስቲያን ሲመጡ ይህን ሁሉ የቀድሞልማዳቸው መተው አለባቸው የቀድሞው ልማዳቸውን ለመተው ፈቃደኞች የሆኑትን ሁሉ ተቀበሉዋቸው ፀሐይን በማምለክና የሥራይን ሥራ የሚሠራ ግን ይወገድ።'),
  ('73304e9e-6274-54c9-acf2-6391b56b8251', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 73, 73, 'ለጨረቃና ለሰማያት ኃይላት ለተራሮችና ለሌሎችም ፍጡራን የሚሰግድና ለእግዚአብሔር መስገዱንም የተወ ቢኖር እንስሳትን እያረደ ለፍጡራን ተራሮች መስዋዕት የሚያቀርብ ሁሉ ከቤተክርስቲያን ይወገድ።'),
  ('7cd65a6d-5521-5427-af81-a63c3d453d14', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 74, 74, 'የካህናትን ምክር ሰምቶ ንሥሐ ከገባ ያለፈውንም ሥሕተቱ አስታውሶ ከተፀፀተ በፈፀመው ስሕተት መጠን ቅጣቱን ሥጡት ይህንን ለማገናዘብ አእምሮ አላችሁና ሴት ሁለት ወንድማማችን ብታገባ ከቤተክርስቲያን ትባረር ወንድም እንዲሁ ሁለት እታማማቾችን ቢያገባ ይሰደድ ባባትና እናታቸው ላይ ስድብን አመንጭቷልና ።'),
  ('c9a12f16-e724-514f-ac6a-11e02c54db0f', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 75, 75, 'ወንድም ይሁን ሴት ይህን የመሰለ የተሳሳተ ጋብቻ ትተው ከተመለሱ ደግሞ ይህን የመሰለ ስህተት እንዳይፈፅሙ በመምከር ወደ ቤተክርስቲያን አስገቡዋቸው። የተስተካከለ ክርስቲያናዊ ጋብቻም እንዲኖራቸው አድርጉ።'),
  ('86258144-ef3f-5ebe-a8e9-f9f705605aeb', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 76, 76, 'ለደናግልም የወደፊቱ ጋብቻቸው ይዞታ የተቃና እንዲሆን እስከዚያውም ድንግልናቸውን በጥንቃቄ ይጠብቁ ዘንድ ምከሩዋቸው ድንግልናቸውን እንደዓይን ብሌን ይጠብቁት በዚህመሠረት አባት ልጁን ይገስፅ እናትም ሴት ልጇን ከመምከር አትቦዝን በአመንዝራነት መንገድ ጋብቻ አይፈፀም እኛ በሠጠናችሁ ህግ መሠረት ይፈፀም እንጂ።'),
  ('73b492b1-6d80-50a6-a8cb-f2aaceb07972', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 77, 77, 'ድንግልናቸውን ጠብቀው ለመኖር የወሰኑትን ሁሉ ከእግዚአብሔር ፊት አቁሙአቸው ለሰማያዊው መሹራም የታጩ እንዲሆኑ አድርጎ እነሱ ራሳቸውን በድንግልናዊ ሕይወት ለመምራት ይችሉ ዘንድ በዚሁመንገድ ሕይወታቸውን ለመምራት ካልቻሉ ግን በቤተክርስቲያን ህግ መሠረት ይጋቡ ንፅሕናን የተላበሰ ጋብቻ የተባረከነውና።'),
  ('4a2e0d15-fbca-5d06-a2ec-86be98adef29', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 78, 78, 'እግዚአብሔር አባታችን አዳምን በአርአያውና በምሳሌው ፈጠረው አንዲት ሚስትንም ሠጠው እሷም ሔዋን ናት እግዚአብሔር ባረካቸው ብዙ ተባዙም አላቸው በዚህ መሠረት እግዚአብሔር የሰው ልጅ በክርስቲያናዊ ሕይወት እንዲኖር አዝዞታል።'),
  ('fd148ed0-e79d-5232-a352-d2c1d4730147', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 79, 79, 'ከብዙ ሴቶች ጋር ለሚኖሩ ግን ከሕግ የወጡ ናቸውና ከኢየሱስ ክርስቶስ መንጋዎች ጋር አይቆጠሩም ድርጊታቸውን ትተውና ተፀፅተው ከተመለሱ ግን ከምዕመናን ጋር ይቆጠራሉ ከመጥፎድርጊታቸው ካልተመለሱ ግን ከቤተክርስቲያን ይለዩ።'),
  ('dc6d4a5b-37e3-5618-a57d-368904d5ff88', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 80, 80, 'ቤተክርስቲያን በዚሁ መንገድ ሥርዓት አስቀመጡላት ሁልጊዜ እግዚአብሔር ያድርባት ዘንድ ለዚሁም ምሳሌ ልስጣችሁ ምሳሌው አንድ ኃብታም ሰው የሠራውቤት ይሆናል አንድ ሰው የምታምር አዳራሽ ሠራ ሰባት ምሰሶዎች ነበሩዋት።'),
  ('a89b94aa-799c-5353-a02f-6ac2a084c929', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 81, 81, 'ሰባተኛው ምሰሶ ከማሕል ተተክሎ ሁሉንም ተሸክሟል በጣምም ያምራል መቆለፊያውም በሚገባ ተዘጋጅቷል ለዚሁ መልካም አዳራሹ ስባት አማካሪዎችን ኣስቀመጠ ሰባተኛ» አማካሪ ሁሉንም ይመራል። ሁለት ሰላዮችንም መደበ እነዚህ ሁለት ሰላዮች መልካሙንና ክፉውን አንድ ባንድ ይቆጣጠራሉ።'),
  ('04d0353c-711a-5b1f-af1b-c9d2e64dd71c', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 82, 82, 'ከነዚህ ሁለት ሰዎች በታች ሁለት ተሸካሚዎችን መደበ ሁለቱ ማንኛውንም ሁሉ ይሸከማሉ ከዚያ አሥር ሰዎችን ሾመ እዩህ ሁሉ ወደፈለገው ሁሉ የሚታዘዙ ናቸው ወደፈለገም ያዛቸዋል።'),
  ('3b28a388-b62e-5dc5-a714-6c4402eb555f', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 83, 83, 'ለዚሁም ትርጓሜው እግዚአብሔር በይሁዳ ታወቀ በእስራኤል ዘንድም ስሙ ከፍ አለ ባገሩም በሰላም ኖረ ማደርያውንም በዕየን አደረገ በዚህም የጦርን ሐይል ስበረ ስልፈኛንና ጋሻንም አሰፋ ማለት ይሆናል።'),
  ('a4581542-f93b-5d50-a400-93fd809d30bb', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 84, 84, 'የቤተክርስቲያን ልጆች መሠረት ይፀና ዘንድ አንተ ይህንን ሥርዓት ትሠራለህ መሠረታቸውም ሲፀና እግዚአብሔር በነሱ ላይ ያድራል ካባቱ ጋርና ከመንፈስቅዱስ ጋርም የሱ ማደርያ ያደርጋቸዋል።'),
  ('fc71d20a-8f14-5e0c-afeb-dc0ff277099e', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 85, 85, 'ደግሞ ሐጢአተኞችን ንሥሐ ችላ እንዳይሉ የቤተክርስቲያንን ሹማምንት ንገራቸው ጌታችን ኢየሱስክርስቶስ በአሕዛብ ላይ ሸክምን አታክብዱ የማይችሉትንም ሸክም አታሽክሙአቸው ብሏል እናንተስ ይህንን እንዳትፈፅሙ አስተዋይ አእምሮ ሥርዓትም አላችሁ። አንድላይ ተሰብስበን በሠጠናችሁ ቤተክርስቲያንን ምሩአት ግን ተኣአዩ ።'),
  ('92cb9110-f9fc-5711-a1f4-208770f9a77e', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 86, 86, 'ጌታችን ራሱ በመንፈስ አስቀድሞ ልባሞችና አዋቂዎች እንሆን 153 ዘንድ አዞናል አስተዋይነታችን ከመጋረጃ ውስጥ ካለው ቅድስና ቦታ ይሆን ዘንድ በናንተ ላይም ክፉ አይገኝ ክፉ ነገር ከእግዚአብሔር እንድትርቁ ያደርጋል።'),
  ('cb4aa264-a9b8-5706-affb-f7485bbbd5fb', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 87, 87, 'ከዚህም ሌላ እንደገና ተሰብሰቡ አሕዛብን ታሥተምሩአቸው ዘንድ እግዚአብሔር ደስ ይለው ዘንድ በናንተ ላይ ነውር አይገኝ በዚያች ከፊቱ በምንቆምባት እለት አሕዛብ ሊሠሩት የሚገባቸውን እንድናስተምራቸው አዘኸናል እኛም ያዘዝከንን አስተምረናቸዋል ብለን ለመመለስ እንችል ዘንድ።'),
  ('fbc52bae-7633-59d7-a93a-6d5791546bb3', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 88, 88, 'አቤቱ ከተረገሙትና ከትእዛዝህ ከራቁ ጋር አትስደደን ትእዛዝህን ከሚጠብቁ መንጋዎችህ ጋር ቁጠረን እንጂ ከምሕረትህም የራቅን አታድርገን ስትሉተ አስተምራችሁ በጸጋ ከወላጆቻችሁ ጋር ይደሰትባችኋል። ከፃድቃንና ከደጋግ ሰዎች ጋርም አዲስ ምድርን ትወርሳላችሁ።'),
  ('10ec3ee3-b60b-560a-a284-1246b61542da', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 89, 89, 'ከምታስተምሩዋቸው አሕዛብ መካከል የሚፈፅሙትን በደል ብታዩ አትለፉዋቸው ገሥፁዋቸው እንጂ ይህን ካላደረጋችሁ እግዚአብሔር ይወቅሳቹኋል ባያችሁትና በሰማችሁት ሁሉ በቅንነት ካስተማራችሁ እግዚአብሔር አስቀድማችሁ ያላያችሁትን የተደበቀ ኀብት ይሠጣቹኋል ።'),
  ('ba75b182-10da-52df-ac85-267d910814a8', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 90, 90, 'ስለዚህ ቅድስት ቤተክርስቲያን አምራ ትታያለች እናንተም እረኞች በቃል ትሰበስባላችሁ ክፋታችሁና ደግነታችሁ ያንጊዜ ይታያል ደጉ ሕመምና ምንዳቤ ከሌለበት የብርሃን ማደርያ ሥቃይ ካለበት በዚህ ቀን አደባባይ ምዕአቱ በአሥራ ሁለት ይሆናል።'),
  ('2ae49d98-54e6-50d3-acdb-c5f8acc13441', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 91, 91, 'ክፉ ቀም የርዕ ማፏጨትና ሥቃይ ካለበት በዚህ ቀን ያልፋል የማይባል ሐዘንና መከራ ልቅሶና ዋይታ ካለበት የጨለማ ቦታ በኵነኔና በእሳት እየተቃጠለ ይኖራል።'),
  ('5d1463fd-010e-51a8-a1c3-ade83a397789', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 92, 92, 'ይቺን ቃሌን ጠብቋት እቺንም ሥርዓቴን ጠብቁዋት ይህንን ካደረጋችሁ በአምላካችሁ አደባባይ ትደሰታላችሁ ብስቀመጣችኋቸው ላይ ያንጊዜ አለቆች ትሆናላችሁ። ይህንንም ጌታችን አሥረድቶናል ። በዳግም ምፅአቱ በአሥራ ሁለት መናብርት ላይ ተተምጠን በአሥራ ሁለቱ ነገደ እሥራኤል ላይ ለመፍረድ እንደምንችል ገልፆልናል።'),
  ('db8ef05f-3119-54c6-a340-dd6b653b1216', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 93, 93, 'በቃላችን ካመናችሁ በመልካምም ህግ ከተመራችሁ ይሆናል ቃላችንን ሰምተው እማያምነ ግን ምስጋናንንም ለማይቀበሉ ዚለዓለማዊ ደይን ይጠብቃቸዋል።'),
  ('f60dc94b-b3b2-52df-a70b-1fcfaa23effb', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 94, 94, 'እናንተ ዚህልም አስተምራችሁ ለመንግሥተሰማያት ካዘጋቹኋቸው ለነሱ ዓለቆች ትሆናላችሁ በመንግሥተ ሰማያትም ከነሱ ጋር ደትደስታላችሁ ነገርግን በትክክል ላታስተምሩዋቸው በመቅረታቸው ለኩነኔ ቢዳረጉ እናንተና እነሱ አብራችሁ ገሐነመእሳት ትገባላችሁ።'),
  ('19550c76-48ae-5768-a4cc-096b7c5416ce', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 95, 95, 'እናተ ችልተኞች ከሆናችሁ አካሄዳችሁም ካላሳመራችሁ በእግዚአብሔር የተጠራችሁበትንም ጥሪ ካላከበራችሁ ፍዳ ይጠብቃቹኋል እኔ ቀሌሚንጦስ እነግራችሁአለሁ ጥቡአን ሁኑ። ስለዚህ ሐጢአተኞችን ልትገሥፁዋቸው ትችላላችሁ አታላዮችንም ከተንኮላቸው ልትመልሱዋቸው ትችላላችሁ ስለነሱም የሰማይንና የምድርን ምሥክርነት ጠይቁ።'),
  ('d8819888-e71d-59fd-a744-7158ae90b550', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 96, 96, 'ነቢይ ስለዚህ ሰማይ ስሚ ልንገርሽ ምድርም አድምጪ (የአፌን ቃል ስሚ) እንደገና ከዚሁ መዝሙር በመቀጠል ይህ ሕዝብ ሰነፍ ነው ብልህ አይደለም ይህ አልነበረም የፈጠረህ ፈጥሮም ሕይወትን ሠጠህ እንደገና በዚሁ መዝሙር ቀጥሎ እንዲህ አለ ያዕቆብ በልቶ ጠገበ ሰባ ደነደነም ወድያውም ተራበ እግዚአብሔርንም ፈጣሪው ተወው ሕይወቱም ከእግዚአብሔር ራቀ።'),
  ('15ddda64-6670-5750-a90c-af9a4baa7309', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 97, 97, 'እንደዚሁ እናንተም እረኞች ከበታቾቻችሁ ያሉትን ሕዝቦች ገሥፁዋቸው የተቀደሰችውንም ሥርዓት አስተምሩዋቸው።'),
  ('47c73973-55a6-5928-a85e-a8880f080e72', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 98, 98, 'ይህን ሥርዓት የመንፈስቅዱስን ፀጋ ትቀበሉ ዘንድ በታላቋና በተቀደሰቿ ዕለት የተቀበላችሁት ነው ከሁሉ በፊት ከሁሉ አስቀድማችሁ የዚያችን ሃይማኖት ጠብቁ በመቀጠልም ሕዝብ እሷን ይጠብቁ ዘንድ አስተምሩዋቸው።'),
  ('d8b2405d-1cc0-5451-a70d-bb35962888c9', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 99, 99, 'መንፈሳዊ ማዕድን ለማቅረብ የሚወድና ነገርግን ከሷ የማይቀምስ ሁሉ ውሸታም ነው።'),
  ('e1400aab-dc27-5f6b-ad4f-7c9ce875d917', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 100, 100, 'የምትናገሩትን ለመሥራት ዝግጁዎች ሁኑ ይህ ካልሆነ ግን የምትናገሩትን የሚያዳምጥ የለም ሌሎች የሚናገሩትን ራሳቸው በሠሩት ነሮ እኛም በሠራነው ነበር። ትምህርታቸውንም በተቀበልነው ነበር ይላሉ።'),
  ('1b6a2f4c-f76f-5453-a9ca-17c0e7bd792f', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 101, 101, 'ነገርግን የሚያስተምሩንን ራሳቸው አይሠሩትም እንዴት እንሰማቸዋለን ትዕዛዛቸውንስ እንዴት እንፈፅማለን ይልቁንስ በነሱ አካሄድ እንሄዳለን ይላሉ የቤተክርስቲያን አለቆች ሆይ የእግዚአብሔርን ትእዛዝ ጠብቁ በፍርድ ጊዜም የሰውን ፊት አይታችሁ አታዳሉ ።'),
  ('388a8759-9167-58a5-aeab-668ce49ae749', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 102, 102, 'ከንፁሕ ሰው ላይ መማለጃ አትያዙ ይህ ድርጊት ከበደል ሁሉ የከፋ ነው የልቡናን ዓይኖች ያሳውራልና ጥበብንም ያጨልማልና ባለፀጋን በባለፀግነቱ ብቻ የበላይነትን አትሥጡት የሙትልጆችንም ችላ አትበሉ ።'),
  ('297ea999-a452-5ee9-a72c-d229f55254ce', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 103, 103, 'እግዚአብሔር ለነዳይ አባቱ ነው ረዳት የሌለውንም ይረዳዋል። ቃሌን ከሚረሱ ላይ ፊቴን እመልሳለሁ እነሱንም ሥራቸውን ነቅየ ከምድር አጠፋቸዋለሁ በቃሌ ላይ የሚገዳደሩትን እንዳልነበሩ አደርጋቸዋለሁ።'),
  ('bd7d4dde-8646-52dd-aeba-ccb0078e4877', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 104, 104, 'የእምነትን ቃል ማስተማር የሚያዘወትሩ ሁሉ የቤተክርስቲያን አለቆች ይሆናሉ። እነዚህ አሕዛብን የኔን መንገድ ያሳዩአቸዋል የኔን ትምህርት የሆነውን በማስተማር የተመሠረተ መልካም ሽልማትም ቤተክርስቲያንን ያሸበርቁዋታል።'),
  ('62e2fc61-229a-52e0-aa39-229c5f341469', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 105, 105, 'ያገሩ ሰዎች በረሐብ ተይዘው እያለ በልብስ እርዛትም ሆነ በውሃ ጥማት እየተቸገሩ እያለ የተለያየ ጣዕም ያላቸውን መባለዕት እያቀያየረ የሚመገብ ኤጴስቆጶስ ኤጴስቆጶስ ተብሉ ሊጠራ አይገባውም ይህ ዓይነቱ ኤጴስቆጶስ ከእግዚአብሔር ዘንድ ፍዳ ይጠብቀዋል ኃላፊነቱን በፍፁም ሊወጣ አልቻለምና።'),
  ('9b3f0e08-ba6a-55f3-a5b4-be0a59b259c9', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 106, 106, 'ያገር ሰዎች ግማሻቸው ሲበሉ ምን ጊዜም ከመካከላቸው ጦምአደሮች አሉ። ግማሻቸው ሊለብሱ በልብስ እጦት የሚራቆቱም ይኖራሉ ረኃብተኞች እግዚአብሔርን የሚያምኑ ከሆነ ለቤተክርስቲያን ደጋግ መሪዎች ያዘጋጀውን (እግዚአብሔር) ምግብ ይመገባሉ።'),
  ('94089ef7-467d-563f-a704-b44279a323ed', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 107, 107, 'የእግዚአብሔርን ትእዛዝና የቤተክርስቲያንን ሥርዓት ያልጠበቁና ተልእኮአቸውንም ያልተወጡ ሁሉ በንዝህላልነታቸው ምክንያት ወልድ በግርማመንግሥቱ ሲመጣ እናንተ የዓመፅ ልጆች ከኔ ራቁ ተብለው ዳግም ሞትን ይሞታሉ።'),
  ('c41071d8-d8f8-5f4d-a65f-173044c91314', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 108, 108, 'በነዳያንና በምስኪን ወንድሞቻችሁ ላይ መልካም ሥራን ስላልሠራችሁ አላውቃችሁም በደሜ ገንዘብ ያደረግሁዋትን ቤተክርስቲያንን በቅንነት ለሚያገለግሉ ቃል የገባሁላቸውንም በረከት ለናንተ አልሠጥም ይላል እግዚአብሔር።'),
  ('0e3a3b35-053a-5aa9-ac7f-ff64de37932c', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 109, 109, 'ራሱን ከፍ ያደረገ ይዋረዳል ራሱን ዝቅ ያደረገ ደግሞ ይከብራል አንተ ባልእንጀራህን የምትንቅ ጥፋ ራስህን ከፍ የምታደርግ ፈሪሳዊና መፀብሐዊ ሊፀልዩ ቤተመቅደስ እንደገቡ አታውቅምን ፈሪሳዊው በትዕቢት ሥለጸለየ ጸሎቱን እግዚአብሔር አልተቀበለም ።'),
  ('4554afb1-c68e-58c7-a08b-4d0155f820e2', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 110, 110, 'መፀብሐዊው ግን ቤተመቅደስ እንኳ ለመግባት አልደፈረም ከሕሊናው በጥልቅ እየተጸጸተ በከባድ ሰቆቃ ተይዞ ወደሰማይ ዓይኖቹን ከፍ በማድረግ ለመጸለይ አይገባኝም በደሌና አበሳየ እጅግ ከመብዛቱ የተነሳ ረክሼአለሁና አለ እንጂ እሱም ከመጸጸቱ የተነሳ ጸደቀ ።'),
  ('59e2d194-404f-57c7-a7cd-eeca7a429051', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 111, 111, 'ዳግመኛስ በወንጌል በዓይንህ ምሰሶ እያለ በጓደኛህ ያለውን ጉድፍ ለምን ታያለህ በዓይንህ ያለውን ምሰሶ ለምን አትመለከትም ባልንጀራህን ከዓይንህ ውስጥ ጉድፍ አለና አውጣ ለምን ትለዋለህ አስቀድመህ በዓይንህ ያለውን ምሰሶ አውጣ ከዚያ በኋላ ባልንጀራህን በዓይንህ ጉድፍ አለና አውጣው ትለዋለህ እግዚአብሔር ራስህን ከፍ ማድረግና ባልንጀራህን ዝቅ ማድረግ ከልክሏል።'),
  ('5fcb68fa-5f9c-5654-ae5a-5d56658fe24c', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 112, 112, 'ባለንጀራችሁን ለመናቅ የሚያነሳሳ ነገርን አትፈልጉ ልቡናችሁም በትዕቢት አይሞላ ትዕቢት ካለበት አካሄድ ከዚህ ውርደት አለ አይሆንም በቤተክርስቲያን አገልጋዮች ላይ ውርደትን አታምጡባቸው ቤተክርስቲያን ማለት እግዚአብሔር በሥርዓት ሁሉ አስተካክሎ የመሠረታት ናት ስለዚህ ሁላችን አብረን በነበርን ጊዜ አምላካችን እግዚአብሔር እንዳዘዘን ሊያደርጉላችሁ የምትፈልጉትን እናንተም አድርጉላቸው ።'),
  ('1dc063e5-92c2-50c8-a7dc-c3dbb87629f6', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 113, 113, 'እግዚአብሔር ለእስራኤል ልጆች ከባእድ ሰው እሳትን አታምጡ እንዲህ ካደረጋችሁ ትሞታላችሁ ብሉ በሙሴ በኩል እንዳዘዛቸው ታውቃላችሁ ስለዚህ እናንተም በቤተክርስቲያን ላይ ክርክርን አታንሱ ።'),
  ('f1a50650-0d72-5feb-a786-cd7694698ea7', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 114, 114, 'እስራኤላውያን የእግዚአብሔርን ትእዛዝ ተላልፈው ከባእድ እሳትን ስላመጡ ሙተዋል በዚህም አካሄድ በዕብደታቸው እንደ ዳታንና እንደ አቢሮን በመምህሮቻቸው ላይ የድፍረትን አካሄድ ከተከተሉ እንደነሱ ምድር አፏን ከፍታ ልትውጣቸው ትችላለች ከቅድስት ጥምቀት ተወልደው የቤተክርስቲያን ልጆች ሳይሆኑ በድፍረት አይግቡ።'),
  ('1e3e76e3-e39f-5120-afd7-5e3dd6e6563e', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 115, 115, 'እናንተም ከተጠመቃችሁ በኋላ ተልእኳችሁን በትክክል ካልተወጣችሁ እስከዘለዓለሙ መውጫ ወደሌለው ነደ እሳት ኩነኔ ትገባላችሁ።'),
  ('fc395462-0fe8-51ba-a48a-9341d689a25f', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 116, 116, 'ልጄ ቀሌሚንጦስ ሆይ አንተም ለብዙዎች አርአያ ትሆን ዘንድ ይገባል መልካምን ስራ ራስህ እየሠራህ ለሌሎች አሳያቸው እነሱ ያንተን መልካም ሥራን መሥራት እየተከተሉ ትምህርት ያግኙ ደካሞችንም ደግፋቸው።'),
  ('d6c1b2c4-cc6c-5b52-a373-a75ce948fdcc', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 117, 117, 'የወደቁትን አንሳቸው የተገፉትንም አድናቸው በደላቸውንና ክፋታቸውንም ይቅር በል ለደጋግ ሰዎች አርአያ ሁናቸው ክፉዎችን ደግሞ ገሥፃቸው ከክፉ ተግባራቸው ይርቁ ዘንድ በፍርድ ጊዜም በደል እንዳይፈዕመ ንገራቸው በቤተክርስቲያን ቀኖና ሠርተናል ስለዚህ በዚሁ ቀኖና እየተመሩ በቤተክርስቲያን ሥር ይኑሩ።'),
  ('4d666ec7-34f8-5864-a515-66836af295f5', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 118, 118, 'በይበልጥ ግን ሐሰትን ከመስማት ከዝሙት ከወንድ ሚስት ዘንድ መሄድ የበከተውን ከመብላት። ለጣዖት መሥዋዕትን ከመሰዋት ይጠበቁ የእግዚአብሄርንም የተቀደሰውን ተፈጥሮ አያርክሱ እግዚአብሔር ቅዱስ ነውና ራሱ ጌታችን ኢየሱስክርስቶስም እኔ ቅዱስነኝና እናንተም ቅዱሳን ሁኑ ብሏል።'),
  ('43cebffb-f997-5ecd-ade1-d85780c4486d', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 119, 119, 'በባልእንጀራችሁ ላይ ስድብን አትናገሩ ዲያብሎስ በስድብ ከመንበሩ ወድቋልና የመላእክት አለቃ ሚካኤልም በትሕትናው ብዛት ከመንበሩ እጅግ ከፍ ያለ የቅዱስ ሚካኤል ሊቀመላእክት ዋና ተግባሩ ነጋሪትን መምታት ነበር። በትሕትናው ግን የዲያብሎስን መንበር ወረሰ።'),
  ('10a13886-0d71-551d-af57-fa3a198c3045', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 120, 120, 'እንዲሁ ካህንም የቤተክርስቲያን አገልጋይ ስለሆነ አስተዋይ የዋህ የበደለኞችን ጥፋት የሚያለዝብ በደለኞችን በቃለሰላም ወደቤተክርስቲያን የሚመልስ መሆን ይገባዋል። ካህን የክርስቶስ መላእክተኛና ገበሬ መሆኑን አይርሳ ካህን ሁለት አፍ ያለው ምላጭ ማለት ስለሆነ በእግዚአብሔር ቃል የሠይጣንን ተንኮል ይቆርጣል።'),
  ('68d15a69-26f7-5abe-a204-a56572cd19c1', 'ea9073d7-ad07-5020-a53a-a9daf2c7449b', '95ab9b49-29e7-51b7-a146-3edd524f91eb', 121, 121, 'እንዲሁም ካህን ፈሩን አስተካክሎ እንደሚያርስ መሆን አለበት ። ገበሬ በእርሻው ጊዜ ፈሩን ግራና ቀኝ ሳያጣምም ያርሳል የእግዚአብሔር መንግሥት የቀናች ናት የእግዚአብሔርን መንግሥት ጠብቁ እንዳትጠፉ ወደ ሲኦልም እንዳትወርዳ ምእመናን ሐጢአተኞች ሊገቡበት ከተዘጋጀው ገሀነም እንዲድነም አስተምሩ ።'),
  ('1549c70d-31bf-54aa-aa33-86c42d7fe84e', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 1, 1, 'ቅዱስ ጴጥሮስ እንዲህ ይላል እኛ ሓዋርያት አሥራሁለት ሁነን ተሰብስበን ሳለ አንድ ድምፅ የሚከተለውን መልእክት አስተላለፍን ። ሰው ሁሉ በራሱ ሊፈፀምበት የማይፈልገውን በሌላውላይ ማድረግ ከክርስቲያናዊነት ያስወጣል ይህንን ሁሉ አሪትና ነቢያት ይከለክላሉ እኛም ሀይማኖታችሁ የፀና ይሁን እንላለን።'),
  ('489626c8-35de-57a6-a27b-da2759285e58', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 2, 2, 'የጌታችን ወዳጅ ዮሐንስም ሥጋውን በዝሙት ለሚያረክስ ሰው ወዮለት የሰው ሥጋ ቤተክርስቲያን አባል ለመሆን በጥምቀት ዳግም ልደትን ካገኘች ጀምሮና ኢየሱስ ክርስቶስ ሥጋንና ደምን ከተቀበለች ጀምሮ በነፍስና በሥጋ ከኢየሱስ ክርስቶስ ጋር አንድ ናትና የክርስቶስን አንድነት ከተቀበላችሁ በኋላና የሱም አካል ከሆናችሁ በኋላ ሥጋችሁ የዝመት አካል ታደርጉታላችሁን መሆን የለበትም ብሏል።'),
  ('b58c8318-c681-5b87-a1dc-ab4abb6a7003', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 3, 3, 'ሰው ሁሉ ባንዲት ሚስት ፀንቶ ይነር እንዲሁም ወንድማችን ጳውሎስ እንዲህ አለ ሚስት ካገባህ ጀምሮ ከሚስትህ ተለይተህ በሌላ ቦታ ብዙ እትቆይ ከባል የተለየች ሴት ካለች ብቻዋን ትነር ሁላችሁም እኔ በሠጠሁዋችሁ ምክር ብትኖሩ ይሻላቹኋል ሚስት ከሌለህ ብዙ ሴቶችን መመልከት የለብህም ይህን ካደረግህ ኃጢአተኛ ነህ ብሏል።'),
  ('d2b10c5d-04d3-5a63-a35e-7a72d04e9057', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 4, 4, 'በሕሊናውም ሆነ በተግባሩ እያመነዘረ ከሚኖር ሚስት አግብቶ የሚኖር ይሻላል ሚስቱ ካልሆነች ሴት ጋር የሚያመነገር ሰው ለአጋንንት የእንስሳትን ደም እንደሚሰዋ ሰው ይቆጠራል በፍርድ ቀንም ፍዳውን ይቀበላል በሠይጣን መንገድ ተጉዟልና ሰይጣን ከኛ አንዱ ሰው እንኳ እንዲድን አይፈልግም።'),
  ('cec97bf3-c05c-5de3-abb1-3079bd3cefc2', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 5, 5, 'የሠይጣን ዘሩ ትዕቢት ትዝህርት ባልንጀራን ማማት፣ ሥሥት፣ መጠጥ ስካር፣ ዝሙት፣ በሐሰት መማል፣ ባልንጀራን መዝለፍ፣ በተሳሳተ ቃል ስሕተትና የመሳስለው ሁሉ ነው መጠቃቀስ፣ መሳቅ፣ ቍጣ፣ ምቀኝነት፣ መሥረቅ፣ ወደ ወንድ ሚስት መሄድም የሠይጣን ናቸው።'),
  ('3dc25612-e6f1-5275-a9ad-434ae301a4fd', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 6, 6, 'ባልንጀራን መጥላት ጨምሮ ከዚህ በላይ የተዘረዘሩት ሁሉ የሠይጣን ዘሮች ናቸው መንፈስቅዱስ በሰው ልቡና የሚዘራቸው ዘሮች ግን ትህትና፣ የዋህነት፣ ፍቅር፣ ሰላም፣ ጾም፣ ጸሎት። ይቅርባይነት ሥዕለት፣ ለድሃ መራራት፣ ምፅዋት፣ ሲሆነ እነዚህ ሁሉ ሕይወቱን ለመንፈስቅዱስ የሠጠ ሰው የሚያገኛቸው ናቸው።'),
  ('7a64c804-ca88-5d5d-a21e-1d71095cdbd8', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 7, 7, 'ብልሆች የእግዚአብሔርን ትእዛዝ ይጠብቁ ዘንድ በሠይጣንም መንገድ እንዳይሄዱ በደስታ አንድጊዜ በሐዘንና በትካዜ ሌላ ጊዜ ሠይጣን ልባቸው እንዳይሠርቅ ይጠንቀቁ እናንተም ደስታችሁን ወደሐዘንና ወደትካዜ ለውጡት ሐዘናችሁንም በአኮቴት ተቀበሉት እግዚአብሔር በናንተ ደስ ይለው ዘንድ።'),
  ('2321fc07-cb54-5cfd-a1ca-0331966edc29', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 8, 8, 'ይህን የመሰለ ሕይወት ካላችሁ ዓይን ያላየውን ጆሮ ያልሰማውንና በሰው ልቡና ያልታሰበውን እግዚአብሔር ይሠጣቹኋል ገነተትፍሥሕት የሰው ዓይን ያላያት ናት የሰው ጆሮም ያልሰማት ናት ስለዚህ ለዚህ ትልቅ ጸጋ ትበቁ ዘንድ ትጉ።'),
  ('c3c45572-d185-55c2-a892-5f36a5a068fe', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 9, 9, 'በገነተ ትፍሥሕት ሐዘን የለም ወደዚሁ ለመግባት ትችሉ ዘንድ ከጌታችን መድሐኒታችን አምላካችን ኢየሱስ ክርስቶስ እግዚአብሔር ዘንድ ለምዕመናን መላእክት የተሠጠውን ሥርዓት ጠብቁ የቅድስት ቤተክርስቲያንን ሥርዓት በመጠበቅ ይህንን ታገኛላችሁ ከዚህውጭ ከሆናችሁ ግን ከመዓሥባንና መናፍቃን ጋር ትቆጠራላችሁ ።'),
  ('af4dbc16-1707-5165-a510-60ee71a812e1', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 10, 10, 'እግዚአብሔር ህጉንና ሥርዓቱን ለሚጠብቁ ሁሉ ምሥጋናቸውንና ዋጋቸውን ይሠጣቸዋል የድካማቸውንም ዋጋ ይከፍላቸዋል ሰማያዊውን ሙሽራ በተቀደሰ አካሄዳቸው ደስ አሰኝኝተውታልና የፅድቅ መንፈስ ባለበት በዚያ ነፃነትና ደስታ መንፈስ አለና መንፈሰ ጽድቅ ከሐጢአት ነፃ ታወጣለችና።'),
  ('7c7ce981-97b4-5bfb-aa46-3a270f3d45b9', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 11, 11, 'እውነት ነፃ የምታወጣችሁ ከሆነ እናንተ በእውነት ነፃነትን የተቀዳጃችሁ ናችሁ ሐጢአትን ለመሥራት የሚያስገድዳችሁ የለም በገዛፈቃዳችሁ ብቻ ሐጢአትን ትሠራላችሁ ካሁን ጀምሮ ግን ነፃ የወጣችሁ ሁኑ ሐጢአት አይግዛችሁ የቤተክርስቲያንን ሥርዓት ሁሉ ተመልከቱ ቤተክርስቲያን ማለት የክርስቲያን ነፍስ ማለት ነው የክርስቲያን ነፍስም የክርስቶስ ነፍስ ማለት ነው።'),
  ('07511717-c97a-5881-aa29-ca0a12677eb6', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 12, 12, 'ኃጢአት ሊወገድ ካለበት ዘንድ ኢየሱስ ክርስቶስ የእግዚአብሔር መንፈስ እንዲህ እያለች ድምጿን ታሰማለች። የምታሰማውም በፃድቅ ሰው ላይ ነው። ድምዕዋንም የምታሰማው እግዚአብሔር ሆይ ማረኝ ይቅርም በለኝ እያለች ነው።'),
  ('0a792d6a-7e16-5c69-ac5b-0c30708287b1', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 13, 13, 'እንዲህ እያለ ሲጮህ ጻድቅ ሰው በሐጢአት አይቸነፍም (ወድቆ አይቀርም) እግዚአብሔር በሱ ላይ አለና ሕሊናውም ሁሉ ከእግዚአብሔር አይርቅምና እግዚአብሔርም የሕሊናው ቅንነት እያየ በአጋንንት እንዲረገጥ አሳልፎ አይሠጠውም ስለዚህ ሁላችን ከአጋንንት ስህተት እንጠበቅ ከሥጋና ከነፍስም ደዌ እየተጠበቅን ሐዋርያት አባቶቻችን እንዳዘዙን ቤተክርስቲያንን እንጠብቃት።'),
  ('03af66f6-c62b-5053-a88d-0f64b89370d3', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 14, 14, 'በዚህም አካሄድ ሕዝቦችን ካልመራቹኋቸው ከኛ ሥር ሁነውም እያለ ከማስተማር ችላ ካላችኋቸው እግዚአብሔር ይወቅሳቹኋል እግዚአብሔር አምላክ ነቢዩን እዝቅኤልን እንዲህ ብሎታል የሰው ልጅ ሆይ በሕዝብ ዘንድ የዓይን ምሥክር አደረግሁህ።'),
  ('6e6d37b7-e8a1-591e-af93-cf267ea55adb', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 15, 15, 'ሐጢአተኞችን ንሥሐ ይገቡ ዘንድ ንገራቸው (ከስሕተታቸው ይመለሱ ዘንድ) አንተ እንዲመለሱ ነግረሃቸው ካልተመለሱ ግን በዚሁም ከሞቱ አንተ ራስህን አዳንክ እነሱም በኃጢአታቸው እንደሞቱ ይቀራሉ ወይም ደግሞ አንተ ስላስተማርካቸው ከተመለሱና ንሥሐ ከገቡ ከኃጢአታቸውም ከራቁ ራሳቸውን ካዳነ አንተ ከእግዚአብሔር አምላክህ ብዙ ሥጦታ አለህ ጻድቁንም ቢሆን ከፅድቁ ወጥቶ እንዳይጠፋ አስተምረው።'),
  ('dc753eae-c6fe-54f6-af0b-93ec98d3f3c0', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 16, 16, 'አንተ እንደ ነገርከው ባንተ ተመርቶ መልካም ከሠራ ራሱን አዳነ ካልተመለሰ ግን ኃጢአቱን ተሸክሞ ይሞታል አንተ ግን ሐላፊነትህን ተወጥተሃል። ባንተምክር ተጠብቆ እስከዕለተሞቱ ድረስ ከቆየ ጽድቁንም ከጠበቀ ከኔ ዘንድ መልካም ሥጦታ አለው አንተም እሱን አስተምረህ በመመለስህ ዋጋህ ብዙ ነው።'),
  ('8b36a70e-bf1b-59d8-a491-dac6d1656a4c', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 17, 17, 'ለካህናት ከእግዚአብሔር የታዘዘው ይህ ነው ካህናት ሐጢአተኛው ንሥሐ እንዲገባ ብዙ መድከም ሥራቸው ነው ይህንን ሲያደርጉ ፊቱን በማየት እንዳያዳሉ ይጠንቀቁ ንጉሥም ይሁን ሌላ ባለሥልጣን ሥጋዊክብሩን ከስብእናው ለይተው'),
  ('5189f786-807d-5803-a27c-0c9516d5c6db', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 18, 18, ''),
  ('1768e9ef-b1c1-5a0e-ad6c-6fa9e187930b', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 19, 19, '')
